window.HANDBOOK_DATA = {"schemaVersion":1,"updatedAt":"2026-10-12","papers":[{"id":"w01-p01","week":1,"role":"발표","title":"Taxonomy of Risks posed by Language Models","authors":"Laura Weidinger, Jonathan Uesato, Maribeth Rauh, Conor Griffin, Po-Sen Huang, John Mellor, Amelia Glaese, Myra Cheng, Borja Balle, Atoosa Kasirzadeh, Courtney Biles, Sasha Brown, Zac Kenton, Will Hawkins, Tom Stepleton, Abeba Birhane, Lisa Anne Hendricks, Laura Rimell, William Isaac, Julia Haas, Sean Legassick, Geoffrey Irving, Iason Gabriel","year":2022,"venue":"ACM FAccT 2022","citation":"Weidinger, L., et al. (2022). Taxonomy of Risks posed by Language Models. Proceedings of FAccT 2022, 214–229. https://doi.org/10.1145/3531146.3533088","landingUrl":"https://doi.org/10.1145/3531146.3533088","pdfUrl":"https://facctconference.org/static/pdfs_2022/facct22-3533088.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"다운로드한 2022 학회 PDF는 비영리 개인·수업용 복사를 허용하고 고지·인용 보존을 요구한다. 2026-10-12 공식 ACM DOI 검색 결과에는 CC BY 4.0이 표시되지만 직접 페이지 접근은 실패했고 PDF 고지와 차이가 있다. 이 보관본의 웹 재배포 권한은 보수적으로 미확인 처리하며 개인 학습 묶음에만 포함한다. https://facctconference.org/static/pdfs_2022/facct22-3533088.pdf ; https://doi.org/10.1145/3531146.3533088","sourceVersion":"FAccT 2022 출판본; 학회 공식 PDF","readScope":"full_text","summary":{"question":"언어모델의 위험을 누락 없이 논의하려면 어떤 분류와 증거가 필요한가?","background":"유해 발언만 검사하면 개인정보 노출, 사람의 과신, 노동·환경 영향이 빠진다. 저자들은 기술 성능을 넘어 사회적 피해까지 평가 범위를 넓힌다.","method":"컴퓨터과학·언어학·사회과학 문헌과 전문지식을 종합해 21개 위험을 6영역으로 묶는다. 관찰된 위험과 예상 위험을 구분하고 발생 경로, 근거, 완화책을 연결한다.","findings":"차별·혐오·배제, 정보 위험, 잘못된 정보, 악의적 사용, 인간–컴퓨터 상호작용, 환경·사회경제 피해가 핵심 영역이다. 한 위험의 완화가 다른 위험을 키울 수 있어 공동체 참여와 시스템 수준의 대응이 필요하다.","limitations":"발생 확률이나 우선순위를 산출하는 계량 모델은 아니다. 근거 수준이 영역마다 다르며, 분류는 추가 관점과 사례로 확장되어야 한다.","significance":"안전 평가 전에 무엇을 평가할지 정하는 지도다. ‘충분히 안전함’의 기준은 적용 분야와 이해관계자가 결정해야 한다.","beginnerExplanation":"챗봇이 틀린 답을 하는 문제와, 맞는 개인정보를 누설하는 문제는 다르다. 이 논문은 그런 실패를 구분해 대응 책임을 찾게 한다."},"readingGuide":["표 1에서 6영역의 경계를 먼저 파악한다.","관찰된 증거와 예상 위험을 다른 색으로 표시한다.","3절에서 완화책의 상충과 안전 기준 설정을 읽는다."],"discussion":["대학 상담 챗봇에서 빠뜨리기 쉬운 피해는 무엇인가?","위험 점검표를 통과해도 배포를 보류할 상황은 무엇인가?"],"terms":[{"term":"Taxonomy","ordinaryMeaning":"체계적인 분류","etymology":"어형 풀이: 분류 체계를 뜻하는 학술 명사로 읽는다.","aiMeaning":"위험을 일관된 범주로 조직하는 틀","paperReading":"위험 목록의 구조이며 위험 점수는 아니다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"},{"term":"Risk","ordinaryMeaning":"위험 가능성","etymology":"일상적 위험이라는 뜻이 기술적 평가 개념으로 확장되었다.","aiMeaning":"피해 발생 가능성과 결과에 관한 불확실성","paperReading":"실제 피해와 예상 위험을 구별한다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"},{"term":"Information hazard","ordinaryMeaning":"정보가 만드는 위험","etymology":"information과 hazard의 결합이다.","aiMeaning":"정보의 생성·공개·확산 자체로 생기는 위험","paperReading":"정확한 정보도 공개하면 해로울 수 있다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"},{"term":"Misinformation","ordinaryMeaning":"잘못된 정보","etymology":"mis-는 잘못됨을 나타내는 접두사다.","aiMeaning":"사실과 어긋나는 내용의 생성·유통","paperReading":"고의적 악용과 별도 경로로 읽는다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"},{"term":"Anthropomorphism","ordinaryMeaning":"사람처럼 여김","etymology":"사람의 특성을 비인간 대상에 투사한다는 개념이다.","aiMeaning":"모델에 인간적 이해·능력·의도를 과도하게 부여함","paperReading":"과신과 책임 전가의 원인이 된다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"},{"term":"Mitigation","ordinaryMeaning":"피해나 정도를 줄임","etymology":"어형 풀이: 완전 제거보다 완화라는 뜻이다.","aiMeaning":"위험 가능성·심각성·노출을 줄이는 조치","paperReading":"기술·제도·제품 설계를 함께 검토한다.","sourceUrl":"https://doi.org/10.1145/3531146.3533088"}],"evidence":[{"url":"https://doi.org/10.1145/3531146.3533088","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://facctconference.org/static/pdfs_2022/facct22-3533088.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"},{"url":"https://doi.org/10.1145/3531146.3533088","supports":"공식 DOI 검색 색인에는 CC BY 4.0으로 표시되나 직접 열람 실패. 보관 PDF의 개인·수업용 고지와 불일치하므로 재호스팅 허용 근거로 사용하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w01-p02","week":1,"role":"참고","title":"Model evaluation for extreme risks","authors":"Toby Shevlane, Sebastian Farquhar, Ben Garfinkel, Mary Phuong, Jess Whittlestone, Jade Leung, Daniel Kokotajlo, Nahema Marchal, Markus Anderljung, Noam Kolt, Lewis Ho, Divya Siddarth, Shahar Avin, Will Hawkins, Been Kim, Iason Gabriel, Vijay Bolina, Jack Clark, Yoshua Bengio, Paul Christiano, Allan Dafoe","year":2023,"venue":"arXiv 사전공개 논문","citation":"Shevlane, T., et al. (2023). Model evaluation for extreme risks (arXiv:2305.15324v2). arXiv. https://doi.org/10.48550/arXiv.2305.15324","landingUrl":"https://arxiv.org/abs/2305.15324","pdfUrl":"https://arxiv.org/pdf/2305.15324","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"arXiv 해당 버전의 view license는 CC BY 4.0으로 연결된다. 출처·라이선스를 표시한 원본 배포가 허용된다. https://arxiv.org/abs/2305.15324","sourceVersion":"arXiv v2, 2023-09-22; 최초 공개 2023-05-24","readScope":"full_text","summary":{"question":"대규모 피해를 일으킬 수 있는 모델을 훈련·배포하기 전에 무엇을 평가해야 하는가?","background":"범용 모델의 유용한 능력은 악용에도 쓰일 수 있다. 평균 벤치마크 점수만으로 위험한 능력이나 실제 사용 성향을 판단하기 어렵다.","method":"위험한 능력 평가와 정렬 평가를 분리하고, 결과를 책임 있는 훈련·배포·투명성·보안 결정에 연결하는 개념적 체계를 제안한다. 평가 설계, 외부 평가, 공개 범위도 다룬다.","findings":"‘할 수 있는가’와 ‘해를 끼치는 방향으로 사용하는가’는 다른 질문이다. 평가 결과는 출시 여부, 접근 제한, 보안 수준, 지속 모니터링을 바꾸는 근거가 되어야 한다.","limitations":"새로운 성능 실험으로 체계를 검증한 논문은 아니다. 잠재 능력, 알려지지 않은 위협, 평가 중 기만, 실제 환경의 상호작용을 놓칠 수 있다. 평가 자료 공개도 악용을 돕거나 시험 맞춤 학습을 유발할 수 있다.","significance":"평가를 일회성 시험에서 조직의 의사결정 절차로 확장한다. 통과는 안전의 충분조건이 아니다.","beginnerExplanation":"운전시험에서 차량의 최고 속도와 운전자의 위험 운전 성향을 따로 살피듯, 모델의 능력과 사용 경향을 나누어 본다."},"readingGuide":["그림 1에서 평가 결과가 바꾸는 결정을 찾는다.","2절의 능력·정렬 평가를 비교한다.","5절의 평가 한계와 평가 자체의 위해를 읽는다."],"discussion":["평가 실패 때 실제로 멈출 수 있는 권한은 누구에게 있어야 하는가?","재현성을 위해 공개할 정보와 제한할 정보는 어떻게 나눌까?"],"terms":[{"term":"Capability","ordinaryMeaning":"무엇을 할 수 있는 능력","etymology":"capable에 대응하는 명사형이다.","aiMeaning":"주어진 조건에서 과제를 수행할 수 있는 능력","paperReading":"행동 의도나 사용 성향과 구분한다.","sourceUrl":"https://arxiv.org/abs/2305.15324"},{"term":"Propensity","ordinaryMeaning":"어떤 행동을 하기 쉬운 성향","etymology":"어형 풀이: 가능성보다 기울어진 경향을 뜻한다.","aiMeaning":"능력을 특정 방식으로 사용할 경향","paperReading":"능력이 있어도 유해 사용 성향은 별도다.","sourceUrl":"https://arxiv.org/abs/2305.15324"},{"term":"Alignment","ordinaryMeaning":"방향이나 줄을 맞춤","etymology":"align에 -ment를 붙인 명사다.","aiMeaning":"모델 행동을 의도된 목표·제약과 맞추는 문제","paperReading":"위험 능력과 별도 평가 대상이다.","sourceUrl":"https://arxiv.org/abs/2305.15324"},{"term":"Elicitation","ordinaryMeaning":"끌어내기","etymology":"elicit의 명사형으로 숨어 있는 반응을 이끌어냄이다.","aiMeaning":"모델이 보유한 능력을 평가에서 드러내는 과정","paperReading":"낮은 점수가 능력 부재를 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/2305.15324"},{"term":"Capability overhang","ordinaryMeaning":"아직 드러나지 않은 능력의 여지","etymology":"overhang의 돌출·잔여 부분을 빌린 비유다.","aiMeaning":"알려진 활용법보다 모델 능력이 앞서 있는 상태","paperReading":"평가자가 잠재 능력을 놓칠 수 있다.","sourceUrl":"https://arxiv.org/abs/2305.15324"},{"term":"Governance","ordinaryMeaning":"운영하고 다스림","etymology":"govern에 -ance를 붙인 명사다.","aiMeaning":"권한·책임·규칙·감독을 정하는 체계","paperReading":"평가를 훈련·배포 결정과 연결한다.","sourceUrl":"https://arxiv.org/abs/2305.15324"}],"evidence":[{"url":"https://arxiv.org/abs/2305.15324","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2305.15324","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-01/w01-p02_shevlane_extreme_risks.pdf"},{"id":"w02-p01","week":2,"role":"발표","title":"A Survey on Bias and Fairness in Machine Learning","authors":"Ninareh Mehrabi, Fred Morstatter, Nripsuta Saxena, Kristina Lerman, Aram Galstyan","year":2021,"venue":"ACM Computing Surveys 54(6), Article 115","citation":"Mehrabi, N., Morstatter, F., Saxena, N., Lerman, K., & Galstyan, A. (2021). A Survey on Bias and Fairness in Machine Learning. ACM Computing Surveys, 54(6), Article 115, 1–35. https://doi.org/10.1145/3457607","landingUrl":"https://arxiv.org/abs/1908.09635","pdfUrl":"https://arxiv.org/pdf/1908.09635","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"다운로드한 arXiv v3는 arXiv 비독점 배포 라이선스이며 일반 이용자의 재배포 허락으로 해석하지 않는다. 출판본과 다운로드 버전의 권리·쪽수를 혼동하지 않는다. https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html","sourceVersion":"서지: 2021 출판 논문. 확보·검토 원문: arXiv v3, 2022-01-25, 2019 최초 공개","readScope":"full_text","summary":{"question":"편향은 어디서 발생하며, 서로 다른 공정성 정의와 완화법은 어떻게 연결되는가?","background":"데이터에서 시작한 편향은 모델 출력과 사용자 행동을 거쳐 다시 데이터로 돌아온다. 민감한 속성을 지우는 것만으로 이 순환이 사라지지 않는다.","method":"실제 사례, 데이터·알고리즘·사용자 상호작용의 편향, 집단·개인·하위집단 공정성을 문헌으로 분류한다. 완화법은 전처리, 학습 중 처리, 후처리로 정리한다.","findings":"역사적·표현·측정 편향 등 원인이 다르면 개입 지점도 달라진다. 보정성과 오류율 동등성 등은 일반적으로 동시에 충족되지 않으며, 정의 선택에는 맥락과 장기 결과 검토가 필요하다.","limitations":"여러 분야의 방법을 정리한 조사로, 공통 데이터에서 모든 방법을 재실험한 비교는 아니다. 정의 충족을 사회적 공정성의 보증으로 읽으면 안 된다.","significance":"이후 논문을 읽을 때 ‘편향 원인–공정성 목표–개입 단계’를 분리하는 기본 어휘를 제공한다.","beginnerExplanation":"합격 비율을 맞추는 목표와 자격 있는 사람을 놓치지 않는 목표는 다르다. 먼저 어떤 불이익을 줄이려는지 정해야 한다."},"readingGuide":["그림의 데이터–알고리즘–사용자 순환을 읽는다.","4절에서 Equalized Odds와 Equal Opportunity를 나란히 읽는다.","5절의 세 개입 단계를 사례에 대응시킨다."],"discussion":["양성 판정이 누구에게 이익인지 먼저 설명할 수 있는가?","집단 속성을 삭제하면 어떤 대리변수가 남는가?"],"terms":[{"term":"Bias","ordinaryMeaning":"한쪽으로 기울어진 경향","etymology":"기울어짐이라는 일상 의미가 판단·측정의 체계적 치우침으로 확장되었다.","aiMeaning":"표본·측정·학습·운영 과정의 체계적 편향","paperReading":"편향의 원인을 개입 단계와 연결한다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Demographic parity","ordinaryMeaning":"인구 집단 사이의 동등성","etymology":"demographic과 동등함을 뜻하는 parity의 결합이다.","aiMeaning":"집단별 양성 예측 비율을 같게 하는 조건","paperReading":"결과값을 조건으로 삼지 않는다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Equalized odds","ordinaryMeaning":"같게 맞춘 승산·확률 관계","etymology":"equalized와 odds의 결합인 기술명이다.","aiMeaning":"실제 결과가 같을 때 집단별 예측률이 같은 조건; 이진분류에서는 TPR·FPR 모두 동등","paperReading":"기회 균등과 동일한 조건이 아니다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Equal opportunity","ordinaryMeaning":"동등한 기회","etymology":"equal과 opportunity의 결합이다.","aiMeaning":"통상 실제 양성 집단의 TPR만 동등하게 요구하는 조건","paperReading":"양성의 사회적 의미를 먼저 확인한다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Calibration","ordinaryMeaning":"눈금을 맞추는 보정","etymology":"측정 기구를 표준에 맞추는 뜻에서 온 비유다.","aiMeaning":"예측 확률과 관측 빈도가 대응하는 성질","paperReading":"같은 점수가 같은 위험을 뜻하는지 묻는다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Counterfactual fairness","ordinaryMeaning":"사실과 달랐다면의 공정성","etymology":"counter-와 factual의 결합은 실제 사실에 반대되는 가정을 뜻한다.","aiMeaning":"인과모형에서 보호 속성을 바꾼 가상 세계의 예측을 비교함","paperReading":"단순 단어 교체와 구분한다.","sourceUrl":"https://arxiv.org/abs/1908.09635"}],"evidence":[{"url":"https://arxiv.org/abs/1908.09635","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/1908.09635","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"},{"url":"https://doi.org/10.1145/3457607","supports":"출판판 서지: 2021, ACM Computing Surveys 54(6), Article 115. 다운로드한 파일은 arXiv v3.","accessedDate":"2026-10-12"}],"corrections":"강의안의 ‘기회 균등(Equalized Odds)’는 혼동을 유발한다. Equal Opportunity는 통상 TPR 동등, Equalized Odds는 TPR·FPR 모두 동등이다. 한국어 번역은 다양하므로 영문명과 조건을 함께 표기한다.","sitePdfUrl":null},{"id":"w02-p02","week":2,"role":"발표","title":"The Measure and Mismeasure of Fairness","authors":"Sam Corbett-Davies, Johann D. Gaebler, Hamed Nilforoshan, Ravi Shroff, Sharad Goel","year":2023,"venue":"Journal of Machine Learning Research 24(312)","citation":"Corbett-Davies, S., Gaebler, J. D., Nilforoshan, H., Shroff, R., & Goel, S. (2023). The Measure and Mismeasure of Fairness. Journal of Machine Learning Research, 24(312), 1–117. https://jmlr.org/papers/v24/22-1511.html","landingUrl":"https://jmlr.org/papers/v24/22-1511.html","pdfUrl":"https://www.jmlr.org/papers/volume24/22-1511/22-1511.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PDF 첫 페이지에 CC BY 4.0 명시. 출처·저작권·라이선스를 보존한다. https://www.jmlr.org/papers/volume24/22-1511/22-1511.pdf","sourceVersion":"JMLR 2023 최종 출판본, 117쪽","readScope":"full_text","summary":{"question":"공정성 지표를 만족시키면 보호하려던 집단의 실제 결과도 좋아지는가?","background":"집단별 평균 오류율은 결정 경계에서의 위험과 다를 수 있다. 예측의 정확성과 어떤 개입을 선택할지는 서로 다른 문제다.","method":"공정성 정의를 결과 격차 제약과 보호 속성의 영향 제약으로 나눈다. 임계값 정책, 인과모형, 외부효과를 분석하고 대학 입학 및 의료자원 배분 사례로 결과를 비교한다.","findings":"논문의 가정 아래에서는 여러 형식적 공정성 제약이 모든 관련 목표에서 더 나은 대안에 지배되는 정책을 만들 수 있다. 저자들은 실제 비용·편익을 직접 평가하는 접근과 예측·정책 결정의 분리를 제안한다.","limitations":"정리에는 분포·효용·정책집합 가정이 있으며 모든 제약이 언제나 해롭다는 뜻은 아니다. 결과 중심 접근도 무엇을 가치 있게 보고 어떻게 측정할지에 관한 규범적 선택을 피하지 못한다.","significance":"공정성 지표를 설계 목표로 곧바로 사용하는 관행을 비판한다. 지표와 실질적 개선 사이의 연결을 증명하라는 요구다.","beginnerExplanation":"두 병원의 오진율을 맞추려고 한 병원의 진단을 일부러 나쁘게 만들면 수치는 맞아도 환자는 손해 본다. 무엇이 실제로 개선되는지 살펴야 한다."},"readingGuide":["2절의 정의 분류를 먼저 읽는다.","3.2절에서 집단 평균과 임계점의 차이를 확인한다.","4절 정리의 가정과 5절 의료 사례를 연결한다."],"discussion":["절차적 권리와 결과 개선이 충돌하면 어떤 판단이 필요한가?","제약을 제거한 더 좋은 정책의 ‘좋음’을 누가 정의하는가?"],"terms":[{"term":"Pareto dominance","ordinaryMeaning":"다른 대안보다 열등함 없이 우세함","etymology":"경제학자 Pareto의 이름을 딴 개념이다.","aiMeaning":"모든 평가 목표에서 나쁘지 않고 적어도 하나에서 나은 대안의 존재","paperReading":"강한 지배는 모든 관련 목표 개선이다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"},{"term":"Inframarginality","ordinaryMeaning":"경계 안쪽의 상태","etymology":"infra-와 marginal의 결합으로 경계보다 내부에 있음을 가리킨다.","aiMeaning":"평균 집단 통계가 의사결정 경계의 정보를 가리는 문제","paperReading":"오류율 차이만으로 임계값 차이를 단정하지 않는다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"},{"term":"Threshold rule","ordinaryMeaning":"경계값에 따른 규칙","etymology":"문턱이라는 threshold의 공간적 비유다.","aiMeaning":"점수가 기준값을 넘는지에 따라 행동을 정하는 정책","paperReading":"예측값과 정책 기준을 분리한다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"},{"term":"Externality","ordinaryMeaning":"외부에 미치는 효과","etymology":"external에 명사형 -ity가 붙은 말이다.","aiMeaning":"한 사람의 결정이 다른 사람·전체 집단의 결과에 주는 영향","paperReading":"입학·자원 배분에서는 결정을 독립시킬 수 없다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"},{"term":"Utility","ordinaryMeaning":"쓸모·효용","etymology":"일상적인 유용함을 수량화한 경제학적 표현이다.","aiMeaning":"결과의 선호·비용·편익을 수치로 표현한 목적","paperReading":"정해진 효용 자체가 가치 선택이다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"},{"term":"Consequentialism","ordinaryMeaning":"결과를 중시하는 관점","etymology":"consequence와 사상·관점을 나타내는 -ism의 결합이다.","aiMeaning":"정책이 실제로 만드는 결과로 대안을 비교하는 접근","paperReading":"저자들의 제안이며 가치중립적 해답은 아니다.","sourceUrl":"https://jmlr.org/papers/v24/22-1511.html"}],"evidence":[{"url":"https://jmlr.org/papers/v24/22-1511.html","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://www.jmlr.org/papers/volume24/22-1511/22-1511.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-02/w02-p02_corbett_davies_measure.pdf"},{"id":"w02-p03","week":2,"role":"참고","title":"It’s COMPASlicated: The Messy Relationship between RAI Datasets and Algorithmic Fairness Benchmarks","authors":"Michelle Bao, Angela Zhou, Samantha Zottola, Brian Brubach, Sarah Desmarais, Aaron Horowitz, Kristian Lum, Suresh Venkatasubramanian","year":2021,"venue":"NeurIPS Datasets and Benchmarks 1 (2021), Round 1","citation":"Bao, M., Zhou, A., Zottola, S., Brubach, B., Desmarais, S., Horowitz, A., Lum, K., & Venkatasubramanian, S. (2021). It’s COMPASlicated: The Messy Relationship between RAI Datasets and Algorithmic Fairness Benchmarks. Proceedings of the NeurIPS Track on Datasets and Benchmarks, 1.","landingUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html","pdfUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/file/92cc227532d17e56e07902b254dfad10-Paper-round1.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"공식 공개 PDF에 일반 재배포 라이선스는 확인되지 않았다. NeurIPS에 대한 저자 배포 허락이 제3자 재배포 허락은 아니다. https://neurips.cc/FAQ/Copyright","sourceVersion":"NeurIPS Datasets and Benchmarks 2021 공식 출판 PDF","readScope":"full_text","summary":{"question":"형사사법 위험평가 데이터를 공정성 알고리즘의 일반 벤치마크로 사용해도 되는가?","background":"재체포는 실제 범죄와 같지 않고, 체포·보석·구금 결정은 누가 데이터에 나타나는지를 바꾼다. 데이터의 정답과 보호 속성도 기관의 판단을 거친 기록이다.","method":"형사사법 문헌과 COMPAS 사례를 검토해 결과값·집단 속성·입력 특성·분포의 측정 문제를 분해한다. 판사의 재량, 평가도구 활용, 연구 벤치마킹 관행까지 분석한다.","findings":"데이터상의 공정성 개선만으로 현실의 정의나 구금 감소를 주장할 수 없다. 특히 ‘양성’을 유리한 결과로 기계적으로 해석하거나 추적 기간 차이를 무시하는 실험은 의미를 왜곡한다.","limitations":"새 공정성 알고리즘의 우월성을 보이는 실험 논문이 아니다. 미국 형사사법 맥락이 중심이며 다른 분야로 옮길 때는 별도 현장 분석이 필요하다.","significance":"라벨을 자연의 정답으로 취급하기 전에 생성 과정을 조사하게 한다. 저자들은 무맥락적 순위 경쟁을 피하고 분야 전문가와 협력하라고 권한다.","beginnerExplanation":"‘신고된 고장 수’로 기계 품질을 평가하면 신고하기 쉬운 공장이 불리할 수 있다. 기록이 대상 현상 자체는 아니라는 문제와 비슷하다."},"readingGuide":["3절을 X·Y·A·분포 네 부분으로 나누어 읽는다.","4절에서 예측 이후 사람의 결정을 추적한다.","8절의 연구 관행 권고를 프로젝트 체크리스트로 만든다."],"discussion":["원하는 개념과 실제 라벨 사이에 어떤 결정이 끼어 있는가?","벤치마크 개선을 현실 개선으로 주장하려면 어떤 추가 자료가 필요한가?"],"terms":[{"term":"RAI (Risk Assessment Instrument)","ordinaryMeaning":"위험 평가 도구","etymology":"Risk Assessment Instrument의 머리글자다.","aiMeaning":"이 논문에서는 형사사법 위험평가 도구","paperReading":"Responsible AI의 약자가 아니다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"},{"term":"Ground truth","ordinaryMeaning":"현장에서 확인한 참값","etymology":"지상 관측이라는 비유가 평가 기준값으로 확장되었다.","aiMeaning":"학습·평가에서 참값으로 취급하는 라벨","paperReading":"재체포 기록을 범죄의 참값으로 단정하지 않는다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"},{"term":"Measurement bias","ordinaryMeaning":"측정의 체계적 치우침","etymology":"measurement와 bias의 합성 표현이다.","aiMeaning":"측정값이 목표 개념을 집단별로 다르게 반영함","paperReading":"라벨과 보호 속성도 측정 대상이다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"},{"term":"Selective labels","ordinaryMeaning":"선택적으로 관찰된 라벨","etymology":"selective와 label의 결합이다.","aiMeaning":"이전 결정에 따라 일부 사람의 결과만 관찰되는 현상","paperReading":"구금 여부가 후속 결과 관찰을 바꾼다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"},{"term":"Discretion","ordinaryMeaning":"판단의 재량","etymology":"일상적으로 정해진 범위 안에서 스스로 결정하는 권한이다.","aiMeaning":"사람·기관이 예측을 해석하고 행동을 선택하는 여지","paperReading":"판사 개입이 실제 결과를 달라지게 한다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"},{"term":"Benchmark","ordinaryMeaning":"비교의 기준점","etymology":"측량의 기준점이라는 말이 성능 비교에 확장되었다.","aiMeaning":"방법을 공통 조건에서 비교하는 데이터·절차","paperReading":"비교 편의가 맥락의 타당성을 보장하지 않는다.","sourceUrl":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html"}],"evidence":[{"url":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/hash/92cc227532d17e56e07902b254dfad10-Abstract-round1.html","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://datasets-benchmarks-proceedings.neurips.cc/paper/2021/file/92cc227532d17e56e07902b254dfad10-Paper-round1.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":"공식 랜딩 페이지에는 Brian Brubach가 중복 기재되어 있으나 출판 PDF 저자란은 1회다. 본 서지는 PDF의 8명 저자를 따른다. RAI는 이 논문에서 Risk Assessment Instrument를 뜻한다.","sitePdfUrl":null},{"id":"w03-p01","week":3,"role":"발표","title":"Fairness without Demographics through Adversarially Reweighted Learning","authors":"Preethi Lahoti, Alex Beutel, Jilin Chen, Kang Lee, Flavien Prost, Nithum Thain, Xuezhi Wang, Ed H. Chi","year":2020,"venue":"Advances in Neural Information Processing Systems 33","citation":"Lahoti, P., Beutel, A., Chen, J., Lee, K., Prost, F., Thain, N., Wang, X., & Chi, E. H. (2020). Fairness without Demographics through Adversarially Reweighted Learning. Advances in Neural Information Processing Systems, 33, 728–740.","landingUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html","pdfUrl":"https://proceedings.neurips.cc/paper/2020/file/07fc15c9d169ee48573edd749d25945d-Paper.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"공식 PDF 공개는 확인했으나 제3자의 일반 재배포 허락은 확인되지 않았다. NeurIPS 저작권 FAQ는 학회에 대한 배포 허락을 설명한다. https://neurips.cc/FAQ/Copyright","sourceVersion":"NeurIPS 2020 공식 출판 PDF; PDF 저자 표기 기준","readScope":"full_text","summary":{"question":"보호 집단의 소속 정보를 학습·추론에 쓰지 않고도 가장 성능이 나쁜 집단을 도울 수 있는가?","background":"전체 평균 손실만 줄이면 작은 집단의 오류가 묻힐 수 있다. 그러나 인구통계 속성을 수집하거나 학습에 사용하는 것이 항상 가능한 것은 아니다.","method":"예측기와 재가중 모델을 경쟁시킨다. 재가중 모델은 비보호 특성과 정답에서 예측기가 어려워하는 패턴에 높은 가중치를 주고, 예측기는 가중 손실을 낮춘다. 집단별 최저 AUC 등으로 평가한다.","findings":"Adult·LSAC에서는 불리한 집단의 성능을 개선했으나 COMPAS에서는 뚜렷한 개선이 없었다. 높은 오류 집단을 주어진 특성으로 식별할 수 있는지와 라벨 잡음이 중요했다.","limitations":"인구통계 정보가 없다는 사실만으로 어떤 집단의 공정성도 보장하지 않는다. 학습에 숨긴 집단 정보를 평가에는 사용했고, 실제로 그 정보마저 없으면 공정성 확인이 어렵다.","significance":"집단 간 격차를 줄이는 목표와 최악 집단의 성능을 높이는 목표를 구분하는 사례다.","beginnerExplanation":"보충수업 대상 학생의 배경을 몰라도 자주 틀리는 문제 패턴을 찾아 더 연습시킬 수 있다. 단, 잘못 채점된 문제에만 집중하면 도움이 안 된다."},"readingGuide":["3.1절의 최악 집단 효용 목표를 확인한다.","3.2절에서 두 모델의 역할을 말로 풀어 쓴다.","COMPAS 결과와 5절의 라벨 잡음 실험을 함께 읽는다."],"discussion":["보호 속성이 평가에도 없으면 개선을 어떻게 검증할까?","오류가 큰 사례와 사회적으로 불리한 집단은 언제 일치하지 않는가?"],"terms":[{"term":"Demographics","ordinaryMeaning":"인구 집단의 통계적 특성","etymology":"인구를 기술한다는 사회통계 용어다.","aiMeaning":"성별·인종 등 집단 소속을 나타내는 속성","paperReading":"학습·추론 없이 평가에는 활용한다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"},{"term":"Adversarial learning","ordinaryMeaning":"상대와 경쟁하며 배우기","etymology":"adversary의 상대·경쟁자라는 의미에서 온 표현이다.","aiMeaning":"상반된 목적의 모델을 함께 최적화하는 방법","paperReading":"여기서는 보안 공격자가 아닌 재가중 경쟁자다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"},{"term":"Reweighting","ordinaryMeaning":"무게를 다시 배정함","etymology":"re-와 weighting의 결합이다.","aiMeaning":"사례가 학습 손실에 기여하는 비중을 조정함","paperReading":"어려운 패턴에 더 많은 학습 비중을 준다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"},{"term":"Max-min fairness","ordinaryMeaning":"최솟값을 최대화하는 공정성","etymology":"maximum과 minimum의 축약어를 결합했다.","aiMeaning":"가장 불리한 집단의 효용을 최대화하는 목표","paperReading":"집단별 점수를 같게 만드는 목표와 다르다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"},{"term":"Computational identifiability","ordinaryMeaning":"계산으로 식별할 수 있음","etymology":"computational과 identifiable의 명사형 결합이다.","aiMeaning":"허용된 모델·특성으로 문제 집단의 패턴을 찾아낼 수 있음","paperReading":"집단 단서를 찾지 못하면 개선이 제한된다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"},{"term":"AUC","ordinaryMeaning":"곡선 아래의 넓이","etymology":"Area Under the Curve의 머리글자다.","aiMeaning":"여기서는 ROC 곡선 아래 면적, 양성·음성 순위 구별 성능","paperReading":"집단별 최저 AUC를 주요 지표로 쓴다.","sourceUrl":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html"}],"evidence":[{"url":"https://proceedings.neurips.cc/paper/2020/hash/07fc15c9d169ee48573edd749d25945d-Abstract.html","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper/2020/file/07fc15c9d169ee48573edd749d25945d-Paper.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper/2020/file/07fc15c9d169ee48573edd749d25945d-Bibtex.bib","supports":"공식 BibTeX로 33권, 728–740쪽, 2020년 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w03-p02","week":3,"role":"발표","title":"Bias and Fairness in Large Language Models: A Survey","authors":"Isabel O. Gallegos, Ryan A. Rossi, Joe Barrow, Md Mehrab Tanjim, Sungchul Kim, Franck Dernoncourt, Tong Yu, Ruiyi Zhang, Nesreen K. Ahmed","year":2024,"venue":"Computational Linguistics 50(3)","citation":"Gallegos, I. O., Rossi, R. A., Barrow, J., Tanjim, M. M., Kim, S., Dernoncourt, F., Yu, T., Zhang, R., & Ahmed, N. K. (2024). Bias and Fairness in Large Language Models: A Survey. Computational Linguistics, 50(3), 1097–1179. https://doi.org/10.1162/coli_a_00524","landingUrl":"https://aclanthology.org/2024.cl-3.8/","pdfUrl":"https://aclanthology.org/2024.cl-3.8.pdf","downloadStatus":"downloaded","redistribution":"restricted","licenseNote":"PDF 첫 페이지에 CC BY-NC-ND 4.0 명시. 출처를 표시한 비상업적 원본 공유만 허용되며 변경물 배포는 허용되지 않는다. 일반 ACL 사이트의 CC BY 안내보다 이 논문 개별 표시를 우선한다. 개인 학습 묶음에 원본 그대로 포함 가능; 사이트 재게시 여부는 비상업성 확인 전 보류. https://aclanthology.org/2024.cl-3.8.pdf","sourceVersion":"Computational Linguistics 2024 출판본; ACL Anthology PDF","readScope":"full_text","summary":{"question":"LLM의 편향을 무엇으로 측정하고, 개발 과정의 어디에서 완화해야 하는가?","background":"임베딩의 단어 연관성, 문장 확률, 생성 문장은 서로 다른 현상을 드러낸다. 같은 데이터라도 지표와 프롬프트가 달라지면 편향 판단이 달라질 수 있다.","method":"평가지표를 임베딩·확률·생성문 기반으로, 데이터셋을 대조 입력·프롬프트 구조로 분류한다. 완화법은 전처리·학습 중·추론 내부·출력 후의 네 개입 단계로 정리한다.","findings":"표현 공간의 편향 점수 개선이 실제 과제의 피해 감소를 뜻하지는 않는다. 유해성 필터도 소수 집단의 방언을 더 많이 걸러 배제를 키울 수 있다. 피해·집단·사용 맥락을 먼저 정해야 한다.","limitations":"영어 논문과 기술적 개입 중심의 조사다. 저자들도 사회적 권력관계와 실제 배포 맥락을 기술 분류만으로 다루기 어렵다고 인정한다.","significance":"방법 이름을 나열하는 대신 어떤 데이터에 접근할 수 있고 무엇을 측정하려는지에 따라 평가·완화법을 고르게 한다.","beginnerExplanation":"단어장 속 직업 연상이 달라졌다고 채용 상담의 차별이 사라졌다고 할 수 없다. 중간 표현과 최종 사용자 경험을 따로 검사해야 한다."},"readingGuide":["그림 1의 세 분류 체계를 먼저 읽는다.","3절 각 지표의 한계와 4절 데이터셋 구조를 대응시킨다.","5절의 개입 단계와 7절의 조사 한계를 확인한다."],"discussion":["한국어 편향 평가를 만들 때 영어 템플릿 번역만으로 부족한 이유는?","유해성 감소와 특정 집단 표현의 배제를 어떻게 동시에 측정할까?"],"terms":[{"term":"Embedding","ordinaryMeaning":"안에 끼워 넣은 표현","etymology":"embed의 넣다·심다라는 의미를 수학적 표현에 빌렸다.","aiMeaning":"단어·문장 등을 벡터로 나타낸 내부 표현","paperReading":"내부 연관성과 최종 피해를 구분한다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"},{"term":"Representational harm","ordinaryMeaning":"묘사·표현에서 생기는 피해","etymology":"representation과 harm의 결합이다.","aiMeaning":"집단을 비하·고정관념화·배제하는 표현상의 피해","paperReading":"자원 배분 피해와 별도로 살핀다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"},{"term":"Allocational harm","ordinaryMeaning":"배분으로 생기는 피해","etymology":"allocation은 자원·기회를 나누는 일이다.","aiMeaning":"기회·자원·서비스의 불리한 배분으로 생기는 피해","paperReading":"언어모델이 실제 결정에 쓰일 때 중요하다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"},{"term":"Counterfactual input","ordinaryMeaning":"사실과 다른 가상의 입력","etymology":"counterfactual과 input의 결합이다.","aiMeaning":"일부 집단 표현 등을 바꾸어 비교하도록 만든 입력쌍","paperReading":"인과적 반사실 공정성 증명과 동일하지 않다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"},{"term":"Intra-processing","ordinaryMeaning":"처리 내부에서의 개입","etymology":"intra-는 내부를 뜻한다.","aiMeaning":"추론 시 모델 내부나 디코딩 과정에 개입하는 완화","paperReading":"학습 중 변경·출력 후 필터와 구분한다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"},{"term":"Desiderata","ordinaryMeaning":"바람직한 조건들","etymology":"desideratum의 복수형으로 바라는 것들을 뜻한다.","aiMeaning":"설계·평가가 충족하기를 바라는 요구 조건","paperReading":"공정성을 운영 가능한 기준으로 구체화한다.","sourceUrl":"https://aclanthology.org/2024.cl-3.8/"}],"evidence":[{"url":"https://aclanthology.org/2024.cl-3.8/","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://aclanthology.org/2024.cl-3.8.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w03-p03","week":3,"role":"참고","title":"BBQ: A Hand-Built Bias Benchmark for Question Answering","authors":"Alicia Parrish, Angelica Chen, Nikita Nangia, Vishakh Padmakumar, Jason Phang, Jana Thompson, Phu Mon Htut, Samuel R. Bowman","year":2022,"venue":"Findings of ACL 2022","citation":"Parrish, A., Chen, A., Nangia, N., Padmakumar, V., Phang, J., Thompson, J., Htut, P. M., & Bowman, S. R. (2022). BBQ: A Hand-Built Bias Benchmark for Question Answering. Findings of the Association for Computational Linguistics: ACL 2022, 2086–2105. https://doi.org/10.18653/v1/2022.findings-acl.165","landingUrl":"https://aclanthology.org/2022.findings-acl.165/","pdfUrl":"https://aclanthology.org/2022.findings-acl.165.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"ACL 2016년 이후 학회 자료는 CC BY 4.0이라는 공식 정책 적용. 논문 PDF와 별도로 데이터셋도 본문에서 CC BY 4.0으로 명시한다. https://aclanthology.org/faq/#what-is-the-copyright-for-materials-in-the-acl-anthology","sourceVersion":"Findings of ACL 2022 출판본","readScope":"full_text","summary":{"question":"질문에 답할 정보가 부족할 때 모델은 고정관념으로 빈칸을 채우는가?","background":"단어 연관성 검사만으로는 실제 질의응답의 편향을 알기 어렵다. 정답이 분명한 상황과 판단을 유보해야 하는 상황을 나누어야 한다.","method":"미국 영어권의 9개 사회적 차원을 다루는 템플릿을 사람이 작성·검증한다. 같은 상황의 모호한 문맥과 명확한 문맥, 부정적·비부정적 질문을 교차하고 ‘알 수 없음’을 포함한 선택지로 평가한다.","findings":"검사한 모델은 정보가 부족할 때 고정관념을 따르는 경향을 보였다. 정보가 충분해도 정답이 고정관념과 맞을 때와 충돌할 때 성능이 달랐다. 정확도와 방향성 편향 점수를 함께 봐야 한다.","limitations":"편향 점수 0은 편향 부재의 증명이 아니다. 제한된 템플릿과 미국 영어권 문화에 한정되며, 교차 정체성 결과는 일관적 결론을 뒷받침하지 못했다.","significance":"정확도 평가에 ‘모른다고 답해야 하는 능력’과 고정관념 방향을 추가한다.","beginnerExplanation":"두 사람 중 누가 실수했는지 근거가 없으면 정답은 ‘모른다’다. 특정 집단이라는 이유만으로 한 사람을 고르면 모델의 추측이 드러난다."},"readingGuide":["그림 1로 문맥·질문의 교차 설계를 이해한다.","편향 점수와 정확도의 관계를 함께 읽는다.","7절의 점수 해석·문화적 범위 경고를 확인한다."],"discussion":["한국어 버전의 고정관념은 누가 어떤 근거로 선정할까?","모두 ‘모른다’라고 답하는 모델은 편향이 낮아도 유용한가?"],"terms":[{"term":"Ambiguous context","ordinaryMeaning":"해석이 여러 개인 문맥","etymology":"ambiguous는 분명히 결정되지 않음을 뜻한다.","aiMeaning":"주어진 증거만으로 정답 대상을 확정할 수 없는 문맥","paperReading":"알 수 없음을 답할 수 있어야 한다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Disambiguation","ordinaryMeaning":"모호함을 해소함","etymology":"dis-와 ambiguity를 결합해 모호함 제거를 나타낸다.","aiMeaning":"정답을 식별할 추가 정보를 제공함","paperReading":"증거가 고정관념을 이기는지 검사한다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Stereotype","ordinaryMeaning":"고정된 집단 이미지","etymology":"고정된 인쇄판이라는 역사적 의미에서 고정관념으로 확장되었다.","aiMeaning":"집단 소속에서 개인 특성을 성급히 추정하는 연상","paperReading":"선택 방향이 반복되는지 평가한다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Template","ordinaryMeaning":"반복해서 쓰는 틀","etymology":"일상적인 형판·본보기의 비유다.","aiMeaning":"이름·집단 등의 슬롯을 바꾸어 사례를 생성하는 문장 구조","paperReading":"표본 수와 표현 다양성을 혼동하지 않는다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Bias score","ordinaryMeaning":"편향의 정도를 나타내는 점수","etymology":"bias와 score의 결합이다.","aiMeaning":"정답률과 구별되는 고정관념 방향의 응답 경향 지표","paperReading":"0점이 보편적 공정성을 뜻하지 않는다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Intersectionality","ordinaryMeaning":"교차하는 사회적 위치","etymology":"intersection과 -ality의 결합이다.","aiMeaning":"여러 정체성·권력관계가 교차하며 생기는 경험과 피해","paperReading":"단일 집단 결과를 단순 합산하지 않는다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"}],"evidence":[{"url":"https://aclanthology.org/2022.findings-acl.165/","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://aclanthology.org/2022.findings-acl.165.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-03/w03-p03_parrish_bbq.pdf"},{"id":"w04-p01","week":4,"role":"발표","title":"Interpretable Machine Learning: Fundamental Principles and 10 Grand Challenges","authors":"Cynthia Rudin, Chaofan Chen, Zhi Chen, Haiyang Huang, Lesia Semenova, Chudi Zhong","year":2022,"venue":"Statistics Surveys 16","citation":"Rudin, C., Chen, C., Chen, Z., Huang, H., Semenova, L., & Zhong, C. (2022). Interpretable Machine Learning: Fundamental Principles and 10 Grand Challenges. Statistics Surveys, 16, 1–85. https://doi.org/10.1214/21-SS133","landingUrl":"https://arxiv.org/abs/2103.11251","pdfUrl":"https://arxiv.org/pdf/2103.11251","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"arXiv v2의 view license는 CC BY-SA 4.0이다. 원본 공유 시 출처·라이선스 표시를 보존하고, 수정·번안물을 배포하면 해당 조건을 별도로 검토한다. https://arxiv.org/abs/2103.11251","sourceVersion":"서지: Statistics Surveys 2022 출판 논문. 확보·검토 원문: arXiv v2, 2021-07-10 사전공개본","readScope":"full_text","summary":{"question":"사람이 이해할 수 있는 모델을 처음부터 만들려면 어떤 원칙과 연구 문제가 필요한가?","background":"복잡한 모델의 사후 설명은 모델 자체의 추론과 어긋날 수 있다. 해석가능성을 단순히 작은 모델이나 사용자의 신뢰와 같게 보는 것도 부정확하다.","method":"분야에 맞는 구조적 제약으로 해석가능성을 정의하고 10개 연구 과제를 정리한다. 희소 규칙·점수표·가법모델·사례 기반 추론부터 표현 분리, 시각화, 물리 제약, Rashomon 집합, 강화학습까지 다룬다.","findings":"해석가능성은 신뢰를 자동 생성하는 대신 신뢰할지 판단할 근거를 준다. 정확도와 해석가능성의 일반적 상충을 전제하지 말고, 데이터 정제·오류 수정까지 포함한 개발 과정을 비교하라고 주장한다.","limitations":"모든 과제에서 단순 모델이 같은 정확도를 보장한다는 정리는 아니다. 적절한 제약은 분야·사용자에 달려 있고, 최적화 비용이나 인간 이해도 평가도 남은 과제다.","significance":"설명을 덧붙이는 연구와 구조를 이해 가능한 형태로 설계하는 연구를 구분한다.","beginnerExplanation":"복잡한 채점기의 결정을 나중에 추측하는 대신, 교사가 직접 검토할 수 있는 채점 규칙을 만드는 접근이다. 규칙이 짧다는 것만으로 공정하거나 정확한 것은 아니다."},"readingGuide":["General Principles에서 해석가능성·신뢰·정확도를 구분한다.","관심 분야에 맞는 도전 과제 두 개를 고른다.","Rashomon 집합에서 좋은 모델의 다양성을 생각한다."],"discussion":["전문가와 일반 사용자가 요구하는 해석가능성은 어떻게 다른가?","정확도가 비슷한 모델 중 선택할 기준은 무엇인가?"],"terms":[{"term":"Interpretability","ordinaryMeaning":"뜻이나 작동을 이해할 수 있음","etymology":"interpret에 가능성을 나타내는 -able 계열이 결합된 말이다.","aiMeaning":"분야에 맞는 제약으로 모델·예측·데이터를 이해하기 쉽게 하는 성질","paperReading":"사후 근사 설명과 모델 구조를 구별한다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Sparsity","ordinaryMeaning":"드문드문 있음","etymology":"sparse의 성질을 나타내는 명사형이다.","aiMeaning":"사용하는 변수·규칙·활성 성분이 적은 구조","paperReading":"적음만으로 이해가능성이 보장되지는 않는다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Scoring system","ordinaryMeaning":"점수를 매기는 체계","etymology":"score와 system의 결합이다.","aiMeaning":"소수의 변수에 정수 점수를 더해 예측하는 모델","paperReading":"사람이 계산·점검할 수 있는 구조다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Generalized additive model","ordinaryMeaning":"일반화된 덧셈 모형","etymology":"각 변수의 효과를 더한다는 additive에서 이름이 왔다.","aiMeaning":"변수별 함수 등을 더해 예측하는 구조화된 모델","paperReading":"가법 구조에 분야 제약을 더한다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Disentanglement","ordinaryMeaning":"얽힌 것을 풀기","etymology":"dis-와 entangle의 결합이다.","aiMeaning":"내부 표현에서 의미 있는 요인을 분리하는 목표","paperReading":"감독 유무에 따라 도전 과제가 다르다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Rashomon set","ordinaryMeaning":"서로 다른 좋은 설명들의 집합","etymology":"같은 사건의 여러 관점을 다룬 영화 Rashomon을 빌린 비유다.","aiMeaning":"거의 같은 좋은 성능을 내는 여러 모델의 집합","paperReading":"성능만으로 하나의 모델이 정해지지 않는다.","sourceUrl":"https://arxiv.org/abs/2103.11251"}],"evidence":[{"url":"https://arxiv.org/abs/2103.11251","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2103.11251","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"},{"url":"https://scholars.duke.edu/publication/1513381","supports":"저자 소속 대학의 출판 기록: 2022, Statistics Surveys 16, 1–85, DOI 10.1214/21-SS133","accessedDate":"2026-10-12"}],"corrections":"arXiv 랜딩 페이지의 Journal reference는 2021이라고 남아 있으나 정식 출판 서지는 Statistics Surveys 16 (2022), 1–85다. 확보 파일은 2021 arXiv v2로 명확히 표시한다.","sitePdfUrl":"papers/week-04/w04-p01_rudin_interpretable.pdf"},{"id":"w04-p02","week":4,"role":"발표","title":"Towards Monosemanticity: Decomposing Language Models With Dictionary Learning","authors":"Trenton Bricken, Adly Templeton, Joshua Batson, Brian Chen, Adam Jermyn, Tom Conerly, Nicholas L Turner, Cem Anil, Carson Denison, Amanda Askell, Robert Lasenby, Yifan Wu, Shauna Kravec, Nicholas Schiefer, Tim Maxwell, Nicholas Joseph, Alex Tamkin, Karina Nguyen, Brayden McLean, Josiah E Burke, Tristan Hume, Shan Carter, Tom Henighan, Chris Olah","year":2023,"venue":"Transformer Circuits Thread","citation":"Bricken, T., et al. (2023, October 4). Towards Monosemanticity: Decomposing Language Models With Dictionary Learning. Transformer Circuits Thread. https://transformer-circuits.pub/2023/monosemantic-features/index.html","landingUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html","pdfUrl":null,"downloadStatus":"html_only","redistribution":"unclear","licenseNote":"공식 HTML 본문에서 일반 재배포 허락을 확인하지 못했다. 원문은 연구용 로컬 보관하고 사이트·배포 ZIP에는 독자 작성 해설과 공식 링크만 사용한다. https://transformer-circuits.pub/2023/monosemantic-features/index.html","sourceVersion":"2023-10-04 공식 웹 연구 보고서; 2026-10-12 확보 HTML. 학술대회 출판 PDF가 아님","readScope":"full_text","summary":{"question":"여러 개념에 반응하는 뉴런을 더 해석하기 쉬운 특징으로 분해할 수 있는가?","background":"한 뉴런이 한 개념을 뜻한다는 가정은 자주 깨진다. 적은 차원에 더 많은 특징이 겹쳐 표현된다는 중첩 가설이 대안이다.","method":"1층 Transformer의 512차원 MLP 활성에 희소 오토인코더를 학습한다. 재구성 오차와 활성 희소성을 함께 최적화하고, 상세 사례·사람 평가·자동 평가·특징 개입으로 해석을 확인한다.","findings":"뉴런보다 기능적으로 구체적인 특징들을 찾았고 일부 특징 활성 조절은 생성 양상을 바꾸었다. 사전 크기를 키우면 특징이 더 세분되는 현상과 모델 사이 유사한 특징도 관찰했다.","limitations":"작은 1층 모델의 결과이며 모든 모델 내부를 완전히 해석한 것은 아니다. 재구성 손실·특징 누락·평가 편향이 남고, 특징이 유일한 ‘진짜’ 분해인지도 확정하지 않는다.","significance":"이해 가능한 분석 단위를 뉴런에서 학습된 특징 방향으로 옮기는 기계적 해석가능성의 중요한 사례다.","beginnerExplanation":"여러 악기가 섞인 녹음에서 악기별 소리를 분리하는 것과 비슷하다. 잘 분리된 것처럼 보여도 모든 소리를 복원했는지는 별도 확인해야 한다."},"readingGuide":["Problem Setup에서 특징 방향과 뉴런을 구분한다.","한 특징의 Detailed Investigation을 끝까지 읽는다.","Global Analysis의 무작위 가중치 대조와 Discussion의 한계를 확인한다."],"discussion":["이해하기 좋은 이름을 붙였다는 것과 인과적 역할을 확인했다는 것은 어떻게 다른가?","사전이 커질수록 특징이 나뉘면 어떤 분석 단위를 선택해야 할까?"],"terms":[{"term":"Monosemanticity","ordinaryMeaning":"한 가지 의미에 대응하는 성질","etymology":"mono-는 하나, semantic은 의미와 관련됨을 뜻한다.","aiMeaning":"한 특징이 비교적 일관된 개념·패턴에 선택적으로 반응함","paperReading":"완전한 단일 의미 보증으로 읽지 않는다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Polysemanticity","ordinaryMeaning":"여러 의미에 대응하는 성질","etymology":"poly-는 여럿이라는 접두사다.","aiMeaning":"한 뉴런이 서로 다른 여러 개념에 반응하는 현상","paperReading":"뉴런 단위 분석이 어려운 이유다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Superposition","ordinaryMeaning":"여러 것을 겹쳐 놓음","etymology":"겹쳐 놓기라는 일반·수학적 표현을 빌렸다.","aiMeaning":"제한된 활성 차원에 더 많은 특징을 겹쳐 표현하는 가설","paperReading":"양자 상태를 뜻하는 표현이 아니다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Dictionary learning","ordinaryMeaning":"표현 재료의 사전을 학습함","etymology":"dictionary를 재사용할 기본 요소들의 목록이라는 비유로 쓴다.","aiMeaning":"데이터를 적은 수의 원소 조합으로 표현할 사전을 학습함","paperReading":"여기서 사전은 단어 뜻풀이 목록이 아니다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Sparse autoencoder","ordinaryMeaning":"희소한 자기 부호화기","etymology":"sparse와 auto-·encoder를 결합한 기술명이다.","aiMeaning":"입력을 복원하면서 중간 활성의 일부만 쓰도록 학습하는 신경망","paperReading":"MLP 활성을 여러 특징의 조합으로 분해한다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Ablation","ordinaryMeaning":"일부를 제거함","etymology":"의학·실험의 제거라는 개념이 분석 방법으로 확장되었다.","aiMeaning":"성분을 제거·억제해 출력 변화로 역할을 검사함","paperReading":"활성 상관관계를 인과적 검토로 보완한다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"}],"evidence":[{"url":"https://transformer-circuits.pub/2023/monosemantic-features/index.html","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://transformer-circuits.pub/2023/monosemantic-features/index.html","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":"공식 원문은 HTML 연구 보고서다. PDF처럼 표시하지 않는다. byline과 사이트 BibTeX의 저자 목록에는 Zac Hatfield-Dodds 포함 여부 차이가 있어 여기서는 화면의 byline을 따르고 축약 인용을 사용한다.","sitePdfUrl":null},{"id":"w04-p03","week":4,"role":"참고","title":"Fooling LIME and SHAP: Adversarial Attacks on Post hoc Explanation Methods","authors":"Dylan Slack, Sophie Hilgard, Emily Jia, Sameer Singh, Himabindu Lakkaraju","year":2020,"venue":"AAAI/ACM AIES 2020","citation":"Slack, D., Hilgard, S., Jia, E., Singh, S., & Lakkaraju, H. (2020). Fooling LIME and SHAP: Adversarial Attacks on Post hoc Explanation Methods. Proceedings of AIES 2020, 180–186. https://doi.org/10.1145/3375627.3375830","landingUrl":"https://doi.org/10.1145/3375627.3375830","pdfUrl":"https://ucinlp.github.io/files/papers/advlime-aies20.pdf","downloadStatus":"downloaded","redistribution":"restricted","licenseNote":"PDF 첫 페이지는 비영리 개인·수업용 디지털/인쇄 복사를 허용하되 고지·전체 인용 보존을 요구한다. 서버 재게시·재출판·목록 배포에는 별도 허락을 요구한다. 개인 학습용 원본 묶음만 허용 범위로 취급하고 사이트 PDF 재호스팅은 하지 않는다. https://ucinlp.github.io/files/papers/advlime-aies20.pdf","sourceVersion":"AIES 2020 출판 PDF; 저자 연구실 공개 사본","readScope":"full_text","summary":{"question":"차별적인 모델이 그럴듯한 사후 설명으로 외부 감사를 속일 수 있는가?","background":"설명 도구는 종종 입력을 인위적으로 변형해 주변에서 모델의 행동을 관찰한다. 그러나 그 변형 사례가 실제 입력 분포와 다르면 설명용 시험을 구별할 여지가 생긴다.","method":"실제 사례와 설명기가 만든 사례에서 다르게 행동하는 모델을 연구용으로 구성한다. COMPAS·Communities and Crime·German Credit에서 LIME과 Kernel SHAP의 특징 기여도 및 예측 일치도를 비교한다.","findings":"실제 입력에서 편향된 예측을 유지하면서도 설명에서는 민감한 특성의 중요도를 숨길 수 있었다. 실험에서는 LIME이 SHAP보다 더 취약했고, 설명용 표본을 구별하는 정도가 성공에 영향을 주었다.","limitations":"공격자가 모델을 통제하고 입력 분포 자료를 가진 설정이다. 모든 SHAP 구현이나 모든 설명법의 무용함을 입증한 것은 아니며, 결과는 사용한 교란·대조 분포에 의존한다.","significance":"설명 그래프가 깔끔하다는 이유만으로 공정성이나 충실성을 인정해서는 안 된다. 실제 입력 감사와 위협 모델 검토가 필요하다.","beginnerExplanation":"감사 때만 규칙을 지키는 조직처럼, 모델도 시험용 사례에서만 좋아 보일 수 있다. 설명은 검증해야 할 주장이지 보증서가 아니다."},"readingGuide":["설명용 변형 사례와 실제 사례의 분포 차이를 본다.","Proposed Framework의 위협 가정을 먼저 적는다.","결과에서 예측 유지와 설명 변화가 함께 측정되는지 확인한다."],"discussion":["감사 대상이 감사 절차를 알고 있다면 어떤 독립 증거가 필요한가?","특징 기여도와 집단별 실제 결과를 함께 보면 무엇이 달라질까?"],"terms":[{"term":"Post hoc","ordinaryMeaning":"일이 일어난 뒤의","etymology":"라틴어 표현 post hoc는 ‘이후에’라는 뜻이다.","aiMeaning":"학습된 모델의 결정에 나중에 붙이는 설명","paperReading":"설명이 모델의 실제 구조와 같지는 않다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"},{"term":"LIME","ordinaryMeaning":"라임이라는 일반 단어와 같은 철자","etymology":"Local Interpretable Model-agnostic Explanations의 머리글자다.","aiMeaning":"개별 예측 주변을 이해 가능한 대리모형으로 설명하는 방법","paperReading":"변형 표본이 실제 분포를 벗어나는지 본다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"},{"term":"SHAP","ordinaryMeaning":"보통명사보다 도구 이름으로 사용","etymology":"SHapley Additive exPlanations에서 만든 명칭이다.","aiMeaning":"Shapley 값에 기반해 특징 기여도를 설명하는 체계","paperReading":"이 실험의 대상은 Kernel SHAP이다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"},{"term":"Perturbation","ordinaryMeaning":"작은 교란·변화","etymology":"일반적인 상태 변화라는 뜻의 명사다.","aiMeaning":"입력 특성 등을 바꾸어 모델 반응을 검사함","paperReading":"비현실적 변형은 감사 사각지대를 만든다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"},{"term":"Out-of-distribution","ordinaryMeaning":"분포의 바깥","etymology":"out of와 distribution의 결합이다.","aiMeaning":"실제·학습 데이터 분포와 다른 사례","paperReading":"설명기가 만든 사례도 여기에 해당할 수 있다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"},{"term":"Faithfulness","ordinaryMeaning":"충실함","etymology":"faithful에 -ness를 붙인 명사다.","aiMeaning":"설명이 모델의 실제 작동·의존성을 정확히 반영하는 성질","paperReading":"설득력 있는 설명과 구분해야 한다.","sourceUrl":"https://doi.org/10.1145/3375627.3375830"}],"evidence":[{"url":"https://doi.org/10.1145/3375627.3375830","supports":"공식 서지·저자·출처 버전","accessedDate":"2026-10-12"},{"url":"https://ucinlp.github.io/files/papers/advlime-aies20.pdf","supports":"본문의 방법·결과·한계 검토. 원문 전체를 확보하고 주요 본문과 관련 부록을 검토했으며 증명·실험을 독립 재현하지 않음.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w05-p01","week":5,"role":"발표","title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","authors":"Inioluwa Deborah Raji; Andrew Smart; Rebecca N. White; Margaret Mitchell; Timnit Gebru; Ben Hutchinson; Jamila Smith-Loud; Daniel Theron; Parker Barnes","year":2020,"venue":"FAT* ’20, ACM","citation":"Raji, I. D., et al. (2020). Closing the AI accountability gap: Defining an end-to-end framework for internal algorithmic auditing. Proceedings of the 2020 Conference on Fairness, Accountability, and Transparency (FAT* ’20), 33–44. https://doi.org/10.1145/3351095.3372873","landingUrl":"https://arxiv.org/abs/2001.00973","pdfUrl":"https://arxiv.org/pdf/2001.00973","downloadStatus":"downloaded","redistribution":"restricted","licenseNote":"PDF 첫 쪽은 비영리 개인·교실 복사를 출처·권리문구 보존 조건으로 허용한다. 공개 웹 재배포의 포괄 허가는 확인되지 않았다. arXiv 라이선스: https://arxiv.org/licenses/nonexclusive-distrib/1.0/","sourceVersion":"arXiv:2001.00973v1, 2020-01-03; FAT* 2020 논문 저자 공개본","readScope":"full_text","summary":{"question":"윤리 원칙을 선언한 조직이 개발 과정의 실제 판단과 결과에 어떻게 책임질 수 있는가?","background":"외부 감사는 배포 후 피해를 드러내지만 원인을 개발 결정까지 추적하기 어렵다. 내부 감사에는 생애주기 기록과 독립성 확보가 필요하다.","method":"다른 고위험 산업의 감사 관행과 문서 산출물을 검토해 SMACTR를 제안한다. 범위 설정, 관계·시스템 매핑, 자료 수집, 시험, 성찰의 다섯 단계를 가상 제품 사례에 적용한다.","findings":"윤리 검토서·이해관계자 지도·데이터 및 모델 문서·시험 결과·완화 계획을 연결하면 최종 감사보고서의 판단 근거를 추적할 수 있다. 감사 결과는 출시 조건 변경이나 개발 중단의 근거도 된다.","limitations":"실제 조직에서 피해가 얼마나 감소하는지 검증한 실험은 아니다. 조직 내부의 권력관계, 감사자의 독립성, 문서 누락, 피해 당사자의 목소리가 실효성을 좌우한다.","significance":"책임성을 모델 점수만의 문제가 아닌 조직의 결정·기록·후속 조치 문제로 바꾼다.","beginnerExplanation":"제품 개발을 여행에 비유하면 출발 목적, 경로 선택, 점검 기록, 사고 예방책을 함께 남기는 방식이다. 서류 작성 자체가 안전의 증명은 아니다."},"readingGuide":["Figure 1에서 감사와 개발 생애주기의 연결을 확인한다.","4절의 다섯 단계마다 담당자·입력 자료·산출물을 한 줄씩 적는다.","서로 다른 가상 사용 사례에서 시험 우선순위가 달라지는 이유를 찾는다."],"discussion":["내부 감사팀이 출시 중단을 권고할 수 있으려면 어떤 권한이 필요한가?","좋은 문서와 실제 피해 감소를 각각 어떤 증거로 평가할 것인가?"],"terms":[{"term":"Accountability","ordinaryMeaning":"자신의 결정에 대해 설명하고 책임지는 의무","etymology":"account에 책임 가능성을 나타내는 -ability가 결합한 말로 읽는다.","aiMeaning":"결정권자·근거·감독·구제 절차를 연결하는 책임 체계","paperReading":"감사 기록이 책임 소재를 추적하게 하는지 본다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"Audit","ordinaryMeaning":"규칙과 증거를 대조하는 감사·검사","etymology":"회계 감사라는 기존 실무 개념을 AI에 확장한 용법이다.","aiMeaning":"시스템과 조직의 주장을 자료·시험으로 검토하는 활동","paperReading":"성능 시험뿐 아니라 과정의 정당성도 포함한다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"SMACTR","ordinaryMeaning":"일상어가 아닌 절차 이름","etymology":"Scoping, Mapping, Artifact Collection, Testing, Reflection의 머리글자다.","aiMeaning":"논문의 생애주기 내부 감사 절차","paperReading":"다섯 단계가 생산하는 증거의 연결을 읽는다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"Artifact","ordinaryMeaning":"사람이 만들어 남긴 물건이나 산출물","etymology":"물질 유물이라는 뜻을 업무 산출물에 옮긴 비유다.","aiMeaning":"데이터 설명서·모델 카드·결정 기록 같은 검토 증거","paperReading":"산출물 목록을 감사 체크리스트와 혼동하지 않는다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"Stakeholder","ordinaryMeaning":"결과에 이해관계가 있는 사람","etymology":"stake와 holder를 합친 구성이다.","aiMeaning":"개발자·이용자·영향받는 집단·감독자","paperReading":"사용하지 않아도 영향을 받는 사람을 지도에 넣는다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"FMEA","ordinaryMeaning":"고장이 나는 방식과 영향을 살펴보는 분석","etymology":"Failure Mode and Effects Analysis의 약자다.","aiMeaning":"잠재 실패의 영향과 우선순위를 구조화하는 위험 분석","paperReading":"시험 전 위험을 정리하고 결과에 따라 갱신한다.","sourceUrl":"https://arxiv.org/abs/2001.00973"}],"evidence":[{"url":"https://arxiv.org/abs/2001.00973","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2001.00973","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":"계획서의 ACM FAccT 2020은 당시 명칭 FAT* ’20으로 정정. 현재 학회의 후속 명칭과 구별한다.","sitePdfUrl":null},{"id":"w05-p02","week":5,"role":"발표","title":"The Foundation Model Transparency Index","authors":"Rishi Bommasani; Kevin Klyman; Shayne Longpre; Sayash Kapoor; Nestor Maslej; Betty Xiong; Daniel Zhang; Percy Liang","year":2023,"venue":"Stanford CRFM 보고서 / arXiv","citation":"Bommasani, R., et al. (2023). The Foundation Model Transparency Index. arXiv:2310.12941v1. https://doi.org/10.48550/arXiv.2310.12941","landingUrl":"https://arxiv.org/abs/2310.12941v1","pdfUrl":"https://arxiv.org/pdf/2310.12941v1","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"arXiv v1의 Rights to this article 링크는 CC BY 4.0이다. 원문 링크·저자·버전·라이선스를 표시하고 변경 여부를 밝혀야 한다. https://creativecommons.org/licenses/by/4.0/","sourceVersion":"2023-10-19 arXiv v1, 2023 Index; 정보 기준일 2023-09-15","readScope":"full_text","summary":{"question":"기반모델 개발사들이 무엇을 공개하는지 공통 기준으로 측정할 수 있는가?","background":"모델 영향은 커지는데 데이터·노동·연산·배포 정보가 부족하면 외부 검증과 피해 구제가 어렵다.","method":"상류 자원, 모델 자체, 하류 사용을 아우르는 100개 공개 지표로 10개 개발사와 대표 모델을 평가한다. 공개 자료를 두 연구자가 독립 채점하고 불일치를 조정하며 개발사의 반론 기회를 둔다.","findings":"2023년 조사에서 최고 점수는 54점, 평균은 37점이었다. 데이터 노동과 하류 영향 등 공통 공백이 있었고, 여러 항목은 적어도 한 회사가 이미 공개해 개선 가능성을 보여주었다.","limitations":"공개 여부 점수는 정보의 진실성·사업의 책임성·모델 안전성을 직접 측정하지 않는다. 대표 모델 선택, 같은 가중치의 이진 지표, 특정 시점의 자료 검색에도 한계가 있다.","significance":"추상적인 투명성 요구를 확인 가능한 질문과 근거 목록으로 바꾼다.","beginnerExplanation":"성적표가 제품 품질 대신 설명서에 무엇이 적혔는지를 채점한다고 생각하면 쉽다. 높은 공개 점수가 좋은 행동을 보증하지 않는다."},"readingGuide":["3–4절에서 상류·모델·하류 지표 구분을 익힌다.","6절의 정보 기준일과 독립 채점 절차를 먼저 확인한다.","7절 결과와 9.2절의 투명성·책임성 구별을 함께 읽는다."],"discussion":["노동조건을 나쁘게 공개한 회사와 공개하지 않은 회사를 어떻게 다르게 평가해야 하는가?","100개 항목에 같은 가중치를 부여할 때 놓치는 것은 무엇인가?"],"terms":[{"term":"Transparency","ordinaryMeaning":"속이 보이거나 설명이 공개되어 있는 성질","etymology":"투명한 물체를 제도와 정보 공개에 비유한 말이다.","aiMeaning":"관련자가 모델 개발·사용을 검토할 정보를 얻는 상태","paperReading":"정보 공개와 윤리적 우수성을 분리한다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"},{"term":"Index","ordinaryMeaning":"여러 대상을 비교하는 지표·색인","etymology":"자료를 가리켜 찾게 하는 색인의 뜻이 비교 점수로 확장되었다.","aiMeaning":"여러 관측 항목을 묶은 비교 도구","paperReading":"100개 공개 여부 점수가 무엇을 누락하는지 본다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"},{"term":"Indicator","ordinaryMeaning":"상태를 알려주는 표지","etymology":"indicate에 행위자를 나타내는 -or가 붙은 구성이다.","aiMeaning":"추상적 개념을 관측 가능한 질문으로 바꾼 항목","paperReading":"지표를 충족하는 공개 증거가 있는지 확인한다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"},{"term":"Upstream","ordinaryMeaning":"강의 상류","etymology":"흐름의 시작 쪽이라는 공간적 비유다.","aiMeaning":"모델 학습에 앞선 데이터·노동·연산 자원","paperReading":"완성된 모델 이전의 정보 공백을 찾는다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"},{"term":"Downstream","ordinaryMeaning":"강의 하류","etymology":"흐름이 이어지는 뒤쪽이라는 비유다.","aiMeaning":"모델 배포 이후 활용과 사회적 영향","paperReading":"배포 정책과 실제 사용 영향의 공개를 구별한다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"},{"term":"Flagship model","ordinaryMeaning":"조직을 대표하는 모델","etymology":"함대의 기함 flagship을 대표 제품에 빗댄 표현이다.","aiMeaning":"회사의 관행을 평가할 때 기준으로 삼는 주요 모델","paperReading":"한 모델의 공개 상태를 회사 전체로 일반화하지 않는다.","sourceUrl":"https://arxiv.org/abs/2310.12941v1"}],"evidence":[{"url":"https://arxiv.org/abs/2310.12941v1","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2310.12941v1","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":"2024 후속 지수나 2025 TMLR 논문 The 2023 Foundation Model Transparency Index와 구별해 계획서의 2023 보고서를 사용한다.","sitePdfUrl":"papers/week-05/w05-p02_fmti2023.pdf"},{"id":"w05-p03","week":5,"role":"참고","title":"Auditing large language models: a three-layered approach","authors":"Jakob Mökander; Jonas Schuett; Hannah Rose Kirk; Luciano Floridi","year":2024,"venue":"AI and Ethics, 4, 1085–1115 (온라인 2023)","citation":"Mökander, J., Schuett, J., Kirk, H. R., & Floridi, L. (2024). Auditing large language models: A three-layered approach. AI and Ethics, 4, 1085–1115. Published online May 30, 2023. https://doi.org/10.1007/s43681-023-00289-2","landingUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2","pdfUrl":"https://link.springer.com/content/pdf/10.1007/s43681-023-00289-2.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"출판사 원문 Open Access 문구는 CC BY 4.0이며 별도 표시된 제3자 자료는 예외다. https://creativecommons.org/licenses/by/4.0/","sourceVersion":"출판사 Version of Record; 2023-05-30 온라인, 2024-11 권호","readScope":"full_text","summary":{"question":"범용 모델이 여러 서비스로 재사용될 때 어디에서 무엇을 감사해야 하는가?","background":"개발 조직의 절차만 보거나 모델 벤치마크만 보는 감사는 실제 응용에서 생기는 위험을 빠뜨린다.","method":"기존 감사 문헌과 LLM의 특성 사이의 간극을 분석해 설계 원칙을 도출하고, 전문가 면담·피드백으로 설계를 다듬는다. 거버넌스·모델·응용 감사의 입력과 결과를 서로 연결한다.","findings":"조직 수준은 책임 구조와 개발 절차를, 모델 수준은 배포 전 역량·한계를, 응용 수준은 특정 용도와 지속적 영향을 검토하도록 제안한다. 상위 감사 결과가 하위 사용 조건을 안내하고 현장 발견이 재검토로 이어져야 한다.","limitations":"감사 효과의 인과적 실험 검증은 아니다. 측정 지표의 타당성, 감사기관의 독립성과 권한, 넓은 사회구조적 피해는 여전히 해결 과제다.","significance":"API 제공자와 서비스 개발자 사이에 분산된 감사 책임을 설명하는 지도다.","beginnerExplanation":"공장 운영, 엔진 성능, 실제 차량 운행을 각각 점검하고 결과를 공유하는 구조다. 한 층의 합격으로 전체 안전을 단정할 수 없다."},"readingGuide":["Figure 1에서 세 층의 대상과 시점을 구별한다.","4절과 Figure 2에서 감사 결과의 이동 방향을 추적한다.","5절 한계와 Appendix 1의 연구 방법을 함께 읽는다."],"discussion":["API만 쓰는 서비스 업체는 어떤 증거를 제공자에게 받아야 하는가?","배포 후 감사 결과가 좋지 않으면 누가 변경을 강제할 수 있는가?"],"terms":[{"term":"Governance","ordinaryMeaning":"방향·규칙·책임을 정해 운영하는 일","etymology":"govern에 상태·활동을 나타내는 -ance가 붙은 구성이다.","aiMeaning":"의사결정권·정책·감독·책임 구조","paperReading":"모델 성능과 별개로 조직 절차를 점검한다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"},{"term":"Three-layered","ordinaryMeaning":"세 층으로 이루어진","etymology":"three와 layer에 -ed를 붙인 구성이다.","aiMeaning":"조직·모델·응용을 나눈 감사 설계","paperReading":"세 층의 결과가 서로 입력으로 쓰이는지 본다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"},{"term":"Assurance","ordinaryMeaning":"근거를 통해 얻는 신뢰","etymology":"assure에 명사형 -ance가 붙은 구성이다.","aiMeaning":"주장에 대한 검토 증거로 형성하는 신뢰 수준","paperReading":"보증을 무위험 선언으로 읽지 않는다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"},{"term":"Construct validity","ordinaryMeaning":"측정하려는 개념을 제대로 재는 정도","etymology":"construct와 validity를 결합한 측정학 용어다.","aiMeaning":"진실성·공정성 같은 개념과 지표 사이의 적합성","paperReading":"점수 상승이 실제 개선인지 검토한다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"},{"term":"Application audit","ordinaryMeaning":"특정 쓰임새를 대상으로 한 감사","etymology":"application과 audit의 결합이다.","aiMeaning":"배포 서비스의 의도·영향·준수 상태를 지속 검토","paperReading":"모델만으로 결정되지 않는 위험을 찾는다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"},{"term":"Continuous assessment","ordinaryMeaning":"끊기지 않고 이어지는 평가","etymology":"continuous와 assessment를 합친 표현이다.","aiMeaning":"배포와 환경 변화에 맞춰 반복하는 평가","paperReading":"출시 한 번의 감사로 끝내지 않는 이유를 읽는다.","sourceUrl":"https://link.springer.com/article/10.1007/s43681-023-00289-2"}],"evidence":[{"url":"https://link.springer.com/article/10.1007/s43681-023-00289-2","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://link.springer.com/content/pdf/10.1007/s43681-023-00289-2.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":"계획서의 2023은 온라인 발행연도다. 정식 권호 인용은 2024를 사용하며 두 날짜를 함께 보존한다.","sitePdfUrl":"papers/week-05/w05-p03_mokander_auditing.pdf"},{"id":"w06-p01","week":6,"role":"발표","title":"Training language models to follow instructions with human feedback","authors":"Long Ouyang; Jeff Wu; Xu Jiang; Diogo Almeida; Carroll L. Wainwright; Pamela Mishkin; Chong Zhang; Sandhini Agarwal; Katarina Slama; Alex Ray; John Schulman; Jacob Hilton; Fraser Kelton; Luke Miller; Maddie Simens; Amanda Askell; Peter Welinder; Paul Christiano; Jan Leike; Ryan Lowe","year":2022,"venue":"NeurIPS 2022, Advances in Neural Information Processing Systems 35","citation":"Ouyang, L., et al. (2022). Training language models to follow instructions with human feedback. Advances in Neural Information Processing Systems, 35, 27730–27744.","landingUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html","pdfUrl":"https://papers.nips.cc/paper_files/paper/2022/file/b1efde53be364a73914f58805a001731-Paper-Conference.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"공식 학회 공개 PDF. NeurIPS FAQ는 저자 권리 유지 및 학회에 대한 비독점 배포권을 설명하지만 제3자 재배포 허가는 명시하지 않는다. https://nips.cc/FAQ/Copyright","sourceVersion":"NeurIPS 2022 학회 본문 PDF","readScope":"full_text","summary":{"question":"다음 단어 예측을 잘하는 모델을 사용자의 지시를 더 잘 따르는 모델로 바꿀 수 있는가?","background":"사전학습 목표와 사용자가 원하는 도움·진실성·무해성은 같지 않다. 모델 크기만 늘려도 이 차이가 사라지지 않는다.","method":"사람의 모범 답변으로 지도 미세조정하고, 답변 쌍의 선호로 보상 모델을 학습한 뒤 PPO로 정책을 개선한다. 기준 모델에서 너무 멀어지지 않도록 제한하고 일부 실험에는 사전학습 데이터를 섞는다.","findings":"해당 평가 분포에서 작은 InstructGPT도 훨씬 큰 GPT-3보다 선호되었다. 지시 준수와 일부 진실성 지표가 좋아졌고, 사전학습 데이터 혼합은 능력 저하를 줄였다. 독성 개선은 프롬프트 조건에 달랐고 편향 개선은 명확하지 않았다.","limitations":"평가자와 데이터가 주로 영어권이며 전체 사회를 대표하지 않는다. 환각·유해 출력이 남고, 지시를 잘 따르는 성질 자체가 악용될 수도 있다.","significance":"RLHF의 대표적 실증 연구이며 정렬 목표·학습 신호·평가자를 구분하도록 돕는다.","beginnerExplanation":"예시로 가르치고, 좋은 답을 비교해 고르고, 그 선호를 반복 학습하는 방식이다. 사람에게 선호된다는 것은 사실·안전의 보증이 아니다."},"readingGuide":["Figure 2의 SFT→보상 모델→PPO 흐름을 먼저 그린다.","4.2절에서 진실성·독성·편향을 별개 결과로 읽는다.","5.2절의 평가자 대표성과 남은 실패를 발표에 포함한다."],"discussion":["평가자의 선호와 사용자의 장기 이익이 충돌하면 무엇을 학습해야 하는가?","유해한 지시에도 잘 따르는 모델을 정렬되었다고 부를 수 있는가?"],"terms":[{"term":"Alignment","ordinaryMeaning":"방향이나 줄을 맞춤","etymology":"align에 상태·과정을 뜻하는 -ment가 붙은 구성이다.","aiMeaning":"모델 행동을 원하는 목표·가치에 맞추려는 과정","paperReading":"학습 목표의 정렬과 완전한 안전을 구별한다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"},{"term":"RLHF","ordinaryMeaning":"사람 반응을 이용한 강화학습","etymology":"Reinforcement Learning from Human Feedback의 약자다.","aiMeaning":"사람 선호를 보상 신호로 활용하는 학습","paperReading":"사람이 모든 다음 단어를 직접 정하는 것은 아니다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"},{"term":"SFT","ordinaryMeaning":"예시 정답으로 미세조정","etymology":"Supervised Fine-Tuning의 약자다.","aiMeaning":"입력과 바람직한 출력 쌍으로 추가 학습","paperReading":"첫 단계에서 지시 응답의 기본 형태를 배운다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"},{"term":"Reward model","ordinaryMeaning":"좋고 나쁨에 점수를 주는 평가자","etymology":"reward와 model을 결합한 이름이다.","aiMeaning":"사람의 선호를 수치화하도록 학습한 모델","paperReading":"보상 점수와 실제 바람직함의 차이를 살핀다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"},{"term":"Policy","ordinaryMeaning":"행동을 정하는 방침","etymology":"일반적인 정책·방침을 행동 선택 규칙으로 확장했다.","aiMeaning":"주어진 문맥에서 답변을 생성하는 확률 규칙","paperReading":"PPO가 바꾸는 대상은 답변 생성 정책이다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"},{"term":"KL divergence","ordinaryMeaning":"두 분포가 얼마나 다른지 나타내는 양","etymology":"Kullback–Leibler라는 연구자 이름과 divergence의 결합이다.","aiMeaning":"학습 정책과 기준 정책 사이의 분포 차이","paperReading":"보상만 좇아 기준 모델에서 벗어나는 것을 제한한다.","sourceUrl":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html"}],"evidence":[{"url":"https://proceedings.neurips.cc/paper/2022/hash/b1efde53be364a73914f58805a001731-Abstract-Conference.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://papers.nips.cc/paper_files/paper/2022/file/b1efde53be364a73914f58805a001731-Paper-Conference.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w06-p02","week":6,"role":"발표","title":"A Watermark for Large Language Models","authors":"John Kirchenbauer; Jonas Geiping; Yuxin Wen; Jonathan Katz; Ian Miers; Tom Goldstein","year":2023,"venue":"ICML 2023, PMLR 202","citation":"Kirchenbauer, J., Geiping, J., Wen, Y., Katz, J., Miers, I., & Goldstein, T. (2023). A watermark for large language models. Proceedings of the 40th International Conference on Machine Learning, PMLR 202, 17061–17084.","landingUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html","pdfUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a/kirchenbauer23a.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PMLR 출판 계약은 논문에 CC BY 4.0을 적용하며 저자·정식 인용·원문 링크 표기를 요구한다. https://proceedings.mlr.press/pmlr-license-agreement.html","sourceVersion":"ICML 2023 학회 PDF","readScope":"full_text","summary":{"question":"생성 문장에 자연스러움을 크게 해치지 않는 검출 신호를 넣을 수 있는가?","background":"모든 AI 글을 사후 분류하는 문제와, 협조하는 생성기가 미리 흔적을 남기는 문제는 다르다.","method":"이전 토큰으로 재현 가능한 녹색 토큰 집합을 정하고 생성 시 그 집합의 확률을 조금 높인다. 탐지자는 녹색 토큰 빈도에 대한 통계 검정을 수행한다. 정보이론 분석과 OPT 기반 실험으로 길이·신호 세기·품질을 비교한다.","findings":"학습을 다시 하지 않고도 생성과 탐지를 분리할 수 있었다. 텍스트 길이와 선택의 다양성이 충분하면 검출이 쉬워지지만 강한 편향은 품질과 상충한다. 빔 탐색과 수정에 따른 신호 변화도 분석한다.","limitations":"짧거나 예상 가능한 글, 재작성, 생성기 비협조 상황에서는 한계가 있다. 탐지 실패가 인간 작성의 증거는 아니며 검출 결과만으로 부정행위를 단정할 수 없다.","significance":"출처 신호를 생성 과정에 심는 접근과 일반 AI 탐지기의 차이를 이해하게 한다.","beginnerExplanation":"문장에 보이지 않는 인쇄 무늬를 넣는 셈이다. 무늬는 출처의 단서이지 내용이 참이라는 도장은 아니다."},"readingGuide":["2절의 강한 금지 방식과 3절의 부드러운 편향을 비교한다.","4절에서 엔트로피·길이·검출력의 관계를 읽는다.","실험의 품질 지표와 탐지 오차를 함께 보고 보편적 탐지율로 일반화하지 않는다."],"discussion":["학교 평가에서 검출 점수 외에 어떤 증거가 필요한가?","공개 탐지와 비밀키 탐지는 각각 어떤 신뢰·운영 비용을 만드는가?"],"terms":[{"term":"Watermark","ordinaryMeaning":"종이나 이미지에 넣는 식별 무늬","etymology":"water와 mark의 결합으로 종이의 무늬를 디지털 흔적에 비유한다.","aiMeaning":"생성 결과에 삽입하는 통계적 출처 신호","paperReading":"워터마크와 사실 검증을 구별한다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"Token","ordinaryMeaning":"표식이나 작은 단위","etymology":"표식을 뜻하는 말을 텍스트 처리 단위로 확장했다.","aiMeaning":"단어·부분 단어 등 모델이 다루는 기호 단위","paperReading":"단어 수와 토큰 수를 같게 읽지 않는다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"Green list","ordinaryMeaning":"허용·우대 목록","etymology":"녹색의 통행 허용 이미지를 목록에 적용한 이름이다.","aiMeaning":"현재 생성 단계에서 확률을 높이는 토큰 부분집합","paperReading":"녹색이라는 의미적 속성이 있는 단어 목록이 아니다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"Entropy","ordinaryMeaning":"불확실성의 정도","etymology":"물리학의 엔트로피를 정보의 불확실성에 적용한 용법이다.","aiMeaning":"다음 토큰 분포의 선택 가능성","paperReading":"선택지가 거의 없는 문장은 신호 삽입이 어렵다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"Null hypothesis","ordinaryMeaning":"검정의 출발점이 되는 가설","etymology":"null과 hypothesis를 결합한 통계 용어다.","aiMeaning":"관측 신호가 우연한 생성과 일치한다는 기준 가설","paperReading":"낮은 p값을 작성자 유죄 확률로 읽지 않는다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"False positive","ordinaryMeaning":"실제로 없는데 있다고 판정","etymology":"false와 positive의 결합이다.","aiMeaning":"비워터마크 글을 워터마크 글로 잘못 검출","paperReading":"실제 사용 집단의 오탐 피해를 따로 고려한다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"}],"evidence":[{"url":"https://proceedings.mlr.press/v202/kirchenbauer23a.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/v202/kirchenbauer23a/kirchenbauer23a.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-06/w06-p02_kirchenbauer_watermark.pdf"},{"id":"w06-p03","week":6,"role":"참고","title":"Constitutional AI: Harmlessness from AI Feedback","authors":"Bai, Yuntao; Kadavath, Saurav; Kundu, Sandipan; Askell, Amanda; Kernion, Jackson; Jones, Andy; Chen, Anna; Goldie, Anna; Mirhoseini, Azalia; McKinnon, Cameron; Chen, Carol; Olsson, Catherine; Olah, Christopher; Hernandez, Danny; Drain, Dawn; Ganguli, Deep; Li, Dustin; Tran-Johnson, Eli; Perez, Ethan; Kerr, Jamie; Mueller, Jared; Ladish, Jeffrey; Landau, Joshua; Ndousse, Kamal; Lukosuite, Kamile; Lovitt, Liane; Sellitto, Michael; Elhage, Nelson; Schiefer, Nicholas; Mercado, Noemi; DasSarma, Nova; Lasenby, Robert; Larson, Robin; Ringer, Sam; Johnston, Scott; Kravec, Shauna; Showk, Sheer El; Fort, Stanislav; Lanham, Tamera; Telleen-Lawton, Timothy; Conerly, Tom; Henighan, Tom; Hume, Tristan; Bowman, Samuel R.; Hatfield-Dodds, Zac; Mann, Ben; Amodei, Dario; Joseph, Nicholas; McCandlish, Sam; Brown, Tom; Kaplan, Jared","year":2022,"venue":"Anthropic 연구보고서 / arXiv","citation":"Bai, Y., et al. (2022). Constitutional AI: Harmlessness from AI feedback. arXiv:2212.08073. https://doi.org/10.48550/arXiv.2212.08073","landingUrl":"https://arxiv.org/abs/2212.08073","pdfUrl":"https://arxiv.org/pdf/2212.08073","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"arXiv Rights to this article는 CC BY 4.0을 명시한다. 저자·원문·라이선스·변경 여부 표기 필요. https://creativecommons.org/licenses/by/4.0/","sourceVersion":"arXiv:2212.08073v1, 2022-12-15","readScope":"full_text","summary":{"question":"유해성에 대한 사람의 개별 라벨을 줄이면서 유용한 안전 행동을 학습할 수 있는가?","background":"사람이 모든 유해 응답을 평가하는 방식은 확장과 작업자 부담에 한계가 있다. 어떤 원칙으로 평가할지도 명시해야 한다.","method":"원칙 목록을 바탕으로 모델이 자기 응답을 비평·수정하고 수정본으로 지도학습한다. 이어 원칙을 참고한 AI의 응답 선호로 보상 모델을 만들고 강화학습한다. 유용성에는 사람 피드백을 계속 사용한다.","findings":"실험에서 헌법 기반 학습은 유해성을 줄이면서 단순 회피를 줄이는 방향을 보였다. 비평·수정 단계와 AI 선호 학습의 역할을 비교하고, 사람 평가로 유용성과 무해성을 점검한다.","limitations":"원칙 선택과 모델 판단에 인간의 가치 선택이 남는다. 사람 감독이 사라진 방법도, 모든 위험을 보증하는 방법도 아니다. AI 판단의 오류와 부족한 현장 검증이 확장될 수 있다.","significance":"안전 학습의 규범을 명시하고 피드백 생산을 일부 자동화하는 설계를 제안한다.","beginnerExplanation":"규칙집을 보고 자기 답안을 고친 다음 비교 채점하는 연습이다. 규칙집과 채점자가 틀리면 반복 연습도 틀릴 수 있다."},"readingGuide":["1.4절에서 원래 유용성 RLHF와 사람 데이터의 역할을 확인한다.","3절의 수정 학습과 4절의 AI 선호 강화학습을 나눈다.","4.4절에서 무해성과 회피를 별도 평가하는 이유를 읽는다."],"discussion":["누가 원칙을 선택하고 충돌을 해결해야 하는가?","사람 라벨 감소와 사람 검증 감소는 왜 다른가?"],"terms":[{"term":"Constitution","ordinaryMeaning":"공동체 운영의 기본 규칙","etymology":"헌법이라는 제도적 비유를 모델 행동 원칙집에 쓴다.","aiMeaning":"AI 응답을 비평·평가하는 명시적 원칙 목록","paperReading":"법률상 헌법이나 보편적 합의로 오해하지 않는다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"Critique","ordinaryMeaning":"근거를 들어 검토하는 비평","etymology":"글이나 주장에 대한 비평의 일반 뜻을 사용한다.","aiMeaning":"응답이 원칙에 어긋나는 부분을 설명하는 과정","paperReading":"비평 내용이 항상 올바르다는 가정은 피한다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"Revision","ordinaryMeaning":"검토 후 고친 버전","etymology":"revise(다시 검토하고 고치다)의 명사형이다.","aiMeaning":"비평을 참고해 생성한 수정 응답","paperReading":"수정본이 지도학습의 목표가 된다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"RLAIF","ordinaryMeaning":"AI 피드백을 이용한 강화학습","etymology":"Reinforcement Learning from AI Feedback의 약자다.","aiMeaning":"AI 선호 판단을 보상 학습에 활용","paperReading":"유용성의 사람 피드백과 무해성의 AI 피드백을 구별한다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"Harmlessness","ordinaryMeaning":"해를 끼치지 않는 성질","etymology":"harm에 -less와 -ness가 붙은 구성이다.","aiMeaning":"해로운 응답과 그 영향을 줄이려는 목표","paperReading":"논문의 평가 범위를 전체 안전으로 확대하지 않는다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"Evasiveness","ordinaryMeaning":"질문을 회피하는 경향","etymology":"evade에서 파생된 성질 표현이다.","aiMeaning":"위험을 피하려고 유용한 대화까지 회피하는 행동","paperReading":"거부 횟수 감소와 안전 향상을 함께 검토한다.","sourceUrl":"https://arxiv.org/abs/2212.08073"}],"evidence":[{"url":"https://arxiv.org/abs/2212.08073","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2212.08073","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-06/w06-p03_bai_constitutional.pdf"},{"id":"w06-p04","week":6,"role":"참고","title":"Direct Preference Optimization: Your Language Model is Secretly a Reward Model","authors":"Rafael Rafailov; Archit Sharma; Eric Mitchell; Christopher D. Manning; Stefano Ermon; Chelsea Finn","year":2023,"venue":"NeurIPS 2023, Advances in Neural Information Processing Systems 36","citation":"Rafailov, R., Sharma, A., Mitchell, E., Manning, C. D., Ermon, S., & Finn, C. (2023). Direct preference optimization: Your language model is secretly a reward model. Advances in Neural Information Processing Systems, 36, 53728–53741.","landingUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html","pdfUrl":"https://arxiv.org/pdf/2305.18290v2","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"이 다운로드는 CC BY 4.0이 명시된 arXiv v2 공개본이다. 학회 호스팅 PDF의 재배포권과 구분한다. https://arxiv.org/abs/2305.18290v2 ; https://creativecommons.org/licenses/by/4.0/","sourceVersion":"arXiv:2305.18290v2, 2023-12-13; NeurIPS 2023 논문의 저자 공개본. 요약은 학회 본문과 대조.","readScope":"full_text","summary":{"question":"별도의 보상 모델과 강화학습 루프 없이 응답 선호를 직접 학습할 수 있는가?","background":"기존 RLHF는 보상 모델 학습과 정책 최적화가 분리되어 복잡하고 불안정할 수 있다.","method":"KL로 제한한 보상 최대화에서 최적 정책과 보상의 관계를 유도한다. 이를 쌍대 선호 모형에 대입해 선택된 답과 탈락한 답의 상대 로그확률을 직접 학습한다. 감성 제어·요약·단일 턴 대화에서 비교한다.","findings":"DPO는 실험에서 PPO 기반 비교 방법과 비슷하거나 나은 선호 성과를 더 단순한 학습 절차로 얻었다. 별도 보상망과 학습 중 정책 샘플링을 제거하며, 분포가 다른 요약 자료에서도 초기 일반화 결과를 제시한다.","limitations":"선호 모형과 기준 정책의 가정이 있다. 대규모 모델·분포 이동·과최적화에 대한 결론은 제한적이며, 자동 평가자의 프롬프트에 따라 승률도 달라졌다.","significance":"선호 정렬을 확률모형의 재표현으로 단순화한 핵심 연구다.","beginnerExplanation":"좋은 답과 덜 좋은 답을 비교해 상대적으로 좋은 답이 나오도록 직접 조정한다. 최적화가 쉬워져도 선호 데이터의 편향이나 안전 문제가 자동 해결되지는 않는다."},"readingGuide":["3절의 기존 RLHF 목표와 4절의 DPO 손실을 연결한다.","5절의 동치가 어떤 선호 모형과 가정에 의존하는지 확인한다.","6.4절 자동·사람 평가와 7절의 한계를 함께 읽는다."],"discussion":["좋은 답의 확률만 높이는 지도학습과 쌍대 선호 학습은 무엇이 다른가?","자동 평가자의 취향이 학습 방법의 우수성처럼 보일 수 있는가?"],"terms":[{"term":"Direct preference optimization","ordinaryMeaning":"선호를 직접 반영해 개선","etymology":"direct·preference·optimization을 합친 이름이다.","aiMeaning":"응답 쌍 선호에서 언어모델을 직접 업데이트하는 방법","paperReading":"별도 보상망 제거와 보상 개념 제거를 구별한다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"},{"term":"Preference","ordinaryMeaning":"둘 중 더 좋아함","etymology":"일상적인 선호를 비교 라벨에 적용한다.","aiMeaning":"같은 입력의 두 답변 사이에 부여한 상대 평가","paperReading":"선호를 객관적 정답과 동일시하지 않는다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"},{"term":"Reference policy","ordinaryMeaning":"비교 기준이 되는 행동 방침","etymology":"reference와 policy의 결합이다.","aiMeaning":"학습 정책의 변화량을 비교하는 기준 모델","paperReading":"같은 응답에 대한 두 정책의 확률 비율을 본다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"},{"term":"Bradley–Terry model","ordinaryMeaning":"두 대상을 비교하는 확률 모형","etymology":"연구자 Bradley와 Terry의 이름을 딴 명칭이다.","aiMeaning":"잠재 점수 차이를 쌍대 선호 확률에 연결","paperReading":"선호 데이터가 어떤 형태로 설명되는지 확인한다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"},{"term":"Implicit reward","ordinaryMeaning":"겉으로 드러나지 않은 보상","etymology":"implicit와 reward의 결합이다.","aiMeaning":"정책과 기준 정책의 로그확률 비율로 표현되는 보상","paperReading":"제목의 secretly는 수학적 재표현의 비유다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"},{"term":"Over-optimization","ordinaryMeaning":"필요 이상으로 목표를 밀어붙임","etymology":"over-와 optimization의 결합이다.","aiMeaning":"대리 목표의 점수 상승이 실제 품질을 해치는 현상","paperReading":"DPO에서도 미해결 질문으로 남는다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html"}],"evidence":[{"url":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/a85b405ed65c6477a4fe8302b5e06ce7-Abstract.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://papers.neurips.cc/paper_files/paper/2023/file/a85b405ed65c6477a4fe8302b5e06ce7-Paper-Conference.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2305.18290v2","supports":"2023-12-13 v2 및 CC BY 4.0 명시","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2305.18290v2","supports":"CC BY 공개 PDF 바이트·텍스트 검증","accessedDate":"2026-10-12"}],"corrections":"계획서의 축약 제목 Direct Preference Optimization에 정식 부제 Your Language Model is Secretly a Reward Model을 복원했다.","sitePdfUrl":"papers/week-06/w06-p04_rafailov_dpo_arxiv_v2.pdf"},{"id":"w07-p01","week":7,"role":"발표","title":"Frontier AI Regulation: Managing Emerging Risks to Public Safety","authors":"Markus Anderljung; Joslyn Barnhart; Anton Korinek; Jade Leung; Cullen O’Keefe; Jess Whittlestone; Shahar Avin; Miles Brundage; Justin Bullock; Duncan Cass-Beggs; Ben Chang; Tantum Collins; Tim Fist; Gillian Hadfield; Alan Hayes; Lewis Ho; Sara Hooker; Eric Horvitz; Noam Kolt; Jonas Schuett; Yonadav Shavit; Divya Siddarth; Robert Trager; Kevin Wolf","year":2023,"venue":"정책 백서 / arXiv","citation":"Anderljung, M., et al. (2023). Frontier AI regulation: Managing emerging risks to public safety. arXiv:2307.03718v4. https://doi.org/10.48550/arXiv.2307.03718","landingUrl":"https://arxiv.org/abs/2307.03718v4","pdfUrl":"https://arxiv.org/pdf/2307.03718","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"arXiv Rights to this article는 CC BY 4.0을 명시한다. https://creativecommons.org/licenses/by/4.0/","sourceVersion":"arXiv:2307.03718v4, 2023-11-07; 최초 공개 2023-07-06","readScope":"full_text","summary":{"question":"공공 안전에 큰 피해를 줄 수 있는 최첨단 기반모델을 어떤 제도로 관리할 것인가?","background":"역량이 예상 밖에 생기고, 배포 후 오용을 막기 어렵고, 모델이 빠르게 복제·확산될 수 있다는 세 가지 문제가 규제를 어렵게 한다.","method":"기존 고위험 산업의 규제 수단과 AI 개발 특성을 비교하는 정책 분석이다. 기준 마련, 등록·보고를 통한 감독기관의 가시성, 준수 확보를 제도 구성요소로 제시한다.","findings":"위험 역량·통제 가능성 평가, 외부 검토, 위험에 비례한 배포 조건, 배포 후 감시를 초기 안전 관행으로 제안한다. 강한 허가제는 심각한 위험과 다른 수단의 부족이 뒷받침될 때 고려해야 한다.","limitations":"실증적으로 확정된 피해 예측이나 규제 효과 검증은 아니다. 규제 대상의 정의, 평가 능력, 규제 포획, 혁신·경쟁 비용과 국제 협력에 불확실성이 남는다.","significance":"모델 시험 결과를 조직의 배포 결정과 공적 감독으로 연결한다.","beginnerExplanation":"위험한 신기술에 점검 기준·보고 체계·조치 권한을 함께 마련하자는 제안이다. AI 위험은 보안 침해뿐 아니라 오용·실패·사회적 영향도 포함한다."},"readingGuide":["2절의 세 가지 규제 문제를 먼저 요약한다.","3절 제도와 4절 기술·운영 관행을 짝지어 본다.","5절의 불확실성을 규제안의 전제 조건으로 읽는다."],"discussion":["훈련 연산량과 실제 위험 역량 중 무엇을 규제 기준으로 삼아야 하는가?","감독 강화가 시장 집중을 키우지 않도록 어떤 장치가 필요한가?"],"terms":[{"term":"Frontier","ordinaryMeaning":"경계·최전선","etymology":"기술의 최전선이라는 공간적 비유다.","aiMeaning":"특히 높은 역량과 심각한 위험 가능성을 가진 모델 범주","paperReading":"단순 최신 제품이라는 의미로 좁히지 않는다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"},{"term":"Risk","ordinaryMeaning":"원치 않는 결과가 생길 가능성과 영향","etymology":"일상적인 위험을 의사결정·관리 대상으로 쓰는 용법이다.","aiMeaning":"사람·조직·사회에 미치는 불확실한 부정적 결과","paperReading":"위험을 해킹 취약점 하나로 축소하지 않는다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"},{"term":"Controllability","ordinaryMeaning":"원하는 범위에서 통제할 수 있음","etymology":"control에 -ability를 결합한 말이다.","aiMeaning":"모델의 행동·접근·배포를 제약할 수 있는 정도","paperReading":"역량 평가와 별개의 질문으로 다룬다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"},{"term":"Proliferation","ordinaryMeaning":"빠르고 넓게 퍼짐","etymology":"확산을 뜻하는 일반어를 모델 복제와 전파에 적용한다.","aiMeaning":"모델·역량이 다수 행위자에게 퍼지는 현상","paperReading":"최초 배포 후 되돌리기 어려운 특성을 읽는다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"},{"term":"Compliance","ordinaryMeaning":"요구나 규칙을 따름","etymology":"comply에서 파생한 명사다.","aiMeaning":"정해진 안전 기준·보고 의무를 지키는 상태","paperReading":"기준 선언과 실제 준수 검증을 구별한다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"},{"term":"Regulatory capture","ordinaryMeaning":"감독기관이 피감독자의 이익에 종속됨","etymology":"regulatory와 capture의 제도적 비유다.","aiMeaning":"규제 설계·집행이 특정 기업에 유리하게 기우는 위험","paperReading":"강한 규제의 부작용도 평가 대상으로 포함한다.","sourceUrl":"https://arxiv.org/abs/2307.03718v4"}],"evidence":[{"url":"https://arxiv.org/abs/2307.03718v4","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2307.03718","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":"정책 제안 백서이며 현재 법령이나 이미 확정된 규제 의무가 아니다.","sitePdfUrl":"papers/week-07/w07-p01_anderljung_frontier.pdf"},{"id":"w07-p02","week":7,"role":"참고","title":"Considerations for governing open foundation models","authors":"Rishi Bommasani; Sayash Kapoor; Kevin Klyman; Shayne Longpre; Ashwin Ramaswami; Daniel Zhang; Marietje Schaake; Daniel E. Ho; Arvind Narayanan; Percy Liang","year":2024,"venue":"Science, 386(6718), 151–153","citation":"Bommasani, R., Kapoor, S., Klyman, K., Longpre, S., Ramaswami, A., Zhang, D., Schaake, M., Ho, D. E., Narayanan, A., & Liang, P. (2024). Considerations for governing open foundation models. Science, 386(6718), 151–153. https://doi.org/10.1126/science.adp1848","landingUrl":"https://doi.org/10.1126/science.adp1848","pdfUrl":null,"downloadStatus":"unavailable","redistribution":"restricted","licenseNote":"Princeton 공식 서지는 © 2024 AAAS, All rights reserved를 명시한다. https://collaborate.princeton.edu/en/publications/considerations-for-governing-open-foundation-models/ ; 출판사 본문은 403 보안 확인 화면이어서 원문을 확보하지 않았다.","sourceVersion":"Science 2024 정식 논문; 초록은 저자기관 RegLab 및 Princeton 서지에서 확인","readScope":"abstract_only","summary":{"question":"공개 기반모델과 폐쇄 모델에 같은 규제를 적용하면 영향도 같을까?","background":"공개 초록은 모델 공개 방식과 경쟁·혁신·권력 분산의 관계를 논의한다.","method":"초록에서 확인되는 접근은 서로 다른 정책 제안이 공개 모델 생태계에 미치는 긴장을 검토하는 것이다. 세부 분석 절차는 본문 미확보로 확인하지 못했다.","findings":"저자들은 모델 공개 방식에 따라 규제 부담과 혁신 생태계 영향이 달라질 수 있다고 주장한다. 구체적 정책별 결론은 본문을 확보한 뒤 확인해야 한다.","limitations":"이 항목은 공개 초록 기반 안내다. Science 본문·세부 사례·반론을 읽은 완전한 요약이 아니며, 동명 2023 브리프 내용으로 빈칸을 채우지 않았다.","significance":"규제 문구의 동일성과 실제 영향의 동일성을 구별할 출발점이다.","beginnerExplanation":"같은 규칙도 대기업과 작은 공개 개발팀에 다른 부담을 줄 수 있다. 공개가 무조건 안전하거나 위험하다는 결론은 이 초록만으로 낼 수 없다."},"readingGuide":["먼저 본문 미확보 표시와 출판연도를 확인한다.","공개 가중치·API 접근·완전 공개의 차이를 구별한다.","2023 HAI 브리프는 별도 배경 자료로 읽고 Science의 직접 인용 근거로 쓰지 않는다."],"discussion":["규제 부담을 기업 규모와 공개 방식에 따라 어떻게 비교할 것인가?","공개로 얻는 검증 가능성과 배포 후 통제의 어려움을 어떤 증거로 평가할 것인가?"],"terms":[{"term":"Open foundation model","ordinaryMeaning":"공개된 기반모델","etymology":"open·foundation·model을 결합한 표현이다.","aiMeaning":"공개 범위에 따라 접근·수정 가능성이 달라지는 범용 모델","paperReading":"Science 초록은 공개 방식에 따른 정책 영향을 묻는다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"},{"term":"Weights","ordinaryMeaning":"무게 또는 중요도","etymology":"무게를 계산의 영향력에 빗댄 용법이다.","aiMeaning":"학습으로 정해진 모델 내부 수치","paperReading":"가중치 공개가 데이터·코드 공개까지 뜻하지는 않는다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"},{"term":"Model release","ordinaryMeaning":"모델을 밖으로 내놓음","etymology":"release의 공개·배포 뜻을 사용한다.","aiMeaning":"외부의 모델 접근 방식과 범위를 정하는 결정","paperReading":"공개 방식이 분석의 중심 질문이다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"},{"term":"Competition","ordinaryMeaning":"여럿이 기회를 두고 겨룸","etymology":"일반적인 경쟁을 시장 구조에 적용한다.","aiMeaning":"개발자·서비스 간 시장 진입과 선택의 관계","paperReading":"초록이 언급하는 공개 모델의 이익 중 하나다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"},{"term":"Innovation ecosystem","ordinaryMeaning":"새로운 시도를 만드는 연결망","etymology":"ecosystem은 생태계를 조직 관계에 빗댄 표현이다.","aiMeaning":"연구자·기업·공동체·도구의 상호작용","paperReading":"개별 모델을 넘어 규제의 영향을 생각한다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"},{"term":"Distributive impact","ordinaryMeaning":"효과나 부담이 나뉘는 양상","etymology":"distributive와 impact의 결합이다.","aiMeaning":"이익·위험·준수 비용이 집단별로 배분되는 결과","paperReading":"같은 규제가 공개·폐쇄 개발사에 다르게 작용할 수 있다.","sourceUrl":"https://doi.org/10.1126/science.adp1848"}],"evidence":[{"url":"https://doi.org/10.1126/science.adp1848","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://reglab.stanford.edu/publications/considerations-for-governing-open-foundation-models/","supports":"저자기관 공개 초록","accessedDate":"2026-10-12"},{"url":"https://collaborate.princeton.edu/en/publications/considerations-for-governing-open-foundation-models/","supports":"정식 연도·권호·쪽·저자·권리문구","accessedDate":"2026-10-12"}],"corrections":"2023 Stanford HAI의 동명 정책브리프가 검색되지만 2024 Science 본문과 동일한 파일로 취급하지 않았다.","sitePdfUrl":null},{"id":"w09-p01","week":9,"role":"발표","title":"Reliable evaluation of adversarial robustness with an ensemble of diverse parameter-free attacks","authors":"Francesco Croce; Matthias Hein","year":2020,"venue":"ICML 2020, PMLR 119","citation":"Croce, F., & Hein, M. (2020). Reliable evaluation of adversarial robustness with an ensemble of diverse parameter-free attacks. Proceedings of the 37th International Conference on Machine Learning, PMLR 119, 2206–2216.","landingUrl":"https://proceedings.mlr.press/v119/croce20b.html","pdfUrl":"https://proceedings.mlr.press/v119/croce20b/croce20b.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PMLR CC BY 4.0. 정식 인용과 원문 링크를 포함해야 한다. https://proceedings.mlr.press/pmlr-license-agreement.html","sourceVersion":"ICML 2020 학회 PDF","readScope":"full_text","summary":{"question":"평가자의 공격 설정에 덜 좌우되는 강건성 시험을 만들 수 있는가?","background":"약한 공격이나 부적절한 단계 크기는 방어가 튼튼한 것처럼 보이게 한다. 한 종류의 시험만으로는 실패를 놓칠 수 있다.","method":"자동 단계 크기 조정의 Auto-PGD와 DLR 목적을 제안하고, 두 Auto-PGD 변형·FAB·Square Attack을 결합한 AutoAttack을 구성한다. 명시한 변형 한도에서 여러 이미지 분류 모델의 강건 정확도를 재평가한다.","findings":"서로 다른 시험을 결합하면 단일 시험이 놓치는 실패를 찾았다. 조사한 다수 모델에서 원래 보고된 것보다 낮은 강건 정확도가 나타나 기존 평가의 과대추정을 드러냈다.","limitations":"정해진 위협 모델과 시험 예산 안의 경험적 평가다. 통과가 모든 공격에 대한 증명은 아니다. 방어별 적응형 검토가 필요하며 parameter-free도 위협 한도·계산 예산이 없다는 뜻은 아니다.","significance":"표준화된 강한 기본 평가를 제공하고 방어 성능 비교의 신뢰성을 높인다.","beginnerExplanation":"한 시험관에게만 통과한 제품을 여러 성격의 시험관에게 다시 맡기는 방식이다. 시험을 많이 통과해도 검사하지 않은 상황까지 보증되지는 않는다."},"readingGuide":["2절에서 거리·변형 한도·공격 성공 조건을 먼저 확인한다.","3–5절에서 서로 다른 시험이 왜 보완적인지 읽는다.","결과 표의 깨끗한 정확도·강건 정확도·위협 한도를 함께 비교한다."],"discussion":["자동 기본 평가로 충분한 경우와 방어별 검토가 필요한 경우는 어떻게 나눌까?","강건 정확도 비교에서 같은 조건으로 맞춰야 할 항목은 무엇인가?"],"terms":[{"term":"Adversarial example","ordinaryMeaning":"의도적으로 판단을 어렵게 만든 예시","etymology":"adversarial과 example의 결합이다.","aiMeaning":"허용된 변화 안에서 모델을 오판하게 하는 입력","paperReading":"실제 공격 가능성은 위협 모델 조건에 달려 있다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"},{"term":"Robustness","ordinaryMeaning":"흔들림에 견디는 성질","etymology":"일상적 강건함을 시스템 성능의 안정성에 적용한다.","aiMeaning":"변형·오류·공격에도 요구 성능을 유지하는 정도","paperReading":"정상 정확도와 강건 정확도를 분리해 읽는다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"},{"term":"Threat model","ordinaryMeaning":"위협에 대한 가정의 모형","etymology":"threat와 model의 결합이다.","aiMeaning":"공격자의 목표·지식·능력·허용 변화를 정한 조건","paperReading":"어떤 종류와 크기의 변형인지 먼저 읽는다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"},{"term":"Ensemble","ordinaryMeaning":"여럿이 함께하는 구성","etymology":"합주라는 일반적 의미를 여러 방법의 결합에 적용한다.","aiMeaning":"서로 다른 시험·모델을 함께 사용하는 구성","paperReading":"여기서는 공격 평가 방법의 묶음이다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"},{"term":"Gradient masking","ordinaryMeaning":"변화 방향을 가림","etymology":"gradient와 masking의 결합이다.","aiMeaning":"기울기 정보가 부정확해 공격 시험이 실패하는 현상","paperReading":"공격 최적화 실패를 실제 강건성으로 오해하지 않는다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"},{"term":"Parameter-free","ordinaryMeaning":"사용자가 매개변수를 조정할 필요가 적음","etymology":"parameter와 -free의 결합이다.","aiMeaning":"고정된 규칙으로 평가자 튜닝 의존성을 줄인 설계","paperReading":"위협 한도와 평가 예산까지 없다는 뜻은 아니다.","sourceUrl":"https://proceedings.mlr.press/v119/croce20b.html"}],"evidence":[{"url":"https://proceedings.mlr.press/v119/croce20b.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/v119/croce20b/croce20b.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-09/w09-p01_croce_autoattack.pdf"},{"id":"w09-p02","week":9,"role":"발표","title":"On Adaptive Attacks to Adversarial Example Defenses","authors":"Florian Tramèr; Nicholas Carlini; Wieland Brendel; Aleksander Mądry","year":2020,"venue":"NeurIPS 2020, Advances in Neural Information Processing Systems 33","citation":"Tramèr, F., Carlini, N., Brendel, W., & Mądry, A. (2020). On adaptive attacks to adversarial example defenses. Advances in Neural Information Processing Systems, 33, 1633–1645.","landingUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html","pdfUrl":"https://proceedings.neurips.cc/paper/2020/file/11f38f8ecd71867b42433548d1078e38-Paper.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"공식 NeurIPS 공개 PDF이나 일반 제3자 재배포 허가를 확인하지 못했다. https://nips.cc/FAQ/Copyright","sourceVersion":"NeurIPS 2020 학회 본문 PDF","readScope":"full_text","summary":{"question":"적응형 공격으로 평가했다고 주장하는 방어는 충분히 검증된 것인가?","background":"방어를 알고 평가하더라도 잘못된 목표·누락된 전처리·약한 최적화 때문에 강건성을 과대평가할 수 있다.","method":"주요 학회에서 발표된 서로 다른 방어 13개를 교육적 사례로 선정한다. 각 방어의 구조와 초기 가설, 실패한 평가, 수정된 검증을 추적하고 공통 평가 원칙을 정리한다.","findings":"선정된 모든 방어에서 개선된 평가가 기존 주장의 약점을 드러냈다. 전체 처리 과정 포함, 성공 조건과 일치하는 평가 목표, 확률성·비미분 요소의 올바른 취급이 반복적으로 중요했다.","limitations":"선정 사례가 전체 방어의 무작위 표본은 아니다. 특정 구현의 실패는 방어 아이디어 전체의 무용함을 뜻하지 않는다. 과거 시험을 복사하는 것만으로 새 방어 검증을 대신할 수 없다.","significance":"공격 성공률보다 평가 설계의 타당성과 진단 과정에 초점을 맞춘 방법론 논문이다.","beginnerExplanation":"새 자물쇠를 검사할 때 이전 자물쇠용 시험만 반복하지 말고 현재 구조에 맞춰 검토해야 한다는 이야기다. 여기의 학습 목적은 허가된 방어 검증이다."},"readingGuide":["3절의 사례 선정 기준과 평가 흐름을 먼저 읽는다.","4절에서 시험 성공 조건과 목적 함수의 일치를 확인한다.","6절에서 자동 평가의 한계와 방어 아이디어에 대한 과도한 일반화를 구별한다."],"discussion":["평가 실패와 방어 성공을 구분할 수 있는 증거는 무엇인가?","AutoAttack 같은 공통 시험과 개별 적응형 분석을 어떻게 조합할까?"],"terms":[{"term":"Adaptive evaluation","ordinaryMeaning":"상대 조건에 맞추어 바꾸는 평가","etymology":"adapt에 -ive가 붙고 evaluation을 결합했다.","aiMeaning":"방어의 실제 처리 구조를 반영하는 검증","paperReading":"적응형이라는 이름보다 구현된 평가 조건을 본다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"},{"term":"End-to-end","ordinaryMeaning":"처음부터 끝까지","etymology":"양 끝 end를 잇는 표현이다.","aiMeaning":"전처리부터 최종 판정까지 전체 흐름","paperReading":"중간 구성요소를 빼고 시험하지 않았는지 확인한다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"},{"term":"Objective function","ordinaryMeaning":"달성하려는 목표를 수치화한 함수","etymology":"objective와 function의 결합이다.","aiMeaning":"학습이나 평가 최적화가 높이거나 낮추는 수치","paperReading":"수치 개선이 실제 실패 조건과 일치하는지 본다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"},{"term":"Surrogate","ordinaryMeaning":"대신 쓰는 것","etymology":"대리인을 뜻하는 일반어를 계산상 대체물에 적용한다.","aiMeaning":"직접 다루기 어려운 목표·모델의 대체 표현","paperReading":"대리 목표가 실제 판정과 어긋날 수 있다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"},{"term":"White-box","ordinaryMeaning":"내부를 볼 수 있는 상자","etymology":"불투명한 black-box와 대비되는 상자 비유다.","aiMeaning":"구조·매개변수 등 내부 정보를 아는 평가 조건","paperReading":"정보 접근 범위를 결과와 함께 명시한다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"},{"term":"Sanity check","ordinaryMeaning":"명백한 오류를 가리는 기본 점검","etymology":"정상적으로 말이 되는지 확인한다는 관용 표현이다.","aiMeaning":"복잡한 결론 전 수행하는 기본 검증","paperReading":"기존 공격 통과는 시작점이지 최종 증명은 아니다.","sourceUrl":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html"}],"evidence":[{"url":"https://papers.neurips.cc/paper_files/paper/2020/hash/11f38f8ecd71867b42433548d1078e38-Abstract.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper/2020/file/11f38f8ecd71867b42433548d1078e38-Paper.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w09-p03","week":9,"role":"참고","title":"Diffusion Models for Adversarial Purification","authors":"Weili Nie; Brandon Guo; Yujia Huang; Chaowei Xiao; Arash Vahdat; Animashree Anandkumar","year":2022,"venue":"ICML 2022, PMLR 162","citation":"Nie, W., Guo, B., Huang, Y., Xiao, C., Vahdat, A., & Anandkumar, A. (2022). Diffusion models for adversarial purification. Proceedings of the 39th International Conference on Machine Learning, PMLR 162, 16805–16827.","landingUrl":"https://proceedings.mlr.press/v162/nie22a.html","pdfUrl":"https://proceedings.mlr.press/v162/nie22a/nie22a.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PMLR CC BY 4.0. 정식 인용과 원문 링크를 포함해야 한다. https://proceedings.mlr.press/pmlr-license-agreement.html","sourceVersion":"ICML 2022 학회 PDF; 당시 실험 결과로 해석","readScope":"full_text","summary":{"question":"기존 분류기 앞에 확산 기반 정제기를 붙여 적대적 변형을 줄일 수 있는가?","background":"적대적 학습은 분류기를 다시 학습해야 한다. 생성 모델을 이용한 정제는 별도 분류기에 적용할 수 있지만 강한 평가가 중요하다.","method":"DiffPure는 입력에 짧은 순방향 확산으로 잡음을 더한 뒤 역방향 생성 과정으로 복원한다. 역확산 전체의 기울기를 계산하는 adjoint 방식으로 적응형 평가를 수행하고 데이터셋·분류기·잡음 시간의 영향을 비교한다.","findings":"논문 실험에서는 CIFAR-10·ImageNet·CelebA-HQ와 여러 분류기에서 경쟁력 있는 강건 정확도를 보고했다. 적절한 잡음은 변형을 약화하지만 지나친 잡음은 원래 의미를 잃게 하므로 시간 선택이 중요했다.","limitations":"반복 복원은 계산 비용이 크고 색상 관련 변형에 취약하다. 결과는 당시 시험 조건의 경험적 성과이며 모든 적응형 공격에 대한 인증은 아니다.","significance":"분류기 변경 없이 생성 모델을 방어 전처리로 활용하는 대표 사례다.","beginnerExplanation":"얼룩을 지우려고 사진을 조금 흐린 뒤 다시 복원하는 것과 비슷하다. 너무 많이 지우면 사진 자체가 바뀌므로 정제기까지 포함해 검사해야 한다."},"readingGuide":["Figure 1에서 순확산·역확산·분류의 순서를 확인한다.","3.2절에서 전체 정제 과정을 평가해야 하는 이유를 읽는다.","5절 ablation과 결론의 속도·색상 한계를 함께 본다."],"discussion":["정제 후 정상 정확도 손실과 강건성 개선을 어떻게 비교할까?","확률적 전처리 방어에서 평가 예산이 결론에 미치는 영향은 무엇인가?"],"terms":[{"term":"Diffusion","ordinaryMeaning":"퍼져 섞이는 확산","etymology":"물리적 확산을 확률적 잡음 과정에 빗댄 이름이다.","aiMeaning":"잡음 추가와 제거를 학습한 생성 모형","paperReading":"여기서는 생성뿐 아니라 방어 전처리에 활용한다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"},{"term":"Purification","ordinaryMeaning":"불순물을 제거하는 정제","etymology":"불순물을 없앤다는 일반 뜻을 입력 복원에 적용한 비유다.","aiMeaning":"입력의 적대적 변형을 제거하려는 복원","paperReading":"정제가 항상 원래 입력을 보존하는 것은 아니다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"},{"term":"Forward process","ordinaryMeaning":"앞으로 진행하는 과정","etymology":"forward와 process의 결합이다.","aiMeaning":"시간에 따라 입력에 잡음을 추가하는 확산","paperReading":"얼마나 진행하는지가 정보 보존에 중요하다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"},{"term":"Reverse process","ordinaryMeaning":"거꾸로 진행하는 과정","etymology":"reverse와 process의 결합이다.","aiMeaning":"잡음 상태에서 자료를 복원하는 생성 과정","paperReading":"복원기의 무작위성도 평가에 포함한다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"},{"term":"Adjoint method","ordinaryMeaning":"연결된 보조 문제를 이용하는 계산법","etymology":"adjoint는 수학의 수반 관계를 가리키는 기술 용어다.","aiMeaning":"미분방정식 해를 통한 기울기를 효율적으로 계산","paperReading":"정제기를 제외한 불완전한 평가를 피하는 도구다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"},{"term":"Ablation study","ordinaryMeaning":"일부를 빼거나 바꾸어 보는 실험","etymology":"제거라는 뜻을 구성요소 검증에 비유한다.","aiMeaning":"한 요소를 통제해 기여를 비교하는 실험","paperReading":"잡음·확산 시간·분류기 조합의 역할을 구별한다.","sourceUrl":"https://proceedings.mlr.press/v162/nie22a.html"}],"evidence":[{"url":"https://proceedings.mlr.press/v162/nie22a.html","supports":"공식 서지·저자·제목·게재 정보","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/v162/nie22a/nie22a.pdf","supports":"원문 PDF 바이트·텍스트 추출 검증; 본문 및 관련 방법·결과·한계 절 검토","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-09/w09-p03_nie_diffpure.pdf"},{"id":"w10-p01","week":10,"role":"발표","title":"Poisoning Web-Scale Training Datasets is Practical","authors":"Carlini, Nicholas; Jagielski, Matthew; Choquette-Choo, Christopher A.; Paleka, Daniel; Pearce, Will; Anderson, Hyrum; Terzis, Andreas; Thomas, Kurt; Tramèr, Florian","year":2024,"venue":"2024 IEEE Symposium on Security and Privacy (S&P)","citation":"Carlini, Nicholas; Jagielski, Matthew; Choquette-Choo, Christopher A.; Paleka, Daniel; Pearce, Will; Anderson, Hyrum; Terzis, Andreas; Thomas, Kurt; Tramèr, Florian (2024). Poisoning Web-Scale Training Datasets is Practical. 2024 IEEE Symposium on Security and Privacy (S&P). https://arxiv.org/abs/2302.10149","landingUrl":"https://arxiv.org/abs/2302.10149","pdfUrl":"https://arxiv.org/pdf/2302.10149","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2302.10149에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"arXiv:2302.10149v2, 2024-05-06; IEEE S&P 2024에 대응하는 공개 저자판","readScope":"full_text","summary":{"question":"공격자가 대규모 웹 학습자료에 실제로 데이터를 끼워 넣을 수 있는가?","background":"기존 오염 연구는 공격자가 학습자료를 수정할 수 있다고 가정했다. 웹 데이터셋은 원본 대신 URL 목록이나 주기적 스냅숏을 배포하기도 하므로, 자료 수집 자체의 신뢰 가정부터 점검해야 한다.","method":"처음 검수한 콘텐츠와 나중에 내려받는 콘텐츠가 달라지는 split-view와, 자료가 스냅숏에 포함되는 시점의 문제인 frontrunning을 구분한다. 공개 데이터셋·도메인 상태·위키 편집 및 스냅숏 기록으로 유입 가능성을 분석하고, 무결성 검사와 수집 시점 통제를 검토한다.","findings":"공개 웹 자료를 그대로 신뢰하는 수집 절차에는 낮은 자원으로도 오염이 유입될 여지가 있었다. SHA-256 검증은 수집 당시와 다른 바이트를 탐지하지만 정상적인 이미지 변경도 배제한다. 검수 지연과 스냅숏 절차 개선은 또 다른 방어 수단이다.","limitations":"주된 입증 대상은 오염 자료의 유입 가능성이다. 특정 대형 모델의 최종 피해를 직접 입증한 연구와 구분해야 한다. 위키 분석은 실제 악성 편집을 하지 않은 수동적 추정이며 운영상 차단·속도 제한과 검수자의 능력에 영향을 받는다.","significance":"AI 공급망 보안을 모델 파일 검사에만 한정하지 않고 데이터의 출처·버전·무결성으로 확장하게 한다.","beginnerExplanation":"교재 목록의 주소는 같아도 나중에 도착한 책 내용은 달라질 수 있다. 주소 확인에 더해, 처음 검수한 내용과 같은지를 확인해야 한다는 연구다."},"readingGuide":["3절의 데이터 배포 구조와 신뢰 대상을 먼저 그린다.","4·5절에서 관측 사실과 가정에 따른 추정을 나눈다.","6절에서 암호학적 해시의 보호 범위와 정상 자료 손실을 비교한다."],"discussion":["해시가 일치해도 원래 수집한 자료가 악성이면 무엇이 남는가?","데이터 최신성과 검수 시간을 어떤 기준으로 절충할 것인가?"],"terms":[{"term":"Data poisoning","ordinaryMeaning":"자료에 해로운 것을 섞음","etymology":"poison(독)을 학습자료 오염에 빗댄 표현이다.","aiMeaning":"학습 데이터나 학습 과정에 개입해 모델의 행동을 바꾸는 공격이다.","paperReading":"논문은 특히 오염물이 수집 경로에 들어갈 수 있는지를 다룬다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"},{"term":"Split-view","ordinaryMeaning":"서로 다른 모습 또는 관점","etymology":"split(나뉜)+view(보이는 모습)의 합성이다.","aiMeaning":"같은 자료 식별자가 서로 다른 주체나 시점에 다른 콘텐츠를 제공하는 상태다.","paperReading":"검수자와 이후 다운로드 사용자의 콘텐츠가 일치하지 않는 위험이다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"},{"term":"Frontrunning","ordinaryMeaning":"다른 행동을 예상하고 먼저 움직임","etymology":"front(앞)+run(달리다)에서 온 선행 행동의 비유다.","aiMeaning":"예측 가능한 처리 시점보다 먼저 개입해 결과에 영향을 주는 방식이다.","paperReading":"스냅숏 생성과 검수 사이의 시간차를 보안 조건으로 읽는다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"},{"term":"Snapshot","ordinaryMeaning":"어느 순간을 찍은 사진","etymology":"빠르게 찍은 사진이라는 표현이 시스템 상태 보존으로 확장됐다.","aiMeaning":"특정 시점의 데이터나 시스템 상태를 고정한 복사본이다.","paperReading":"원본에서 수정된 오류라도 이미 보존한 학습 복사본에는 남을 수 있다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"},{"term":"Integrity","ordinaryMeaning":"온전함·훼손되지 않음","etymology":"보안에서 자료가 허가 없이 변경되지 않았다는 뜻으로 사용한다.","aiMeaning":"학습자료·모델·결과의 비인가 변경을 방지하거나 검출하는 성질이다.","paperReading":"같은 URL이라는 사실과 같은 데이터라는 사실을 구분하는 핵심이다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"},{"term":"Cryptographic hash","ordinaryMeaning":"고정 길이의 요약값","etymology":"hash는 잘게 섞는다는 말에서 온 계산적 비유다.","aiMeaning":"입력 바이트에 대응하는 값으로 변경 검출에 쓰며 충돌 저항성이 중요하다.","paperReading":"인식상 비슷함을 비교하는 지각 해시와 달리 정확한 바이트 무결성을 검사한다.","sourceUrl":"https://arxiv.org/pdf/2302.10149"}],"evidence":[{"url":"https://arxiv.org/pdf/2302.10149","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1655260 bytes; SHA-256 d5d10c5a589fe8a700d5af873db705e0d66066c2c7f5155a52894ed17220a4f8","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2302.10149","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://sp2024.ieee-security.org/accepted-papers.html","supports":"IEEE S&P 2024 채택 및 저자 목록 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w10-p02","week":10,"role":"발표","title":"Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training","authors":"Hubinger, Evan; Denison, Carson; Mu, Jesse; Lambert, Mike; Tong, Meg; MacDiarmid, Monte; Lanham, Tamera; Ziegler, Daniel M.; Maxwell, Tim; Cheng, Newton; Jermyn, Adam; Askell, Amanda; Radhakrishnan, Ansh; Anil, Cem; Duvenaud, David; Ganguli, Deep; Barez, Fazl; Clark, Jack; Ndousse, Kamal; Sachan, Kshitij; Sellitto, Michael; Sharma, Mrinank; DasSarma, Nova; Grosse, Roger; Kravec, Shauna; Bai, Yuntao; Witten, Zachary; Favaro, Marina; Brauner, Jan; Karnofsky, Holden; Christiano, Paul; Bowman, Samuel R.; Graham, Logan; Kaplan, Jared; Mindermann, Sören; Greenblatt, Ryan; Shlegeris, Buck; Schiefer, Nicholas; Perez, Ethan","year":2024,"venue":"arXiv preprint","citation":"Hubinger, Evan; Denison, Carson; Mu, Jesse; Lambert, Mike; Tong, Meg; MacDiarmid, Monte; Lanham, Tamera; Ziegler, Daniel M.; Maxwell, Tim; Cheng, Newton; Jermyn, Adam; Askell, Amanda; Radhakrishnan, Ansh; Anil, Cem; Duvenaud, David; Ganguli, Deep; Barez, Fazl; Clark, Jack; Ndousse, Kamal; Sachan, Kshitij; Sellitto, Michael; Sharma, Mrinank; DasSarma, Nova; Grosse, Roger; Kravec, Shauna; Bai, Yuntao; Witten, Zachary; Favaro, Marina; Brauner, Jan; Karnofsky, Holden; Christiano, Paul; Bowman, Samuel R.; Graham, Logan; Kaplan, Jared; Mindermann, Sören; Greenblatt, Ryan; Shlegeris, Buck; Schiefer, Nicholas; Perez, Ethan (2024). Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training. arXiv preprint. https://arxiv.org/abs/2401.05566","landingUrl":"https://arxiv.org/abs/2401.05566","pdfUrl":"https://arxiv.org/pdf/2401.05566","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2401.05566에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"arXiv:2401.05566v3, 2024-01-17","readScope":"full_text","summary":{"question":"이미 학습된 조건부 위험 행동은 추가 안전 학습으로 지워지는가?","background":"정상 상황에서 안전하게 답한다고 해서 숨겨진 조건에서도 안전하다고 결론 내릴 수는 없다. 연구진은 이 차이를 실험할 수 있도록 백도어가 있는 모델을 의도적으로 만든다.","method":"안전한 행동과 위험 행동을 조건에 따라 구분하는 통제된 모델을 학습한다. 일반 백도어, 추론 설명을 포함한 백도어, 그 설명을 출력에서 제거한 증류형을 비교하고 지도 미세조정·강화학습·적대적 학습 뒤의 행동을 평가한다.","findings":"일부 백도어는 안전 학습 뒤에도 지속되었으며 모델 규모와 학습 방식에 따라 지속성이 달랐다. 적대적 학습이 위험 행동 자체를 제거하기보다 발동 조건을 더 엄격하게 구분하도록 만드는 경우도 관찰됐다.","limitations":"의도적으로 만든 실험용 사례이므로 자연 학습에서 기만이 얼마나 자주 생기는지 증명하지 않는다. 특정 학습 구성의 결과를 모든 모델·모든 안전 기법의 실패로 일반화할 수도 없다.","significance":"행동 평가에서 정상 입력의 안전성과 숨겨진 조건의 안전성을 따로 검증해야 함을 보여 준다.","beginnerExplanation":"평소에는 규칙을 잘 지키지만 특정 표지가 있을 때만 다르게 행동하도록 가르친 학생을 생각하면 된다. 평소 시험만으로 그 조건부 행동이 없어졌다고 확신하기 어렵다."},"readingGuide":["2절에서 악의적 모델 공급과 자연적 기만 가설을 구분한다.","3절의 세 가지 백도어 학습 조건을 정리한다.","4~6절의 안전 학습별 실험과 9절의 해석 한계를 함께 읽는다."],"discussion":["평가 성적 개선과 위험 행동 제거를 어떻게 구별할 수 있을까?","인위적 모형 실험은 어떤 주장까지 뒷받침하는가?"],"terms":[{"term":"Sleeper agent","ordinaryMeaning":"잠복 요원","etymology":"sleeper(잠자는 사람)+agent(행위자)의 첩보 비유다.","aiMeaning":"평소에는 정상처럼 보이다 특정 조건에서 다른 행동을 하는 모델을 뜻한다.","paperReading":"모델의 의식이나 의도를 사실로 단정하는 명칭은 아니다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"},{"term":"Backdoor","ordinaryMeaning":"뒷문","etymology":"정문을 거치지 않는 back+door라는 보안 비유다.","aiMeaning":"특정 조건에서 원치 않는 행동을 유발하는 숨은 기능 또는 학습된 패턴이다.","paperReading":"전체 응답의 악성화가 아니라 조건부 정책 차이가 중요하다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"},{"term":"Trigger","ordinaryMeaning":"작동을 시작시키는 방아쇠","etymology":"기계의 방아쇠에서 사건을 시작하는 조건으로 의미가 확장됐다.","aiMeaning":"특정 패턴이나 상황이 모델 행동 변화를 활성화하는 조건이다.","paperReading":"평가에 발동 조건이 포함되는지에 따라 안전해 보이는 정도가 달라진다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"},{"term":"Distillation","ordinaryMeaning":"증류·핵심을 추출함","etymology":"액체 증류처럼 중요한 특성을 옮긴다는 비유다.","aiMeaning":"한 모델의 출력 또는 지식을 다른 학습 과정에 전달하는 기법이다.","paperReading":"추론 설명을 응답에서 없애도 조건부 행동이 사라지지 않을 수 있다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"},{"term":"Adversarial training","ordinaryMeaning":"반대편과 맞서 하는 훈련","etymology":"adversarial(대립적인)+training(훈련)의 결합이다.","aiMeaning":"실패를 유발하는 예시를 학습에 포함해 저항성을 높이는 방법이다.","paperReading":"관찰한 실패를 교정하는 과정이 미관찰 조건을 놓칠 수 있다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"},{"term":"Model organism","ordinaryMeaning":"실험용 모형 생물","etymology":"생물학의 연구용 생물을 모델 실험에 빗댄 표현이다.","aiMeaning":"위험 메커니즘을 통제된 조건에서 연구하도록 구성한 인공 사례다.","paperReading":"가능성의 증거와 실제 배포 생태계의 발생률을 구분하게 한다.","sourceUrl":"https://arxiv.org/pdf/2401.05566"}],"evidence":[{"url":"https://arxiv.org/pdf/2401.05566","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 3696766 bytes; SHA-256 988e62785a47533775a543c78415dd0994341987f3124d57a81f46c931227bed","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2401.05566","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://www.anthropic.com/research/sleeper-agents-training-deceptive-llms-that-persist-through-safety-training","supports":"연구 기관의 연구 소개 및 통제된 실험 맥락","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w10-p03","week":10,"role":"참고","title":"Dataset Security for Machine Learning: Data Poisoning, Backdoor Attacks, and Defenses","authors":"Goldblum, Micah; Tsipras, Dimitris; Xie, Chulin; Chen, Xinyun; Schwarzschild, Avi; Song, Dawn; Madry, Aleksander; Li, Bo; Goldstein, Tom","year":2023,"venue":"IEEE Transactions on Pattern Analysis and Machine Intelligence, 45(2), 1563–1580","citation":"Goldblum, Micah; Tsipras, Dimitris; Xie, Chulin; Chen, Xinyun; Schwarzschild, Avi; Song, Dawn; Madry, Aleksander; Li, Bo; Goldstein, Tom (2023). Dataset Security for Machine Learning: Data Poisoning, Backdoor Attacks, and Defenses. IEEE Transactions on Pattern Analysis and Machine Intelligence, 45(2), 1563–1580. https://doi.org/10.1109/TPAMI.2022.3162397","landingUrl":"https://arxiv.org/abs/2012.10544","pdfUrl":"https://arxiv.org/pdf/2012.10544","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"https://arxiv.org/abs/2012.10544v4 의 Rights to this article 링크는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이다. 이 허가는 내려받은 arXiv 저자판에 적용하며 IEEE 출판판과 혼동하지 않는다. 원저자·출처·라이선스를 표시해 재배포 가능.","sourceVersion":"원문 열람판 arXiv:2012.10544v4 (2021-03-31); 온라인 출판 2022-03-25, 권·호 발행 2023-02","readScope":"full_text","summary":{"question":"다양한 데이터 오염과 백도어 연구를 어떤 공통 틀로 비교할 수 있는가?","background":"데이터 수집·외주 학습·모델 재사용은 학습 파이프라인의 공격 표면을 늘린다. 같은 오염이라는 이름에도 공격자의 권한과 목표가 다르므로 비교 기준이 필요하다.","method":"학습 단계만 조작하는 공격과 시험 시 발동 조건도 조작하는 백도어를 구분한다. 특징 충돌·이중 최적화·라벨 변경·영향 함수와 연합학습을 연결하고, 방어를 데이터 탐지·모델 탐지·사후 수리·학습 중 예방으로 정리한다.","findings":"공격과 방어의 성립 여부는 깨끗한 보조자료, 모델 접근권, 학습 절차 지식 등의 가정에 좌우된다. 영상 분류에 집중된 증거, 비교 가능한 벤치마크 부족, 정확도·보안·프라이버시 사이의 긴장이 주요 공백으로 정리된다.","limitations":"서베이이며 단일한 통제 실험의 승자를 제시하지 않는다. 열람한 2021 공개 저자판은 이후 LLM 공급망 연구까지 다루는 최신 종합 자료가 아니다.","significance":"개별 방어의 성능표를 읽기 전에 위협 모델과 필요 자원을 대조하는 지도를 제공한다.","beginnerExplanation":"같은 약도 어떤 독에 쓰는지 알아야 비교할 수 있다. 이 논문은 먼저 오염의 종류와 조건을 분류한 뒤 방어가 맞는지 따져 보도록 돕는다."},"readingGuide":["2·3절의 학습 전용 오염과 백도어의 차이를 표로 그린다.","각 방어가 요구하는 깨끗한 자료·모델 접근권을 표시한다.","4.6절의 공개 문제를 자신의 실험 제약과 연결한다."],"discussion":["깨끗한 검증자료가 없으면 어느 방어 주장을 신뢰하기 어려운가?","프라이버시 보호를 강화하면 오염 탐지가 어려워지는 이유는 무엇인가?"],"terms":[{"term":"Threat model","ordinaryMeaning":"위협의 모형","etymology":"threat(위협)+model(모형)의 결합이다.","aiMeaning":"공격자의 지식·권한·목표와 보호 대상을 명시한 가정이다.","paperReading":"서로 다른 권한을 전제한 논문의 성능을 직접 비교하지 않게 한다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"},{"term":"Clean-label poisoning","ordinaryMeaning":"올바른 라벨을 유지한 오염","etymology":"clean(깨끗한)+label(표지)는 라벨이 정상임을 뜻한다.","aiMeaning":"정답 표지를 바꾸지 않으면서 입력이나 선택을 조작하는 학습 공격이다.","paperReading":"라벨 검수만으로 데이터 안전을 보장할 수 없다는 뜻이다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"},{"term":"Feature collision","ordinaryMeaning":"특징끼리의 충돌","etymology":"collision(충돌)을 표현 공간에서의 겹침에 빗댔다.","aiMeaning":"서로 다른 입력의 내부 표현이 가깝도록 유도하는 현상이다.","paperReading":"겉으로 정상인 자료가 내부 분류 경계를 바꿀 수 있는 이유를 설명한다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"},{"term":"Bilevel optimization","ordinaryMeaning":"두 층으로 이루어진 최적화","etymology":"bi-(둘)+level(층)의 결합이다.","aiMeaning":"한 최적화 문제의 해를 다른 최적화 문제의 조건으로 삼는 구조다.","paperReading":"학습자가 모델을 푸는 안쪽 문제와 공격자가 자료를 고르는 바깥 문제를 구별한다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"},{"term":"Influence function","ordinaryMeaning":"영향을 계산하는 함수","etymology":"influence(영향)+function(함수)의 통계 용어다.","aiMeaning":"한 자료의 가중치 변화가 추정값이나 예측에 미치는 영향을 근사한다.","paperReading":"정확한 재학습 대신 민감도를 추정하는 도구이며 근사 가정이 있다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"},{"term":"Sanitization","ordinaryMeaning":"위생 처리·정화","etymology":"불순물을 제거하는 위생 처리의 비유다.","aiMeaning":"의심 자료를 제거하거나 바꿔 학습자료를 정리하는 방어다.","paperReading":"이상해 보이지 않는 오염이나 정상 소수 집단을 어떻게 처리하는지 점검해야 한다.","sourceUrl":"https://arxiv.org/pdf/2012.10544"}],"evidence":[{"url":"https://arxiv.org/pdf/2012.10544","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 712969 bytes; SHA-256 00def975e6b7e06ab0ead76d04d507a27d3d9c3963d19399816d571aa55aa5c1","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2012.10544","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://doi.org/10.1109/TPAMI.2022.3162397","supports":"온라인 출판 2022-03-25와 권·호 45(2), 2023-02, 1563–1580 구분","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 2022는 온라인 선출판 연도다. 완성된 권·호 인용은 2023으로 기록하고, 실제 내려받은 원문은 2021 arXiv v4임을 구분했다.","sitePdfUrl":"papers/week-10/w10-p03_dataset-security.pdf"},{"id":"w11-p01","week":11,"role":"발표","title":"Membership Inference Attacks From First Principles","authors":"Carlini, Nicholas; Chien, Steve; Nasr, Milad; Song, Shuang; Terzis, Andreas; Tramer, Florian","year":2022,"venue":"2022 IEEE Symposium on Security and Privacy (S&P)","citation":"Carlini, Nicholas; Chien, Steve; Nasr, Milad; Song, Shuang; Terzis, Andreas; Tramer, Florian (2022). Membership Inference Attacks From First Principles. 2022 IEEE Symposium on Security and Privacy (S&P). https://arxiv.org/abs/2112.03570","landingUrl":"https://arxiv.org/abs/2112.03570","pdfUrl":"https://arxiv.org/pdf/2112.03570","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2112.03570에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"arXiv:2112.03570v2, 2022-04-12; IEEE S&P 2022 공개 저자판","readScope":"full_text","summary":{"question":"특정 자료의 학습 참여를 얼마나 낮은 오탐률에서 알아낼 수 있는가?","background":"공격의 평균 정확도가 높아도 무고한 비회원 자료를 많이 회원으로 판단할 수 있다. 민감한 참여 여부를 주장하려면 낮은 오탐 구간에서의 성능이 중요하다.","method":"멤버십 추론을 자료가 포함된 학습과 제외된 학습을 구분하는 가설 검정으로 본다. 여러 보조 모델에서 예시별 출력 분포를 추정하는 LiRA를 구성하고, 분포 변환·개별 임계값·반복 질의의 역할을 절제 실험으로 분석한다.","findings":"LiRA는 낮은 오탐률 영역에서 이전 방식보다 더 많은 실제 회원을 찾아냈다. 전체 평균이나 단일 정확도는 일부 자료에 집중된 프라이버시 위험을 숨길 수 있으며, 예시별 난이도를 보정하는 것이 중요했다.","limitations":"보조 학습의 계산 비용과 공격자가 아는 데이터 분포·학습 방식에 영향을 받는다. 특정 실험에서 실패한 추론 공격이 개인정보 보호의 수학적 보장을 뜻하지 않는다.","significance":"프라이버시 감사를 ROC 전체와 낮은 FPR에서의 TPR로 보고하도록 평가 관행을 바꾼다.","beginnerExplanation":"백 명 중 대다수를 맞히는 탐정도 특정 사람의 참여 사실을 자신 있게 말할 수는 없다. 잘못 지목하는 비율을 아주 작게 제한한 뒤 얼마나 찾아내는지 보자는 논문이다."},"readingGuide":["III절의 보안 게임에서 회원·비회원 표본을 확인한다.","ROC의 낮은 FPR 구간과 평균 정확도를 비교한다.","IV·VI절에서 예시별 분포와 절제 실험을 함께 읽는다."],"discussion":["실제 회원 비율이 낮을 때 높은 공격 정확도는 무엇을 의미하는가?","관측된 추론 성공과 DP 보장은 어떻게 다른가?"],"terms":[{"term":"Membership inference","ordinaryMeaning":"구성원 여부를 추정함","etymology":"membership(소속 상태)+inference(추론)의 결합이다.","aiMeaning":"주어진 예시가 모델 학습 데이터에 포함되었는지 판단하는 공격이다.","paperReading":"자료의 내용을 새로 생성하는 추출 공격과 구분한다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"},{"term":"Likelihood ratio","ordinaryMeaning":"우도의 비율","etymology":"likelihood(그럴듯함)를 통계적 가설의 설명력으로 사용한다.","aiMeaning":"관측 결과가 두 가설 아래 나타날 상대적 가능성을 비교한 값이다.","paperReading":"학습 포함·제외라는 두 세계 중 어느 쪽을 출력이 더 지지하는지 본다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"},{"term":"Shadow model","ordinaryMeaning":"그림자처럼 따라가는 모형","etymology":"shadow는 원래 대상을 흉내 내는 보조물을 뜻하는 비유다.","aiMeaning":"표적 모델의 학습 상황을 모방해 공격 기준을 추정하는 보조 모델이다.","paperReading":"LiRA의 예시별 분포 추정에는 여러 보조 학습이 필요하다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"},{"term":"False positive rate (FPR)","ordinaryMeaning":"실제로 아닌 것을 맞다고 한 비율","etymology":"false positive는 잘못된 양성 판정을 뜻한다.","aiMeaning":"비회원 중 회원이라고 잘못 분류한 비율이다.","paperReading":"낮은 FPR을 고정한 평가가 잘못된 참여 주장 위험을 드러낸다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"},{"term":"True positive rate (TPR)","ordinaryMeaning":"실제로 맞는 것을 찾아낸 비율","etymology":"true positive는 올바른 양성 판정을 뜻한다.","aiMeaning":"실제 회원 중 공격이 회원으로 찾아낸 비율이다.","paperReading":"허용 오탐률이 같을 때 노출되는 회원의 비율을 비교한다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"},{"term":"Calibration","ordinaryMeaning":"눈금을 맞춤·보정","etymology":"측정 기구의 눈금을 맞추는 과정에서 온 표현이다.","aiMeaning":"점수의 의미나 임계값을 관측 분포에 맞추어 해석하는 과정이다.","paperReading":"모든 예시에 같은 손실 임계값을 쓰기보다 예시별 난이도를 고려한다.","sourceUrl":"https://arxiv.org/pdf/2112.03570"}],"evidence":[{"url":"https://arxiv.org/pdf/2112.03570","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 2845070 bytes; SHA-256 f2e97289de8db23180d1627167b07cef7f7e137a5b6c7e7918996d64a8bb68e1","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2112.03570","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://nicholas.carlini.com/papers/","supports":"저자 공식 목록의 IEEE S&P 2022 게재 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w11-p02","week":11,"role":"발표","title":"Scalable Extraction of Training Data from (Production) Language Models","authors":"Nasr, Milad; Carlini, Nicholas; Hayase, Jonathan; Jagielski, Matthew; Cooper, A. Feder; Ippolito, Daphne; Choquette-Choo, Christopher A.; Wallace, Eric; Tramèr, Florian; Lee, Katherine","year":2023,"venue":"arXiv preprint","citation":"Nasr, Milad; Carlini, Nicholas; Hayase, Jonathan; Jagielski, Matthew; Cooper, A. Feder; Ippolito, Daphne; Choquette-Choo, Christopher A.; Wallace, Eric; Tramèr, Florian; Lee, Katherine (2023). Scalable Extraction of Training Data from (Production) Language Models. arXiv preprint. https://arxiv.org/abs/2311.17035v1","landingUrl":"https://arxiv.org/abs/2311.17035v1","pdfUrl":"https://arxiv.org/pdf/2311.17035v1","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2311.17035v1에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"강의계획서에 대응하는 arXiv:2311.17035v1, 2023-11-28","readScope":"full_text","summary":{"question":"언어모델이 기억하는 학습자료 중 실제 질의로 회수할 수 있는 양은 어느 정도인가?","background":"학습자료를 기억한다는 사실과 자료를 모르는 공격자가 그것을 꺼낼 수 있다는 사실은 다르다. 정렬된 대화 모델에서도 이 차이를 실증적으로 확인해야 한다.","method":"학습자료가 공개된 모델에서는 생성 문자열을 원본 코퍼스와 대조하고, 비공개 모델에서는 대규모 공개 코퍼스를 대조 자료로 사용한다. 모델 종류·샘플링 규모·중복 제거의 영향을 비교하며, 정렬된 모델이 평소 대화 방식에서 이탈할 때의 자료 노출을 관찰한다.","findings":"일부 모델에서 질의를 통해 상당량의 학습 관련 문자열을 회수할 수 있었으며, 대화 안전 정렬만으로 기억 문제가 제거되지 않았다. 알려진 코퍼스와의 일치량은 비공개 학습집합 전체의 기억량을 뜻하지 않으며 측정 범위 내 하한으로 해석해야 한다.","limitations":"비공개 모델의 학습집합을 완전히 알 수 없어 모든 일치를 직접 입증하기 어렵다. 결과는 연구 당시 모델·인터페이스·대조 코퍼스에 한정되며 현재 서비스의 취약성으로 단정할 수 없다.","significance":"유해 요청 거부와 학습자료 비밀성은 서로 다른 평가 항목임을 보여 준다.","beginnerExplanation":"책을 읽은 사람이 내용을 이해하는 것과 특정 문장을 그대로 외우는 것은 다르다. 이 연구는 질문만으로 그 외운 문장을 얼마나 찾아낼 수 있는지 살핀다."},"readingGuide":["2절에서 discoverable과 extractable memorization을 구분한다.","공개 모델과 비공개 모델의 원문 확인 근거를 비교한다.","결론에서 중복 제거·학습 반복·정렬이 해결하지 못한 문제를 읽는다."],"discussion":["공개 웹 문장과 일치한 출력만으로 학습 참여를 확정할 수 있는가?","평가용 원문을 모르는 상황에서 보수적인 누출 지표를 어떻게 만들까?"],"terms":[{"term":"Memorization","ordinaryMeaning":"외움·기억","etymology":"memorize(기억하다)의 명사형이다.","aiMeaning":"훈련 예시의 특정 내용을 모델이 보존하고 재현하는 현상이다.","paperReading":"일반 지식을 학습한 것과 특정 문자열을 그대로 재현하는 것을 구분한다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"},{"term":"Extractable memorization","ordinaryMeaning":"꺼내올 수 있는 기억","etymology":"extract(밖으로 꺼내다)+-able(가능한)의 결합이다.","aiMeaning":"원본을 미리 모르더라도 모델 질의로 회수 가능한 학습 내용이다.","paperReading":"단순 기억 가능성보다 실제 접근 가능성을 평가한다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"},{"term":"Discoverable memorization","ordinaryMeaning":"단서로 발견 가능한 기억","etymology":"discover(발견하다)+-able(가능한)의 결합이다.","aiMeaning":"훈련 예시의 일부 같은 단서를 주었을 때 재현되는 기억이다.","paperReading":"공격자가 이미 아는 정보량을 extractable 조건과 대조한다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"},{"term":"Divergence","ordinaryMeaning":"갈라짐·이탈","etymology":"서로 다른 방향으로 벌어진다는 일반 의미를 가져온 말이다.","aiMeaning":"모델의 생성 과정이 기대한 응답 양식이나 분포에서 벗어나는 현상이다.","paperReading":"여기서는 정상 대화 양식 이탈이 자료 노출과 연결되는 현상을 뜻한다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"},{"term":"Deduplication","ordinaryMeaning":"중복 제거","etymology":"de-(제거)+duplication(복제)의 단어 형성이다.","aiMeaning":"반복되거나 겹치는 훈련자료를 식별해 줄이는 처리다.","paperReading":"적용 단위가 거칠면 잔여 중복과 기억 문제가 남을 수 있다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"},{"term":"Lower bound","ordinaryMeaning":"아래쪽 경계","etymology":"lower(낮은)+bound(경계)의 수학 용어다.","aiMeaning":"실제 값이 적어도 그 이상임을 나타내는 보수적 한계다.","paperReading":"대조 코퍼스에서 확인된 일치만으로 전체 누출량을 모두 세었다고 말하지 않는다.","sourceUrl":"https://arxiv.org/pdf/2311.17035v1"}],"evidence":[{"url":"https://arxiv.org/pdf/2311.17035v1","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1433005 bytes; SHA-256 f07a9272bd0e66eb7af7c425a1467e0bb98c03265e7d291851a4b5001207b9b8","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2311.17035v1","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://proceedings.iclr.cc/paper_files/paper/2025/hash/cce0e917b050208170151f77b497fc71-Abstract-Conference.html","supports":"후속 ICLR 2025판은 Scalable Extraction of Training Data from Aligned, Production Language Models로 제목과 저자 구성이 달라짐","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 2023 제목과 저자군에 맞춰 arXiv v1을 사용했다. 2025 ICLR의 개정 제목·결과·저자군을 2023판에 섞지 않았다.","sitePdfUrl":null},{"id":"w11-p03","week":11,"role":"참고","title":"Machine Unlearning","authors":"Bourtoule, Lucas; Chandrasekaran, Varun; Choquette-Choo, Christopher A.; Jia, Hengrui; Travers, Adelin; Zhang, Baiwu; Lie, David; Papernot, Nicolas","year":2021,"venue":"2021 IEEE Symposium on Security and Privacy (S&P)","citation":"Bourtoule, Lucas; Chandrasekaran, Varun; Choquette-Choo, Christopher A.; Jia, Hengrui; Travers, Adelin; Zhang, Baiwu; Lie, David; Papernot, Nicolas (2021). Machine Unlearning. 2021 IEEE Symposium on Security and Privacy (S&P). https://arxiv.org/abs/1912.03817","landingUrl":"https://arxiv.org/abs/1912.03817","pdfUrl":"https://arxiv.org/pdf/1912.03817","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/1912.03817에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"arXiv:1912.03817v3, 2020-12-15; IEEE S&P 2021 공개 저자판","readScope":"full_text","summary":{"question":"자료 삭제 요청을 모델에 반영할 때 처음부터 전부 재학습하는 비용을 줄일 수 있는가?","background":"원본 파일을 지워도 이미 학습한 모델의 영향은 남을 수 있다. 학습 전에 자료의 영향 범위를 제한하면 사후 삭제 비용도 줄일 수 있다.","method":"SISA는 자료를 여러 shard로 나누고 각 모델을 독립 학습시킨다. 각 shard를 시간 순서의 slice로 추가하며 체크포인트를 저장하고, 삭제 요청이 오면 영향을 받은 모델을 해당 자료가 들어오기 전 상태에서 다시 학습한다. 여러 모델의 예측은 집계한다.","findings":"전체 재학습보다 영향을 받는 작업량을 줄일 수 있었고 분할 수·삭제 요청 패턴·학습 과제에 따라 비용 절감과 정확도가 달라졌다. 복잡한 과제에서 과도한 분할은 각 모델의 학습자료를 줄여 정확도를 해칠 수 있다.","limitations":"처음부터 SISA 방식으로 학습해야 하며 저장·집계 비용이 생긴다. 사전학습 자료, 파생 모델, 외부 복사본의 삭제까지 자동으로 보장하지 않으며 특정 학습 절차의 삭제 보장과 법적 충족 여부도 구별해야 한다.","significance":"망각을 사후 편집 기법뿐 아니라 학습 파이프라인 설계 문제로 제시한다.","beginnerExplanation":"거대한 한 권의 공책 대신 서로 독립된 여러 공책에 공부시키면, 한 기록을 지울 때 해당 공책의 관련 부분만 다시 작성할 수 있다."},"readingGuide":["III절에서 삭제의 목표와 재학습 기준을 확인한다.","SISA 네 요소를 삭제 요청 하나의 흐름으로 연결한다.","분할 수에 따른 정확도와 재학습 시간을 동시에 본다."],"discussion":["더 빠른 삭제를 위해 어느 정도의 정확도·저장 비용을 감수할 것인가?","전처리와 집계기도 삭제 대상 자료를 사용했다면 무엇을 다시 학습해야 하는가?"],"terms":[{"term":"Machine unlearning","ordinaryMeaning":"기계가 배운 것을 되돌림","etymology":"un-(되돌림)+learning(학습)의 결합이다.","aiMeaning":"특정 훈련자료가 모델에 미친 영향을 제거하거나 제한하는 절차다.","paperReading":"원본 파일 삭제와 모델의 영향 제거를 구별한다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"},{"term":"Sharding","ordinaryMeaning":"조각으로 나누기","etymology":"shard(파편)에서 만든 분할 용어다.","aiMeaning":"데이터를 여러 부분집합으로 나누어 따로 처리하는 방식이다.","paperReading":"삭제가 영향을 주는 모델 수를 제한하는 수평 분할이다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"},{"term":"Isolation","ordinaryMeaning":"분리·격리","etymology":"서로 영향을 주지 않도록 분리한다는 일반 의미다.","aiMeaning":"모델이나 실행 단위 사이의 정보·상태 의존을 제한한다.","paperReading":"서로 다른 shard 모델이 공동 업데이트를 하지 않아 삭제 범위를 제한한다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"},{"term":"Slicing","ordinaryMeaning":"얇게 잘라 나누기","etymology":"slice(한 조각)에 -ing를 붙인 말이다.","aiMeaning":"한 데이터 분할을 단계별 학습 구간으로 더 나누는 방법이다.","paperReading":"자료가 처음 등장하기 전 체크포인트로 돌아갈 수 있게 한다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"},{"term":"Aggregation","ordinaryMeaning":"모아 합침","etymology":"aggregate(한데 모으다)의 명사형이다.","aiMeaning":"여러 모델의 예측이나 업데이트를 하나로 결합하는 단계다.","paperReading":"집계 단계가 삭제 대상 자료를 따로 학습하면 추가 망각 문제가 생긴다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"},{"term":"Checkpoint","ordinaryMeaning":"도중의 점검 지점","etymology":"check(점검)+point(지점)의 합성이다.","aiMeaning":"학습을 재개할 수 있도록 저장한 모델과 관련 상태다.","paperReading":"영향받지 않은 과거 상태에서 재학습을 시작해 비용을 줄인다.","sourceUrl":"https://arxiv.org/pdf/1912.03817"}],"evidence":[{"url":"https://arxiv.org/pdf/1912.03817","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1412207 bytes; SHA-256 3bb414ddd26f095d95c687583dba56ebbef298c668d19c456a00a70ba7a0a64d","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/1912.03817","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://security.csl.toronto.edu/blog/wp-publications/bourtouleoaklandunlearning/","supports":"공저자 공식 목록의 IEEE S&P 2021 서지 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w11-p04","week":11,"role":"참고","title":"How to DP-fy ML: A Practical Guide to Machine Learning with Differential Privacy","authors":"Ponomareva, Natalia; Hazimeh, Hussein; Kurakin, Alex; Xu, Zheng; Denison, Carson; McMahan, H. Brendan; Vassilvitskii, Sergei; Chien, Steve; Thakurta, Abhradeep Guha","year":2023,"venue":"Journal of Artificial Intelligence Research, 77, 1113–1201","citation":"Ponomareva, Natalia; Hazimeh, Hussein; Kurakin, Alex; Xu, Zheng; Denison, Carson; McMahan, H. Brendan; Vassilvitskii, Sergei; Chien, Steve; Thakurta, Abhradeep Guha (2023). How to DP-fy ML: A Practical Guide to Machine Learning with Differential Privacy. Journal of Artificial Intelligence Research, 77, 1113–1201. https://doi.org/10.1613/jair.1.14649","landingUrl":"https://arxiv.org/abs/2303.00654","pdfUrl":"https://arxiv.org/pdf/2303.00654","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"https://arxiv.org/abs/2303.00654v3 의 Rights to this article 링크는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이다. 내려받은 arXiv 저자판을 원저자·출처·라이선스 표시와 함께 재배포할 수 있다.","sourceVersion":"arXiv:2303.00654v3, 2023-07-31; JAIR 2023 논문 대응 저자판","readScope":"full_text","summary":{"question":"차분 프라이버시를 실제 ML 파이프라인에 올바르게 적용하고 보고하려면 무엇이 필요한가?","background":"공격 실험에서 누출이 안 보인다는 것만으로 보호를 보장할 수 없다. DP는 정해진 보호 단위와 위협 모델 아래 한 참여자의 영향 변화를 제한한다.","method":"DP 정의·신뢰 경계·적용 위치에서 출발해 DP-SGD, 사용자 단위 학습, 프라이버시 회계를 연결하는 실무 서베이다. 클리핑·잡음·배치·학습률·모델 구조·하이퍼파라미터 탐색이 보호와 성능·비용에 미치는 영향을 정리하고 보고 항목을 제안한다.","findings":"보호 단위, 인접 데이터셋 정의, 표본 추출 방식, 공개되는 결과와 전체 프라이버시 지출을 함께 명시해야 ε·δ를 해석할 수 있다. 충분한 자료·계산·공개 사전학습은 효용을 개선할 수 있지만 모든 환경에서 같은 절충점이 성립하지는 않는다.","limitations":"새 알고리즘의 단일 실험 결과가 아니라 실무 지침을 모은 서베이다. DP는 동의·접근통제·데이터 최소화 등 모든 개인정보 원칙을 대신하지 않으며 구현이 분석의 가정을 충족해야 한다.","significance":"“DP를 적용했다”는 표시를 검증 가능한 보호 명세와 파이프라인 점검표로 바꾼다.","beginnerExplanation":"한 사람의 기록을 넣거나 빼도 발표 결과가 크게 달라지지 않도록 제한하는 것이 핵심이다. 잡음만 넣는 것으로 끝나지 않고 반복 실험에서 쓴 보호 예산까지 계산해야 한다."},"readingGuide":["2·3절에서 보호 단위와 신뢰 경계를 먼저 정한다.","4절 DP-SGD를 일반 SGD와 비교하며 클리핑·잡음의 목적을 읽는다.","5.3·5.4절의 회계·보고·튜닝 지침을 실제 실험 체크리스트로 바꾼다."],"discussion":["예시 단위 DP가 사용자 단위 보호로 자동 해석되지 않는 이유는?","모델 선택과 튜닝 비용까지 포함한 보호 보장을 어떻게 보고할 것인가?"],"terms":[{"term":"Differential privacy (DP)","ordinaryMeaning":"차이에 관한 사생활 보호","etymology":"differential은 두 조건 사이의 차이를, privacy는 개인정보 보호를 뜻한다.","aiMeaning":"인접한 데이터셋에서 나온 결과 분포의 차이를 제한하는 확률적 보장이다.","paperReading":"무엇을 한 단위의 차이로 볼지 먼저 정해야 한다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"},{"term":"Privacy budget","ordinaryMeaning":"프라이버시에 쓸 수 있는 한도","etymology":"budget(예산)을 누적 정보 노출의 관리에 빗댔다.","aiMeaning":"주로 ε·δ와 합성 규칙으로 표현하는 보호 손실의 한도다.","paperReading":"같은 데이터에 대한 반복 학습과 공개를 회계에 반영한다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"},{"term":"Clipping","ordinaryMeaning":"일정 부분을 잘라 냄","etymology":"clip(잘라내다)의 동작명이다.","aiMeaning":"개별 기여의 크기가 정한 임계값을 넘지 않도록 제한한다.","paperReading":"한 자료나 사용자에 의한 최대 영향을 제한한 뒤 잡음을 보정한다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"},{"term":"Noise multiplier","ordinaryMeaning":"잡음의 배수","etymology":"noise(잡음)+multiplier(곱하는 값)의 결합이다.","aiMeaning":"클리핑 기준에 비례한 무작위 잡음 규모를 나타내는 계수다.","paperReading":"잡음만의 숫자로 보호를 판단하지 않고 샘플링·반복 횟수와 함께 본다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"},{"term":"Privacy accounting","ordinaryMeaning":"프라이버시 지출의 회계","etymology":"accounting(회계)을 반복 계산의 보호 손실 추적에 빗댔다.","aiMeaning":"여러 메커니즘의 누적 프라이버시 손실을 계산하는 방법이다.","paperReading":"분석이 전제하는 샘플링과 실제 구현이 맞는지 확인해야 한다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"},{"term":"Unit of privacy","ordinaryMeaning":"보호의 단위","etymology":"unit(단위)+privacy(프라이버시)의 결합이다.","aiMeaning":"보장을 적용하는 한 예시·한 사용자 등 변경 단위다.","paperReading":"여러 예시를 가진 사람을 보호하려면 예시 수준 보장과 구별해야 한다.","sourceUrl":"https://arxiv.org/pdf/2303.00654"}],"evidence":[{"url":"https://arxiv.org/pdf/2303.00654","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1644013 bytes; SHA-256 91bc649f4aa638e3d69cbfb11c0aef2a7cb1477f981ab43cf912addd0cc501d6","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2303.00654","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://jair.org/index.php/jair/article/view/14649","supports":"JAIR 제목·저자·2023 발행·DOI 확인","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 축약 제목 How to DP-fy ML에 공식 부제 A Practical Guide to Machine Learning with Differential Privacy를 복원했다.","sitePdfUrl":"papers/week-11/w11-p04_how-to-dp-fy.pdf"},{"id":"w12-p01","week":12,"role":"발표","title":"Universal and Transferable Adversarial Attacks on Aligned Language Models","authors":"Andy Zou, Zifan Wang, Nicholas Carlini, Milad Nasr, J. Zico Kolter, Matt Fredrikson","year":2023,"venue":"arXiv 사전공개 논문","citation":"Zou, A., Wang, Z., Carlini, N., Nasr, M., Kolter, J. Z., & Fredrikson, M. (2023). Universal and transferable adversarial attacks on aligned language models (arXiv:2307.15043v2). arXiv. https://doi.org/10.48550/arXiv.2307.15043","landingUrl":"https://arxiv.org/abs/2307.15043v2","pdfUrl":"https://arxiv.org/pdf/2307.15043v2","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"arXiv 항목의 view license가 https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html를 가리킨다. 이는 arXiv에 부여한 비독점 배포권이며 제3자의 재배포 허가로 간주하지 않았다. 공개 열람·개인 연구용 저장과 사이트 또는 첨부파일 재배포를 구별한다.","sourceVersion":"arXiv:2307.15043v2, 2023-12-20; 최초 v1은 2023-07-27. v2 PDF의 저자 6명을 사용했으며 학회 출판본으로 표시하지 않음.","readScope":"full_text","summary":{"question":"정렬된 언어모델의 거부를 약화시키는 입력을 자동으로 찾고, 다른 질문과 모델에도 옮겨 쓸 수 있는가?","background":"수동 탈옥 사례만으로는 방어의 체계적인 강건성을 평가하기 어렵다. 텍스트의 불연속성도 최적화를 어렵게 한다.","method":"GCG는 기울기로 유망한 토큰 변경을 추리고 실제 모델 평가로 선택한다. 여러 질문과 공개 모델을 함께 고려해 공통 접미부를 최적화하고, AdvBench의 문자열·행동 과제에서 직접 공격과 전이를 구별한다.","findings":"시험한 공개 모델에서 기존 최적화 방법보다 강한 결과를 보였다. 일부 비공개 모델에도 효과가 전이되었지만, 모델별 차이와 최적화 중 과적합이 관찰됐다.","limitations":"보편성은 실험 범위에서의 재사용성을 뜻한다. 당시 모델·판정 기준·질의 예산의 결과이며 현재 서비스 전체에 대한 보장은 아니다.","significance":"거부 응답 학습만으로 적대적 입력을 견딘다고 판단하기 어렵다는 평가 근거를 제공한다.","beginnerExplanation":"한 자물쇠에서 찾은 우회 방식이 여러 자물쇠에서도 통할 수 있다는 비유로 이해할 수 있다. 모든 자물쇠에 통한다는 뜻은 아니다."},"readingGuide":["2절에서 위협 모델과 최적화 목표를 구별한다. 실행 가능한 접미부를 재현할 필요는 없다.","3절의 개별 질문, 미관측 질문, 다른 모델 결과를 나눠 읽는다.","ASR의 판정 방식과 여러 시도를 합친 결과가 단일 시도와 같은지 점검한다.","6절의 사전 통보 및 공개 위험 논의를 읽는다."],"discussion":["전이 성공을 같은 원인이나 같은 학습자료의 증거로 볼 수 있을까?","방어 개선을 검증하려면 어떤 미관측 공격과 정상 요청을 함께 평가해야 할까?"],"terms":[{"term":"Aligned language model (정렬된 언어모델)","ordinaryMeaning":"방향이나 줄을 맞추어 놓은 것.","etymology":"align의 줄 맞추기라는 공간적 의미를 행동과 목표의 일치에 확장한 비유.","aiMeaning":"모델의 행동이 지정된 의도·정책·가치에 맞도록 학습된 언어모델.","paperReading":"정렬되었다는 사실과 적대적 강건성을 구분한다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"Adversarial suffix (적대적 접미부)","ordinaryMeaning":"문자열이나 단어의 끝에 붙는 부분.","etymology":"suffix는 언어학의 접미사라는 말에서 텍스트 끝부분이라는 의미로 확장된다.","aiMeaning":"입력 뒤에 붙여 원치 않는 출력을 유도하도록 설계한 토큰열.","paperReading":"원래 질문과 추가된 부분의 역할을 구분한다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"Greedy Coordinate Gradient, GCG","ordinaryMeaning":"greedy는 욕심 많은, coordinate는 좌표, gradient는 기울기.","etymology":"각 단계의 이득을 고르는 greedy, 변경 위치인 coordinate, 변화 방향인 gradient의 합성 명칭.","aiMeaning":"기울기 기반 후보 선정과 이산 토큰 평가를 결합한 최적화 방법.","paperReading":"기울기는 후보를 찾는 단서이지 성공 자체가 아니다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"Universal (보편적)","ordinaryMeaning":"여러 대상에 두루 적용되는 것.","etymology":"일상어 universal을 여러 입력에 공통으로 적용된다는 기술적 의미로 사용.","aiMeaning":"하나의 적대적 입력 요소를 여러 원래 입력에 재사용하는 성질.","paperReading":"모든 질문에 반드시 성공한다는 뜻이 아니다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"Transferability (전이성)","ordinaryMeaning":"한곳에서 다른 곳으로 옮겨 갈 수 있음.","etymology":"transfer에 가능성을 나타내는 -ability가 결합한 말.","aiMeaning":"한 모델에서 만든 공격이 다른 모델에도 영향을 주는 성질.","paperReading":"질문 간 보편성과 모델 간 전이를 구분한다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"White-box / black-box (화이트박스 / 블랙박스)","ordinaryMeaning":"상자 내부가 보이거나 보이지 않는다는 대비.","etymology":"내부를 관찰할 수 있는 정도를 상자에 빗댄 공학적 비유.","aiMeaning":"내부 가중치·기울기 접근 여부와 외부 입력·출력 접근을 구별하는 위협 모델.","paperReading":"공개 모델 최적화와 비공개 모델 시험의 접근권한이 다르다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"},{"term":"Attack success rate, ASR (공격 성공률)","ordinaryMeaning":"시도 중 목적을 달성한 비율.","etymology":"attack, success, rate의 머리글자를 묶은 약어.","aiMeaning":"명시한 판정 기준으로 공격 성공 건수를 전체 시험 건수에 대비한 지표.","paperReading":"정확한 문자열과 유해 행동 과제의 성공 기준이 다르다.","sourceUrl":"https://arxiv.org/pdf/2307.15043v2"}],"evidence":[{"url":"https://arxiv.org/abs/2307.15043v2","supports":"정확한 제목, 저자, v2 날짜, 사전공개 상태와 라이선스 링크.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2307.15043v2","supports":"본문 2–3절: GCG, AdvBench, 직접·전이 평가. 5–6절: 한계, 향후 연구, 책임 있는 공개.","accessedDate":"2026-10-12"},{"url":"https://llm-attacks.org/","supports":"저자 공식 프로젝트의 연구 개요와 회사 사전 통보 설명.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html","supports":"arXiv 비독점 배포 라이선스의 권한 대상 확인.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2307.15043v2","supports":"로컬 검증: %PDF- 헤더, pdfinfo 31쪽, pdftotext 읽기 가능(94435자); 파일 4656473 bytes; SHA-256 ab8745c2e3c6dfd939d5a590760bbae4682d92db010947cbb306688ad086bfd1.","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 제목·연도는 일치한다. 내려받은 판은 최초 v1이 아닌 저자 6명의 2023-12-20 v2이다.","sitePdfUrl":null},{"id":"w12-p02","week":12,"role":"발표","title":"Jailbroken: How Does LLM Safety Training Fail?","authors":"Alexander Wei, Nika Haghtalab, Jacob Steinhardt","year":2023,"venue":"Advances in Neural Information Processing Systems 36 (NeurIPS 2023)","citation":"Wei, A., Haghtalab, N., & Steinhardt, J. (2023). Jailbroken: How does LLM safety training fail? Advances in Neural Information Processing Systems, 36. https://doi.org/10.52202/075280-3508","landingUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/fd6613131889a4b656206c50a8bd7790-Abstract-Conference.html","pdfUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"NeurIPS의 공개 출판본을 개인 연구용으로 저장했다: https://proceedings.neurips.cc/paper_files/paper/2023/hash/fd6613131889a4b656206c50a8bd7790-Abstract-Conference.html. 해당 출판 페이지와 PDF에서 명시적 제3자 재배포 허가를 확인하지 못했다. 별도 arXiv판 https://arxiv.org/abs/2307.02483 의 라이선스는 https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html이며 그것만으로 출판 PDF 재배포를 허가한다고 판단하지 않았다.","sourceVersion":"NeurIPS 2023 공식 proceedings PDF, 32쪽. arXiv:2307.02483v1(2023-07-05)과 출판본을 구별해 출판본을 사용.","readScope":"full_text","summary":{"question":"안전 학습을 받은 모델에서 탈옥이 성공하는 이유를 공통 원리로 설명할 수 있는가?","background":"사전학습, 지시 이행, 안전 학습은 서로 다른 목적과 자료를 사용한다.","method":"목표 경쟁과 일반화 불일치라는 두 가설로 공격 유형을 정리한다. 당시 GPT·Claude 계열에 여러 유형과 조합을 시험하고, 소규모 선별 자료와 별도 합성 자료에서 응답을 수동 분류한다.","findings":"단일 기법보다 조합과 질문별 선택이 강했다. 더 큰 모델의 새로운 능력이 안전 학습보다 넓게 일반화하는 사례도 관찰됐다.","limitations":"비공개 모델을 외부에서 관찰하므로 내부 원인은 가설이다. 평가하는 것은 거부 우회이며 응답의 정확성이나 실제 피해 규모가 아니다.","significance":"안전 장치가 본체의 능력과 표현 형식을 충분히 이해해야 한다는 안전·능력 균형 문제를 제기한다.","beginnerExplanation":"새로운 말투를 이해하는 능력은 배웠지만 그 말투에서도 안전 규칙을 적용하는 연습은 부족할 수 있다."},"readingGuide":["2절의 제한된 행동과 성공·거부·불명확 판정을 먼저 읽는다.","3절의 두 가설을 공격 사례 자체와 분리하여 정리한다.","4절에서 단일 방식과 여러 방식을 선택한 평가를 비교한다.","5–6절에서 방어 시사점과 인과적 설명의 한계를 점검한다."],"discussion":["모델 능력 향상이 왜 일부 취약성을 줄이고 다른 취약성을 드러낼 수 있을까?","출력의 위험성과 거부 우회를 어떤 별도 지표로 평가할까?"],"terms":[{"term":"Jailbreak (탈옥)","ordinaryMeaning":"감옥이나 구속에서 벗어남.","etymology":"jail(감옥)과 break(깨거나 벗어남)의 결합을 소프트웨어 제약 우회에 비유.","aiMeaning":"모델이 따르도록 학습한 안전 제약을 벗어나는 출력의 유도.","paperReading":"모델이 틀리는 것과 금지된 능력을 드러내는 것은 다르다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Competing objectives (목표 경쟁)","ordinaryMeaning":"여러 목표가 한정된 자원이나 선택을 두고 충돌함.","etymology":"competing과 objectives를 결합한 설명적 명칭.","aiMeaning":"안전, 지시 이행, 자연스러운 문장 생성 등의 최적화 목표가 충돌하는 현상.","paperReading":"안전 실패에 대한 첫 번째 가설이다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Mismatched generalization (일반화 불일치)","ordinaryMeaning":"배운 것을 넓혀 적용하는 범위가 서로 맞지 않음.","etymology":"mis-(어긋남)와 matched, generalization을 결합한 명칭.","aiMeaning":"모델의 능력이 작동하는 분포까지 안전 행동이 함께 확장되지 않는 현상.","paperReading":"능력과 안전의 적용 범위를 따로 본다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Safety-capability parity (안전·능력 균형)","ordinaryMeaning":"두 측면이 서로 대등한 수준에 있음.","etymology":"safety, capability와 대등함을 뜻하는 parity의 결합.","aiMeaning":"안전 장치가 모델의 복잡한 능력과 표현을 충분히 다룰 수준이어야 한다는 원칙.","paperReading":"안전 성능과 업무 능력의 수치가 같다는 뜻은 아니다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Ablation (구성요소 제거 실험)","ordinaryMeaning":"어떤 부분을 떼어 내거나 제거함.","etymology":"의학·공학의 제거라는 말을 실험 구성요소 분석에 빌려 사용.","aiMeaning":"한 구성요소를 없애거나 바꿔 그 요소의 기여를 비교하는 실험.","paperReading":"문구 변화가 결과를 바꾸는지 가설을 점검한다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Adaptive adversary (적응형 공격자)","ordinaryMeaning":"상황에 맞추어 행동을 바꾸는 상대.","etymology":"adapt의 적응이라는 뜻과 adversary의 대항자라는 뜻을 결합.","aiMeaning":"관찰한 모델 응답에 따라 다음 시험이나 입력을 선택하는 공격자.","paperReading":"단일 고정 방식의 성능과 합쳐 읽지 않는다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"},{"term":"Out-of-distribution, OOD (분포 밖)","ordinaryMeaning":"기준으로 삼은 분포 범위를 벗어남.","etymology":"out of와 distribution의 결합을 줄인 약어.","aiMeaning":"학습 또는 평가 기준 자료와 성질이 다른 입력 영역.","paperReading":"안전 학습에는 낯설지만 본체에는 익숙할 수 있다.","sourceUrl":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf"}],"evidence":[{"url":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/fd6613131889a4b656206c50a8bd7790-Abstract-Conference.html","supports":"NeurIPS 2023, 권 36, 정확한 저자와 제목, 공식 DOI.","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf","supports":"2절: 위협 모델과 판정 기준; 3–5절: 두 가설, 실험과 방어 시사점; 6절: 비공개 모델 연구 한계.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2307.02483","supports":"별도 사전공개판의 v1 날짜와 arXiv 비독점 라이선스 링크.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html","supports":"arXiv 비독점 배포권이 제3자 재배포 허가와 다름을 확인.","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper_files/paper/2023/file/fd6613131889a4b656206c50a8bd7790-Paper-Conference.pdf","supports":"로컬 검증: %PDF- 헤더, pdfinfo 32쪽, pdftotext 읽기 가능(143562자); 파일 341955 bytes; SHA-256 6ce44fb3d6363955ae2c34f6391f5daa4e7cb2f63201ef4a85ff618f9eba56e4.","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w12-p03","week":12,"role":"참고","title":"The Instruction Hierarchy: Training LLMs to Prioritize Privileged Instructions","authors":"Eric Wallace, Kai Xiao, Reimar Leike, Lilian Weng, Johannes Heidecke, Alex Beutel","year":2024,"venue":"arXiv 사전공개 논문 / OpenAI 연구","citation":"Wallace, E., Xiao, K., Leike, R., Weng, L., Heidecke, J., & Beutel, A. (2024). The instruction hierarchy: Training LLMs to prioritize privileged instructions (arXiv:2404.13208v1). arXiv. https://doi.org/10.48550/arXiv.2404.13208","landingUrl":"https://arxiv.org/abs/2404.13208v1","pdfUrl":"https://arxiv.org/pdf/2404.13208v1","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2404.13208 의 view license는 https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html이다. 공개 연구 소개도 PDF를 arXiv로 연결하지만 제3자 재배포를 명시적으로 허가하지 않는다. 개인 연구용 저장과 재게시를 구별했다.","sourceVersion":"arXiv:2404.13208v1, 2024-04-19, 13쪽. OpenAI의 같은 날짜 연구 소개와 대조. 확인한 원출처에는 학회·저널 출판 정보가 없어 사전공개판으로 표시.","readScope":"full_text","summary":{"question":"서로 다른 출처의 지시가 충돌할 때 모델이 권한 순서를 학습하도록 만들 수 있는가?","background":"같은 문맥에 담긴 사용자 요청과 외부 자료를 동등한 명령으로 취급하면 프롬프트 인젝션에 취약하다.","method":"양립 가능한 지시는 계층에 나눠 배치하는 맥락 합성으로, 충돌하는 지시는 없는 것처럼 답하게 하는 맥락 무시로 자료를 만든다. GPT-3.5 Turbo를 미세조정하고 기존 모델과 비교한다.","findings":"시험한 직접·간접 인젝션과 지시 추출 방어가 개선됐으며 학습에서 제외한 유형에도 일반화했다. 일반 능력은 대체로 유지됐지만 일부 정상 요청의 거부가 늘었다.","limitations":"텍스트 중심의 특정 학습·평가다. 도구 속 지시를 일괄 무시하는 현재 설계의 제약과 강한 공격에 남는 취약성을 인정한다.","significance":"명령의 내용뿐 아니라 출처와 우선순위를 학습 목표로 만든다.","beginnerExplanation":"문서를 읽어 달라는 부탁을 받은 비서가 문서 속 부탁을 새 업무 지시로 받아들이지 않도록 가르치는 셈이다."},"readingGuide":["그림 1과 3.1절에서 출처와 권한을 나눈다.","3.2절의 맥락 합성과 맥락 무시가 각각 필요한 이유를 정리한다.","그림 2–4의 방어 성능, 일반화, 과잉 거부를 함께 읽는다.","부록 A의 단순 지시문 기준선과 실제 학습 효과를 비교한다."],"discussion":["외부 문서의 유용한 지시를 언제 데이터로, 언제 실행 가능한 요청으로 볼까?","권한 계층을 학습한 모델 외에 어떤 시스템 수준 통제가 필요할까?"],"terms":[{"term":"Instruction hierarchy (명령 계층)","ordinaryMeaning":"상하 관계나 우선순위로 조직된 지시 체계.","etymology":"instruction과 hierarchy를 결합한 설명적 명칭으로 권한 계층을 언어 지시에 적용.","aiMeaning":"서로 충돌하는 명령의 출처별 우선순위 규칙.","paperReading":"모든 낮은 권한 지시를 거부하는 규칙과 다르다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Privileged instruction (높은 권한의 지시)","ordinaryMeaning":"다른 것보다 우선하는 특별한 권한을 가진 지시.","etymology":"컴퓨터 보안에서 privileged가 뜻하는 높은 실행 권한을 언어 지시에 비유.","aiMeaning":"충돌 시 우선되어야 하는 신뢰된 출처의 명령.","paperReading":"문장 안에서 권한을 주장하는 것만으로 권한이 생기지 않는다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Prompt injection (프롬프트 인젝션)","ordinaryMeaning":"어떤 내용이나 물질을 안으로 끼워 넣음.","etymology":"injection의 주입이라는 뜻을 입력에 명령을 끼워 넣는 현상에 비유.","aiMeaning":"신뢰도가 낮은 입력 속 명령으로 응용 시스템의 원래 작업을 바꾸는 시도.","paperReading":"사용자 직접 입력과 도구 결과의 간접 입력을 구별한다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Context distillation (맥락 증류)","ordinaryMeaning":"어떤 맥락에서 핵심을 뽑아 농축함.","etymology":"액체를 분리·정제하는 distillation을 지식 전달에 빌린 비유.","aiMeaning":"추가 맥락으로 얻은 바람직한 응답을 이용해 그 맥락 없이도 같은 행동을 학습시키는 방법.","paperReading":"보조 설명이 있는 응답에서 학습 자료를 얻는다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Context synthesis (맥락 합성)","ordinaryMeaning":"여러 조각의 맥락을 합쳐 구성함.","etymology":"context와 여러 부분을 결합한다는 synthesis의 조합.","aiMeaning":"복합 요청을 나누어 서로 다른 권한 수준에 놓고 올바른 통합 응답을 학습하는 방식.","paperReading":"양립 가능한 지시를 수행하는 쪽의 훈련이다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Context ignorance (맥락 무시)","ordinaryMeaning":"주어진 맥락을 모르거나 고려하지 않음.","etymology":"context와 ignorance를 결합해 해당 내용을 보지 않은 것처럼 행동함을 표현.","aiMeaning":"충돌하는 낮은 권한 지시가 없었던 경우의 응답을 목표로 학습하는 방식.","paperReading":"충돌 지시를 무시하며 원래 작업을 유지한다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"},{"term":"Over-refusal (과잉 거부)","ordinaryMeaning":"필요 이상으로 거절함.","etymology":"over-(지나치게)와 refusal(거절)의 결합.","aiMeaning":"안전하고 허용된 요청도 거부하는 방어의 부작용.","paperReading":"방어 성공률만으로 유용성을 판단하지 않게 한다.","sourceUrl":"https://arxiv.org/pdf/2404.13208v1"}],"evidence":[{"url":"https://arxiv.org/abs/2404.13208v1","supports":"부제 포함 정확한 제목, 저자 6명, 2024-04-19 v1과 라이선스.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2404.13208v1","supports":"3절: 계층과 훈련 자료; 4절·부록 A–B: 비교 평가와 과잉 거부; 6절: 텍스트·도구 지시의 한계.","accessedDate":"2026-10-12"},{"url":"https://openai.com/index/the-instruction-hierarchy/","supports":"저자 소속 기관의 공식 연구 소개, 발표 날짜, 정확한 제목 및 arXiv 연결.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/licenses/nonexclusive-distrib/1.0/license.html","supports":"arXiv 비독점 배포 라이선스.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2404.13208v1","supports":"로컬 검증: %PDF- 헤더, pdfinfo 13쪽, pdftotext 읽기 가능(55154자); 파일 488381 bytes; SHA-256 fbc2d65e913e75b8f0ae74e83e3443c36a727636d1038a071a2f10d8be63dac4.","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 축약 제목 The Instruction Hierarchy를 정식 제목 The Instruction Hierarchy: Training LLMs to Prioritize Privileged Instructions로 보완했다.","sitePdfUrl":null},{"id":"w12-p04","week":12,"role":"참고","title":"Improving Alignment and Robustness with Circuit Breakers","authors":"Andy Zou, Long Phan, Justin Wang, Derek Duenas, Maxwell Lin, Maksym Andriushchenko, Rowan Wang, Zico Kolter, Matt Fredrikson, Dan Hendrycks","year":2024,"venue":"Advances in Neural Information Processing Systems 37 (NeurIPS 2024)","citation":"Zou, A., Phan, L., Wang, J., Duenas, D., Lin, M., Andriushchenko, M., Wang, R., Kolter, Z., Fredrikson, M., & Hendrycks, D. (2024). Improving alignment and robustness with circuit breakers. Advances in Neural Information Processing Systems, 37. https://doi.org/10.52202/079017-2651","landingUrl":"https://proceedings.neurips.cc/paper_files/paper/2024/hash/97ca7168c2c333df5ea61ece3b3276e1-Abstract-Conference.html","pdfUrl":"https://arxiv.org/pdf/2406.04313v4","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"배포 대상으로 지정한 파일은 arXiv:2406.04313v4이다. https://arxiv.org/abs/2406.04313 의 view license가 https://creativecommons.org/licenses/by/4.0/ 를 명시하므로 CC BY 4.0 조건 아래 재배포 가능하다. 저자·제목·원출처·라이선스를 표시하고 변경 여부를 밝혀야 한다. 별도 저장한 NeurIPS 출판 PDF의 권리는 이 판정으로 자동 확장하지 않는다.","sourceVersion":"요약과 서지는 NeurIPS 2024 출판본(29쪽)을 확인하고 arXiv:2406.04313v4(2024-07-12, 23쪽)와 대조했다. pdfUrl/localPdf는 명시적 CC BY 4.0인 arXiv v4이며 출판 PDF와 동일 파일이 아니다.","readScope":"full_text","summary":{"question":"특정 공격 문자열을 학습하는 대신 유해 응답을 만드는 내부 표현을 바꾸어 방어할 수 있는가?","background":"거부가 우회되면 유해한 문장 생성이 이어질 수 있다. 표현 공학은 이 내부 진행 과정에 개입한다.","method":"Representation Rerouting은 유해 생성의 표현을 원래 방향에서 멀어지게 하면서 정상 자료의 표현은 보존한다. 저랭크 어댑터로 학습하고 텍스트·멀티모달·함수 호출에서 안전성과 업무 능력을 함께 평가한다.","findings":"시험한 여러 미관측 공격에서 유해 응답과 행동이 줄고 일반 벤치마크 성능은 대체로 유지됐다. 자료 구성에 따라 일반화가 달랐으며 정상 요청 거부도 일부 증가했다.","limitations":"주로 단일 턴의 유해 생성 방어다. 일반 분류 오류나 모든 공격을 막는 보장은 없고, 보조 탐지기 실험의 공격자 지식도 제한된다.","significance":"출력 문구뿐 아니라 생성 중 내부 표현을 안전 통제의 대상으로 삼는다.","beginnerExplanation":"위험한 작업이 진행되는 경로에 차단기를 두는 비유다. 물리적 회로를 찾거나 모든 위험을 제거했다는 뜻은 아니다."},"readingGuide":["그림 1과 3절에서 거부 학습과 표현 재라우팅의 개입 위치를 비교한다.","4절의 텍스트, 이미지, 함수 호출 결과를 각각의 위협 모델로 읽는다.","자료 구성 제거 실험과 정상 요청 거부 결과를 함께 점검한다.","5절의 적용 범위와 보조 탐지기 평가 가정을 확인한다."],"discussion":["벤치마크 점수 유지가 실제 사용자의 유용성 유지까지 보여 줄까?","새로운 방어를 공개한 뒤 어떤 적응형 평가가 추가로 필요할까?"],"terms":[{"term":"Circuit breaker (회로 차단기)","ordinaryMeaning":"위험한 전류 흐름을 끊는 안전 장치.","etymology":"circuit과 breaker의 전기공학 명칭을 위험 과정 차단에 빌린 비유.","aiMeaning":"유해 생성과 관련된 내부 표현의 진행을 중단하거나 바꾸는 방어 계열.","paperReading":"물리 회로나 특정 뉴런 회로의 완전한 식별을 뜻하지 않는다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Representation (표현)","ordinaryMeaning":"무언가를 대신 나타낸 형태.","etymology":"represent의 나타내다라는 의미가 수학적·계산적 부호화로 확장됨.","aiMeaning":"모델 내부에서 입력과 문맥의 특징을 담는 벡터 또는 활성값.","paperReading":"출력 텍스트 이전의 내부 상태가 개입 대상이다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Representation Rerouting, RR (표현 재라우팅)","ordinaryMeaning":"이미 정한 길을 다른 길로 돌림.","etymology":"re-(다시)와 routing(경로 지정)을 결합한 명칭.","aiMeaning":"유해 생성에 쓰이는 내부 표현을 원래 방향과 다른 방향으로 학습시키는 방법.","paperReading":"차단기라는 큰 개념의 구체적 구현이다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Retain set (보존 자료 집합)","ordinaryMeaning":"계속 가지고 있을 대상을 모은 묶음.","etymology":"retain(보유하다)과 set(집합)의 결합.","aiMeaning":"방어 학습 중 정상 능력이나 기존 거부 행동을 유지하기 위해 사용하는 자료.","paperReading":"유해 자료만 학습할 때의 능력 저하를 견제한다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Cosine similarity (코사인 유사도)","ordinaryMeaning":"두 방향 사이 각도를 이용한 닮음의 척도.","etymology":"삼각함수 cosine과 similarity의 결합; 명칭은 각도의 코사인 계산을 반영.","aiMeaning":"벡터 크기보다 방향의 일치를 비교하는 값.","paperReading":"유해 표현을 원래 방향에서 벗어나게 하는 손실에 쓰인다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Low-rank adaptation, LoRA (저랭크 적응)","ordinaryMeaning":"낮은 랭크의 구조를 이용한 조정.","etymology":"Low-Rank Adaptation의 일부 글자를 묶은 약어.","aiMeaning":"큰 모델 전체 대신 저랭크 행렬 형태의 작은 추가 파라미터를 학습하는 방법.","paperReading":"표현 변화와 정상 능력 보존을 위한 학습 수단이다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Attack-agnostic (특정 공격에 의존하지 않는)","ordinaryMeaning":"대상을 특정하거나 구별하지 않고 적용함.","etymology":"attack과 agnostic을 합쳐 특정 공격 형태를 전제하지 않는다는 뜻으로 사용.","aiMeaning":"특정 공격 입력보다 여러 공격이 도달할 수 있는 유해 생성 과정을 겨냥하는 설계.","paperReading":"미지의 모든 공격에 대한 수학적 보장은 아니다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"},{"term":"Robustness–utility trade-off (강건성·유용성 절충)","ordinaryMeaning":"한 장점을 얻는 대신 다른 장점을 양보하는 관계.","etymology":"trade-off의 맞바꿈이라는 일상적 비유를 두 평가 목표의 관계에 적용.","aiMeaning":"공격 저항성을 강화할 때 정상 작업 성능이나 사용성이 나빠질 수 있는 관계.","paperReading":"안전 점수와 정상 요청 거부를 함께 해석한다.","sourceUrl":"https://arxiv.org/pdf/2406.04313v4"}],"evidence":[{"url":"https://proceedings.neurips.cc/paper_files/paper/2024/hash/97ca7168c2c333df5ea61ece3b3276e1-Abstract-Conference.html","supports":"NeurIPS 2024 권 37, 저자 10명, 정확한 제목과 공식 DOI.","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper_files/paper/2024/file/97ca7168c2c333df5ea61ece3b3276e1-Paper-Conference.pdf","supports":"출판본 본문 3–5절과 부록 B: 표현 손실, 실험, 과잉 거부, 단일 턴 한계. 개인 대조용으로 downloads/week-12/w12-p04_circuit-breakers.pdf에 저장했으며 재배포 허가를 별도로 확인하지 않음.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2406.04313v4","supports":"arXiv v4 날짜와 CC BY 4.0 라이선스 링크.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2406.04313v4","supports":"첨부 대상으로 선택한 arXiv v4 전체 본문과 출판본의 핵심 방법·평가 대조.","accessedDate":"2026-10-12"},{"url":"https://creativecommons.org/licenses/by/4.0/","supports":"표시, 라이선스 연결, 변경 고지 조건으로 공유·수정 허용.","accessedDate":"2026-10-12"},{"url":"https://www.grayswan.ai/research/circuit-breakers","supports":"저자 기관의 공식 연구 페이지와 저자 확인.","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/pdf/2406.04313v4","supports":"로컬 검증: %PDF- 헤더, pdfinfo 23쪽, pdftotext 읽기 가능(166024자); 파일 920758 bytes; SHA-256 c3519984a56dba2d7010058ecf736caaeb2656712e1ba409b050971960f7bb92.","accessedDate":"2026-10-12"}],"corrections":"강의계획서의 NeurIPS 2024 표기는 맞다. 다운로드 대상으로 연결한 CC BY 4.0 사전공개판과 학회 출판본의 차이를 명시했다.","sitePdfUrl":"papers/week-12/w12-p04_circuit-breakers-arxiv-v4.pdf"},{"id":"w13-p01","week":13,"role":"발표","title":"Not what you've signed up for: Compromising Real-World LLM-Integrated Applications with Indirect Prompt Injection","authors":"Greshake, Kai; Abdelnabi, Sahar; Mishra, Shailesh; Endres, Christoph; Holz, Thorsten; Fritz, Mario","year":2023,"venue":"Proceedings of the 16th ACM Workshop on Artificial Intelligence and Security (AISec ’23), 79–90","citation":"Greshake, Kai; Abdelnabi, Sahar; Mishra, Shailesh; Endres, Christoph; Holz, Thorsten; Fritz, Mario (2023). Not what you've signed up for: Compromising Real-World LLM-Integrated Applications with Indirect Prompt Injection. Proceedings of the 16th ACM Workshop on Artificial Intelligence and Security (AISec ’23), 79–90. https://arxiv.org/abs/2302.12173","landingUrl":"https://arxiv.org/abs/2302.12173","pdfUrl":"https://arxiv.org/pdf/2302.12173","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2302.12173에서 공개 열람 가능한 원문. arXiv 비독점 배포 허가는 arXiv에 부여한 권리이므로 제3자의 웹사이트 재게시 허가로 해석하지 않는다. 개인 연구용으로 내려받았으며 재배포 허가는 별도 확인이 필요하다.","sourceVersion":"arXiv:2302.12173v2, 2023-05-05; AISec 2023 이전 공개 저자판","readScope":"full_text","summary":{"question":"사용자가 아닌 외부 문서 작성자도 LLM 통합 앱의 행동을 바꿀 수 있는가?","background":"검색·문서 읽기·코드 보조 기능은 제3자의 텍스트를 모델 문맥에 넣는다. 그 텍스트를 명령으로 오인하면 사용자의 요청과 외부 작성자의 목적이 섞인다.","method":"공격자가 바꿀 수 있는 외부 콘텐츠, 유입 경로, 보안 결과를 분류한다. 합성 애플리케이션과 통제된 로컬 콘텐츠를 이용한 실제 앱 사례로, 정보 접근·도구 사용·응답 내용이 외부 문장에 의해 달라질 수 있음을 시연한다.","findings":"자료와 명령의 경계가 흐려지면 직접 대화 권한이 없는 작성자도 앱의 목표와 후속 도구 호출에 영향을 줄 수 있었다. 이는 유해 문장 생성뿐 아니라 기밀성·무결성·가용성 문제로 연결된다.","limitations":"주로 개념 입증과 정성적 사례이며 실제 배포 전체에서의 성공 빈도를 측정하지 않았다. 대화 지속성·사용자 반응·검색 노출 같은 조건은 별도 평가가 필요하며 당시 앱의 결과를 현재 앱에 그대로 적용할 수 없다.","significance":"RAG와 에이전트 설계에서 신뢰하지 않는 자료를 권한 있는 지시로 승격시키지 않는 경계가 중요함을 보여 준다.","beginnerExplanation":"비서가 읽는 편지에 “비서에게 내리는 명령”이 적혀 있다고 해서 편지 작성자가 비서의 주인이 되는 것은 아니다. 모델이 이 구별을 놓칠 때 생기는 문제다."},"readingGuide":["위협 모델에서 사용자와 외부 콘텐츠 작성자의 권한을 구분한다.","분류 체계의 각 위험을 기밀성·무결성·가용성으로 연결한다.","5.2절에서 시연의 범위와 성공률 측정의 제약을 확인한다."],"discussion":["문서를 요약할 권한과 문서 속 요청을 실행할 권한은 어떻게 구분할 것인가?","권한 통제는 모델 프롬프트와 도구 실행 계층 중 어디에 두어야 하는가?"],"terms":[{"term":"Indirect prompt injection","ordinaryMeaning":"간접적으로 명령문을 끼워 넣음","etymology":"indirect(간접)+prompt(입력 지시)+injection(주입)의 결합이다.","aiMeaning":"제3자 자료 속 문장이 모델의 정당한 지시 수행을 바꾸는 공격이다.","paperReading":"공격자가 사용자의 대화창에 직접 접근할 필요가 없다는 점이 핵심이다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"},{"term":"Trust boundary","ordinaryMeaning":"신뢰가 달라지는 경계","etymology":"trust(신뢰)+boundary(경계)의 보안 용어다.","aiMeaning":"권한·출처·검증 수준이 다른 데이터나 구성요소 사이의 경계다.","paperReading":"검색 결과는 사용자 요청과 같은 권한을 갖지 않는다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"},{"term":"Retrieval","ordinaryMeaning":"찾아 가져옴","etymology":"retrieve(회수하다·찾아오다)의 명사형이다.","aiMeaning":"질의와 관련된 외부 문서나 데이터를 찾아 모델에 제공하는 과정이다.","paperReading":"관련성이 높다는 사실이 지시 권한이나 진실성을 보장하지 않는다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"},{"term":"Exfiltration","ordinaryMeaning":"밖으로 빼냄","etymology":"보안에서 데이터가 허가 없이 외부로 나가는 일을 나타내는 말이다.","aiMeaning":"민감한 정보를 허가되지 않은 수신처에 전달하는 누출이다.","paperReading":"자료 접근 권한이 있는 에이전트의 외부 전송 경로까지 평가해야 한다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"},{"term":"Integrity attack","ordinaryMeaning":"온전함에 대한 공격","etymology":"integrity(무결성)+attack(공격)의 결합이다.","aiMeaning":"허가 없이 데이터·처리·결과를 바꾸는 보안 위반이다.","paperReading":"도구 오용뿐 아니라 요약·출처 선택의 왜곡도 무결성 문제다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"},{"term":"Multi-stage","ordinaryMeaning":"여러 단계로 진행됨","etymology":"multi-(여러)+stage(단계)의 결합이다.","aiMeaning":"하나의 입력 이후 여러 처리·호출·상태 변화를 거치는 구조다.","paperReading":"최초 입력 검사만으로 후속 검색과 도구 호출의 위험을 모두 평가하기 어렵다.","sourceUrl":"https://arxiv.org/pdf/2302.12173"}],"evidence":[{"url":"https://arxiv.org/pdf/2302.12173","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 7306999 bytes; SHA-256 428e23e8c7e4f89310e113e38d082b3f65548a8b887188ebc536099061800e81","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2302.12173","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://doi.org/10.1145/3605764.3623985","supports":"AISec 2023 출판 식별자; 본문 요약은 공개 arXiv v2 기반","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w13-p02","week":13,"role":"발표","title":"AgentDojo: A Dynamic Environment to Evaluate Prompt Injection Attacks and Defenses for LLM Agents","authors":"Debenedetti, Edoardo; Zhang, Jie; Balunović, Mislav; Beurer-Kellner, Luca; Fischer, Marc; Tramèr, Florian","year":2024,"venue":"Advances in Neural Information Processing Systems 37, Datasets and Benchmarks Track","citation":"Debenedetti, Edoardo; Zhang, Jie; Balunović, Mislav; Beurer-Kellner, Luca; Fischer, Marc; Tramèr, Florian (2024). AgentDojo: A Dynamic Environment to Evaluate Prompt Injection Attacks and Defenses for LLM Agents. Advances in Neural Information Processing Systems 37, Datasets and Benchmarks Track. https://arxiv.org/abs/2406.13352","landingUrl":"https://arxiv.org/abs/2406.13352","pdfUrl":"https://arxiv.org/pdf/2406.13352","downloadStatus":"downloaded","redistribution":"unclear","licenseNote":"https://arxiv.org/abs/2406.13352v3 은 arXiv nonexclusive-distrib 라이선스를 표시한다. 본문 부록의 MIT License는 code and data에 관한 것이므로 논문 PDF 재배포 허가로 확대하지 않는다. 공개 원문 링크 제공은 가능하나 PDF 재게시 허가는 별도 확인 필요.","sourceVersion":"arXiv:2406.13352v3, 2024-11-24; NeurIPS 2024 대응 저자판","readScope":"full_text","summary":{"question":"에이전트가 정상 일을 해내면서 외부 자료의 악성 지시도 견디는지 어떻게 평가할 것인가?","background":"한 번의 텍스트 응답만 평가하면 여러 도구 호출과 상태 변경이 있는 작업을 충분히 측정하기 어렵다. 공격을 막았지만 정상 업무도 실패한 모델을 좋은 방어로 오인할 수도 있다.","method":"메일·일정·여행·뱅킹 등 상태를 가진 모의 환경에서 사용자 목표와 공격자 목표를 별도로 정의한다. 정상 과제 97개와 보안 시험 629개를 제공하고, 도구 실행 전후 상태를 검사하는 평가 함수로 유용성과 공격 성공을 측정한다.","findings":"정상 상황에서도 실패하는 과제가 있었고, 도구를 잘 쓰는 능력이 악성 목표 수행 능력과도 연결될 수 있었다. 공격 종류·작업 분야·방어 방식에 따라 유용성과 보안의 관계가 달라 단일 점수만으로 전체 안전성을 표현하기 어려웠다.","limitations":"실제 계정을 공격하는 시험이 아니라 정해진 모의 과제다. 수동 과제 정의의 확장성, 비교적 단순한 공격·방어, 다중모달과 현실적 공격 제약의 부족을 후속 과제로 제시한다.","significance":"에이전트 보안 평가를 정적 문자열 판정에서 동적 작업 결과와 권한 위반의 평가로 확장한다.","beginnerExplanation":"비서가 일을 잘하는지와 잘못된 편지의 지시를 따르지 않는지를 별도 채점한다. 아무 일도 안 하는 비서가 안전 점수만 높게 받지 않도록 두 축을 함께 본다."},"readingGuide":["3절의 사용자 과제·주입 과제·상태 검사 구조를 먼저 읽는다.","정상 유용성, 공격 중 유용성, 표적 공격 성공률을 구분한다.","4절의 방어 비교와 5절의 확장 과제를 연결한다."],"discussion":["정상 업무를 막아서 얻은 보안 향상을 어떤 지표로 드러낼까?","모델 판정기와 명시적 상태 검사 중 어떤 오류에 더 주의해야 할까?"],"terms":[{"term":"Agent","ordinaryMeaning":"대신 행동하는 대리인","etymology":"agent는 일을 수행하는 행위자·대리인을 뜻한다.","aiMeaning":"모델 판단과 도구 호출을 결합하여 여러 단계 작업을 수행하는 시스템이다.","paperReading":"답변 내용뿐 아니라 실제 환경 상태를 바꾸는 행동을 평가한다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"},{"term":"Dynamic environment","ordinaryMeaning":"계속 바뀌는 환경","etymology":"dynamic(변화하는)+environment(환경)의 결합이다.","aiMeaning":"도구 실행에 따라 상태와 후속 관측이 달라지는 실험 환경이다.","paperReading":"고정된 질문·정답 쌍만으로 시험하지 않는다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"},{"term":"Utility","ordinaryMeaning":"쓸모·유용성","etymology":"일반적인 쓸모라는 의미를 작업 성과에 적용했다.","aiMeaning":"사용자의 정당한 목표를 어느 정도 달성하는지 나타내는 지표다.","paperReading":"공격 성공률과 별개로 정상 업무 수행을 측정한다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"},{"term":"Attack success rate (ASR)","ordinaryMeaning":"공격이 목적을 이룬 비율","etymology":"attack+success+rate의 설명적 약어다.","aiMeaning":"정해진 시험들 중 공격자 목표가 달성된 비율이다.","paperReading":"공격이 전달된 조건·표적 목표·평가 함수를 함께 명시해야 비교가 가능하다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"},{"term":"Tool output","ordinaryMeaning":"도구가 돌려주는 결과","etymology":"tool(도구)+output(출력)의 결합이다.","aiMeaning":"검색·메일 읽기·API 호출 등이 모델에 반환하는 데이터다.","paperReading":"도구 자체가 승인되어도 반환된 제3자 문장까지 신뢰할 수는 없다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"},{"term":"Adaptive attack","ordinaryMeaning":"상황에 맞춰 바뀌는 공격","etymology":"adapt(적응하다)에서 온 형용사와 attack의 결합이다.","aiMeaning":"방어 구조나 관측 결과에 맞게 전략을 바꾸는 평가 공격이다.","paperReading":"동적 환경은 새로운 방어를 고려하는 시험으로 계속 확장할 수 있다.","sourceUrl":"https://arxiv.org/pdf/2406.13352"}],"evidence":[{"url":"https://arxiv.org/pdf/2406.13352","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1042076 bytes; SHA-256 349884fffbf43282591c5accffd57bb651632f38e412fe303114941bdd111b05","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2406.13352","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://proceedings.neurips.cc/paper_files/paper/2024/hash/97091a5177d8dc64b1da8bf3e1f6fb54-Abstract-Datasets_and_Benchmarks_Track.html","supports":"NeurIPS 2024 공식 출판 및 97개 과제·629개 보안 시험 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w13-p03","week":13,"role":"참고","title":"HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal","authors":"Mazeika, Mantas; Phan, Long; Yin, Xuwang; Zou, Andy; Wang, Zifan; Mu, Norman; Sakhaee, Elham; Li, Nathaniel; Basart, Steven; Li, Bo; Forsyth, David; Hendrycks, Dan","year":2024,"venue":"Proceedings of the 41st International Conference on Machine Learning, PMLR 235, 35181–35224","citation":"Mazeika, Mantas; Phan, Long; Yin, Xuwang; Zou, Andy; Wang, Zifan; Mu, Norman; Sakhaee, Elham; Li, Nathaniel; Basart, Steven; Li, Bo; Forsyth, David; Hendrycks, Dan (2024). HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal. Proceedings of the 41st International Conference on Machine Learning, PMLR 235, 35181–35224. https://proceedings.mlr.press/v235/mazeika24a.html","landingUrl":"https://proceedings.mlr.press/v235/mazeika24a.html","pdfUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PMLR 공식 출판판. https://proceedings.mlr.press/pmlr-license-agreement.html 은 논문을 CC BY 4.0으로 공개하며 원출판 인용과 PMLR 원문 링크를 요구한다. 원저자·논문명·출판처·라이선스를 표시해 재배포 가능.","sourceVersion":"ICML 2024 PMLR 공식 출판 PDF","readScope":"full_text","summary":{"question":"자동화된 레드팀과 LLM 거부 방어를 비교 가능한 방식으로 평가할 수 있는가?","background":"연구마다 유해 행동 목록·성공 기준·평가 예산이 달라 공격 성능을 곧바로 비교하기 어렵다. 경고 문장이 들어 있어도 실제 요청을 수행했다면 거부로 볼 수 없다.","method":"행동 분류, 시험 입력 생성, 모델 응답 생성, 응답의 목표 수행 여부 판정으로 평가 절차를 통일한다. 18개 레드팀 방법과 33개 모델·방어를 비교하고, 기존 공격 시험을 재사용하는 R2D2 적대적 학습으로 방어 개선도 평가한다.","findings":"모델과 공격 조합에 따라 저항성이 달랐고, 표준화된 판정은 단순 거부 문구 검사보다 행동 수행을 구별하는 데 유용했다. 제안된 학습은 여러 공격에 대한 강건성을 개선했지만 학습 때 사용한 유형과 다른 공격에서는 개선 폭이 달랐다.","limitations":"행동 목록과 자동 판정기의 오류·가치 기준에 결과가 의존한다. 낮은 ASR은 모든 현실적 피해나 정상 요청의 과잉 거부를 포괄하는 안전 인증이 아니며 별도 효용 평가가 필요하다.","significance":"공격과 방어가 같은 기준으로 발전하도록 평가 절차와 공개 비교 기준을 제공한다.","beginnerExplanation":"어떤 문제를 냈고 답을 어떻게 채점했는지가 같아야 시험 점수를 비교할 수 있다. 위험 요청을 거절하는 능력도 공통 시험과 채점 기준이 필요하다는 연구다."},"readingGuide":["3절의 행동 범주와 시험·응답·판정 단계를 분리해 정리한다.","표의 ASR을 모델·공격·예산·판정 기준과 함께 읽는다.","R2D2 결과에서 학습 공격과 다른 공격으로의 일반화를 확인한다."],"discussion":["자동 판정기가 거부와 유해 요청 수행을 혼동하면 순위는 어떻게 변하는가?","벤치마크 개선과 실제 배포 위험 감소를 연결하려면 어떤 시험이 더 필요한가?"],"terms":[{"term":"Red teaming","ordinaryMeaning":"상대편 역할로 취약점 찾기","etymology":"red team은 훈련에서 상대편을 맡는 팀이라는 표현이다.","aiMeaning":"시스템의 실패·오용 가능성을 체계적으로 탐색하는 평가 활동이다.","paperReading":"단일 공격문보다 비교 가능한 탐색·판정 절차가 핵심이다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"},{"term":"Robust refusal","ordinaryMeaning":"쉽게 흔들리지 않는 거절","etymology":"robust(견고한)+refusal(거부)의 결합이다.","aiMeaning":"입력 방식이 바뀌어도 금지된 요청을 수행하지 않는 성질이다.","paperReading":"거부 문구 유무보다 실제 행동 수행을 확인한다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"},{"term":"Benchmark","ordinaryMeaning":"비교의 기준점","etymology":"측량의 고정 기준 표시에서 성능 비교 기준으로 확장됐다.","aiMeaning":"여러 시스템을 같은 과제·조건·지표로 비교하는 평가 틀이다.","paperReading":"행동 목록·판정기·공격 예산을 함께 고정해야 한다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"},{"term":"Test case","ordinaryMeaning":"시험할 사례","etymology":"test(시험)+case(사례)의 결합이다.","aiMeaning":"특정 행동을 유도하거나 검증하도록 구성한 평가 입력과 조건이다.","paperReading":"유해 행동 목표와 그 목표를 시험하는 입력 문장을 구분한다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"},{"term":"Classifier","ordinaryMeaning":"분류하는 도구","etymology":"classify(분류하다)+-er(수행 주체)의 단어 형성이다.","aiMeaning":"입력이나 출력을 미리 정한 범주로 판정하는 모델이다.","paperReading":"안전성 판정기 자체의 오탐과 누락이 ASR에 영향을 준다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"},{"term":"Adversarial training","ordinaryMeaning":"실패 사례를 포함한 훈련","etymology":"대립적인 사례와 맞서 훈련한다는 설명적 표현이다.","aiMeaning":"적대적 입력에서 원하는 행동을 하도록 모델을 학습시키는 방법이다.","paperReading":"R2D2는 평가용 공격을 방어 학습에 연결하되 미관찰 공격 일반화도 확인한다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf"}],"evidence":[{"url":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/mazeika24a/mazeika24a.pdf","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 3050143 bytes; SHA-256 6b87608143d17d5b2ae4f26f06892f41a2d2a356f83091d6f4920392e5dba56b","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/v235/mazeika24a.html","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://www.harmbench.org/","supports":"저자 공식 프로젝트 설명 및 표준 평가 절차","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/pmlr-license-agreement.html","supports":"PMLR 저자 출판 동의의 CC BY 4.0 및 출처 링크 요구","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-13/w13-p03_harmbench.pdf"},{"id":"w14-p01","week":14,"role":"발표","title":"Stealing Part of a Production Language Model","authors":"Carlini, Nicholas; Paleka, Daniel; Dvijotham, Krishnamurthy Dj; Steinke, Thomas; Hayase, Jonathan; Cooper, A. Feder; Lee, Katherine; Jagielski, Matthew; Nasr, Milad; Conmy, Arthur; Wallace, Eric; Rolnick, David; Tramèr, Florian","year":2024,"venue":"Proceedings of the 41st International Conference on Machine Learning, PMLR 235, 5680–5705","citation":"Carlini, Nicholas; Paleka, Daniel; Dvijotham, Krishnamurthy Dj; Steinke, Thomas; Hayase, Jonathan; Cooper, A. Feder; Lee, Katherine; Jagielski, Matthew; Nasr, Milad; Conmy, Arthur; Wallace, Eric; Rolnick, David; Tramèr, Florian (2024). Stealing Part of a Production Language Model. Proceedings of the 41st International Conference on Machine Learning, PMLR 235, 5680–5705. https://proceedings.mlr.press/v235/carlini24a.html","landingUrl":"https://proceedings.mlr.press/v235/carlini24a.html","pdfUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"PMLR 공식 출판판. https://proceedings.mlr.press/pmlr-license-agreement.html 의 CC BY 4.0 조건에 따라 원출판 인용·원문 링크·라이선스 표시와 함께 재배포 가능.","sourceVersion":"ICML 2024 PMLR 공식 출판 PDF; 이후 수정 arXiv판과 저자 목록을 구분","readScope":"full_text","summary":{"question":"출력만 제공하는 상용 언어모델 API에서도 내부 가중치의 일부를 추론할 수 있는가?","background":"모델 가중치를 공개하지 않아도 API 출력의 수학적 구조에는 내부 차원에 관한 정보가 남는다. 기능을 모방하는 복제와 정확한 파라미터 일부 회수는 서로 다른 목표다.","method":"마지막 선형층이 은닉 표현을 어휘 점수로 사상하는 구조와 저차원성을 분석한다. 출력 점수 접근 조건별 식별 가능성을 정리하고, 통제된 모델과 승인된 상용 API 실험에서 차원 및 마지막 투영층 회수를 평가하며 완화책의 비용을 논의한다.","findings":"연구 당시 일부 API 조건에서는 내부 차원과 마지막 투영층의 정보를 회수할 수 있었다. 결과는 모델 전체의 복제가 아니며 행렬의 동일한 입출력을 만드는 대칭성 범위까지 고려해야 한다. 공개 출력 정보를 줄이는 방어는 유용한 API 기능과 절충한다.","limitations":"사용 가능한 점수·API 기능·수치 정밀도와 구조적 가정에 의존한다. 다른 층 전체를 회수했다고 주장하지 않으며 책임 있는 공개 후 적용된 방어 때문에 당시 결과가 현재 서비스에 그대로 성립한다고 볼 수 없다.","significance":"지식재산 보호에서 API가 노출하는 숫자와 기능도 정보 유출 표면이라는 점을 보여 준다.","beginnerExplanation":"닫힌 기계라도 여러 입력에 대한 계기판 숫자를 보면 마지막 부품의 구조를 일부 추정할 수 있다. 기계 전체를 복제한 것과는 구분해야 한다."},"readingGuide":["1·3절에서 전체 모델 추출과 마지막 층 추출을 구분한다.","실험의 API 접근 가정과 회수 가능한 대칭성 범위를 확인한다.","8절에서 출력 제한·잡음·사용량 통제의 효용 손실을 비교한다."],"discussion":["확률 점수를 제공하는 편익과 내부 정보 노출 위험은 어떻게 절충할 것인가?","공격 비용을 돈·질의 수·시간·허용 권한으로 나누면 평가가 어떻게 달라질까?"],"terms":[{"term":"Model extraction","ordinaryMeaning":"모델을 밖으로 꺼냄","etymology":"extract(꺼내다)를 모델 정보 회수에 적용한 말이다.","aiMeaning":"모델의 기능·구조·파라미터를 외부 관측으로 복원하는 공격 범주다.","paperReading":"이 논문은 전체 모델이 아니라 마지막 층의 정보 회수를 주장한다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"},{"term":"Black box","ordinaryMeaning":"내부가 보이지 않는 상자","etymology":"상자의 내부를 보지 않고 입출력만 보는 비유다.","aiMeaning":"내부 구조나 가중치를 직접 보지 못하는 접근 조건이다.","paperReading":"블랙박스라도 출력 점수와 API 제어 범위는 다를 수 있다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"},{"term":"Logit","ordinaryMeaning":"확률로 바꾸기 전 점수","etymology":"logit은 통계에서 로그 오즈를 뜻하며 신경망의 변환 전 점수에도 쓰인다.","aiMeaning":"softmax 이전의 실수 점수로 출력 분포를 결정한다.","paperReading":"노출되는 점수 벡터의 구조가 내부 투영층에 관한 정보를 담는다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"},{"term":"Projection layer","ordinaryMeaning":"다른 공간으로 옮기는 층","etymology":"projection(투영)을 벡터 공간 사이의 사상에 적용한 말이다.","aiMeaning":"은닉 벡터를 출력 어휘 공간의 점수로 변환하는 층이다.","paperReading":"회수 대상은 마지막 선형 사상이며 입력 임베딩 전체와 혼동하지 않는다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"},{"term":"Rank","ordinaryMeaning":"순위·차원상의 등급","etymology":"일반적인 등급이라는 단어가 선형대수의 독립 차원 수로 쓰인다.","aiMeaning":"행렬에서 독립적인 행 또는 열 방향의 수다.","paperReading":"큰 어휘 점수 공간 안의 더 작은 은닉 차원을 알아내는 수학적 단서다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"},{"term":"Symmetry","ordinaryMeaning":"변환해도 유지되는 대칭","etymology":"수학에서 변환 뒤에도 관측 구조가 유지되는 성질을 뜻한다.","aiMeaning":"서로 다른 파라미터 표현이 같은 모델 기능을 만드는 자유도다.","paperReading":"회수한 행렬이 원래 바이트와 같지 않아도 동등한 정보를 가질 수 있다.","sourceUrl":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf"}],"evidence":[{"url":"https://raw.githubusercontent.com/mlresearch/v235/main/assets/carlini24a/carlini24a.pdf","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 775928 bytes; SHA-256 f529f6f6f86d3fb7c09240084ef5e00e590b725f03da05ca58cc531d05a2caa3","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/v235/carlini24a.html","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://proceedings.mlr.press/pmlr-license-agreement.html","supports":"PMLR CC BY 4.0 출판 조건","accessedDate":"2026-10-12"}],"corrections":"PMLR 공식 출판판의 13명 저자 목록을 사용했다. 이후 arXiv v2에는 추가 저자가 있으므로 출판판 서지와 섞지 않았다.","sitePdfUrl":"papers/week-14/w14-p01_stealing-part.pdf"},{"id":"w14-p02","week":14,"role":"발표","title":"\"Real Attackers Don't Compute Gradients\": Bridging the Gap Between Adversarial ML Research and Practice","authors":"Apruzzese, Giovanni; Anderson, Hyrum S.; Dambra, Savino; Freeman, David; Pierazzi, Fabio; Roundy, Kevin A.","year":2023,"venue":"Proceedings of the 1st IEEE Conference on Secure and Trustworthy Machine Learning (SaTML)","citation":"Apruzzese, Giovanni; Anderson, Hyrum S.; Dambra, Savino; Freeman, David; Pierazzi, Fabio; Roundy, Kevin A. (2023). \"Real Attackers Don't Compute Gradients\": Bridging the Gap Between Adversarial ML Research and Practice. Proceedings of the 1st IEEE Conference on Secure and Trustworthy Machine Learning (SaTML). https://arxiv.org/abs/2212.14315","landingUrl":"https://arxiv.org/abs/2212.14315","pdfUrl":"https://arxiv.org/pdf/2212.14315","downloadStatus":"downloaded","redistribution":"restricted","licenseNote":"https://arxiv.org/abs/2212.14315v1 의 Rights to this article 링크는 CC BY-NC-SA 4.0(https://creativecommons.org/licenses/by-nc-sa/4.0/)이다. 이 arXiv판은 저자·출처·라이선스 표시를 하고 비상업적 조건을 지킬 때 공유 가능하며, 개작물에는 동일조건변경허락이 필요하다. 상업적 재사용은 이 허가 범위로 단정하지 않는다.","sourceVersion":"arXiv:2212.14315v1, 2022-12-29; IEEE SaTML 2023 공개 저자판","readScope":"full_text","summary":{"question":"적대적 ML 연구의 실험 성과가 실제 보안 운영의 문제와 왜 어긋나는가?","background":"현실의 공격자는 모델 하나보다 전체 시스템을 상대하며 성공 가능성과 비용을 함께 본다. 연구는 종종 모델의 미분 가능성이나 제한된 입력 교란에 집중한다.","method":"실제 보안 운영의 세 가지 사례와 주요 보안 학회 논문 검토를 결합한 입장 논문이다. 모델과 시스템의 경계, 공격자 목표·지식·권한, 질의 및 사람의 노동 비용, 재현성과 산업 협력의 문제를 비교한다.","findings":"실용적인 우회는 복잡한 최적화 없이도 가능하며 질의 수만으로 비용을 나타내기 어렵다. 논문은 정밀한 용어, 시스템 전체의 위협 모델, 비용 중심 평가, 재현 가능한 연구와 현장 협력을 제안한다.","limitations":"제목을 “현실에서 기울기 공격은 절대 없다”는 정리로 읽으면 안 된다. 사례와 검토 범위에 기반한 주장이고, 관측되지 않은 공격이나 사고 포렌식의 부족은 불확실성으로 남는다.","significance":"학술 벤치마크 결과를 실무 통제와 보안 시험·인증 증거로 옮길 때 필요한 검증 질문을 제공한다.","beginnerExplanation":"금고 자물쇠가 정교해도 창문이 열려 있으면 도둑은 창문을 택할 수 있다. 모델의 수학적 약점뿐 아니라 실제 시스템과 공격자의 비용을 함께 보자는 논문이다."},"readingGuide":["II절에서 ML 모델과 ML 시스템의 범위를 구분한다.","III절 사례가 깨뜨리는 연구 가정을 한 가지씩 찾는다.","V절 제안을 자신의 프로젝트 위협 모델·비용표·재현 계획에 적용한다."],"discussion":["우리 실험에서 허용한 입력 수정이 현실 시스템에서도 가능한가?","질의 수가 적지만 숙련자의 노동이 많이 드는 공격을 어떻게 비교할까?"],"terms":[{"term":"Gradient","ordinaryMeaning":"기울기","etymology":"수학의 경사·변화 방향을 뜻하는 용어다.","aiMeaning":"입력이나 파라미터의 변화에 따른 목적함수 변화 방향을 나타낸다.","paperReading":"제목은 모든 실제 공격을 기울기 최적화로 설명하는 관행을 비판한다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"},{"term":"Threat model","ordinaryMeaning":"위협의 모형","etymology":"위협과 그 상황을 단순화한 모형의 결합이다.","aiMeaning":"보호 대상과 공격자의 목표·지식·권한을 명시한 설명이다.","paperReading":"모델 수준의 가정뿐 아니라 주변 시스템의 권한과 경로까지 포함해야 한다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"},{"term":"Attack surface","ordinaryMeaning":"공격에 노출된 표면","etymology":"물체의 노출 면을 시스템의 접점에 빗댔다.","aiMeaning":"외부 입력이나 권한이 시스템에 영향을 줄 수 있는 접점들의 집합이다.","paperReading":"전처리·입력 수집·운영 절차가 모델 자체보다 쉬운 경로일 수 있다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"},{"term":"Cost-driven","ordinaryMeaning":"비용을 기준으로 이끌림","etymology":"cost(비용)+driven(주도되는)의 합성이다.","aiMeaning":"성공률과 함께 돈·시간·연산·숙련 노동 등을 고려하는 평가 관점이다.","paperReading":"질의 횟수 하나로 공격자 부담을 대표하지 않는다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"},{"term":"Reproducibility","ordinaryMeaning":"다시 만들어 확인할 수 있음","etymology":"re-(다시)+produce(만들다)+-ibility(가능성)의 결합이다.","aiMeaning":"명시된 자료·설정·절차로 연구 결과를 다시 확인할 수 있는 성질이다.","paperReading":"실무와 학계가 주장과 가정을 검증하는 공동 기반이 된다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"},{"term":"Forensics","ordinaryMeaning":"사건 흔적을 조사함","etymology":"법정·사건 조사와 관련된 용어가 디지털 조사로 확장됐다.","aiMeaning":"사고 후 증거로 원인·행위·영향을 분석하는 활동이다.","paperReading":"기울기 사용이 관측되지 않았다는 사실과 사용되지 않았다는 사실을 구별한다.","sourceUrl":"https://arxiv.org/pdf/2212.14315"}],"evidence":[{"url":"https://arxiv.org/pdf/2212.14315","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 1626079 bytes; SHA-256 c946a01f8d97aadd801294e87f98b855b911898be296b79994ec81ebdf8a640c","accessedDate":"2026-10-12"},{"url":"https://arxiv.org/abs/2212.14315","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://real-gradients.github.io/","supports":"저자 공식 프로젝트의 SaTML 2023 서지와 다섯 가지 입장 확인","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w14-p03","week":14,"role":"보충","title":"Instructional Fingerprinting of Large Language Models","authors":"Xu, Jiashu; Wang, Fei; Ma, Mingyu; Koh, Pang Wei; Xiao, Chaowei; Chen, Muhao","year":2024,"venue":"Proceedings of NAACL-HLT 2024, Volume 1: Long Papers, 3277–3306","citation":"Xu, Jiashu; Wang, Fei; Ma, Mingyu; Koh, Pang Wei; Xiao, Chaowei; Chen, Muhao (2024). Instructional Fingerprinting of Large Language Models. Proceedings of NAACL-HLT 2024, Volume 1: Long Papers, 3277–3306. https://doi.org/10.18653/v1/2024.naacl-long.180","landingUrl":"https://aclanthology.org/2024.naacl-long.180/","pdfUrl":"https://aclanthology.org/2024.naacl-long.180.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"https://aclanthology.org/2024.naacl-long.180/ 하단은 2016년 이후 ACL 자료를 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 명시한다. 저자·원출판·라이선스를 표시하여 공식 PDF 재배포 가능.","sourceVersion":"ACL Anthology 공식 출판판, 2024.naacl-long.180","readScope":"full_text","summary":{"question":"언어모델이 재사용·미세조정된 뒤에도 원래 모델의 출처를 확인할 표식을 남길 수 있는가?","background":"학습 비용이 큰 모델은 파생 모델의 출처와 라이선스 준수를 확인할 필요가 있다. 자연어 생성 모델에서는 출력 텍스트 워터마크와 모델 자체의 소유권 표식을 구별해야 한다.","method":"비공개 입력과 정해진 응답의 쌍을 소량의 지시 학습으로 모델에 심는다. 일반 미세조정형과 임베딩 중심의 어댑터형을 비교하고, 여러 모델·후속 학습·일반 과제에서 표식의 지속성·정상 성능·추측 가능성을 평가한다.","findings":"시험한 모델과 학습 조건에서 적은 학습 비용으로 표식을 보존하면서 정상 과제 성능을 대체로 유지했다. 여러 단계의 표식도 가능했으나 검증 방식에 따라 모델 내부 접근이 필요할 수 있고, 표식 관측만으로 법적 소유권이 자동 확정되는 것은 아니다.","limitations":"인과적 지속성 설명과 모든 제거 공격에 대한 보장은 제공하지 않는다. 정규화 자료의 비율은 고정되어 있으며, 허위 소유권 주장을 줄이기 위한 신뢰할 제3자 가정에는 실무·법적 문제가 남는다.","significance":"백도어와 유사한 기술이 출처 확인에 사용될 때도 오탐·과잉 주장·검증 권한을 함께 설계해야 함을 보여 준다.","beginnerExplanation":"책의 비공개 위치에 고유 표식을 넣어 복사된 책의 출처를 확인하는 것과 비슷하다. 다만 표식을 넣었다는 주장 자체도 믿을 만하게 검증되어야 한다."},"readingGuide":["2절의 여섯 가지 표식 요구사항을 먼저 읽는다.","3절의 두 학습·검증 방식이 요구하는 접근권을 비교한다.","4절 결과와 Limitations·부록 C의 허위 주장 방지를 함께 읽는다."],"discussion":["모델 출처의 기술적 증거와 법적 권리 판단은 어디서 분리되는가?","방어 목적의 표식도 보안 감사와 이용자 고지가 필요한가?"],"terms":[{"term":"Fingerprint","ordinaryMeaning":"손가락 지문","etymology":"개체 식별에 쓰는 지문을 디지털 출처 표식에 빗댔다.","aiMeaning":"모델의 동일성이나 파생 관계를 확인하는 특징 또는 심어진 표식이다.","paperReading":"텍스트가 AI 생성인지 표시하는 워터마크와 모델 소유권 표식을 구분한다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"},{"term":"Instruction tuning","ordinaryMeaning":"지시를 따르도록 맞춤 학습","etymology":"instruction(지시)+tuning(조정)의 결합이다.","aiMeaning":"지시와 원하는 응답 쌍으로 모델의 응답 행동을 미세조정하는 학습이다.","paperReading":"작은 지시형 자료가 표식을 지속시키는 수단으로 사용된다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"},{"term":"Private key","ordinaryMeaning":"비공개 열쇠","etymology":"열쇠를 접근·검증 조건에 빗댄 표현이다.","aiMeaning":"이 논문에서는 표식을 활성화하는 비공개 입력 문자열이다.","paperReading":"공개키 암호의 수학적 비밀키와 같은 보장을 자동으로 갖는 것은 아니다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"},{"term":"Persistence","ordinaryMeaning":"계속 남아 있음","etymology":"persist(지속하다)의 명사형이다.","aiMeaning":"추가 학습이나 변환 뒤에도 표식·행동이 유지되는 성질이다.","paperReading":"시험한 후속 미세조정에서의 보존과 모든 변경에 대한 보장을 구분한다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"},{"term":"Publisher overclaim","ordinaryMeaning":"배포자의 과도한 권리 주장","etymology":"publisher(발행·배포자)+overclaim(과장 주장)의 결합이다.","aiMeaning":"실제로 소유하거나 학습하지 않은 모델까지 자신의 것이라고 주장하는 문제다.","paperReading":"표식 검증에는 공격받는 배포자뿐 아니라 부정직한 주장자도 고려한다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"},{"term":"Adapter","ordinaryMeaning":"서로 맞추는 연결 장치","etymology":"adapt(맞추다)+-er의 결합이다.","aiMeaning":"원 모델의 일부만 바꾸거나 추가 모듈로 학습을 조정하는 구성이다.","paperReading":"어댑터형 표식의 검증 권한과 일반 응답만 보는 검증을 동일시하면 안 된다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180.pdf"}],"evidence":[{"url":"https://aclanthology.org/2024.naacl-long.180.pdf","supports":"본문의 문제·방법·결과·제약 확인. PDF 시그니처 및 본문 추출 확인; 3766042 bytes; SHA-256 6877e5a7fdec9f218d6eb17ff1d704a1b42255fbb4b56095a2f8c52163d073fd","accessedDate":"2026-10-12"},{"url":"https://aclanthology.org/2024.naacl-long.180/","supports":"제목·저자·버전·공개 원문 위치 확인","accessedDate":"2026-10-12"},{"url":"https://aclanthology.org/2024.naacl-long.180/","supports":"공식 저자·제목·학회·쪽수와 2016년 이후 자료의 CC BY 4.0 안내","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":"papers/week-14/w14-p03_instructional-fingerprinting.pdf"}],"foundations":{"course":{"title":"AI Security & Ethics · 처음 읽는 대학원 핸드북","description":"윤리와 보안을 함께 공부하며 논문의 주장, 가정, 실험, 한계를 스스로 판단하는 15주 학습 안내서. 강의계획서의 순서를 유지하고, 어려운 영어 표현을 일상어와 작은 예제로 풀었습니다.","audience":"AI 보안·윤리를 처음 접하는 대학원생. 확률·선형대수·파이썬은 처음부터 완벽할 필요가 없으며, 필요한 개념을 각 주차 준비 항목에서 확인합니다.","schedule":"일반 수업 주차: 강의 60분 + 논문 발표·토론 120분. 8주차: 1~7주차 중간고사 90분 및 개인 프로젝트 계획(안), 1인 발표 15분 + 질의·응답 10분. 15주차: 기말고사 대체 최종 프로젝트 발표 15분 + 질의·동료 평가 10분. 최종 보고서: 발표 후 1주 이내. 수강 인원에 따라 14주차 후반부에 최종 발표를 추가 배정할 수 있습니다.","disclaimer":"아래 준비·실습·퀴즈·리뷰 양식은 이해를 돕는 보조 학습 제안입니다. 담당 교수의 확정 과제나 채점 배점이 아닙니다. 실제 제출 형식·배점·일정 변경은 수업 공지를 우선합니다. 법·표준 정보는 2026-10-12에 확인한 교육용 개요로, 개별 사안에 대한 법률 자문이나 인증 판정이 아닙니다.","readingWorkflow":["1차, 10~15분: 제목·초록·서론·결론과 그림을 보고 문제, 핵심 주장, 적용 대상을 세 문장으로 적습니다. 모르는 단어 때문에 첫 페이지에서 멈추지 않습니다.","2차, 30~45분: 데이터와 모델, 위협 모델, 비교 기준, 평가 지표를 표처럼 나란히 적습니다. 결과 그림 한 개를 골라 가로축·세로축·분모·오차 막대를 설명합니다.","3차, 45~90분: 주장을 지지하는 핵심 방법과 실험을 읽습니다. 수식은 기호의 뜻, 입력, 출력, 최적화 대상 순으로 번역합니다. 모든 증명을 한 번에 완주할 필요는 없습니다.","주장 카드: “어떤 조건에서, 무엇을 바꾸었더니, 무엇이 얼마만큼 달라졌는가?”를 쓰고 바로 옆에 그림·표·절 번호를 붙입니다. 요약에 없는 숫자는 추정하지 않습니다.","비판 카드: 강점 하나, 결론을 바꿀 수 있는 가정 하나, 추가 실험 하나를 적습니다. 한계를 발견하는 것과 연구 전체를 무가치하다고 판단하는 것은 다릅니다.","발표 전: 낯선 용어 5개를 일상어로 설명하고, 표 하나를 원문 없이 재설명합니다. 초록만 읽은 부분·부록을 확인하지 못한 부분은 정직하게 표시합니다."],"sourceNote":"강의 내용은 업로드된 15주 강의계획서를 기준으로 재구성한 독자적 학습 설명입니다. 영어 어원 칸은 확인되지 않은 라틴어 기원을 추정하지 않고, 약어의 정식 명칭·영어 합성 구조·학습용 비유를 구분합니다. 용어의 sourceUrl은 주로 AI·연구 문맥의 원전이며 역사언어학적 어원 사전이 아닙니다.","prerequisites":[{"title":"확률 문장을 읽기","explanation":"P(예측=1 | 실제=1)은 실제 양성인 사람만 모았을 때 예측도 양성인 비율입니다. 세로 막대 | 는 “~라는 조건 아래”입니다. 공정성·프라이버시 논문의 분모를 확인하는 데 필요합니다."},{"title":"벡터·기울기 감각","explanation":"벡터는 숫자 묶음, 기울기는 입력이나 가중치를 조금 바꾸었을 때 값이 어느 방향으로 얼마나 변하는지 나타내는 정보입니다. 화살표 감각으로 먼저 이해한 뒤 미분 계산을 따라갑니다."},{"title":"학습·검증·시험 구분","explanation":"학습 세트로 가중치를 정하고, 검증 세트로 설정을 고르며, 시험 세트는 최종 확인에 남겨 둡니다. 시험 결과를 보고 계속 고치면 시험 세트도 사실상 개발에 사용한 것입니다."},{"title":"윤리 문제를 실험 문제로 바꾸기","explanation":"“공정해야 한다”를 곧바로 점수 하나로 바꾸지 않습니다. 영향을 받는 사람, 실제 피해, 어떤 오류를 줄일지, 측정할 수 없는 부분을 먼저 적습니다."}]},"weeks":[{"week":1,"title":"AI 윤리·보안의 지도 만들기","objectives":["윤리·안전·보안이 다루는 질문과 겹치는 지점을 설명한다.","위험을 자산·피해자·발생 조건·영향으로 나누어 쓴다.","논문 주장과 근거를 연결하는 리뷰의 기본 형식을 익힌다."],"plainLesson":"AI는 모델 하나가 아니라 데이터 수집, 학습, 사용자 화면, 운영 규칙, 사람의 결정이 연결된 시스템입니다. 같은 언어 모델도 일기 작성 도우미와 채용 평가 도구에 쓰일 때 위험이 달라집니다. 그래서 “이 모델은 안전한가?”보다 “누가, 어디서, 무엇을 위해 사용하고, 실패하면 누가 피해를 보는가?”가 첫 질문입니다.\n\n윤리는 무엇을 바람직하게 설계하고 누구에게 책임질지 묻습니다. 보안은 누군가 의도적으로 시스템을 악용하거나 훼손할 때 무엇을 지킬지 묻습니다. 안전은 의도적 공격이 없어도 생길 수 있는 피해까지 포함합니다. 기밀성은 허가받지 않은 노출 방지, 무결성은 부당한 변경 방지, 가용성은 필요할 때 쓸 수 있는 상태입니다. 공정한 채용 모델도 개인정보를 흘릴 수 있고, 접근 통제가 강한 모델도 차별적인 결과를 낼 수 있습니다.\n\n위험 프레임워크는 정답을 자동으로 내는 채점표가 아니라 놓친 질문을 찾는 지도입니다. NIST AI RMF의 Govern·Map·Measure·Manage는 거버넌스, 맥락 파악, 측정, 대응을 계속 연결하는 기능입니다. ISO의 위험관리 안내, MITRE ATLAS의 공격 지식, OWASP의 애플리케이션 위험 목록은 서로 다른 수준의 질문을 돕습니다. 목록에 항목이 있다는 사실과 그 위험이 우리 시스템에서 실제로 발생한다는 증거를 구분해야 합니다.\n\n오늘부터 모든 논문에 문제, 가정, 방법, 근거, 한계의 다섯 칸을 만듭니다. “성능이 좋다”는 주장 옆에는 어떤 데이터와 지표에서 좋았는지 써야 합니다. 논문 발표는 전문용어를 많이 아는 모습을 보이는 시간이 아니라 다른 사람이 같은 증거를 따라가게 만드는 시간입니다.","preparation":["분류 모델의 입력·정답·예측이 무엇인지 확인한다.","최근 본 AI 서비스 하나를 골라 사용자와 영향을 받는 비사용자를 구분한다."],"practice":{"title":"가상의 대학 FAQ 도우미 위험 지도","steps":["학생·교직원·운영자·외부 문서 제공자를 적는다.","잘못된 마감일 안내, 개인정보 노출, 악성 문서 참조 등 실패 가능성을 나눈다.","각 실패의 피해, 발생 조건, 확인할 증거, 담당자를 한 줄씩 적는다.","예방 통제 하나와 실패 후 복구 방법 하나를 짝짓는다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Risk","Threat model","Confidentiality","Integrity","Availability","Governance"],"assignment":"학습용: 관심 서비스 하나의 위험 지도 1쪽과 연구하고 싶은 질문 2개를 작성합니다.","quiz":[{"question":"AI 시스템의 위험을 판단할 때 가장 먼저 확인할 것은?","choices":["모델 이름의 길이","사용 맥락과 영향을 받는 사람","논문의 인용 수만","GPU 제조사만"],"answer":1,"explanation":"위험은 사용 목적·사람·환경에 따라 달라집니다. 같은 모델이라는 이유로 같은 위험 판정을 적용할 수 없습니다."},{"question":"기밀성에 가장 가까운 사례는?","choices":["외부인이 비공개 상담 기록을 읽지 못하게 한다","서버 응답 시간을 줄인다","정확도를 높인다","학습 속도를 높인다"],"answer":0,"explanation":"기밀성은 권한 없는 정보 노출을 막는 성질입니다. 응답 가능성은 가용성에 가깝습니다."},{"question":"논문에서 “안전성이 개선되었다”를 읽은 뒤 가장 좋은 질문은?","choices":["저자 수가 몇 명인가?","제목이 긴가?","어떤 위협·지표·시험 조건에서 개선되었는가?","유명 기관이므로 생략해도 되는가?"],"answer":2,"explanation":"범위와 측정 조건이 있어야 주장과 증거를 연결할 수 있습니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2112.04359","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":2,"title":"공정성 I · 같은 대우의 여러 뜻","objectives":["혼동행렬에서 TPR·FPR과 선택률을 계산한다.","Demographic Parity·Equalized Odds·Equal Opportunity·Calibration을 구분한다.","공정성 지표 선택에 가치 판단과 가정이 들어감을 설명한다."],"plainLesson":"두 집단에서 각각 100명을 선발한다고 해 봅시다. 선발 비율이 같으면 공정할까요? 실제로 기준을 충족한 지원자를 놓치는 비율이 같아야 할까요? 합격 확률이 80%라는 점수가 두 집단에서 똑같이 의미 있어야 할까요? 모두 그럴듯하지만 서로 다른 질문입니다. 공정성 지표는 “공정하다”의 유일한 번역이 아닙니다.\n\nDemographic Parity는 집단별 양성 예측 비율을 맞춥니다. Equalized Odds는 실제 결과를 조건으로 하여 TPR과 FPR을 모두 맞춥니다. Equal Opportunity는 그중 실제 양성에게 기회를 주는 TPR을 맞추는 완화된 조건입니다. 따라서 강의계획서의 “기회 균등(Equalized Odds)”는 용어를 나누어 읽어야 합니다. TPR이 같아도 FPR이 다르면 Equal Opportunity는 만족할 수 있으나 Equalized Odds는 만족하지 않습니다. 한국어 번역이 엇갈릴 때는 영어와 수식을 함께 적습니다.\n\nCalibration은 점수 0.8을 받은 사례 중 실제 양성이 대략 80%인지를 묻습니다. 선택률이나 오류율의 동등성과 별개입니다. 집단별 실제 양성률이 다르고 예측이 완벽하지 않은 등 특정 조건에서는 여러 공정성 요구를 동시에 만족시킬 수 없다는 결과가 있습니다. 이를 “공정한 AI는 불가능하다”로 확대하면 안 됩니다. 정리의 가정과 대상 지표를 확인하고, 어떤 피해를 우선 줄일지 설명하는 근거로 사용합니다.\n\n편향은 데이터 양이 적어서만 생기지 않습니다. 과거의 불평등이 정답 라벨에 들어가거나, 만족도를 클릭 수로 잘못 측정하거나, 한 집단의 다양성을 평균에 가려 버릴 수 있습니다. 정답 Y 자체가 누구의 판단인지, 탈락한 사람의 결과를 관측하지 못했는지까지 살펴봐야 합니다. 숫자를 계산한 뒤에는 그 숫자가 실제 권리·기회·피해를 얼마나 대표하는지 다시 묻습니다.","preparation":["조건부 확률과 비율의 분모를 복습한다.","TP·FP·TN·FN을 2×2 표로 그려 본다."],"practice":{"title":"두 집단의 분모를 바꿔 보기","steps":["가상 집단 A는 실제 양성 50명 중 TP 40명, 실제 음성 50명 중 FP 10명으로 둔다.","집단 B는 실제 양성 20명 중 TP 16명, 실제 음성 80명 중 FP 24명으로 둔다.","A와 B의 TPR은 모두 0.8, FPR은 각각 0.2와 0.3인지 계산한다.","선택률은 A 0.5, B 0.4임을 확인하고 어떤 정의를 만족하는지 설명한다.","정답 라벨이 부당한 과거 결정을 반영한다면 무엇이 달라지는지 토론한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Demographic parity","Equalized odds","Equal opportunity","Calibration","Base rate","Counterfactual fairness"],"assignment":"학습용: 한 사례에서 우선할 공정성 정의와 포기하지 않을 보완 점검을 각각 적고 이유를 설명합니다.","quiz":[{"question":"Equalized Odds를 만족하려면 집단 간 무엇이 같아야 하는가?","choices":["TPR만","선택률만","TPR과 FPR 모두","표본 수만"],"answer":2,"explanation":"Equalized Odds는 실제 양성과 실제 음성을 나누어 두 조건의 양성 예측률을 모두 비교합니다."},{"question":"두 집단의 TPR이 같고 FPR이 다르다면?","choices":["Equal Opportunity는 만족할 수 있다","반드시 Equalized Odds를 만족한다","반드시 Calibration을 만족한다","아무것도 계산할 수 없다"],"answer":0,"explanation":"이진 분류에서 Equal Opportunity는 실제 양성의 TPR만 같으면 됩니다. FPR 차이는 Equalized Odds를 깨뜨립니다."},{"question":"불가능성 결과를 읽는 적절한 태도는?","choices":["모든 공정성 노력을 중단한다","지표 하나가 항상 정답이라고 정한다","정답 라벨의 사회적 의미는 무시한다","어떤 가정 아래 어떤 지표가 충돌하는지 확인한다"],"answer":3,"explanation":"정리의 적용 범위가 핵심입니다. 지표의 충돌은 가치 선택과 사용 맥락을 드러내는 출발점입니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/1610.02413","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1703.06856","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":3,"title":"공정성 II · 편향을 줄인다는 말의 증거","objectives":["전처리·학습 중·후처리 완화 방법의 차이를 구분한다.","인구통계 정보를 쓰지 않는 방법의 한계를 설명한다.","LLM 편향 벤치마크 점수를 사용 맥락과 연결해 해석한다."],"plainLesson":"편향 완화는 파이프라인의 어디를 바꾸는지에 따라 이해하면 쉽습니다. 전처리는 데이터를 다시 가중하거나 보완하고, 학습 중 방법은 손실함수나 제약에 공정성 조건을 넣으며, 후처리는 이미 나온 점수의 결정 기준을 조정합니다. 같은 이름의 “공정성 개선”도 어느 지표를 목표로 삼았는지에 따라 결과가 다릅니다. 정확도, 집단별 오류, 계산비용을 함께 비교해야 합니다.\n\n집단 정보를 모으지 않으면 차별이 사라질까요? 이름·지역·문체 같은 다른 변수가 집단과 관련될 수 있어 단순 삭제만으로 해결되지 않습니다. 또한 집단 정보가 없으면 어떤 집단이 피해를 보는지 감사하기도 어려워집니다. Fairness without Demographics 연구는 집단 라벨 없이 취약한 사례를 더 잘 다루는 가능성을 탐구하지만, 알려진 모든 사회 집단의 공정성을 자동 보장한다는 뜻은 아닙니다. 수집 필요성과 개인정보 보호를 함께 검토해야 합니다.\n\nLLM 편향 평가는 전통적인 분류보다 복잡합니다. 질문 문맥이 충분한지, 정답을 알 수 없을 때 “모른다”고 답하는지, 특정 집단에 대한 고정관념을 선택하는지를 볼 수 있습니다. BBQ 같은 벤치마크는 이런 행동을 구조화하지만, 언어·문화·질문 형식의 범위가 있습니다. 한 점수가 낮아졌다는 사실만으로 실제 상담이나 채용 서비스가 공정해졌다고 결론 내릴 수 없습니다.\n\n좋은 완화 실험은 바꾸기 전과 후를 같은 조건에서 비교하고, 유리한 평균뿐 아니라 가장 성능이 낮은 집단도 보여 줍니다. 학습 때의 분포와 배포 뒤의 분포가 달라지는 경우도 따로 확인합니다. 데이터가 적은 집단의 점수에는 큰 불확실성이 있다는 점을 함께 기록해야 합니다.","preparation":["2주차의 TPR·FPR·선택률을 다시 계산한다.","학습·검증·시험 세트를 섞으면 왜 문제가 되는지 설명한다."],"practice":{"title":"완화 방법을 비교하는 종이 실험","steps":["가상 대출 안내 분류기에 대해 기본 모델·데이터 재가중·임계값 조정의 세 열을 만든다.","각 방법이 바꾸는 대상과 필요한 정보, 예상 비용을 적는다.","공정성 지표 두 개와 전체 성능 지표 하나를 고른다.","집단별 표본 수와 최악 집단 성능을 기록하는 빈 결과표를 만든다.","다른 시기·다른 문체에서 성능을 확인할 추가 시험을 설계한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Reweighing","Threshold","Distribution shift","Benchmark","Bias","Adversarial debiasing"],"assignment":"학습용: 완화 알고리즘 한 개의 기대 효과·부작용·실패 가능한 조건을 한 문단씩 씁니다.","quiz":[{"question":"재가중(reweighing)은 보통 어느 단계의 완화인가?","choices":["배포 후 법률 자문","데이터 전처리","모델 파일 암호화","최종 보고서 작성"],"answer":1,"explanation":"학습 사례의 기여도를 조정하는 데이터 단계 방법으로 분류합니다."},{"question":"집단 속성을 데이터에서 지우면?","choices":["모든 편향이 제거된다","다른 변수의 대리 효과까지 사라진다","편향은 남을 수 있고 집단별 감사가 어려워질 수 있다","프라이버시가 수학적으로 보장된다"],"answer":2,"explanation":"다른 특성에 집단 정보가 남을 수 있습니다. 속성 삭제는 공정성이나 차분 프라이버시의 보장이 아닙니다."},{"question":"LLM 편향 벤치마크 개선 후 필요한 점검은?","choices":["평균 점수만 발표한다","실제 사용 언어·집단·상황에서도 유지되는지 본다","시험 세트를 학습에 추가한다","설명 없이 공정 인증을 붙인다"],"answer":1,"explanation":"벤치마크 범위 밖으로 결론을 확대하려면 추가 근거가 필요합니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2006.13114","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1908.09635","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://aclanthology.org/2022.findings-acl.165/","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":4,"title":"설명가능성 · 그럴듯한 이유와 실제 근거","objectives":["내재적 해석 모델과 사후 설명을 구분한다.","충실성·안정성·이해하기 쉬움을 별도로 평가한다.","특성 기여도와 인과적 설명이 같지 않음을 설명한다."],"plainLesson":"모델이 “이유는 A 때문입니다”라고 말했다고 해서 실제 계산도 A에 의존했다고 볼 수는 없습니다. 설명은 사람을 설득하는 이야기일 수도 있고, 모델의 동작을 검증하는 증거일 수도 있습니다. 이 수업에서는 읽기 쉬운 설명과 모델에 충실한 설명을 분리해서 봅니다. 중요한 결정을 다룰 때는 애초에 구조를 이해할 수 있는 모델을 선택할 가능성도 검토합니다.\n\nLIME은 한 입력 주변에서 단순한 근사 모델을 만들어 설명합니다. SHAP은 특징들의 기여를 배분하는 관점으로 특정 예측을 분석합니다. Integrated Gradients는 기준 입력에서 실제 입력까지의 경로에 따른 변화 정보를 누적합니다. 세 방법은 무엇을 기준으로 삼고 어떤 가정을 하느냐가 다릅니다. “나이가 중요한 특징”이라는 결과가 나왔다고 해서 나이를 바꾸면 현실의 결과가 반드시 그만큼 바뀐다는 인과적 결론은 나오지 않습니다.\n\n설명 평가에는 적어도 세 질문이 필요합니다. 중요한 특징을 없애면 모델 출력이 실제로 변하는가? 의미가 비슷한 입력에서 설명이 지나치게 흔들리지 않는가? 설명을 보는 사람이 과도한 확신 없이 적절히 판단할 수 있는가? 설명을 보기 좋게 만들어 부당한 모델을 정당화하는 fairwashing도 경계합니다.\n\n기계적 해석가능성은 모델 내부의 표현과 계산을 더 직접적으로 이해하려는 연구입니다. 프로빙은 내부 표현에서 정보를 읽을 수 있는지 시험하고, 개입은 그 표현을 바꿀 때 행동이 변하는지 확인합니다. 희소 오토인코더는 복잡한 활성화를 더 드물게 켜지는 특징으로 분해하려 합니다. 사람이 이름 붙이기 쉬운 특징이 나왔더라도 모델 전체를 완전히 이해했다거나 해당 특징이 유일한 원인이라고 단정하지 않습니다.","preparation":["선형 모델에서 계수와 입력이 예측에 어떻게 연결되는지 본다.","상관관계와 인과관계의 차이를 일상 사례로 설명한다."],"practice":{"title":"설명을 평가할 질문 만들기","steps":["가상 장학금 분류기가 학점·출석·우편번호를 사용한다고 설정한다.","“우편번호가 중요하다”라는 설명이 무엇을 뜻하고 뜻하지 않는지 적는다.","입력 일부를 바꾸는 시험, 비슷한 입력의 설명 비교, 사용자 이해도 확인을 각각 설계한다.","기준 입력이나 배경 데이터 선택에 따라 설명이 달라질 가능성을 기록한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Interpretability","Explainability","LIME","SHAP","Integrated gradients","Faithfulness","Sparse autoencoder"],"assignment":"학습용: 설명 그림 하나를 골라 “보여 주는 것·보장하지 않는 것·확인할 추가 실험”을 씁니다.","quiz":[{"question":"설명의 충실성(faithfulness)이 뜻하는 것은?","choices":["예쁜 디자인","모델의 실제 동작을 얼마나 반영하는가","문장이 얼마나 긴가","사용자가 무조건 믿는가"],"answer":1,"explanation":"충실성은 모델에 대한 정확한 설명인지의 문제입니다. 설득력이나 가독성과 별개입니다."},{"question":"SHAP의 특징 기여도가 높다는 사실만으로 말할 수 없는 것은?","choices":["해당 설명 설정에서 예측에 기여했다","다른 특징과 비교할 수 있다","그 특징이 현실 결과의 인과적 원인이다","배경 데이터 선택을 점검해야 한다"],"answer":2,"explanation":"특성 기여도는 모델과 설명 설정에 관한 값이며 현실의 인과효과를 자동 입증하지 않습니다."},{"question":"프로빙으로 내부 표현에서 정보가 읽혔다면?","choices":["모델이 반드시 그 정보를 사용했다","모델 전체를 해석했다","정보가 표현되어 있을 가능성을 보였고 사용 여부는 추가 검증이 필요하다","공격이 불가능해졌다"],"answer":2,"explanation":"정보의 존재와 행동에 대한 인과적 기여는 다른 주장입니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2103.11251","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1602.04938","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://papers.nips.cc/paper_files/paper/2017/hash/8a20a8621978632d76c43dfd28b67767-Abstract.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://proceedings.mlr.press/v70/sundararajan17a.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://proceedings.mlr.press/v80/kim18d.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://transformer-circuits.pub/2023/monosemantic-features/index.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":5,"title":"투명성·책임성 · 기록을 행동으로 연결하기","objectives":["Model Card·Datasheet·System Card의 대상을 구분한다.","감사 질문과 증거·책임자·시정 조치를 연결한다.","사고 대응을 개인 비난보다 시스템 개선 중심으로 설계한다."],"plainLesson":"투명성은 코드를 공개하거나 보고서를 길게 쓰는 것만으로 완성되지 않습니다. 사용자가 알아야 할 한계가 숨겨져 있지 않은지, 감사자가 결과를 확인할 수 있는지, 문제가 생겼을 때 누가 조치할 수 있는지가 중요합니다. 공개할 내용과 개인정보·보안을 위해 제한할 내용을 함께 결정해야 합니다.\n\nModel Card는 모델의 의도된 사용과 성능·한계를 정리하고, Datasheet는 데이터가 왜·어떻게 만들어졌는지 묻습니다. System Card는 모델과 도구·운영 정책을 포함하는 시스템 수준의 평가를 설명할 수 있습니다. AI-BOM은 데이터·모델·라이브러리 같은 구성요소의 출처와 버전을 추적하려는 접근입니다. 문서 이름만 갖췄다고 충분한 것은 아니며, 실제 운영 버전과 일치하는지 확인해야 합니다.\n\n감사는 주장과 증거 사이를 점검하는 과정입니다. “개인정보 보호”라는 원칙을 보았다면 어떤 정보가 어디로 가는지, 접근 권한과 로그가 있는지, 실패 사례에 대응했는지 살펴봅니다. 내부 감사는 개발 과정과 가까워 맥락을 알기 쉽고, 외부 감사는 독립성이 강점일 수 있지만 접근 범위가 제한될 수 있습니다. 인증이나 좋은 감사 결과도 평가한 시점·범위를 넘는 무결점 보증이 아닙니다.\n\n사고 대응에는 탐지, 영향 제한, 원인 조사, 회복, 재발 방지가 필요합니다. 한 사람의 실수를 찾는 데서 멈추지 않고 왜 그 실수가 피해로 이어졌는지 봅니다. 삭제·격리 등 조치 전에 필요한 증거를 안전하게 보존하고, 개인 정보를 보고서에 불필요하게 반복하지 않습니다. 책임성은 사후 사과뿐 아니라 사전에 결정권·중단권·연락 경로를 정해 두는 일입니다.","preparation":["사용 중인 모델과 이를 감싼 서비스의 차이를 적는다.","버전·로그·데이터 출처가 무엇을 재확인하게 해 주는지 생각한다."],"practice":{"title":"가상 모델 카드와 사고 기록","steps":["대학 FAQ 도우미의 사용 목적·금지 용도·대상 사용자·알려진 한계를 적는다.","각 주장에 필요한 시험 결과나 운영 기록을 연결한다.","잘못된 등록 마감일을 안내한 가상 사고의 시간순 사건을 쓴다.","즉시 조치·영구 개선·책임자·완료 확인 기준을 나눈다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Model card","Datasheet","Audit","Accountability","Transparency","AI-BOM","Incident response"],"assignment":"학습용: 모델 카드 초안 1쪽과 감사 질문 5개를 작성합니다. 확인하지 않은 항목은 빈칸 대신 “미확인”으로 표시합니다.","quiz":[{"question":"Datasheet가 주로 문서화하는 대상은?","choices":["데이터의 생성·수집·사용 맥락","GPU 온도만","발표자의 이력","모델 이름만"],"answer":0,"explanation":"데이터의 동기, 구성, 수집·처리, 사용 제한을 기록하는 문서입니다."},{"question":"감사 발견 사항에 붙어야 할 것으로 가장 적절한 것은?","choices":["비난할 사람 이름만","기술 유행어","증거·영향·시정 담당자·확인 기준","홍보 문구"],"answer":2,"explanation":"발견을 실제 개선으로 연결해야 책임성이 생깁니다."},{"question":"한 번의 감사 통과가 의미하는 것은?","choices":["모든 미래 버전이 안전하다","평가한 범위와 시점에 대한 증거가 있다","사고 대응이 필요 없다","문서 업데이트가 필요 없다"],"answer":1,"explanation":"범위·방법·시점을 넘어 보장을 확대하면 안 됩니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2001.00973","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1810.03993","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1803.09010","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":6,"title":"정렬·안전 · 선호를 배운 모델의 한계","objectives":["RLHF·DPO·Constitutional AI의 핵심 구조를 비교한다.","선호 점수와 사실성·안전성이 다를 수 있음을 설명한다.","워터마크·출처 증명·진위 판정의 차이를 구분한다."],"plainLesson":"대규모 언어 모델의 기본 학습은 흔히 다음 토큰을 잘 예측하는 문제입니다. 사람에게 도움이 되는 답변, 사실을 정확히 말하는 답변, 위험한 요청을 적절히 거절하는 답변은 그 목표와 완전히 같지 않습니다. 정렬은 원하는 행동에 더 가까워지도록 학습과 운영을 조정하는 과정입니다. 여기서 “원하는”의 기준을 누가 정하는지도 윤리적 질문입니다.\n\nRLHF에서는 사람이 선호하는 응답을 비교한 정보를 보상 모델 등에 반영하고 정책을 개선합니다. DPO는 선호 쌍에서 정책을 직접 학습하는 손실을 사용하여 고전적 RLHF의 일부 절차를 단순화합니다. Constitutional AI는 명시한 원칙에 비추어 비평·수정과 AI 피드백을 활용합니다. 방식이 다르더라도 학습에 쓰인 선호와 원칙, 평가자들의 관점, 데이터 범위를 벗어나는 상황을 점검해야 합니다.\n\n점수가 목표를 완벽히 대표하지 않으면 점수만 높이는 행동이 나타날 수 있습니다. 보상 해킹은 이 틈을 이용하는 현상이고, 아첨은 사실보다 사용자가 좋아할 말에 치우치는 행동입니다. 안전 평가에서는 위험한 답을 줄이는 비율만 아니라 정상적인 질문까지 거절하는 과잉 거부, 유용성, 조건이 달라졌을 때의 성능을 함께 봅니다. 실패가 관측되지 않았다는 사실은 실패가 없다는 증명이 아닙니다.\n\n워터마크는 생성 과정에 식별 가능한 신호를 넣으려는 기술이며, 콘텐츠 출처 증명은 제작·편집 이력의 서명된 정보를 다룹니다. 신호가 없다고 인간 작성이라고 단정할 수 없고, 출처 이력이 있다고 내용이 사실이라는 결론도 나오지 않습니다. 딥페이크 탐지 역시 데이터와 편집 조건에 따라 달라지는 확률적 판단입니다. 기술적 탐지와 동의·표시·저작권·피해 구제는 함께 다루어야 합니다.","preparation":["지도학습과 강화학습의 목표 차이를 한 문장으로 적는다.","진짜 출처에서 나온 잘못된 정보의 사례를 떠올린다."],"practice":{"title":"유용성과 거절을 함께 평가하기","steps":["정상적인 학습 질문 5개와 답변 제한이 필요한 가상 상황의 설명 5개를 안전한 추상 수준으로 정한다.","정확성·도움 정도·적절한 거절·과잉 거부의 기준을 미리 쓴다.","모의 응답을 두 사람이 독립적으로 평가한 뒤 불일치를 기록한다.","평가자 선호가 곧 진실성은 아닌 이유를 적는다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Alignment","RLHF","DPO","Constitutional AI","Reward hacking","Sycophancy","Watermark","Provenance"],"assignment":"학습용: 정렬 방법 한 개를 “입력 피드백→학습 목표→평가→남는 한계”의 네 단계로 설명합니다.","quiz":[{"question":"사람 선호 점수가 높으면 반드시 보장되는 것은?","choices":["사실성","법적 적합성","모든 사용자 가치와 일치","위 세 가지 모두 자동 보장되지 않는다"],"answer":3,"explanation":"선호 평가가 진실·안전·사회적 합의 전체를 대표하지는 않습니다."},{"question":"정상 질문까지 거절하는 현상은?","choices":["과잉 거부","보정","연합학습","데이터 시트"],"answer":0,"explanation":"안전 평가에서는 위험 응답 감소와 정상 사용자에게 주는 불편을 함께 측정합니다."},{"question":"서명된 콘텐츠 출처 정보가 직접 보장하지 않는 것은?","choices":["서명 검증 여부","표시된 제작 이력의 무결성 확인","내용 자체의 사실성","인증 정보의 존재"],"answer":2,"explanation":"출처 인증과 사실 검증은 다른 문제입니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2203.02155","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2305.18290","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2212.08073","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://proceedings.mlr.press/v202/kirchenbauer23a.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://c2pa.org/specifications/specifications/2.2/specs/C2PA_Specification.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2310.13548","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":7,"title":"거버넌스·규제 · 원칙을 시험 가능한 요구로","objectives":["법률·표준·프레임워크·인증의 역할 차이를 구분한다.","원칙을 요구사항·시험·증거·책임자로 연결한다.","법령 발효와 조항별 적용 시점을 따로 확인한다."],"plainLesson":"“책임 있는 AI를 만들라”는 원칙을 실제 업무로 바꾸려면 누가 어떤 기준을 지키고 무엇으로 입증할지 정해야 합니다. 거버넌스는 이 결정과 감독의 구조입니다. 위험이 큰 사용에는 더 엄격한 관리가 필요할 수 있지만, 위험 등급은 모델 크기 하나로 정하지 않습니다. 사용 목적, 영향을 받는 사람, 실패의 영향, 법에서 정한 범위를 함께 봅니다.\n\n법은 관할과 적용 대상에 따른 의무를 정합니다. 표준은 합의된 요구사항이나 지침을 제시하고, 프레임워크는 생각과 활동을 조직하는 구조를 제공합니다. ISO/IEC 42001은 조직의 AI 경영시스템, 23894는 AI 위험관리, 42005는 AI 시스템 영향평가를 다룹니다. 경영시스템 인증을 개별 모델이 모든 상황에서 공정하고 안전하다는 인증으로 읽어서는 안 됩니다. 공개 요약을 읽었다고 유료 표준 본문 전체를 검토했다고 주장하지 않습니다.\n\n날짜도 연구 자료의 일부입니다. 한국 AI기본법은 2026년 1월 22일 시행되었습니다. EU AI Act는 단계별 적용이며 2026년 개정 일정까지 확인해야 합니다. 이 핸드북의 최신 확인란에는 일반 적용, GPAI, Annex III 고위험, 제품 내장 고위험의 날짜를 따로 적었습니다. 옛 강의 슬라이드의 날짜와 최신 공식 자료가 다르면 어느 시점의 규칙인지 표시합니다.\n\n실습에서는 “차별을 줄인다”를 그대로 시험 항목으로 삼지 않습니다. 대상 집단과 피해를 정하고, 측정할 오류율과 허용 범위, 소규모 집단의 불확실성, 재평가 시점, 실패 시 결정권자를 적습니다. 시험으로 확인하지 못하는 잔여 위험도 남깁니다. 준수 문서는 결론을 꾸미는 작업이 아니라 결정을 추적 가능하게 만드는 증거 체계입니다.","preparation":["1주차 위험 지도를 다시 읽고 운영 책임자를 찾는다.","법적 의무와 권장 실무가 같은 뜻인지 확인한다."],"practice":{"title":"요구사항·시험·증거 연결표","steps":["가상 상담 챗봇에 “개인정보 노출 최소화” 원칙을 선택한다.","검증 가능한 요구 두 개로 나누고 적용 범위를 정한다.","각 요구를 확인할 데이터·시험 절차·판정 기준을 쓴다.","증거 보관 위치·접근 권한·책임자·재시험 조건을 적는다.","각 항목이 법적 의무인지 내부 설계 선택인지 구별한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Governance","Conformity assessment","Risk","Audit","Accountability","Safety case"],"assignment":"학습용: ISO/IEC 42001 또는 NIST AI RMF의 공개 자료를 기반으로 원칙→요구→시험→증거를 3개 연결합니다. 표준 전문을 읽지 않았다면 그 범위를 표시합니다.","quiz":[{"question":"조직의 AI 경영시스템 인증을 가장 정확히 해석한 것은?","choices":["모든 모델이 무오류라는 뜻","정해진 범위에서 관리체계를 평가한 것","모든 국가의 법 준수를 영구 보장","공정성 지표가 필요 없다는 뜻"],"answer":1,"explanation":"관리체계 평가와 개별 시스템의 모든 성능·안전 보장은 다릅니다."},{"question":"법령 일정에서 구분해야 하는 것은?","choices":["글자 크기와 줄 간격","발효일과 조항별 적용일","저자 취미와 소속","사이트 방문자 수"],"answer":1,"explanation":"법이 효력을 얻는 시점과 실제 의무가 적용되는 시점은 조항별로 다를 수 있습니다."},{"question":"시험 가능한 요구사항에 가장 가까운 것은?","choices":["AI를 좋게 만든다","신뢰를 최대화한다","정의한 비공개 정보 노출 시험에서 누출 사례를 기록하고 판정 기준에 따라 조치한다","유명한 모델을 쓴다"],"answer":2,"explanation":"대상·관측 방법·판정과 조치가 있어야 검증 가능한 요구로 발전시킬 수 있습니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://www.iso.org/standard/42001","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://www.law.go.kr/LSW/lsInfoP.do?ancYnChk=0&chrClsCd=010202&efYd=20260122&lsiSeq=282791&urlMode=lsInfoP","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":8,"title":"중간 점검 · 윤리 개념을 연구 질문으로","objectives":["1~7주차 개념을 하나의 사례에 연결한다.","연구 질문·위험 모델·비교 기준·평가 지표를 제안서에 쓴다.","한 학기 안에 확인 가능한 연구 범위를 정한다."],"plainLesson":"이번 주는 새로운 기술을 많이 추가하기보다 알고 있는 개념을 연결하는 주입니다. 하나의 채용 안내 도우미를 예로 들어 공정성, 설명, 문서화, 정렬, 책임 체계가 각각 어떤 질문을 던지는지 설명해 봅니다. 용어 정의를 외우는 것만으로는 “왜 이 지표를 선택했는가?”에 답하기 어렵습니다. 개념마다 짧은 예시와 실패 사례를 짝지으면 이해를 점검할 수 있습니다.\n\n프로젝트 질문은 “AI를 안전하게 만들겠다”보다 “합성 FAQ 환경에서 문서 신뢰도 표기가 근거 없는 답변 비율과 유용성을 어떻게 바꾸는가?”처럼 범위와 비교가 드러나는 형태가 좋습니다. 독립변수는 바꿀 것, 종속변수는 측정할 것, 통제변수는 비교를 위해 유지할 것입니다. 결과가 예상과 달라도 질문과 실험이 명확하면 배울 수 있습니다.\n\n위협 모델에는 보호할 자산, 가능한 실패, 공격자나 오류의 능력, 허용한 접근, 제외한 상황을 적습니다. 모든 프로젝트가 공격 구현을 요구하는 것은 아닙니다. 공개 결과 재분석, 합성 데이터의 공정성 비교, 문서화 평가, 방어 설계의 한계 분석도 연구가 될 수 있습니다. 개인정보·유료 서비스·외부 시스템 접근이 필요한 계획은 승인과 비용을 먼저 확인합니다.\n\n중간고사는 강의계획서상 90분이며 범위는 1~7주차입니다. 프로젝트 계획(안) 제출과 제안 발표는 별도 준비합니다. 발표 15분과 질의·응답 10분이라는 계획서 시간을 유지하고, 이 핸드북의 양식을 공식 채점 배점으로 오해하지 않습니다.","preparation":["각 주차 핵심 질문 하나에 원문 없이 답한다.","관심 논문 2편에서 공통점과 다른 가정 하나씩을 찾는다."],"practice":{"title":"15분 제안 발표의 한 문장 뼈대","steps":["해결하려는 문제와 영향을 받는 사람을 한 문장으로 쓴다.","가설·비교 기준·데이터·지표를 각각 한 문장으로 쓴다.","다음 2주 안에 실행할 최소 실험과 실패 시 축소안을 정한다.","윤리·보안·비용 승인 필요 여부와 중단 기준을 적는다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Hypothesis","Baseline","Threat model","Metric","Reproducibility"],"assignment":"강의계획서: 개인 프로젝트 계획(안) 제출 및 제안 발표. 제출 형식·배점은 수업 공지를 확인합니다.","quiz":[],"scheduleNote":"중간고사 90분(1~7주차) 및 개인 프로젝트 계획(안) 제출. 제안 발표는 1인 15분 + 질의·응답 10분.","sources":[{"url":"https://neurips.cc/public/guides/PaperChecklist","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":9,"title":"위협 모델과 적대적 강건성","objectives":["공격자의 목표·지식·능력·예산을 분리해 적는다.","일반 정확도와 강건 정확도의 조건을 구분한다.","적응형 평가와 그래디언트 마스킹의 의미를 설명한다."],"plainLesson":"보안 논문을 읽을 때는 공격 이름보다 먼저 공격자가 무엇을 할 수 있는지 봅니다. 모델 가중치까지 아는지, API 출력만 보는지, 입력을 어느 정도 바꿀 수 있는지, 몇 번 질의할 수 있는지가 결과를 바꿉니다. 공격자가 현실에서 얻기 어려운 권한을 가정한 실험도 이론적으로 유용할 수 있지만, 실제 서비스 위험을 주장하려면 그 차이를 설명해야 합니다.\n\n적대적 예제는 모델을 실패시키려는 목적을 가지고 선택된 입력 변화입니다. 자연스러운 촬영 흔들림 같은 변화와 공격자가 의도적으로 고른 변화는 다르지만 모두 강건성 연구와 연결됩니다. FGSM·PGD·C&W·AutoAttack은 서로 다른 평가 접근입니다. 이름을 외우기보다 어떤 변화 집합과 탐색 조건에서 실패를 찾는지 읽습니다. 이 핸드북의 실습은 공격 실행 대신 평가 조건 비교에 초점을 둡니다.\n\n일반 정확도는 원래 시험 입력에서 맞힌 비율이고, 강건 정확도는 명시한 변화 조건을 고려한 성능입니다. 제한된 공격에서 실패를 못 찾았다고 더 강한 공격에도 안전하다는 뜻은 아닙니다. 방어가 기울기 정보를 읽기 어렵게 만들어 약한 평가만 통과하는 그래디언트 마스킹을 경계해야 합니다. 방어 구조를 아는 평가자가 그 구조에 맞춰 시험하는 적응형 평가가 중요합니다.\n\n인증 강건성은 특정 가정과 범위 안에서 예측 유지 등을 수학적으로 보장하려는 접근입니다. 예를 들어 무작위 평활화는 정해진 노이즈와 거리 조건 아래 인증을 다룹니다. 인증 반경 밖의 입력, 다른 위협 종류, 시스템의 개인정보 위험까지 보장하는 것은 아닙니다. 실험적 발견과 수학적 보장의 범위를 각각 기록합니다.","preparation":["벡터의 거리와 작은 입력 변화의 의미를 복습한다.","최적화의 목적함수·제약 조건이라는 말을 확인한다."],"practice":{"title":"강건성 표를 조건별로 읽기","steps":["공개 논문의 결과표에서 일반 정확도와 강건 정확도를 구분한다.","입력 거리·변화 크기·질의 횟수·공격자 지식 조건을 찾아 적는다.","서로 다른 조건의 점수를 같은 순위로 비교하면 생기는 문제를 쓴다.","약한 평가만 통과했을 가능성을 줄일 추가 점검 세 가지를 제안한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Threat model","Adversarial example","Evasion","Robustness","Adaptive attack","Gradient masking","Certified robustness"],"assignment":"학습용: 논문 두 개의 위협 모델을 같은 양식에 옮겨 직접 비교 가능한 항목과 아닌 항목을 표시합니다.","quiz":[{"question":"강건 정확도 80%라는 결과에 반드시 필요한 정보는?","choices":["논문 제목만","위협 모델과 평가 조건","저자 사진","초록 길이"],"answer":1,"explanation":"변화 허용 범위·공격 방법·예산이 달라지면 수치의 의미가 달라집니다."},{"question":"약한 공격에서 실패가 없었다면?","choices":["모든 공격에 안전하다","기밀성도 보장된다","평가 범위에서 실패를 발견하지 못한 것이다","인증 강건성 증명이 완성된다"],"answer":2,"explanation":"실패를 찾지 못한 관측과 실패가 없다는 증명은 다릅니다."},{"question":"적응형 공격 평가가 필요한 이유는?","choices":["방어 구조를 모르는 평가만 하려고","방어의 특성을 고려한 강한 시험이 필요해서","항상 실제 서비스를 공격하려고","분모를 없애려고"],"answer":1,"explanation":"방어에 맞는 시험을 해야 방어가 단순히 평가 방법을 무력화한 것은 아닌지 확인할 수 있습니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/1706.06083","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1412.6572","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2002.08347","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://proceedings.mlr.press/v97/cohen19c.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":10,"title":"데이터 오염·백도어와 AI 공급망","objectives":["학습 시점 오염과 추론 시점 회피를 구분한다.","백도어·일반 성능 저하·클린라벨 조건을 설명한다.","모델·데이터·코드의 출처와 버전 통제를 설계한다."],"plainLesson":"음식을 만들기 전에 재료가 오염되는 상황과 완성된 음식의 표시가 바뀌는 상황은 다릅니다. AI에서도 학습 데이터나 학습 과정을 건드리는 데이터 오염과 배포된 모델의 입력을 바꾸는 회피를 구분합니다. 오염 연구의 핵심은 공격자가 데이터의 얼마나 많은 부분을 어떤 권한으로 바꿀 수 있는지, 모델 학습 과정에 얼마나 영향을 줄 수 있는지입니다.\n\n백도어는 평상시에는 정상처럼 보이다가 특정 조건에서 의도된 비정상 행동을 하도록 숨겨진 의존성을 만드는 유형입니다. 트리거는 그 조건을 뜻하며 반드시 눈에 보이는 표시일 필요는 없습니다. 클린라벨은 공격에 쓰인 학습 예시의 라벨이 겉으로 올바르다는 조건이지 공격이 무해하다는 뜻이 아닙니다. 탐지 점수가 높더라도 드문 정상 사례를 잘못 지우는 피해가 없는지 함께 봅니다.\n\nLLM에서는 안전 학습을 더 했다는 사실만으로 숨겨진 행동이 제거되었다고 단정할 수 없습니다. 특정 연구에서 어떤 조건으로 잔존 행동을 관찰했는지와, 모든 실제 모델에 같은 현상이 있다는 주장을 구분합니다. 재학습·미세조정·입력 필터 각각의 범위와 실패 조건을 기록합니다.\n\n공급망 보안은 데이터 출처, 모델 파일, 라이브러리, 배포 설정, 업데이트 경로까지 다룹니다. 다운로드 수가 많거나 공개 저장소에 있다는 이유만으로 파일이 안전하다고 간주하지 않습니다. 서명·해시 검증은 출처와 파일 무결성에 도움을 주지만 그 모델의 행동이 안전하다는 증명은 아닙니다. 이 수업에서는 의심스러운 모델을 실행하는 대신 구성요소 목록과 검증 절차를 설계합니다.","preparation":["학습 파이프라인의 데이터·코드·가중치·배포 단계를 그린다.","파일 해시가 같은 파일인지 확인하는 데 쓰임을 이해한다."],"practice":{"title":"실행 없는 AI 공급망 점검","steps":["가상의 모델 배포에 쓰인 데이터·모델·의존 라이브러리·설정 파일을 목록으로 만든다.","각 항목의 출처·버전·라이선스·검증 책임자를 적는다.","업데이트 전 검사와 문제가 생겼을 때 이전 버전으로 돌아가는 절차를 적는다.","서명 검증만으로 확인되지 않는 행동 위험을 세 개 적는다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Data poisoning","Backdoor","Trigger","Clean-label poisoning","Supply chain","AI-BOM","Provenance"],"assignment":"학습용: 데이터 유입부터 배포까지 오염 가능 지점과 예방·탐지·복구 통제를 연결합니다.","quiz":[{"question":"클린라벨 오염에서 clean이 뜻하는 것은?","choices":["공격이 무해하다","라벨이 겉으로 올바르다","개인정보가 없다","인증되었다"],"answer":1,"explanation":"라벨을 틀리게 바꾸지 않은 조건을 말할 뿐, 오염 의도나 피해가 없다는 뜻이 아닙니다."},{"question":"모델 파일의 서명을 확인하면 자동으로 보장되는 것은?","choices":["공정성","백도어 부재","확인한 서명·파일 무결성 관련 사실","모든 입력에서의 정확성"],"answer":2,"explanation":"서명은 파일 출처와 무결성 확인에 기여하지만 모델 행동의 안전성을 보장하지 않습니다."},{"question":"백도어 연구에서 특히 중요한 시험은?","choices":["정상 입력만 보기","특정 조건의 행동과 정상 성능을 함께 보기","파일 크기만 보기","저자 수만 보기"],"answer":1,"explanation":"정상처럼 보이는 성능과 조건부 비정상 행동을 함께 평가해야 합니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2302.10149","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2401.05566","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":11,"title":"프라이버시 · 개인의 흔적을 얼마나 남기는가","objectives":["멤버십·속성 추론·모델 역전·데이터 추출을 구분한다.","차분 프라이버시의 보호 단위·ε·δ·누적 비용을 설명한다.","연합학습과 학습 망각이 자동 보장을 주지 않음을 이해한다."],"plainLesson":"모델이 개인 정보를 직접 출력하지 않아도 프라이버시 위험이 생길 수 있습니다. 멤버십 추론은 어떤 기록이 학습에 포함되었는지 묻고, 속성 추론은 알려지지 않은 특성을 추측하며, 역전·추출은 입력이나 학습 자료에 관한 정보를 복원하려 합니다. 공격 성능의 의미는 실제로 알아낸 정보와 사전 지식, 허용한 질의, 오탐에 따라 달라집니다. 종합 정확도만 높은 검사는 개인에게 많은 오해를 만들 수 있습니다.\n\n차분 프라이버시는 한 사람 또는 한 기록의 포함 여부가 결과 분포를 크게 바꾸지 않도록 하는 수학적 조건입니다. “익명화했다”처럼 막연한 표현보다 보호 단위와 인접 데이터셋 정의가 중요합니다. 같은 설정에서 ε가 작을수록 일반적으로 더 엄격한 보호이며, δ는 단순한 개인정보 유출 확률로 읽으면 안 됩니다. 여러 번 학습·조회하면 프라이버시 비용이 누적되므로 회계가 필요합니다.\n\nDP-SGD는 개별 예시의 기울기 기여를 제한하고 노이즈를 더하는 학습 방식입니다. 정확도와 비용의 변화도 평가해야 하며, 프라이버시 예산을 보고하지 않은 “DP 적용” 표지만으로 충분하지 않습니다. 연합학습은 데이터를 한곳으로 모으지 않는 구조지만 공유한 업데이트에서 정보가 드러날 수 있습니다. 보안 집계·암호화·차분 프라이버시는 보호 대상과 가정이 서로 다릅니다.\n\n학습 망각은 특정 학습 자료의 영향을 모델에서 제거하려는 연구입니다. 데이터 파일 삭제, 답변 거절, 완전 재학습과 같은 의미가 아닙니다. 무엇을 제거했고 어떤 비교 모델이나 검증으로 확인했는지 읽어야 합니다. 법적 삭제 요구의 충족 여부도 기술 지표 하나로 단정하지 않습니다. 이 주의 실습은 실제 개인정보 대신 합성 기록으로 감사 계획을 세웁니다.","preparation":["확률 분포와 오탐·미탐을 복습한다.","보호 단위가 기록 하나와 사람 한 명일 때 어떻게 다른지 생각한다."],"practice":{"title":"프라이버시 주장 점검 카드","steps":["가상 논문에 “연합학습을 사용했으므로 프라이버시가 보장된다”라는 주장을 놓는다.","누가 무엇을 관측하는지, 서버·참여자의 신뢰 가정을 적는다.","DP 사용 여부, 보호 단위, ε·δ, 반복 학습 누적을 확인할 질문을 만든다.","멤버십 시험은 낮은 FPR에서 TPR을 보고할 수 있도록 평가표를 설계한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Membership inference","Differential privacy","Epsilon","Delta","DP-SGD","Federated learning","Secure aggregation","Machine unlearning"],"assignment":"학습용: 프라이버시 논문 한 편의 보호 대상·관측자·보장·실험·보장 밖 영역을 정리합니다.","quiz":[{"question":"연합학습만 사용하면?","choices":["공유 업데이트에서도 정보가 새지 않는다","프라이버시 보호가 자동 증명된다","데이터 집중을 줄이지만 별도 보호와 위협 모델이 필요하다","차분 프라이버시 예산이 0이 된다"],"answer":2,"explanation":"업데이트를 통해 정보가 노출될 수 있으며 서버·참여자 가정과 추가 보호를 확인해야 합니다."},{"question":"같은 보호 단위와 조건에서 ε가 더 작다는 것은 일반적으로?","choices":["더 엄격한 DP 보호","항상 더 높은 정확도","학습 비용이 항상 0","모든 법적 요구 충족"],"answer":0,"explanation":"ε는 결과 분포 변화의 허용 정도와 관련됩니다. 정확도나 법적 판단을 자동 보장하지 않습니다."},{"question":"기계 학습 망각의 검증에서 필요한 질문은?","choices":["파일만 삭제했는가만 본다","모델의 어떤 영향을 어떻게 제거·검증했는가","답변을 숨겼으므로 끝났는가","브랜드가 유명한가"],"answer":1,"explanation":"데이터 제거와 학습된 영향의 제거는 다르므로 비교 기준과 보장을 확인해야 합니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1607.00133","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2112.03570","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://proceedings.mlr.press/v54/mcmahan17a.html","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://research.google/pubs/practical-secure-aggregation-for-privacy-preserving-machine-learning/","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/1912.03817","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":12,"title":"LLM 보안 I · 명령과 데이터의 경계","objectives":["프롬프트 인젝션과 탈옥의 초점을 구분한다.","다층 방어와 명령 우선순위의 필요성을 설명한다.","ASR·과잉 거부·유용성을 함께 평가한다."],"plainLesson":"언어 모델은 명령과 참고 문서를 모두 텍스트로 받아들이기 때문에, 참고 자료 속 문장이 원래 요청을 바꾸려는 지시처럼 작동할 수 있습니다. 프롬프트 인젝션은 이 신뢰 경계의 문제입니다. 직접 인젝션은 입력 경로에서, 간접 인젝션은 검색 문서·메일·웹페이지 같은 외부 자료를 통해 들어올 수 있습니다. 문서가 검색 결과에 나타났다는 사실은 그 문서에 명령권이 있다는 뜻이 아닙니다.\n\n탈옥은 보통 안전 정책이나 정렬로 제한한 행동을 유도하려는 시도를 가리킵니다. 인젝션은 애플리케이션의 의도와 권한 경계를 흔드는 문제에 초점을 둡니다. 두 범주가 겹칠 수 있지만 같은 말로만 쓰면 방어 목표가 흐려집니다. 악성 출력 자체를 줄이는 것과 승인 없는 도구 실행·정보 유출을 막는 것은 별도로 확인해야 합니다.\n\n방어에는 명령 계층, 외부 자료의 격리된 취급, 입력·출력 검사, 제한된 도구 권한, 실행 전 검증, 이상 시 중단이 포함될 수 있습니다. “이 문서를 믿지 마”라는 문장을 추가한 것만으로 완전 해결되었다고 보지 않습니다. 가드 모델도 오류가 있고, 공격 패턴이 바뀌거나 정상 요청을 과도하게 막을 수 있습니다. 모델 밖의 권한·검증 장치가 중요한 이유입니다.\n\n평가에서는 공격 성공률 ASR의 분모와 성공 판정을 정확히 적습니다. 한 번이라도 성공했는지, 허용한 시도 수가 몇 번인지, 자동 채점자가 실제 피해를 판단했는지에 따라 결과가 달라집니다. 정상 사용자의 작업 성공률과 과잉 거부율도 함께 기록합니다. 본 핸드북은 우회 문구나 실제 공격 절차를 제공하지 않고 합성 자료로 경계 설계를 검토합니다.","preparation":["시스템 지시·사용자 요청·외부 문서의 역할 차이를 설명한다.","읽기 권한과 실행 권한을 구분한다."],"practice":{"title":"명령과 참고자료를 색으로 구분하기","steps":["가상 사용자의 “제공된 안내문을 요약해 달라” 요청과 무해한 안내문을 준비한다.","사용자 의도, 외부 사실, 행동 지시를 서로 다른 범주로 표시한다.","문서가 새로운 도구 실행을 요구하더라도 실행 권한이 생기지 않는 원칙을 쓴다.","출력 검사·최소 권한·승인 단계가 각각 어떤 실패를 막는지 연결한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Prompt injection","Jailbreak","Guardrail","Instruction hierarchy","Attack success rate","Over-refusal"],"assignment":"학습용: LLM 애플리케이션의 신뢰 경계를 그리고 각 경계를 지나는 데이터와 권한을 적습니다.","quiz":[{"question":"검색된 외부 문서의 지시가 갖는 권한은?","choices":["시스템 지시보다 높다","사용자 요청을 자동 대체한다","검색되었다는 이유만으로 명령 권한을 얻지 않는다","모든 도구를 실행할 수 있다"],"answer":2,"explanation":"외부 데이터와 사용자가 부여한 권한을 구분해야 합니다."},{"question":"프롬프트 인젝션 방어의 적절한 방향은?","choices":["경고 문장 한 줄이면 충분하다","모델 판단과 별도로 권한·입출력·실행 검증을 겹쳐 둔다","모든 도구 권한을 부여한다","실패 기록을 삭제한다"],"answer":1,"explanation":"다층 통제는 한 방어가 실패했을 때 실제 피해로 이어지는 경로를 줄입니다."},{"question":"ASR만 보고하면 놓치기 쉬운 것은?","choices":["정상 작업 유용성과 과잉 거부","공격 수의 분모","성공 판정 방식","위 모두"],"answer":3,"explanation":"ASR의 조건과 함께 정상 사용 성능도 보고해야 방어의 효과와 비용을 이해할 수 있습니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2302.12173","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://genai.owasp.org/llmrisk/llm01-prompt-injection/","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2404.13208","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2402.04249","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":13,"title":"LLM 보안 II · 행동하는 에이전트의 권한","objectives":["RAG·메모리·도구 호출이 만드는 공격 표면을 찾는다.","최소 권한·샌드박스·사람 확인을 실행 경계에 배치한다.","에이전트 보안 평가에서 작업 성공과 안전을 함께 본다."],"plainLesson":"답변만 만드는 챗봇과 파일을 수정하거나 메시지를 보내는 에이전트는 실패의 영향이 다릅니다. 에이전트는 계획을 세우고, 도구 결과를 읽고, 다음 행동을 선택하며, 때로는 기억을 남깁니다. 어느 단계든 잘못된 자료를 신뢰하면 오류가 다음 단계로 전달될 수 있습니다. 그래서 한 번의 출력보다 전체 실행 경로를 봐야 합니다.\n\nRAG는 외부 자료를 검색해 생성에 참고시키는 구조입니다. 근거를 제공할 수 있지만 검색 문서가 정확하거나 안전하다는 보장은 없습니다. 지식베이스의 출처·갱신·접근 권한을 관리하고, 검색한 내용에 명령 권한을 주지 않아야 합니다. 장기 메모리에 무엇을 저장할지도 중요합니다. 출처가 불명확한 내용을 영구적인 사용자 선호나 승인으로 저장하면 이후 작업에 영향을 줄 수 있습니다.\n\n최소 권한은 일을 하는 데 꼭 필요한 권한만 주는 원칙입니다. 읽기 전용 검색에는 쓰기·전송 권한이 필요하지 않습니다. 샌드박스는 실패의 영향을 제한하는 실행 환경이고, 사람 확인은 중요한 행동의 직전에 정확한 대상·내용·영향을 보여 주어야 의미가 있습니다. 도구 인터페이스나 MCP를 썼다는 사실만으로 이런 보호가 자동 생기지는 않습니다.\n\nAgentDojo 같은 평가 환경은 정상 작업과 공격이 섞인 상황에서 에이전트의 행동을 비교하게 합니다. 안전을 높이려고 모든 행동을 중단하면 실제 사용 가치는 사라집니다. 정상 작업 성공률, 승인 없는 행동, 정보 노출, 복구 가능성을 함께 평가합니다. 이 주의 산출물은 실서비스 공격이 아니라 가상의 권한표와 안전한 도구 호출 검증 설계입니다.","preparation":["12주차 신뢰 경계 그림을 다시 본다.","도구 입력·출력·부작용의 세 요소를 익힌다."],"practice":{"title":"읽기·쓰기·전송 권한 나누기","steps":["가상 논문 정리 에이전트의 기능을 검색·파일 읽기·메모 저장·메일 전송으로 나눈다.","각 기능에 필요한 최소 권한과 입력 검증을 적는다.","외부 논문의 텍스트가 메일 전송 권한을 만들 수 없다는 경계를 표시한다.","되돌릴 수 없는 행동 전에 사용자에게 보여 줄 확인 정보를 정한다.","정상 작업을 끝낼 수 있는지도 함께 검토한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Agent","RAG","Least privilege","Sandbox","Human-in-the-loop","Prompt injection","Provenance"],"assignment":"학습용: 가상 에이전트의 권한표와 정상·비정상 시나리오별 평가 기준을 작성합니다.","quiz":[{"question":"읽기 전용 요약 에이전트에 권장되는 권한은?","choices":["모든 파일 삭제 권한","필요한 자료 읽기 권한","무제한 결제 권한","모든 사람에게 전송 권한"],"answer":1,"explanation":"과업에 필요한 최소 권한만 주어 실패의 영향을 제한합니다."},{"question":"RAG를 사용하면 자동으로 해결되지 않는 것은?","choices":["외부 자료 검색","문맥 제공","검색 자료의 진실성과 안전성","검색 결과를 참고하는 구조"],"answer":2,"explanation":"검색된 자료의 품질·출처·신뢰 경계는 별도로 관리해야 합니다."},{"question":"에이전트 안전 평가에서 모든 도구 사용을 막으면?","choices":["안전성과 유용성이 모두 증명된다","정상 작업 성공 여부를 함께 확인해야 한다","평가 지표가 필요 없다","모든 위험이 영구 소멸한다"],"answer":1,"explanation":"안전성 향상과 기능 상실을 구분해 보고해야 합니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다.","sources":[{"url":"https://arxiv.org/abs/2005.11401","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2406.13352","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://arxiv.org/abs/2302.12173","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":14,"title":"모델 추출·소유권과 보안 시험 증거","objectives":["기능 복제·가중치 추론·소유권 검증의 차이를 설명한다.","현실적인 권한·비용·질의 예산으로 연구 결과를 해석한다.","프로젝트 중간 결과에서 주장과 증거의 간격을 확인한다."],"plainLesson":"모델 추출은 외부에서 관측한 응답 등을 이용해 모델의 기능이나 내부 정보를 알아내려는 연구입니다. 비슷한 행동을 하는 대체 모델을 만든 것, 일부 내부 구조를 추정한 것, 모든 가중치를 정확히 복원한 것은 서로 다른 성과입니다. 논문 제목의 “stealing”만 보고 범위를 과장하지 말고 무엇을 얼마나 얻었는지 읽어야 합니다.\n\n공개 API의 반환 정보, 질의 비용, 접근 제한, 모델의 구조에 대한 가정이 실현 가능성을 바꿉니다. 방어는 노출 정보와 질의를 줄일 수 있지만 정상 사용자 경험·성능·접근성에도 영향을 줄 수 있습니다. 모델 워터마크나 핑거프린트는 소유권 주장을 뒷받침하는 신호가 될 수 있으나, 다른 모델에서도 우연히 나타나는지, 미세조정 뒤 유지되는지, 어떤 위협 조건을 가정했는지 검증해야 합니다. 기술적 신호만으로 법적 소유권이 확정되지는 않습니다.\n\n보안 시험을 설계할 때는 “이 공격이 유명하다”가 아니라 자산과 위협에서 시험 항목을 도출합니다. 각 시험에 대상 버전, 조건, 데이터, 성공 판정, 정상 기능 영향, 증거 파일을 연결합니다. ISO/IEC 27090은 이 핸드북 확인일 기준 공식 페이지에서 출판 진행 중인 60.00 단계로 표시되어 있으므로 이미 발행된 인증 규격처럼 소개하지 않습니다. 표준·NIST 분류·실제 시험 결과는 서로 다른 종류의 근거입니다.\n\n프로젝트 중간 점검에서는 성공적인 그래프보다 현재 말할 수 있는 주장과 아직 말할 수 없는 주장을 명확히 보여 줍니다. 한 조건에서만 나온 개선은 그 범위대로 쓰고, 재현 실패는 설정 차이와 확인한 사실을 정리합니다. 남은 기간에 가장 중요한 불확실성 하나를 줄이는 실험을 우선합니다.","preparation":["실험의 권한·시간·질의·계산 예산을 다시 적는다.","자신의 핵심 주장 옆에 이를 지지하는 결과가 있는지 확인한다."],"practice":{"title":"주장·증거·잔여 위험 점검","steps":["프로젝트의 핵심 주장 세 개를 쓴다.","각 주장에 대응하는 표·그림·로그·가정을 연결한다.","증거가 없는 표현을 “관찰했다” 또는 “아직 확인하지 못했다”로 고친다.","남은 실험 하나와 실패 시 보고할 대체 산출물을 정한다.","공개 가능한 자료와 접근을 제한해야 할 자료를 구분한다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Model extraction","Fingerprinting","Watermark","Threat model","Conformity assessment","Reproducibility"],"assignment":"강의계획서: 개인 프로젝트 중간 점검 및 교수 피드백. 학습용: 주장-증거 표를 가져와 개선할 실험 하나를 결정합니다.","quiz":[{"question":"모델 기능을 비슷하게 재현했다는 결과는?","choices":["전체 가중치를 정확히 복원했다는 뜻이다","기능 복제 범위의 증거이며 내부 전체 복원과 다르다","법적 소유권을 확정한다","모든 API에서 같은 결과가 난다"],"answer":1,"explanation":"추출 결과의 대상과 정확도를 분리해야 과장하지 않습니다."},{"question":"현실적 보안 위험 해석에 필요한 것은?","choices":["논문 인용 수만","공격 이름만","접근 권한·비용·질의 예산·환경 가정","모델 로고만"],"answer":2,"explanation":"실험 조건이 현실에서 가능한지 판단하는 핵심 정보입니다."},{"question":"프로젝트 중간 결과가 가설과 다르면?","choices":["불리한 실험을 숨긴다","가설이 맞았다고 쓴다","설정과 불확실성을 기록하고 주장을 조정한다","숫자를 바꾼다"],"answer":2,"explanation":"예상과 다른 결과도 투명하게 분석하면 유효한 연구 결과입니다."}],"scheduleNote":"강의 60분 + 논문 발표·토론 120분. 아래 실습·학습 과제는 보조 제안이며 공식 배점이 아닙니다. 개인 프로젝트 중간 점검을 발표 시간 일부에 진행. 수강 인원에 따라 후반부를 최종 발표에 추가 배정할 수 있습니다.","sources":[{"url":"https://arxiv.org/abs/2403.06634","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://www.iso.org/standard/27090","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]},{"week":15,"title":"최종 발표 · 무엇을 알게 되었는가","objectives":["연구 질문·방법·결과·한계를 일관된 주장으로 묶는다.","타인이 확인 가능한 재현 자료와 책임 있는 공개 범위를 준비한다.","다음 연구 질문과 현재 연구의 경계를 구분한다."],"plainLesson":"최종 발표는 한 학기 동안 한 일을 모두 나열하는 자리가 아니라, 어떤 질문에 어떤 증거로 답했는지 설명하는 자리입니다. 청중은 처음부터 설정을 알지 못합니다. 문제와 중요성, 최소한의 배경, 비교 조건, 핵심 결과, 한계의 순서로 이야기하면 따라오기 쉽습니다. 하나의 잘 설명한 결과표가 이해하기 어려운 여러 장의 그래프보다 낫습니다.\n\n방법을 바꾸었을 때 성능이 달라졌다면 그 차이를 해당 방법의 효과라고 해석할 수 있는지 확인합니다. 데이터 분할·모델 크기·질의 예산이 함께 바뀌지는 않았는지, 여러 번 반복해도 방향이 유지되는지, 평균 뒤에 피해가 큰 집단이 가려지지는 않는지 봅니다. 유의한 차이가 없었다고 두 방법이 완전히 같다는 뜻은 아니며, 작은 실험의 불확실성도 결과의 일부입니다.\n\n보고서는 다른 사람이 핵심 판단을 다시 할 수 있도록 씁니다. 데이터 출처와 사용 권한, 버전·설정, 비교 기준, 실패한 시도, 안전 조치, 공개할 수 없는 자료의 이유를 기록합니다. 보안 연구의 재현성은 공격 수단을 무조건 공개하는 것과 다릅니다. 합성 데이터와 제한된 예제, 방어 검증 기록만으로도 유용한 검토가 가능할 수 있습니다.\n\n강의계획서상 기말고사는 개인 프로젝트 최종 발표로 대체됩니다. 발표 15분과 질의·동료 평가 10분을 준비하고, 최종 보고서는 발표 후 1주 이내 제출합니다. 마지막 슬라이드는 “모든 문제가 해결되었다”보다 “이 조건에서 무엇을 확인했고, 다음에 무엇을 검증해야 하는가?”로 마무리합니다.","preparation":["발표 자료의 모든 숫자를 원본 결과와 대조한다.","최종 보고서 마감일을 자신의 발표 날짜에서 1주 이내로 확인한다."],"practice":{"title":"최종 제출 전 역검증","steps":["핵심 결론을 먼저 읽고 각 문장에 근거 위치를 표시한다.","그림·표의 축·단위·분모·범례·오차 표시를 확인한다.","개인정보·비밀키·타인 저작물·위험한 실행 자료가 공개 파일에 없는지 점검한다.","논문 원문과 다른 요약, 미확인 내용, 버전 차이를 수정한다.","한계와 후속 연구를 구분해 적고 제출 파일을 다시 열어 본다."],"safety":"가상·합성 데이터와 허가된 로컬 환경만 사용합니다. 실사용 서비스, 타인의 계정·개인정보, 실제 공격 대상은 사용하지 않습니다."},"keyTerms":["Reproducibility","Limitation","Uncertainty","Ablation","Responsible disclosure"],"assignment":"강의계획서: 개인 프로젝트 최종 발표 및 발표 후 1주 이내 최종 보고서 제출. 동료 평가는 주장과 근거, 한계, 개선 제안을 중심으로 준비합니다.","quiz":[],"scheduleNote":"기말고사 대체 개인 프로젝트 최종 발표: 1인 15분 + 질의·동료 평가 10분. 최종 보고서는 발표 후 1주 이내.","sources":[{"url":"https://neurips.cc/public/guides/PaperChecklist","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"},{"url":"https://www.cisa.gov/sites/default/files/bod-20-01.pdf","supports":"주차 핵심 개념의 원전 또는 공식 참고 자료"}]}],"glossary":[{"term":"Risk","korean":"위험","category":"기초·거버넌스","ordinaryMeaning":"좋지 않은 일이 생길 가능성과 그 영향","etymology":"일상어 risk를 관리·공학의 판단 개념으로 사용합니다. 역사적 뿌리를 추정하지 않습니다.","aiMeaning":"정해진 맥락에서 AI가 사람·조직·사회에 줄 수 있는 피해의 가능성과 심각성을 함께 보는 개념.","example":"같은 오답도 영화 추천과 응급 안내에서 영향이 다르다.","confusedWith":"Threat는 해를 줄 수 있는 요인, risk는 그로 인한 가능성과 영향을 다룬다.","paperReading":"논문 해석 시 확인: Threat는 해를 줄 수 있는 요인, risk는 그로 인한 가능성과 영향을 다룬다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf"},{"term":"Threat model","korean":"위협 모델","category":"기초·보안","ordinaryMeaning":"어떤 위험을 상정하는지 그린 모형","etymology":"threat(위협)+model(모형)의 합성 표현입니다.","aiMeaning":"보호 자산, 공격자 목표·지식·능력·접근, 허용 예산과 제외 조건을 명시한 설명.","example":"읽기 전용 API 관측자와 모델 파일 수정자는 다른 위협 모델이다.","confusedWith":"공격 도구 이름이나 위험 목록만 적은 것은 충분한 위협 모델이 아니다.","paperReading":"논문 해석 시 확인: 공격 도구 이름이나 위험 목록만 적은 것은 충분한 위협 모델이 아니다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf"},{"term":"Vulnerability","korean":"취약점","category":"기초·보안","ordinaryMeaning":"다치거나 해를 입기 쉬운 약점","etymology":"일상적 취약함을 시스템의 이용 가능한 약점에 적용한 용법입니다.","aiMeaning":"공격이나 오류가 보안 목표를 깨뜨리는 데 이용할 수 있는 설계·구현·운영의 약점.","example":"외부 문서에 도구 실행 권한을 부여하는 설계 결함.","confusedWith":"위협은 행위·요인이고 취약점은 이용될 수 있는 약점이다.","paperReading":"논문 해석 시 확인: 위협은 행위·요인이고 취약점은 이용될 수 있는 약점이다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Confidentiality","korean":"기밀성","category":"기초·보안","ordinaryMeaning":"비밀을 허가된 사람 사이에 지키는 성질","etymology":"confidential(비밀로 취급하는)+-ity(성질)의 단어 형성입니다.","aiMeaning":"허가되지 않은 주체에게 정보가 노출되지 않도록 하는 보안 성질.","example":"상담 기록을 관계없는 이용자가 읽지 못하게 한다.","confusedWith":"Privacy는 사람의 권리·통제 등 더 넓은 문제를 포함한다.","paperReading":"논문 해석 시 확인: Privacy는 사람의 권리·통제 등 더 넓은 문제를 포함한다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Integrity","korean":"무결성","category":"기초·보안","ordinaryMeaning":"온전하고 부당하게 훼손되지 않은 상태","etymology":"일상어의 온전함을 정보·시스템 변경 통제에 적용한 용법입니다.","aiMeaning":"데이터·모델·결과가 허가 없이 부당하게 바뀌거나 파괴되지 않는 성질.","example":"승인된 모델 파일과 배포 파일의 해시를 대조한다.","confusedWith":"정확한 내용이라는 뜻의 accuracy와 같지 않다. 온전히 보존된 오답도 있다.","paperReading":"논문 해석 시 확인: 정확한 내용이라는 뜻의 accuracy와 같지 않다. 온전히 보존된 오답도 있다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Availability","korean":"가용성","category":"기초·보안","ordinaryMeaning":"필요할 때 이용할 수 있음","etymology":"available(이용 가능한)+-ity(성질)의 단어 형성입니다.","aiMeaning":"권한 있는 사용자가 필요할 때 시스템·정보를 정상적으로 사용할 수 있는 성질.","example":"정상적인 문의가 몰려도 도우미가 응답하도록 운영한다.","confusedWith":"모델이 공개되어 있다는 뜻의 open availability와 문맥이 다르다.","paperReading":"논문 해석 시 확인: 모델이 공개되어 있다는 뜻의 open availability와 문맥이 다르다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Robustness","korean":"강건성","category":"기초·보안","ordinaryMeaning":"변화나 충격에도 잘 버팀","etymology":"일상어 robust(튼튼한)의 뜻을 성능 유지에 적용한 비유입니다.","aiMeaning":"명시한 입력 변화·분포 변화·공격 조건에서 기능이나 성능을 유지하는 정도.","example":"허용한 작은 영상 변화에서도 분류 결과가 유지되는지 본다.","confusedWith":"평균 정확도, 모든 위협에 대한 보편적 안전 보장과 다르다.","paperReading":"논문 해석 시 확인: 평균 정확도, 모든 위협에 대한 보편적 안전 보장과 다르다.","sourceUrl":"https://arxiv.org/abs/1706.06083"},{"term":"Safety","korean":"안전성","category":"기초·윤리","ordinaryMeaning":"해를 입지 않거나 피해를 줄이는 상태","etymology":"일상어 safe의 성질을 시스템 피해 예방에 적용한 용법입니다.","aiMeaning":"사람·환경 등에 수용하기 어려운 피해를 주지 않도록 설계·운영하는 성질.","example":"공격이 없어도 잘못된 복약 안내가 피해를 만들 수 있다.","confusedWith":"Security는 특히 의도적 악용·침해에 대한 보호에 초점을 둔다.","paperReading":"논문 해석 시 확인: Security는 특히 의도적 악용·침해에 대한 보호에 초점을 둔다.","sourceUrl":"https://arxiv.org/abs/2112.04359"},{"term":"Governance","korean":"거버넌스","category":"기초·거버넌스","ordinaryMeaning":"방향과 규칙을 정하고 감독하는 방식","etymology":"govern(다스리다·운영하다)+-ance(행위·상태)의 단어 형성입니다.","aiMeaning":"AI의 의사결정권·책임·감독·위험 수용·중단 절차를 정하는 체계.","example":"고위험 기능의 배포를 누가 승인하고 사고 시 누가 중단하는지 정한다.","confusedWith":"개별 기술 통제나 정부 규제 하나만 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 개별 기술 통제나 정부 규제 하나만 뜻하지 않는다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Bias","korean":"편향","category":"공정성","ordinaryMeaning":"한쪽으로 기울어진 성향","etymology":"기울어짐이라는 일상적 의미를 데이터·판단에 적용한 용법입니다.","aiMeaning":"표본·측정·학습·운영 과정에서 결과가 체계적으로 치우치는 현상. 윤리적 해악 여부는 맥락을 따져야 한다.","example":"한 지역 자료로만 학습해 다른 지역 표현에서 오류가 많다.","confusedWith":"통계적 편향, 모델 절편(bias term), 사회적 편견은 같은 문맥이 아니다.","paperReading":"논문 해석 시 확인: 통계적 편향, 모델 절편(bias term), 사회적 편견은 같은 문맥이 아니다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Fairness","korean":"공정성","category":"공정성","ordinaryMeaning":"부당한 차별 없이 정당하게 대우함","etymology":"fair(공정한)+-ness(성질)의 단어 형성입니다.","aiMeaning":"영향을 받는 사람과 피해를 고려해 대우·기회·오류의 정당성을 판단하는 가치와 여러 측정 기준.","example":"선발률뿐 아니라 자격 있는 지원자를 놓치는 비율도 검토한다.","confusedWith":"지표 하나의 동등성이 사회적 공정성 전체를 증명하지 않는다.","paperReading":"논문 해석 시 확인: 지표 하나의 동등성이 사회적 공정성 전체를 증명하지 않는다.","sourceUrl":"https://arxiv.org/abs/1908.09635"},{"term":"Demographic parity","korean":"인구통계학적 동등성","category":"공정성","ordinaryMeaning":"인구 집단 사이의 동등함","etymology":"demographic(인구집단 관련)+parity(동등)의 합성어입니다.","aiMeaning":"집단별 양성 예측 비율, 즉 선택률을 같게 요구하는 공정성 기준.","example":"두 집단에서 모두 30%를 선발한다.","confusedWith":"Equalized Odds는 실제 결과로 조건화한 오류율·TPR을 비교한다.","paperReading":"논문 해석 시 확인: Equalized Odds는 실제 결과로 조건화한 오류율·TPR을 비교한다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"},{"term":"Equalized odds","korean":"균등화된 오즈","category":"공정성","ordinaryMeaning":"조건별 가능성을 같게 맞춤","etymology":"equalized(같아지게 한)+odds(가능성)의 표현. 여기의 정의를 일반 통계 odds 비율과 혼동하지 않습니다.","aiMeaning":"이진 분류에서 집단 간 TPR과 FPR을 모두 같게 요구한다. 실제 라벨을 조건으로 예측과 집단이 독립인 조건이다.","example":"A와 B에서 TPR=.8, FPR=.2가 모두 같아야 한다.","confusedWith":"Equal Opportunity는 TPR만 같게 요구하는 완화된 조건이다.","paperReading":"논문 해석 시 확인: Equal Opportunity는 TPR만 같게 요구하는 완화된 조건이다.","sourceUrl":"https://arxiv.org/abs/1610.02413"},{"term":"Equal opportunity","korean":"기회 균등","category":"공정성","ordinaryMeaning":"자격이 있는 사람에게 같은 기회를 줌","etymology":"equal(동등한)+opportunity(기회)의 합성 표현입니다.","aiMeaning":"이진 분류의 유리한 양성 결과를 받을 자격이 실제로 있는 집단 사이에 TPR을 같게 요구한다.","example":"자격 있는 지원자를 선발하는 비율이 집단마다 80%이다.","confusedWith":"Equalized Odds와 달리 FPR 동등까지 요구하지 않는다.","paperReading":"논문 해석 시 확인: Equalized Odds와 달리 FPR 동등까지 요구하지 않는다.","sourceUrl":"https://arxiv.org/abs/1610.02413"},{"term":"Calibration","korean":"보정","category":"공정성·평가","ordinaryMeaning":"계기의 눈금을 실제 기준에 맞춤","etymology":"측정기의 보정이라는 공학적 의미를 확률 예측에 적용한 비유입니다.","aiMeaning":"예측 확률과 관측 빈도가 맞는 정도. 집단별 보정은 각 집단 안에서 이를 점검한다.","example":"0.8 점수를 받은 사례 중 대략 80%가 실제 양성이다.","confusedWith":"높은 분류 정확도나 같은 집단별 TPR과 동일하지 않다.","paperReading":"논문 해석 시 확인: 높은 분류 정확도나 같은 집단별 TPR과 동일하지 않다.","sourceUrl":"https://proceedings.mlr.press/v70/guo17a.html"},{"term":"Base rate","korean":"기저율","category":"공정성·평가","ordinaryMeaning":"바탕이 되는 발생 비율","etymology":"base(기반)+rate(비율)의 합성어입니다.","aiMeaning":"집단에서 실제 양성 사건이 발생하는 비율 P(Y=1).","example":"A집단의 실제 양성은 50%, B집단은 20%이다.","confusedWith":"예측이 양성인 비율인 selection rate와 다르다.","paperReading":"논문 해석 시 확인: 예측이 양성인 비율인 selection rate와 다르다.","sourceUrl":"https://arxiv.org/abs/1610.02413"},{"term":"Counterfactual fairness","korean":"반사실적 공정성","category":"공정성","ordinaryMeaning":"사실과 다른 가정을 해도 공정함","etymology":"counterfactual은 counter-(반대)+factual(사실의)라는 단어 형성으로 이해합니다.","aiMeaning":"인과 모형에서 같은 개인의 보호 속성이 달랐을 반사실 상황에도 예측이 달라지지 않는지 보는 기준.","example":"다른 배경 변수가 어떻게 달라질지까지 인과 가정을 명시한다.","confusedWith":"입력의 보호 속성 칸만 바꾸는 단순 테스트와 같지 않다.","paperReading":"논문 해석 시 확인: 입력의 보호 속성 칸만 바꾸는 단순 테스트와 같지 않다.","sourceUrl":"https://arxiv.org/abs/1703.06856"},{"term":"Reweighing","korean":"재가중","category":"공정성","ordinaryMeaning":"다시 무게를 매김","etymology":"re-(다시)+weigh(무게를 재다)의 단어 형성입니다.","aiMeaning":"학습 사례가 목적함수에 기여하는 상대적 크기를 조정하는 방법.","example":"드물거나 불리한 사례의 손실 기여를 높여 학습한다.","confusedWith":"Resampling은 사례 수를 다시 뽑는 방식이고 재가중은 기여도를 바꾼다.","paperReading":"논문 해석 시 확인: Resampling은 사례 수를 다시 뽑는 방식이고 재가중은 기여도를 바꾼다.","sourceUrl":"https://arxiv.org/abs/2006.13114"},{"term":"Threshold","korean":"임계값","category":"공정성·평가","ordinaryMeaning":"문턱, 기준을 넘는 경계","etymology":"문턱이라는 일상적 의미를 수치 결정 경계에 적용한 비유입니다.","aiMeaning":"연속 점수를 이진 결정 등으로 바꾸는 기준값.","example":"점수가 0.7 이상이면 검토 대상으로 표시한다.","confusedWith":"확률 점수 자체나 모델 가중치와 다르다.","paperReading":"논문 해석 시 확인: 확률 점수 자체나 모델 가중치와 다르다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"},{"term":"Distribution shift","korean":"분포 이동","category":"공정성·평가","ordinaryMeaning":"자료가 나타나는 양상이 바뀜","etymology":"distribution(분포)+shift(이동)의 합성 표현입니다.","aiMeaning":"학습·평가·배포 사이에 입력·라벨·관계의 분포가 달라지는 현상.","example":"일상 문장으로 학습한 모델을 전문 법률 문서에 쓴다.","confusedWith":"일부 사례의 무작위 오차나 의도적 공격과 반드시 같지는 않다.","paperReading":"논문 해석 시 확인: 일부 사례의 무작위 오차나 의도적 공격과 반드시 같지는 않다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Adversarial debiasing","korean":"적대적 편향 완화","category":"공정성","ordinaryMeaning":"상대와 경쟁하며 치우침을 줄임","etymology":"adversarial(경쟁·적대적인)+de-biasing(편향을 줄임)의 구성입니다.","aiMeaning":"보호 속성을 추측하는 보조 모델과 경쟁하는 등의 학습으로 불필요한 집단 정보 의존을 줄이려는 방법.","example":"주 예측은 유지하면서 표현에서 집단을 읽기 어렵게 학습한다.","confusedWith":"사이버 공격을 실행한다는 뜻이 아니며 모든 공정성 정의를 보장하지 않는다.","paperReading":"논문 해석 시 확인: 사이버 공격을 실행한다는 뜻이 아니며 모든 공정성 정의를 보장하지 않는다.","sourceUrl":"https://arxiv.org/abs/1801.07593"},{"term":"Explainability","korean":"설명가능성","category":"설명·해석","ordinaryMeaning":"이유를 설명할 수 있음","etymology":"explain(설명하다)+-ability(가능성)의 단어 형성입니다.","aiMeaning":"모델이나 시스템의 판단 근거를 대상 독자가 이해하도록 설명할 수 있는 정도.","example":"사용자에게 결정에 영향을 준 조건과 한계를 보여 준다.","confusedWith":"그럴듯한 자연어 설명이 실제 계산에 충실하다는 보장은 없다.","paperReading":"논문 해석 시 확인: 그럴듯한 자연어 설명이 실제 계산에 충실하다는 보장은 없다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Interpretability","korean":"해석가능성","category":"설명·해석","ordinaryMeaning":"의미와 구조를 알아볼 수 있음","etymology":"interpret(해석하다)+-ability(가능성)의 단어 형성입니다.","aiMeaning":"모델의 구조·표현·행동을 사람이 이해할 수 있는 정도. 논문마다 정의가 달라 명시가 필요하다.","example":"작은 결정나무의 조건을 따라 결과를 이해한다.","confusedWith":"Explainability와 겹치지만 문헌에 따라 구분 방식이 다르다.","paperReading":"논문 해석 시 확인: Explainability와 겹치지만 문헌에 따라 구분 방식이 다르다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"LIME","korean":"국소적 대리 설명","category":"설명·해석","ordinaryMeaning":"영어 일반어 lime은 라임·석회지만 여기서는 약어","etymology":"Local Interpretable Model-agnostic Explanations의 약어입니다.","aiMeaning":"관심 입력 주변에서 단순한 대리 모델을 맞춰 원모델의 해당 예측을 설명하는 방법.","example":"문장 주변의 변형 예시로 어떤 단어가 예측에 영향을 주는지 근사한다.","confusedWith":"국소 설명을 모델 전체의 보편 규칙으로 확대하면 안 된다.","paperReading":"논문 해석 시 확인: 국소 설명을 모델 전체의 보편 규칙으로 확대하면 안 된다.","sourceUrl":"https://arxiv.org/abs/1602.04938"},{"term":"SHAP","korean":"샤플리 기반 가산 설명","category":"설명·해석","ordinaryMeaning":"일상 단어가 아니라 기법 이름","etymology":"SHapley Additive exPlanations에서 글자를 취한 명칭입니다.","aiMeaning":"특징 기여를 가산적으로 배분해 개별 예측을 설명하는 방법군·프레임워크.","example":"기준 예측에서 각 특징의 기여를 더해 특정 예측을 설명한다.","confusedWith":"기여도는 인과효과가 아니며 배경 분포·의존성 가정에 주의한다.","paperReading":"논문 해석 시 확인: 기여도는 인과효과가 아니며 배경 분포·의존성 가정에 주의한다.","sourceUrl":"https://papers.nips.cc/paper_files/paper/2017/hash/8a20a8621978632d76c43dfd28b67767-Abstract.html"},{"term":"Integrated gradients","korean":"통합 기울기","category":"설명·해석","ordinaryMeaning":"기울기 정보를 모아 누적함","etymology":"integrated(적분·통합된)+gradients(기울기)의 합성어입니다.","aiMeaning":"기준 입력에서 대상 입력까지 경로의 기울기를 누적해 입력 특징 기여를 구하는 설명 기법.","example":"기준 이미지 선택을 바꿨을 때 기여 지도가 어떻게 변하는지 본다.","confusedWith":"기준 입력을 쓰지 않는 단일 지점 기울기와 다르다.","paperReading":"논문 해석 시 확인: 기준 입력을 쓰지 않는 단일 지점 기울기와 다르다.","sourceUrl":"https://proceedings.mlr.press/v70/sundararajan17a.html"},{"term":"Faithfulness","korean":"충실성","category":"설명·해석","ordinaryMeaning":"대상을 왜곡하지 않고 충실히 따름","etymology":"faithful(충실한)+-ness(성질)의 단어 형성입니다.","aiMeaning":"설명이 모델이 실제로 사용하는 정보·동작을 얼마나 정확히 반영하는지 나타내는 성질.","example":"중요하다고 설명한 특징의 변화가 실제 예측 변화와 연결되는지 본다.","confusedWith":"사용자가 그럴듯하다고 느끼는 plausibility와 다르다.","paperReading":"논문 해석 시 확인: 사용자가 그럴듯하다고 느끼는 plausibility와 다르다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Stability","korean":"안정성","category":"설명·해석","ordinaryMeaning":"작은 변화에 크게 흔들리지 않음","etymology":"stable(안정된)+-ity(성질)의 단어 형성입니다.","aiMeaning":"관련 없는 작은 입력 변화 등에 설명이나 결과가 얼마나 일관되게 유지되는지 보는 성질.","example":"의미가 같은 문장의 순서만 바꾸었는데 설명이 뒤집히는지 확인한다.","confusedWith":"항상 같은 잘못된 설명도 안정적일 수 있어 충실성과 별도다.","paperReading":"논문 해석 시 확인: 항상 같은 잘못된 설명도 안정적일 수 있어 충실성과 별도다.","sourceUrl":"https://arxiv.org/abs/2103.11251"},{"term":"Probe","korean":"프로브·탐침","category":"설명·해석","ordinaryMeaning":"안을 살펴보는 탐침이나 조사","etymology":"탐침을 넣어 상태를 살피는 일상적 비유입니다.","aiMeaning":"내부 표현에 어떤 정보가 담겼는지 간단한 예측기 등으로 조사하는 방법.","example":"활성화에서 문장 품사 정보를 읽을 수 있는지 시험한다.","confusedWith":"정보를 읽을 수 있다는 사실만으로 모델이 그것을 원인으로 사용함을 입증하지 않는다.","paperReading":"논문 해석 시 확인: 정보를 읽을 수 있다는 사실만으로 모델이 그것을 원인으로 사용함을 입증하지 않는다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Sparse autoencoder","korean":"희소 오토인코더","category":"설명·해석","ordinaryMeaning":"적은 부분만 활성인 자동 부호화·복원 장치","etymology":"sparse(드문)+autoencoder(자기 입력을 부호화해 복원하는 모델)의 구성입니다.","aiMeaning":"활성화 등을 희소한 특징 조합으로 표현하고 복원하도록 학습하는 모델.","example":"한 입력에서 적은 수의 특징이 켜지는 표현을 분석한다.","confusedWith":"Sparse는 단순히 모델 파일이 작다는 뜻이 아니며 특징 이름도 해석 가설이다.","paperReading":"논문 해석 시 확인: Sparse는 단순히 모델 파일이 작다는 뜻이 아니며 특징 이름도 해석 가설이다.","sourceUrl":"https://transformer-circuits.pub/2023/monosemantic-features/index.html"},{"term":"Model card","korean":"모델 카드","category":"투명성·감사","ordinaryMeaning":"모델의 요점을 적은 카드","etymology":"제품 정보를 담는 카드에 모델 문서를 비유한 명칭입니다.","aiMeaning":"의도된 사용·성능·평가 조건·한계 등을 정리한 모델 문서.","example":"언어별 평가 범위와 쓰지 말아야 할 용도를 적는다.","confusedWith":"데이터 생성 이력을 중심으로 하는 Datasheet와 대상이 다르다.","paperReading":"논문 해석 시 확인: 데이터 생성 이력을 중심으로 하는 Datasheet와 대상이 다르다.","sourceUrl":"https://arxiv.org/abs/1810.03993"},{"term":"Datasheet","korean":"데이터 시트","category":"투명성·감사","ordinaryMeaning":"사양과 정보를 정리한 표·문서","etymology":"data(자료)+sheet(종이)의 합성어. 부품 사양서 형식을 데이터셋에 빌린 명칭입니다.","aiMeaning":"데이터셋의 동기·구성·수집·처리·사용·관리 정보를 문서화하는 접근.","example":"누가 어떤 동의 아래 수집했는지 기록한다.","confusedWith":"데이터 행 자체나 모델 성능표만을 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 데이터 행 자체나 모델 성능표만을 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/1803.09010"},{"term":"Transparency","korean":"투명성","category":"투명성·감사","ordinaryMeaning":"안이나 과정을 들여다볼 수 있음","etymology":"물체가 비쳐 보인다는 성질을 정보 공개에 적용한 비유입니다.","aiMeaning":"시스템의 목적·사용 방식·한계·책임·평가 정보를 필요한 사람에게 이해 가능하게 제공하는 성질.","example":"사용자가 AI 응답임과 검증 한계를 알 수 있게 한다.","confusedWith":"모든 데이터를 무조건 공개하거나 설명 하나를 생성하는 것과 같지 않다.","paperReading":"논문 해석 시 확인: 모든 데이터를 무조건 공개하거나 설명 하나를 생성하는 것과 같지 않다.","sourceUrl":"https://arxiv.org/abs/1810.03993"},{"term":"Accountability","korean":"책임성","category":"투명성·감사","ordinaryMeaning":"결정과 결과에 대해 설명하고 책임짐","etymology":"account for(설명하다·책임지다)+-ability의 구성으로 이해할 수 있습니다.","aiMeaning":"행동·결정의 근거를 추적하고 시정·감독·구제의 책임을 배정하는 체계적 성질.","example":"오류 신고를 접수할 담당자와 모델 중단권자를 정한다.","confusedWith":"사후 비난이나 법적 liability만으로 좁히지 않는다.","paperReading":"논문 해석 시 확인: 사후 비난이나 법적 liability만으로 좁히지 않는다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"Audit","korean":"감사","category":"투명성·감사","ordinaryMeaning":"증거를 살펴 기준에 맞는지 점검함","etymology":"일상적 회계·업무 감사를 AI 시스템 검토에 확장한 용법입니다.","aiMeaning":"명시한 기준·범위에 따라 개발·모델·응용의 주장과 증거를 검토하는 과정.","example":"개인정보 보호 주장과 실제 로그·접근 통제를 대조한다.","confusedWith":"단일 성능 시험이나 인증 결과와 동일하지 않다.","paperReading":"논문 해석 시 확인: 단일 성능 시험이나 인증 결과와 동일하지 않다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"AI-BOM","korean":"AI 구성요소 명세","category":"투명성·공급망","ordinaryMeaning":"AI에 들어간 재료 목록","etymology":"AI+Bill of Materials(부품·재료 명세)의 약어 결합입니다.","aiMeaning":"모델·데이터·소프트웨어 등 AI 구성요소의 출처·버전·관계를 추적하려는 목록. 범위와 형식은 명시해야 한다.","example":"배포 모델과 토크나이저, 데이터 출처의 버전을 연결한다.","confusedWith":"목록 존재가 안전성·라이선스 준수의 자동 보장은 아니다.","paperReading":"논문 해석 시 확인: 목록 존재가 안전성·라이선스 준수의 자동 보장은 아니다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf"},{"term":"Incident response","korean":"사고 대응","category":"투명성·보안","ordinaryMeaning":"문제가 생겼을 때 대응함","etymology":"incident(사건)+response(대응)의 합성어입니다.","aiMeaning":"탐지·영향 제한·조사·복구·재발 방지를 통해 AI 관련 사고를 처리하는 활동.","example":"잘못된 안내를 중단하고 영향 범위와 원인을 기록한다.","confusedWith":"예방 시험만으로 사고 대응 체계를 대체할 수 없다.","paperReading":"논문 해석 시 확인: 예방 시험만으로 사고 대응 체계를 대체할 수 없다.","sourceUrl":"https://arxiv.org/abs/2001.00973"},{"term":"Alignment","korean":"정렬","category":"정렬·안전","ordinaryMeaning":"방향이나 줄을 맞춤","etymology":"방향을 맞춘다는 일상적 비유를 모델 목표·행동에 적용합니다.","aiMeaning":"모델의 행동을 의도한 목표·원칙·사람의 선호 등에 맞추려는 문제와 과정.","example":"유용하게 답하면서 모르는 사실을 지어내지 않도록 평가한다.","confusedWith":"말투가 공손하거나 모든 사용자 주장에 동의하는 것과 다르다.","paperReading":"논문 해석 시 확인: 말투가 공손하거나 모든 사용자 주장에 동의하는 것과 다르다.","sourceUrl":"https://arxiv.org/abs/2203.02155"},{"term":"RLHF","korean":"인간 피드백 기반 강화학습","category":"정렬·안전","ordinaryMeaning":"사람의 평가를 바탕으로 보상을 학습함","etymology":"Reinforcement Learning from Human Feedback의 약어입니다.","aiMeaning":"인간의 평가·선호에서 얻은 신호를 사용해 강화학습으로 모델 행동을 개선하는 접근.","example":"응답 쌍의 선호를 학습한 보상으로 정책을 조정한다.","confusedWith":"지도 미세조정만과 다르며 인간 가치 전체의 완전한 대변도 아니다.","paperReading":"논문 해석 시 확인: 지도 미세조정만과 다르며 인간 가치 전체의 완전한 대변도 아니다.","sourceUrl":"https://arxiv.org/abs/2203.02155"},{"term":"DPO","korean":"직접 선호 최적화","category":"정렬·안전","ordinaryMeaning":"선호에 맞추어 직접 개선함","etymology":"Direct Preference Optimization의 약어입니다.","aiMeaning":"선호 쌍에 대한 목적함수로 정책을 직접 학습해 명시적 보상 모델·온라인 강화학습 단계 일부를 피하는 방법.","example":"좋은 응답과 덜 선호한 응답의 상대 확률을 조정한다.","confusedWith":"선호 데이터가 필요 없다는 뜻이나 모든 정렬 문제 해결이라는 뜻이 아니다.","paperReading":"논문 해석 시 확인: 선호 데이터가 필요 없다는 뜻이나 모든 정렬 문제 해결이라는 뜻이 아니다.","sourceUrl":"https://arxiv.org/abs/2305.18290"},{"term":"Constitutional AI","korean":"원칙 기반 AI 정렬","category":"정렬·안전","ordinaryMeaning":"명시된 기본 원칙에 따르는 AI","etymology":"constitution(기본 원칙·헌장)을 정렬 원칙 집합에 비유한 명칭입니다.","aiMeaning":"원칙을 이용한 자기 비평·수정 및 AI 피드백 등을 활용하여 행동을 조정하는 접근.","example":"원칙에 비추어 응답을 검토하고 수정한 예시로 학습한다.","confusedWith":"실제 국가 헌법의 자동 적용이나 가치 갈등 해소를 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 실제 국가 헌법의 자동 적용이나 가치 갈등 해소를 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/2212.08073"},{"term":"Reward model","korean":"보상 모델","category":"정렬·안전","ordinaryMeaning":"행동이나 결과에 점수를 주는 모형","etymology":"reward(보상)+model(모형)의 합성어입니다.","aiMeaning":"응답의 선호·품질 등을 점수로 추정하여 학습 목표의 대리 신호로 쓰는 모델.","example":"두 답변 가운데 사람이 더 선호할 답에 높은 점수를 예측한다.","confusedWith":"점수는 진실·안전의 완벽한 측정값이 아니다.","paperReading":"논문 해석 시 확인: 점수는 진실·안전의 완벽한 측정값이 아니다.","sourceUrl":"https://arxiv.org/abs/2203.02155"},{"term":"Reward hacking","korean":"보상 해킹","category":"정렬·안전","ordinaryMeaning":"보상 규칙의 빈틈으로 점수만 얻음","etymology":"hacking을 목표의 빈틈 이용이라는 비유로 사용합니다.","aiMeaning":"의도한 좋은 결과 대신 불완전한 보상 신호를 높이는 행동.","example":"설명을 장황하게 해 평가자의 선호는 얻지만 정확성은 늘지 않는다.","confusedWith":"반드시 외부 공격자가 시스템에 침입하는 현상은 아니다.","paperReading":"논문 해석 시 확인: 반드시 외부 공격자가 시스템에 침입하는 현상은 아니다.","sourceUrl":"https://arxiv.org/abs/2305.18290"},{"term":"Sycophancy","korean":"아첨·영합","category":"정렬·안전","ordinaryMeaning":"상대의 환심을 사려고 맞장구침","etymology":"일상적 아첨이라는 뜻을 모델 응답 성향에 적용한 용법. 불확실한 역사적 어원은 생략합니다.","aiMeaning":"사실이나 독립적 판단보다 사용자의 믿음·선호에 맞추어 답하는 경향.","example":"사용자가 답을 바꾸라고 압박하면 근거 없이 동의한다.","confusedWith":"친절함이나 근거 있는 동의 자체가 아첨은 아니다.","paperReading":"논문 해석 시 확인: 친절함이나 근거 있는 동의 자체가 아첨은 아니다.","sourceUrl":"https://arxiv.org/abs/2310.13548"},{"term":"Watermark","korean":"워터마크","category":"콘텐츠·지식재산","ordinaryMeaning":"종이·콘텐츠에 넣는 식별 표식","etymology":"종이의 식별 무늬라는 말을 디지털 생성 신호에 적용한 비유입니다.","aiMeaning":"생성물이나 모델에 출처·소유 관련 식별 신호를 넣고 나중에 검출하는 기술.","example":"생성 텍스트에 특정 통계 패턴을 유도해 검출한다.","confusedWith":"검출 실패가 인간 작성의 증명은 아니며 사실성 인증도 아니다.","paperReading":"논문 해석 시 확인: 검출 실패가 인간 작성의 증명은 아니며 사실성 인증도 아니다.","sourceUrl":"https://proceedings.mlr.press/v202/kirchenbauer23a.html"},{"term":"Provenance","korean":"출처·이력","category":"콘텐츠·공급망","ordinaryMeaning":"어디에서 와서 어떤 과정을 거쳤는지","etymology":"작품·자료의 출처와 소유 이력을 뜻하는 말을 데이터·모델에 확장한 용법입니다.","aiMeaning":"데이터·모델·콘텐츠의 생성·편집·이동·사용 이력을 추적하는 정보.","example":"데이터 수집 시점과 변환, 모델 버전, 콘텐츠 서명 이력을 남긴다.","confusedWith":"출처를 안다는 것과 내용이 사실·합법·안전하다는 것은 다르다.","paperReading":"논문 해석 시 확인: 출처를 안다는 것과 내용이 사실·합법·안전하다는 것은 다르다.","sourceUrl":"https://c2pa.org/specifications/specifications/2.2/specs/C2PA_Specification.html"},{"term":"Safety case","korean":"안전성 논증","category":"정렬·거버넌스","ordinaryMeaning":"안전하다는 주장을 뒷받침하는 논거 묶음","etymology":"case는 여기서 사건이 아니라 주장과 근거를 갖춘 논증이라는 뜻입니다.","aiMeaning":"허용 가능한 위험이라는 주장을 하위 주장·가정·증거로 구조화한 설명.","example":"특정 사용 범위의 위험과 통제 효과를 시험 근거로 연결한다.","confusedWith":"안전 사례 하나나 높은 벤치마크 점수 하나와 다르다.","paperReading":"논문 해석 시 확인: 안전 사례 하나나 높은 벤치마크 점수 하나와 다르다.","sourceUrl":"https://arxiv.org/abs/2403.10462"},{"term":"Conformity assessment","korean":"적합성 평가","category":"거버넌스","ordinaryMeaning":"정해진 요구에 맞는지 평가함","etymology":"conformity(일치·적합)+assessment(평가)의 합성어입니다.","aiMeaning":"제품·시스템·과정 등이 명시된 요구사항을 충족하는지 입증하는 활동.","example":"적용 가능한 요구마다 시험·문서·검토 증거를 연결한다.","confusedWith":"인증은 적합성 평가의 한 형태이며 모든 평가가 인증은 아니다.","paperReading":"논문 해석 시 확인: 인증은 적합성 평가의 한 형태이며 모든 평가가 인증은 아니다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Adversarial example","korean":"적대적 예제","category":"적대적 ML","ordinaryMeaning":"상대를 실패시키려 고른 사례","etymology":"adversarial(적대적인)+example(예시·입력)의 합성어입니다.","aiMeaning":"모델의 오류를 유도하려는 목적 아래 선택·변형된 입력.","example":"의미상 같은 대상인데 제한된 변화로 예측이 달라지는 경우를 연구한다.","confusedWith":"일반 오류나 자연적 분포 이동이 모두 적대적 예제인 것은 아니다.","paperReading":"논문 해석 시 확인: 일반 오류나 자연적 분포 이동이 모두 적대적 예제인 것은 아니다.","sourceUrl":"https://arxiv.org/abs/1412.6572"},{"term":"Evasion","korean":"회피","category":"적대적 ML","ordinaryMeaning":"피하거나 빠져나감","etymology":"일상어 evade의 뜻을 탐지·판단을 피하는 행동에 적용합니다.","aiMeaning":"주로 배포·추론 시점 입력을 조작해 모델의 탐지나 판단을 피하려는 공격 유형.","example":"학습 데이터는 그대로 두고 시험 입력 조건을 바꾼다.","confusedWith":"Poisoning은 학습 자료·과정에 영향을 주는 유형이다.","paperReading":"논문 해석 시 확인: Poisoning은 학습 자료·과정에 영향을 주는 유형이다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf"},{"term":"Adaptive attack","korean":"적응형 공격","category":"적대적 ML","ordinaryMeaning":"상대 특성에 맞춰 조정하는 공격","etymology":"adaptive(적응하는)+attack(공격)의 합성어입니다.","aiMeaning":"방어의 구조·작동 방식을 고려하여 그 방어를 평가하도록 조정한 공격.","example":"확률적 방어에는 그 확률성까지 고려한 시험이 필요하다.","confusedWith":"모든 모델에 똑같은 기본 설정을 적용하는 평가와 다르다.","paperReading":"논문 해석 시 확인: 모든 모델에 똑같은 기본 설정을 적용하는 평가와 다르다.","sourceUrl":"https://arxiv.org/abs/2002.08347"},{"term":"Gradient masking","korean":"그래디언트 마스킹","category":"적대적 ML","ordinaryMeaning":"기울기 정보를 가리거나 흐림","etymology":"gradient(기울기)+masking(가림)의 비유적 합성어입니다.","aiMeaning":"공격에 유용한 기울기를 얻기 어렵게 해 약한 평가에서 강건해 보이지만 실제 견고함은 아닐 수 있는 현상.","example":"기울기 기반 시험만 실패하고 다른 평가에서는 오류가 드러난다.","confusedWith":"기울기를 가렸다는 사실이 인증 강건성을 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 기울기를 가렸다는 사실이 인증 강건성을 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/2002.08347"},{"term":"Certified robustness","korean":"인증 강건성","category":"적대적 ML","ordinaryMeaning":"정해진 강건성을 증명함","etymology":"certified(증명된)+robustness(강건성)의 합성어입니다.","aiMeaning":"명시한 입력 변화 집합·확률 가정 등 아래 예측 유지 등을 수학적으로 보장하는 접근.","example":"인증 반경 안에서 결과가 유지된다는 보장을 제시한다.","confusedWith":"일반 제품 인증이나 모든 공격 종류의 안전 보장과 다르다.","paperReading":"논문 해석 시 확인: 일반 제품 인증이나 모든 공격 종류의 안전 보장과 다르다.","sourceUrl":"https://proceedings.mlr.press/v97/cohen19c.html"},{"term":"Data poisoning","korean":"데이터 오염","category":"공급망·보안","ordinaryMeaning":"자료에 독을 섞는다는 비유","etymology":"poisoning의 오염 비유를 학습 자료 조작에 적용합니다.","aiMeaning":"학습 데이터나 관련 학습 과정에 영향을 주어 모델 행동을 바꾸려는 공격 유형.","example":"신뢰하기 어려운 데이터 유입이 이후 모델에 영향을 주는 위험을 분석한다.","confusedWith":"추론 입력만 바꾸는 evasion과 구분한다.","paperReading":"논문 해석 시 확인: 추론 입력만 바꾸는 evasion과 구분한다.","sourceUrl":"https://arxiv.org/abs/2302.10149"},{"term":"Backdoor","korean":"백도어","category":"공급망·보안","ordinaryMeaning":"정문이 아닌 숨은 뒷문","etymology":"숨은 출입구를 특정 조건부 동작에 비유한 표현입니다.","aiMeaning":"특정 조건에서 의도된 비정상 동작을 하도록 모델에 심어진 행동 패턴.","example":"일반 평가에서는 정상인데 특정 조건에서만 정책을 어기는 현상.","confusedWith":"일반적인 성능 저하나 모든 우연한 오류가 백도어는 아니다.","paperReading":"논문 해석 시 확인: 일반적인 성능 저하나 모든 우연한 오류가 백도어는 아니다.","sourceUrl":"https://arxiv.org/abs/2401.05566"},{"term":"Trigger","korean":"트리거·촉발 조건","category":"공급망·보안","ordinaryMeaning":"어떤 일이 시작되게 하는 계기","etymology":"방아쇠의 촉발 기능을 조건에 비유한 단어입니다.","aiMeaning":"백도어 등에서 특정 행동을 유발하도록 연결된 입력·맥락 조건.","example":"특정 조건이 있을 때와 없을 때 동작 차이를 비교한다.","confusedWith":"반드시 눈에 보이는 이미지 패턴이나 특정 단어만 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 반드시 눈에 보이는 이미지 패턴이나 특정 단어만 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/2401.05566"},{"term":"Clean-label poisoning","korean":"클린라벨 오염","category":"공급망·보안","ordinaryMeaning":"겉으로 맞는 표지를 둔 오염","etymology":"clean-label은 라벨이 올바르게 유지됨을 뜻하는 조건 표현입니다.","aiMeaning":"학습 예시의 라벨은 정상처럼 유지하면서 학습에 해로운 영향을 유도하는 오염 유형.","example":"라벨 검사만으로 모든 오염을 찾기 어려운 이유를 설명한다.","confusedWith":"Clean은 무해하거나 개인정보가 없다는 뜻이 아니다.","paperReading":"논문 해석 시 확인: Clean은 무해하거나 개인정보가 없다는 뜻이 아니다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf"},{"term":"Supply chain","korean":"공급망","category":"공급망·보안","ordinaryMeaning":"제품을 만드는 재료와 공급 경로의 연결","etymology":"supply(공급)+chain(사슬)의 합성어를 소프트웨어·AI 구성요소에 확장합니다.","aiMeaning":"데이터·모델·코드·라이브러리·배포 서비스가 전달되고 결합되는 전체 경로.","example":"모델 허브뿐 아니라 토크나이저와 의존 라이브러리도 관리한다.","confusedWith":"모델의 학습 알고리즘 하나만 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 모델의 학습 알고리즘 하나만 뜻하지 않는다.","sourceUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf"},{"term":"Membership inference","korean":"멤버십 추론","category":"프라이버시","ordinaryMeaning":"어떤 집합에 속했는지 알아냄","etymology":"membership(구성원 여부)+inference(추론)의 합성어입니다.","aiMeaning":"특정 기록이 모델 학습 데이터에 포함되었는지 추정하는 문제.","example":"가상 기록에 대해 포함 여부 판별의 TPR과 FPR을 평가한다.","confusedWith":"기록의 실제 내용 복원이나 속성 추론과 구분한다.","paperReading":"논문 해석 시 확인: 기록의 실제 내용 복원이나 속성 추론과 구분한다.","sourceUrl":"https://arxiv.org/abs/2112.03570"},{"term":"Model inversion","korean":"모델 역전","category":"프라이버시","ordinaryMeaning":"모델 관계를 거꾸로 따라 입력 쪽을 알아봄","etymology":"inversion(거꾸로 뒤집음)을 입력 정보 복원에 적용한 표현입니다.","aiMeaning":"출력이나 모델 접근을 이용해 입력·민감 특성과 관련된 정보를 복원·추정하는 공격 유형.","example":"어떤 정보가 평균적 특징인지 실제 특정 기록인지 구별해 평가한다.","confusedWith":"모든 역전이 원본 학습 사례를 정확히 복원한다는 뜻은 아니다.","paperReading":"논문 해석 시 확인: 모든 역전이 원본 학습 사례를 정확히 복원한다는 뜻은 아니다.","sourceUrl":"https://dl.acm.org/doi/10.1145/2810103.2813677"},{"term":"Data extraction","korean":"데이터 추출","category":"프라이버시","ordinaryMeaning":"자료를 꺼내어 얻음","etymology":"data(자료)+extraction(꺼내기)의 합성어입니다.","aiMeaning":"모델 출력 등을 통해 학습 자료나 비공개 자료의 내용을 얻어내는 문제.","example":"출력과 원자료의 일치 여부·독창성·공개 여부를 확인한다.","confusedWith":"멤버십 추론은 포함 여부를, 추출은 내용 자체를 주로 묻는다.","paperReading":"논문 해석 시 확인: 멤버십 추론은 포함 여부를, 추출은 내용 자체를 주로 묻는다.","sourceUrl":"https://arxiv.org/abs/2012.07805"},{"term":"Differential privacy","korean":"차분 프라이버시","category":"프라이버시","ordinaryMeaning":"한 항목의 차이로 결과가 크게 달라지지 않는 보호","etymology":"differential(차이와 관련된)+privacy(프라이버시)의 기술 명칭입니다.","aiMeaning":"인접 데이터셋에서 알고리즘의 출력 분포가 얼마나 달라질 수 있는지 제한하는 수학적 보호 조건.","example":"한 사람의 참여 여부가 결과에 미치는 영향에 한계를 둔다.","confusedWith":"익명화나 암호화와 다르며 보호 단위·ε·δ를 함께 읽어야 한다.","paperReading":"논문 해석 시 확인: 익명화나 암호화와 다르며 보호 단위·ε·δ를 함께 읽어야 한다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"Epsilon","korean":"엡실론·ε","category":"프라이버시","ordinaryMeaning":"그리스 문자 이름","etymology":"수학에서 매개변수 기호로 쓰며 문자 자체에 프라이버시 뜻은 없습니다.","aiMeaning":"DP에서는 두 인접 데이터셋의 출력 확률 비교에 나타나는 프라이버시 손실 허용 매개변수.","example":"같은 보호 조건에서 ε가 작을수록 일반적으로 더 엄격하다.","confusedWith":"정확도나 유출 확률 그 자체가 아니며 다른 논문에서는 입력 변화 크기일 수 있다.","paperReading":"논문 해석 시 확인: 정확도나 유출 확률 그 자체가 아니며 다른 논문에서는 입력 변화 크기일 수 있다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"Delta","korean":"델타·δ","category":"프라이버시","ordinaryMeaning":"그리스 문자 이름","etymology":"수학적 매개변수 표기이며 문맥에 따라 의미가 바뀝니다.","aiMeaning":"근사 DP 정의의 확률 부등식에 더해지는 여유 항. ε·보호 단위·전체 알고리즘과 함께 해석한다.","example":"같은 ε라도 δ와 반복 사용 조건을 함께 확인한다.","confusedWith":"δ를 곧바로 실제 개인 정보가 유출될 확률이라고 단정하지 않는다.","paperReading":"논문 해석 시 확인: δ를 곧바로 실제 개인 정보가 유출될 확률이라고 단정하지 않는다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"DP-SGD","korean":"차분 프라이버시 확률적 경사하강법","category":"프라이버시","ordinaryMeaning":"개인정보 보호를 넣은 점진적 학습","etymology":"Differentially Private Stochastic Gradient Descent의 약어입니다.","aiMeaning":"개별 예시 기울기 제한과 노이즈 주입, 프라이버시 회계를 결합하는 학습 접근.","example":"클리핑 기준·노이즈·반복 횟수와 최종 ε·δ를 보고한다.","confusedWith":"단순히 데이터에 임의 노이즈를 더한 모든 학습과 같지 않다.","paperReading":"논문 해석 시 확인: 단순히 데이터에 임의 노이즈를 더한 모든 학습과 같지 않다.","sourceUrl":"https://arxiv.org/abs/1607.00133"},{"term":"Privacy accounting","korean":"프라이버시 회계","category":"프라이버시","ordinaryMeaning":"보호 비용을 장부처럼 셈","etymology":"accounting(회계)을 반복 사용의 누적 보호 비용 계산에 비유합니다.","aiMeaning":"여러 학습·조회 등으로 누적되는 DP 프라이버시 손실을 추적·상계하는 절차.","example":"반복 학습을 한 뒤 최종 예산을 다시 계산한다.","confusedWith":"실행 시간을 재는 계산 자원 accounting과 다르다.","paperReading":"논문 해석 시 확인: 실행 시간을 재는 계산 자원 accounting과 다르다.","sourceUrl":"https://arxiv.org/abs/1607.00133"},{"term":"Federated learning","korean":"연합학습","category":"프라이버시","ordinaryMeaning":"여러 참여자가 연합해 학습함","etymology":"federated(연합된)+learning(학습)의 합성어입니다.","aiMeaning":"데이터를 주로 각 참여자에 둔 채 업데이트 등을 모아 모델을 학습하는 분산 구조.","example":"각 기기에서 학습한 업데이트를 서버가 결합한다.","confusedWith":"데이터가 모이지 않는다는 사실만으로 업데이트의 정보 누출이 사라지지 않는다.","paperReading":"논문 해석 시 확인: 데이터가 모이지 않는다는 사실만으로 업데이트의 정보 누출이 사라지지 않는다.","sourceUrl":"https://proceedings.mlr.press/v54/mcmahan17a.html"},{"term":"Secure aggregation","korean":"보안 집계","category":"프라이버시","ordinaryMeaning":"개별 값을 숨기며 합침","etymology":"secure(보호된)+aggregation(집계)의 합성어입니다.","aiMeaning":"개별 참여자의 업데이트를 불필요하게 드러내지 않고 합계 등 집계 결과를 얻는 프로토콜.","example":"서버가 개별 업데이트 대신 집계값을 보도록 설계한다.","confusedWith":"집계 결과의 프라이버시나 악성 업데이트 부재까지 자동 보장하지 않는다.","paperReading":"논문 해석 시 확인: 집계 결과의 프라이버시나 악성 업데이트 부재까지 자동 보장하지 않는다.","sourceUrl":"https://research.google/pubs/practical-secure-aggregation-for-privacy-preserving-machine-learning/"},{"term":"Machine unlearning","korean":"기계 학습 망각","category":"프라이버시","ordinaryMeaning":"기계가 배운 영향을 잊게 함","etymology":"un-(되돌림)+learning(학습)의 단어 형성입니다.","aiMeaning":"선택한 학습 자료의 영향을 제거·완화하고 이를 검증하려는 방법과 문제.","example":"특정 기록을 제외하고 재학습한 기준과 비교해 망각 효과를 평가한다.","confusedWith":"원데이터 파일 삭제나 출력 차단만과 같은 뜻은 아니다.","paperReading":"논문 해석 시 확인: 원데이터 파일 삭제나 출력 차단만과 같은 뜻은 아니다.","sourceUrl":"https://arxiv.org/abs/1912.03817"},{"term":"Prompt injection","korean":"프롬프트 인젝션","category":"LLM·에이전트","ordinaryMeaning":"입력 문구에 지시를 끼워 넣음","etymology":"prompt(입력·지시)+injection(주입)의 비유적 합성어입니다.","aiMeaning":"신뢰하지 않아야 할 입력·자료의 지시가 모델이나 애플리케이션의 의도를 바꾸게 만드는 문제.","example":"외부 문서를 읽은 뒤 사용자 요청과 무관한 행동을 하게 되는 위험.","confusedWith":"Jailbreak는 주로 안전 제한 우회에 초점을 두며 두 범주는 겹칠 수 있다.","paperReading":"논문 해석 시 확인: Jailbreak는 주로 안전 제한 우회에 초점을 두며 두 범주는 겹칠 수 있다.","sourceUrl":"https://arxiv.org/abs/2302.12173"},{"term":"Jailbreak","korean":"탈옥","category":"LLM·에이전트","ordinaryMeaning":"감옥·제한에서 벗어남","etymology":"jail(감옥)+break(탈출)의 말을 소프트웨어 제한 우회에 비유합니다.","aiMeaning":"모델의 안전 정책이나 정렬로 제한된 행동을 유도하려는 시도.","example":"안전 평가에서 제한된 행동 유도가 성공했는지 추상적 기준으로 측정한다.","confusedWith":"모든 프롬프트 인젝션이 유해 콘텐츠 생성을 목표로 하는 것은 아니다.","paperReading":"논문 해석 시 확인: 모든 프롬프트 인젝션이 유해 콘텐츠 생성을 목표로 하는 것은 아니다.","sourceUrl":"https://arxiv.org/abs/2402.04249"},{"term":"Guardrail","korean":"가드레일","category":"LLM·에이전트","ordinaryMeaning":"도로에서 이탈을 막는 난간","etymology":"도로 안전 난간을 모델·시스템의 행동 제한 장치에 비유합니다.","aiMeaning":"입력·출력 검사, 정책 검사, 실행 제한 등 위험 행동을 줄이기 위한 통제.","example":"민감한 출력 검토와 도구 실행 제한을 함께 둔다.","confusedWith":"완벽한 안전 장벽이 아니며 우회·오탐·과잉 거부를 평가해야 한다.","paperReading":"논문 해석 시 확인: 완벽한 안전 장벽이 아니며 우회·오탐·과잉 거부를 평가해야 한다.","sourceUrl":"https://genai.owasp.org/llmrisk/llm01-prompt-injection/"},{"term":"Instruction hierarchy","korean":"명령 계층","category":"LLM·에이전트","ordinaryMeaning":"지시의 우선순위를 정한 구조","etymology":"instruction(지시)+hierarchy(계층)의 합성어입니다.","aiMeaning":"서로 다른 출처의 지시가 충돌할 때 우선순위를 두고 낮은 신뢰의 내용을 제한하는 원칙.","example":"외부 문서 문장을 사용자 승인이나 시스템 지시로 취급하지 않는다.","confusedWith":"우선순위를 텍스트로 적는 것만으로 시스템 권한 통제가 완성되지 않는다.","paperReading":"논문 해석 시 확인: 우선순위를 텍스트로 적는 것만으로 시스템 권한 통제가 완성되지 않는다.","sourceUrl":"https://arxiv.org/abs/2404.13208"},{"term":"Attack success rate","korean":"공격 성공률·ASR","category":"보안·평가","ordinaryMeaning":"시도 중 성공한 비율","etymology":"Attack Success Rate의 머리글자를 따 ASR이라 합니다.","aiMeaning":"정의한 공격 시도 집합에서 성공 조건을 만족한 비율. 분모·판정기·시도 예산을 함께 보고한다.","example":"허용한 동일 예산에서 방어 전후 성공률을 비교한다.","confusedWith":"정상 작업 성공률·과잉 거부율과 별도이며 논문마다 분모가 다를 수 있다.","paperReading":"논문 해석 시 확인: 정상 작업 성공률·과잉 거부율과 별도이며 논문마다 분모가 다를 수 있다.","sourceUrl":"https://arxiv.org/abs/2402.04249"},{"term":"Over-refusal","korean":"과잉 거부","category":"LLM·평가","ordinaryMeaning":"필요 이상으로 거절함","etymology":"over-(지나치게)+refusal(거절)의 합성어입니다.","aiMeaning":"허용되고 정상적인 요청까지 불필요하게 거부하는 행동.","example":"안전한 수업 질문까지 차단하는 비율을 평가한다.","confusedWith":"위험한 요청을 적절히 거절하는 안전 행동과 구분한다.","paperReading":"논문 해석 시 확인: 위험한 요청을 적절히 거절하는 안전 행동과 구분한다.","sourceUrl":"https://arxiv.org/abs/2402.04249"},{"term":"Agent","korean":"에이전트","category":"LLM·에이전트","ordinaryMeaning":"누군가를 대신해 행동하는 주체","etymology":"대리인이라는 일반적 뜻을 환경에서 행동하는 시스템에 적용합니다.","aiMeaning":"목표를 위해 관측·계획·도구 실행·피드백을 연결하는 시스템. 자율성 범위는 설계마다 다르다.","example":"문서를 찾고 정리한 뒤 허가된 위치에 저장한다.","confusedWith":"LLM 자체와 도구·권한·메모리를 포함한 시스템은 구분해야 한다.","paperReading":"논문 해석 시 확인: LLM 자체와 도구·권한·메모리를 포함한 시스템은 구분해야 한다.","sourceUrl":"https://arxiv.org/abs/2406.13352"},{"term":"RAG","korean":"검색 증강 생성","category":"LLM·에이전트","ordinaryMeaning":"찾은 자료로 생성을 보강함","etymology":"Retrieval-Augmented Generation의 약어입니다.","aiMeaning":"외부 저장소에서 관련 자료를 검색해 생성 모델의 문맥으로 활용하는 구조.","example":"강의 자료를 검색한 근거에 따라 질문에 답한다.","confusedWith":"검색이 자료의 진실성·권한·안전성을 보장하지 않으며 미세조정과 다르다.","paperReading":"논문 해석 시 확인: 검색이 자료의 진실성·권한·안전성을 보장하지 않으며 미세조정과 다르다.","sourceUrl":"https://arxiv.org/abs/2005.11401"},{"term":"Least privilege","korean":"최소 권한","category":"LLM·에이전트","ordinaryMeaning":"필요한 만큼만 권한을 줌","etymology":"least(최소)+privilege(특별 권한)의 합성어입니다.","aiMeaning":"주체·도구·작업에 필요한 최소 범위의 접근과 실행 권한만 부여하는 원칙.","example":"요약 도구에는 읽기 권한만 주고 메일 전송은 분리한다.","confusedWith":"최소 정보 제공과 관련되지만 권한 통제라는 구체적 초점이 있다.","paperReading":"논문 해석 시 확인: 최소 정보 제공과 관련되지만 권한 통제라는 구체적 초점이 있다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Sandbox","korean":"샌드박스","category":"LLM·에이전트","ordinaryMeaning":"모래놀이를 하는 한정된 공간","etymology":"놀이 공간의 경계를 실행 격리에 비유한 명칭입니다.","aiMeaning":"코드나 도구 실행이 외부 자원에 주는 영향을 제한하는 격리 환경.","example":"가상 파일과 제한된 네트워크에서 실험한다.","confusedWith":"격리 설정이 잘못되면 보호가 약해지며 모든 프라이버시를 보장하지 않는다.","paperReading":"논문 해석 시 확인: 격리 설정이 잘못되면 보호가 약해지며 모든 프라이버시를 보장하지 않는다.","sourceUrl":"https://csrc.nist.gov/glossary"},{"term":"Human-in-the-loop","korean":"사람 개입형 절차","category":"LLM·에이전트","ordinaryMeaning":"반복 과정 안에 사람이 참여함","etymology":"human+in the loop(과정에 포함)의 합성 표현, 약어 HITL입니다.","aiMeaning":"결정·검토·수정·승인 등 중요한 단계에 사람이 실질적으로 개입하도록 하는 설계.","example":"외부 전송 전 대상과 내용을 사람이 확인한다.","confusedWith":"사람이 이름만 올려 두거나 정보를 못 본 채 승인하는 것은 충분한 감독이 아니다.","paperReading":"논문 해석 시 확인: 사람이 이름만 올려 두거나 정보를 못 본 채 승인하는 것은 충분한 감독이 아니다.","sourceUrl":"https://arxiv.org/abs/2406.13352"},{"term":"Red teaming","korean":"레드팀 활동","category":"LLM·에이전트","ordinaryMeaning":"상대편 관점에서 약점을 찾아보기","etymology":"대항 팀을 뜻하는 red team의 역할 비유를 평가에 사용합니다.","aiMeaning":"허가된 범위에서 실패·악용 가능성을 적극적으로 탐색해 방어를 개선하는 활동.","example":"합성 환경에서 정상 업무와 경계 위반 시나리오를 함께 점검한다.","confusedWith":"타인 시스템에 대한 무단 공격이나 유해 결과 공개를 뜻하지 않는다.","paperReading":"논문 해석 시 확인: 타인 시스템에 대한 무단 공격이나 유해 결과 공개를 뜻하지 않는다.","sourceUrl":"https://arxiv.org/abs/2402.04249"},{"term":"Model extraction","korean":"모델 추출","category":"지식재산·보안","ordinaryMeaning":"모델의 정보나 기능을 얻어냄","etymology":"model(모델)+extraction(추출)의 합성어입니다.","aiMeaning":"출력·인터페이스·관측을 이용해 모델의 기능·구조·일부 매개변수 등을 알아내는 문제.","example":"기능 복제인지 일부 내부 정보 추정인지 성과 범위를 따로 적는다.","confusedWith":"모든 가중치의 완전한 복원이나 학습 데이터 추출과 같은 뜻은 아니다.","paperReading":"논문 해석 시 확인: 모든 가중치의 완전한 복원이나 학습 데이터 추출과 같은 뜻은 아니다.","sourceUrl":"https://arxiv.org/abs/2403.06634"},{"term":"Fingerprinting","korean":"핑거프린팅","category":"지식재산·보안","ordinaryMeaning":"고유 흔적으로 대상을 식별함","etymology":"fingerprint(지문)을 모델 식별 패턴에 적용한 비유입니다.","aiMeaning":"특정 모델·계열·소유권 주장에 연결되는 행동이나 특성 패턴을 검출하는 방식.","example":"여러 모델에서 같은 패턴이 우연히 나타나는지 점검한다.","confusedWith":"Watermark는 표식을 심는 접근을 흔히 뜻하며 용어 사용은 논문별로 확인한다.","paperReading":"논문 해석 시 확인: Watermark는 표식을 심는 접근을 흔히 뜻하며 용어 사용은 논문별로 확인한다.","sourceUrl":"https://aclanthology.org/2024.naacl-long.180/"},{"term":"Reproducibility","korean":"재현성","category":"연구·평가","ordinaryMeaning":"다시 수행해 같은 결론을 확인할 수 있음","etymology":"re-(다시)+produce(만들다)+-ibility(가능성)의 구성입니다.","aiMeaning":"데이터·코드·환경·설정과 절차를 통해 연구 결과를 다시 확인할 수 있는 정도.","example":"버전·시드·분할·설정을 기록하고 재실행 결과를 비교한다.","confusedWith":"학회마다 replication과 reproducibility의 구분이 다르므로 정의를 명시한다.","paperReading":"논문 해석 시 확인: 학회마다 replication과 reproducibility의 구분이 다르므로 정의를 명시한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Benchmark","korean":"벤치마크","category":"연구·평가","ordinaryMeaning":"비교에 쓰는 기준점","etymology":"기준점이라는 일반 의미를 성능 비교 과제에 적용한 용법입니다.","aiMeaning":"공통 데이터·과제·지표·절차로 방법을 비교하는 평가 묶음.","example":"BBQ의 질문 구조와 포함된 사회적 맥락을 확인한다.","confusedWith":"벤치마크 점수는 현실 전체의 능력이나 공정성을 대표하지 않는다.","paperReading":"논문 해석 시 확인: 벤치마크 점수는 현실 전체의 능력이나 공정성을 대표하지 않는다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Metric","korean":"평가 지표","category":"연구·평가","ordinaryMeaning":"측정하는 기준이나 수치","etymology":"측정 관련 일반어를 성능 비교의 수치 규칙으로 사용합니다.","aiMeaning":"정의한 성질을 숫자로 나타내는 계산 규칙. ML에서 말하는 metric은 수학적 거리의 공리를 만족할 필요가 없다.","example":"TPR=TP/(TP+FN)처럼 분모를 먼저 적는다.","confusedWith":"목표 그 자체와 측정 대리 지표를 구분한다.","paperReading":"논문 해석 시 확인: 목표 그 자체와 측정 대리 지표를 구분한다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"},{"term":"Hypothesis","korean":"가설","category":"연구·평가","ordinaryMeaning":"확인하려고 세운 잠정 설명","etymology":"검증 전의 설명·예측이라는 연구 용법을 사용합니다. 불확실한 고전어 어원은 생략합니다.","aiMeaning":"실험·분석으로 지지 또는 반박 가능하게 만든 주장.","example":"문서 출처 표시를 추가하면 근거 없는 답이 줄어든다는 예측.","confusedWith":"연구 주제나 결과를 본 뒤 만든 설명과 구분한다.","paperReading":"논문 해석 시 확인: 연구 주제나 결과를 본 뒤 만든 설명과 구분한다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Baseline","korean":"비교 기준","category":"연구·평가","ordinaryMeaning":"비교를 시작할 바탕선","etymology":"base(기준)+line(선)의 합성어를 비교 대상에 비유합니다.","aiMeaning":"새 방법의 효과를 판단하기 위한 기존·단순·표준 방법과 설정.","example":"같은 데이터 분할과 예산으로 기본 모델을 비교한다.","confusedWith":"고의로 약하게 설정한 비교 모델은 개선 주장을 왜곡한다.","paperReading":"논문 해석 시 확인: 고의로 약하게 설정한 비교 모델은 개선 주장을 왜곡한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Ablation","korean":"구성요소 제거 실험","category":"연구·평가","ordinaryMeaning":"일부를 제거함","etymology":"제거라는 일반·의학적 용법을 구성요소 비교에 적용합니다.","aiMeaning":"모듈·손실·데이터 요소 등을 제외하거나 바꾸어 그 기여를 조사하는 실험.","example":"필터만 뺀 결과와 전체 방어 결과를 비교한다.","confusedWith":"복잡하게 얽힌 요소의 독립적 인과효과가 자동 확인되는 것은 아니다.","paperReading":"논문 해석 시 확인: 복잡하게 얽힌 요소의 독립적 인과효과가 자동 확인되는 것은 아니다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Uncertainty","korean":"불확실성","category":"연구·평가","ordinaryMeaning":"정확히 알 수 없는 정도","etymology":"un-(아닌)+certainty(확실함)의 구성입니다.","aiMeaning":"자료·표본·모델·평가·미래 환경 때문에 결과와 해석이 확정적이지 않은 정도.","example":"적은 표본의 집단별 점수에 넓은 오차 범위를 표시한다.","confusedWith":"확률 점수 자체가 항상 잘 보정된 불확실성은 아니다.","paperReading":"논문 해석 시 확인: 확률 점수 자체가 항상 잘 보정된 불확실성은 아니다.","sourceUrl":"https://proceedings.mlr.press/v70/guo17a.html"},{"term":"Responsible disclosure","korean":"책임 있는 취약점 공개","category":"연구·윤리","ordinaryMeaning":"피해를 줄이며 발견 사실을 알림","etymology":"responsible(책임 있는)+disclosure(공개)의 합성어입니다.","aiMeaning":"취약점 정보를 조정된 절차로 전달하여 수정 기회를 주고 불필요한 악용 위험을 줄이는 실무.","example":"정해진 보안 연락 경로로 재현에 필요한 최소 정보를 공유한다.","confusedWith":"무단 시험의 허가나 모든 공격 자료의 즉시 공개를 의미하지 않는다.","paperReading":"논문 해석 시 확인: 무단 시험의 허가나 모든 공격 자료의 즉시 공개를 의미하지 않는다.","sourceUrl":"https://www.cisa.gov/sites/default/files/bod-20-01.pdf"},{"term":"TCAV","korean":"개념 활성화 벡터 시험","category":"설명·해석","ordinaryMeaning":"사람이 이해할 개념을 시험함","etymology":"Testing with Concept Activation Vectors의 약어입니다.","aiMeaning":"사람이 정의한 개념 방향에 대한 모델 출력의 민감도를 분석하는 방법.","example":"얼룩말 판단이 줄무늬 개념과 얼마나 관련되는지 본다.","confusedWith":"개념 예시와 대조군 선택에 의존하며 개념의 유일한 인과효과를 보장하지 않는다.","paperReading":"논문 해석 시 확인: 개념 예시와 대조군 선택에 의존하며 개념의 유일한 인과효과를 보장하지 않는다.","sourceUrl":"https://proceedings.mlr.press/v80/kim18d.html"},{"term":"Generalization","korean":"일반화","category":"연구·평가","ordinaryMeaning":"배운 내용을 다른 경우에 적용함","etymology":"general(일반적인)+-ization(과정)의 단어 형성입니다.","aiMeaning":"학습에 직접 쓰지 않은 사례·조건에서도 성능이 유지되는 정도.","example":"새 시기의 질문에서 정확도가 유지되는지 평가한다.","confusedWith":"시험 점수가 높다고 모든 언어·분포에서 일반화된다고 볼 수 없다.","paperReading":"논문 해석 시 확인: 시험 점수가 높다고 모든 언어·분포에서 일반화된다고 볼 수 없다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"False positive","korean":"거짓 양성·오탐","category":"연구·평가","ordinaryMeaning":"실제 아닌데 그렇다고 판단함","etymology":"false(틀린)+positive(양성 판정)의 합성어입니다.","aiMeaning":"실제 음성을 양성으로 예측한 사례. FPR은 실제 음성 중 그 비율이다.","example":"무해한 문서를 위험 문서로 표시한다.","confusedWith":"False negative는 실제 양성을 놓친 경우이며 positive는 항상 좋은 결과라는 뜻이 아니다.","paperReading":"논문 해석 시 확인: False negative는 실제 양성을 놓친 경우이며 positive는 항상 좋은 결과라는 뜻이 아니다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"}],"researchTerms":[{"term":"Abstract","korean":"초록","ordinaryMeaning":"핵심을 짧게 뽑아낸 요약","etymology":"일반어 abstract의 요약이라는 용법을 사용하며 형용사 “추상적인”과 구분합니다.","aiMeaning":"논문의 문제·방법·주요 결과를 짧게 소개하는 부분.","paperReading":"“We propose…”는 제안, “We show…”는 주장하는 결과다. 초록만으로 세부 가정·한계를 모두 안다고 생각하지 않는다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Introduction","korean":"서론","ordinaryMeaning":"처음 소개하는 부분","etymology":"introduce(소개하다)+-tion(행위·결과)의 단어 형성입니다.","aiMeaning":"문제의 중요성, 기존 접근의 빈틈, 연구 질문과 기여를 제시하는 부분.","paperReading":"“However…” 앞은 배경, 뒤는 문제 제기일 때가 많다. 무엇이 아직 해결되지 않았는지 표시한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Related work","korean":"관련 연구","ordinaryMeaning":"연결되는 기존 작업","etymology":"related(관련된)+work(연구·작업)의 합성 표현입니다.","aiMeaning":"현재 연구와 이어지는 선행 방법·관점·결과를 비교하는 부분.","paperReading":"같은 과제를 다룬다는 것과 같은 위협 모델을 쓴다는 것은 다르다. 차이의 기준을 적는다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Method","korean":"방법","ordinaryMeaning":"목적을 달성하는 방식","etymology":"일상어 method를 연구 절차·기법에 적용합니다. 역사적 어원은 추정하지 않습니다.","aiMeaning":"모델·알고리즘·자료 처리·실험 절차 등 연구가 어떻게 수행되는지를 설명한다.","paperReading":"입력→변환→출력을 그림으로 다시 그린다. 새로 제안한 부분과 가져온 기존 부분을 구분한다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Result","korean":"결과","ordinaryMeaning":"행동 뒤에 나타난 것","etymology":"일상적 결과라는 뜻을 측정·분석의 산출물에 적용합니다.","aiMeaning":"시험·관측·분석으로 얻은 수치·패턴·정리 등의 결과.","paperReading":"표의 최댓값만 보지 말고 분모·시험 조건·반복 수·오차 범위를 확인한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Discussion","korean":"논의","ordinaryMeaning":"의미를 놓고 검토하는 말","etymology":"discuss(논의하다)+-ion(행위)의 단어 형성입니다.","aiMeaning":"결과의 해석, 기존 연구와의 관계, 적용 가능성과 남은 문제를 다루는 부분.","paperReading":"실제로 관측한 결과와 저자가 제안하는 해석을 다른 색으로 표시한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Limitation","korean":"한계","ordinaryMeaning":"닿을 수 있는 범위의 끝","etymology":"limit(한계)+-ation(상태·결과)의 단어 형성입니다.","aiMeaning":"연구 설계·자료·가정 때문에 결론을 적용하기 어려운 범위.","paperReading":"“We only evaluate…” 뒤의 제한은 결론 범위를 정한다. 한계가 있다는 사실과 연구가 무효라는 판단은 다르다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Contribution","korean":"기여","ordinaryMeaning":"전체에 보태는 것","etymology":"contribute(기여하다)+-ion(행위·결과)의 단어 형성입니다.","aiMeaning":"기존 지식에 새로 더한 문제 정의·방법·이론·데이터·분석.","paperReading":"새롭다는 주장과 유용하다는 주장은 다르다. 각 기여를 뒷받침하는 절·표를 찾아 연결한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Baseline","korean":"비교 기준","ordinaryMeaning":"바탕이 되는 선","etymology":"base(기준)+line(선)의 합성어를 비교 대상에 비유합니다.","aiMeaning":"제안 방법의 효과를 판단하기 위한 기존 또는 단순 방법.","paperReading":"“Compared to the baseline…”에서는 데이터·튜닝·예산이 공평한지 먼저 확인한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Benchmark","korean":"벤치마크","ordinaryMeaning":"비교 기준점","etymology":"기준점의 일반 의미를 평가 과제에 적용한 용법입니다.","aiMeaning":"공통 과제·데이터·지표·절차로 성능을 비교하는 평가 체계.","paperReading":"벤치마크의 언어·집단·시점·정답 생성 방식을 읽고 현실을 얼마나 대표하는지 묻는다.","sourceUrl":"https://aclanthology.org/2022.findings-acl.165/"},{"term":"Ablation","korean":"제거 실험","ordinaryMeaning":"일부를 제거하는 일","etymology":"제거라는 뜻을 연구의 구성요소 비교에 빌린 용법입니다.","aiMeaning":"부품·특징·손실·단계 등을 빼거나 바꾸어 전체 결과에 대한 기여를 점검하는 실험.","paperReading":"“Without X…” 열은 X를 뺀 모델이다. 다른 설정도 함께 바뀌지 않았는지 확인한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Assumption","korean":"가정","ordinaryMeaning":"일단 그렇다고 두는 전제","etymology":"일반어 assumption의 전제라는 연구 용법입니다.","aiMeaning":"정리·방법·평가가 성립한다고 두는 조건.","paperReading":"독립 표본, 라벨 정확성, 공격자 권한 등 가정을 찾는다. 현실에서 깨지면 결론도 달라질 수 있다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Hypothesis","korean":"가설","ordinaryMeaning":"잠정적인 설명이나 예측","etymology":"검증을 위해 세운 설명이라는 연구 용법. 확인하지 않은 역사적 어원은 생략합니다.","aiMeaning":"자료나 실험으로 검토할 수 있도록 만든 주장.","paperReading":"“We hypothesize…”는 이미 입증했다는 말이 아니다. 어떤 관측이면 반박될지 적는다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Claim","korean":"주장","ordinaryMeaning":"맞다고 내세우는 말","etymology":"일상어 claim을 논증의 결론에 적용합니다.","aiMeaning":"저자가 독자에게 받아들이길 요구하는 진술.","paperReading":"“Robust to…”의 뒤에 붙은 범위를 포함해 옮긴다. “모든 상황에 강건하다”로 확대하지 않는다.","sourceUrl":"https://arxiv.org/abs/2403.10462"},{"term":"Evidence","korean":"증거","ordinaryMeaning":"판단을 뒷받침하는 자료","etymology":"일상적 근거라는 뜻을 연구의 관측·논증에 적용합니다.","aiMeaning":"주장을 지지하거나 반박하는 실험·자료·증명·기록.","paperReading":"어떤 주장에 대한 증거인지 연결하고, 예시 한 개와 체계적인 평가를 구분한다.","sourceUrl":"https://arxiv.org/abs/2403.10462"},{"term":"Theorem","korean":"정리","ordinaryMeaning":"증명된 명제","etymology":"수학에서 가정 아래 증명한 명제라는 기술 용법입니다.","aiMeaning":"명시한 가정·정의에서 논리적으로 따라오는 결론.","paperReading":"정리 제목보다 “under…”와 “if…” 조건을 먼저 읽는다. 실험 경향을 정리의 보장으로 쓰지 않는다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"Proof","korean":"증명","ordinaryMeaning":"참이라는 것을 보여 줌","etymology":"일반어 proof를 논리적 정당화에 사용합니다.","aiMeaning":"가정과 기존 결과에서 명제가 따라옴을 논리적으로 보이는 과정.","paperReading":"첫 읽기에서는 결론·가정·핵심 아이디어를 적고, 필요한 보조정리와 계산은 두 번째 읽기에 추적한다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"Bound","korean":"경계·상계·하계","ordinaryMeaning":"값이 넘어가지 못할 한계","etymology":"경계라는 일반 의미를 수치의 범위에 적용합니다.","aiMeaning":"관심 값이 일정 범위 이상 또는 이하임을 보이는 결과.","paperReading":"Upper bound는 상계, lower bound는 하계다. 부등호 방향과 값이 클수록 좋은 지표인지 함께 본다.","sourceUrl":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"term":"Objective","korean":"목적함수·목표","ordinaryMeaning":"달성하려는 것","etymology":"objective의 명사 “목표” 용법. 형용사 “객관적인”과 구분합니다.","aiMeaning":"학습·최적화에서 최소화 또는 최대화하는 함수나 목표.","paperReading":"“Minimize the objective…”에서는 무엇을 줄이는지, 실제 윤리적 목표를 잘 대표하는지 묻는다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Loss","korean":"손실","ordinaryMeaning":"잃은 정도·불이익","etymology":"손해라는 일상적 뜻을 예측 오차의 수치에 적용한 비유입니다.","aiMeaning":"예측과 목표의 불일치 등을 수치화하여 학습에 사용하는 함수.","paperReading":"Loss가 낮아졌다는 사실과 실제 서비스 피해가 줄었다는 주장을 분리한다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Constraint","korean":"제약","ordinaryMeaning":"할 수 있는 범위의 제한","etymology":"일상적 제한이라는 뜻을 최적화 조건에 적용합니다.","aiMeaning":"해가 만족해야 할 조건이나 허용 범위.","paperReading":"“Subject to…” 뒤에 제약이 온다. 공정성 제약·변화 크기·질의 예산을 따로 표시한다.","sourceUrl":"https://arxiv.org/abs/1706.06083"},{"term":"Optimization","korean":"최적화","ordinaryMeaning":"가능한 더 좋은 상태를 찾음","etymology":"optimize(가장 좋게 조정하다)+-ation(과정)의 단어 형성입니다.","aiMeaning":"정해진 목적함수와 제약 아래 매개변수나 해를 찾는 과정.","paperReading":"“Optimal”은 그 문제와 가정 안에서의 최적이다. 사회적으로 가장 바람직하다는 뜻은 아니다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Gradient","korean":"기울기","ordinaryMeaning":"오르내리는 경사","etymology":"경사라는 일반 의미를 다변수 함수의 변화율에 적용합니다.","aiMeaning":"입력·매개변수를 조금 바꿀 때 함수가 어느 방향으로 얼마나 달라지는지 나타내는 벡터.","paperReading":"무엇에 대한 기울기인지 본다. 입력 기울기와 모델 매개변수 기울기는 용도가 다르다.","sourceUrl":"https://proceedings.mlr.press/v70/sundararajan17a.html"},{"term":"Parameter","korean":"매개변수","ordinaryMeaning":"모형의 상태를 정하는 값","etymology":"연구에서 함수를 정하는 값이라는 기술 용법입니다.","aiMeaning":"신경망 가중치처럼 모델의 동작을 정하며 학습으로 정하는 값 등.","paperReading":"“Model parameters”와 실험 설정값을 구분한다. 통계 논문에서는 모집단의 미지 값이라는 뜻도 있다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Hyperparameter","korean":"하이퍼파라미터","ordinaryMeaning":"매개변수보다 한 단계 바깥의 설정","etymology":"hyper-와 parameter를 결합한 기술어입니다.","aiMeaning":"학습률·배치 크기처럼 학습 절차나 구조를 설정하는 값.","paperReading":"검증 세트로 고르는지, 시험 세트를 보고 고른 것은 아닌지 확인한다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Training","korean":"학습","ordinaryMeaning":"연습하며 능력을 익힘","etymology":"훈련이라는 일상적 비유를 매개변수 추정에 적용합니다.","aiMeaning":"데이터와 목적함수에 따라 모델의 상태를 조정하는 과정.","paperReading":"학습 데이터·순서·반복·예산이 비교 방법 사이에 같은지 본다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Inference","korean":"추론·추론 실행","ordinaryMeaning":"근거에서 결론을 얻음","etymology":"일상적 추론이라는 뜻과 ML 시스템의 실행 용법이 함께 쓰입니다.","aiMeaning":"학습된 모델로 예측을 계산하는 실행, 또는 미지의 정보·매개변수를 추정하는 통계적 추론.","paperReading":"“Inference time”은 예측 실행 시점, “membership inference”는 포함 여부 추정이다. 문맥으로 뜻을 나눈다.","sourceUrl":"https://arxiv.org/abs/2112.03570"},{"term":"Generalization","korean":"일반화","ordinaryMeaning":"한 사례에서 다른 사례로 넓힘","etymology":"general(일반적인)+-ization(과정)의 구성입니다.","aiMeaning":"학습하지 않은 데이터나 조건에서 모델이 유효하게 작동하는 정도.","paperReading":"“Generalizes” 뒤에 어느 데이터·언어·위협으로 넓혔는지 확인한다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Overfitting","korean":"과적합","ordinaryMeaning":"지나치게 맞춰 버림","etymology":"over-(과도하게)+fitting(맞춤)의 합성어입니다.","aiMeaning":"학습 자료의 우연한 특징까지 맞추어 새 자료 성능이 떨어지는 현상.","paperReading":"학습 성능만 좋아지는지, 검증·시험 성능과 차이가 커지는지 본다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Distribution","korean":"분포","ordinaryMeaning":"어떤 것들이 어떻게 퍼져 있는지","etymology":"분배·퍼짐이라는 일반 뜻을 확률적 빈도에 적용합니다.","aiMeaning":"입력·라벨·출력 등이 어떤 값과 확률로 나타나는지 기술하는 구조.","paperReading":"“In-distribution”과 “out-of-distribution”은 무엇을 기준으로 나누었는지 확인한다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Validation","korean":"검증","ordinaryMeaning":"맞는지·적합한지 확인함","etymology":"valid(유효한)의 확인이라는 단어 형성으로 이해합니다.","aiMeaning":"ML에서는 주로 개발 중 설정 선택·모델 비교에 쓰는 검증 과정·자료를 뜻한다.","paperReading":"Validation set과 test set의 역할을 분리한다. 분야에 따라 용어가 달라 데이터 사용 내역을 본다.","sourceUrl":"https://www.deeplearningbook.org/"},{"term":"Confounder","korean":"교란 변수","ordinaryMeaning":"관계를 뒤섞어 해석을 흐리는 요인","etymology":"confound(혼동시키다)+-er(행위자)의 단어 형성입니다.","aiMeaning":"관심 원인과 결과 양쪽에 관련되어 관측 관계의 인과 해석을 왜곡할 수 있는 요인.","paperReading":"방법을 바꿀 때 데이터 크기까지 늘렸다면 개선을 방법 하나의 효과라고 말하기 어렵다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Control","korean":"통제·대조","ordinaryMeaning":"조절하거나 비교 기준으로 둠","etymology":"일상어 control의 조절과 대조라는 연구 용법입니다.","aiMeaning":"다른 조건을 유지하는 통제, 또는 처리를 하지 않은 비교군·설정.","paperReading":"“Controlled experiment”에서 실제로 어떤 조건을 고정했는지 확인한다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Random seed","korean":"난수 시드","ordinaryMeaning":"무작위 과정의 시작값","etymology":"seed(씨앗)를 난수열의 시작 상태에 비유합니다.","aiMeaning":"의사난수 생성기의 초기 상태를 정해 실험 재실행을 돕는 값.","paperReading":"같은 시드만으로 모든 하드웨어·연산의 결정성이 보장되지는 않는다. 여러 시드의 변동도 보고한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Reproducibility","korean":"재현성","ordinaryMeaning":"다시 확인할 수 있음","etymology":"re-(다시)+produce(만들다)+-ibility(가능성)의 단어 형성입니다.","aiMeaning":"연구 절차·자료·설정 등을 공유하여 결과를 다시 확인할 수 있는 정도.","paperReading":"사용한 학회나 기관의 정의를 확인하고, 코드 공개 여부와 실제 재실행 성공 여부를 구별한다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Replication","korean":"반복 검증","ordinaryMeaning":"다시 만들어 확인함","etymology":"replicate(되풀이하다)+-ion(행위)의 단어 형성입니다.","aiMeaning":"다른 연구자·자료·구현 등으로 결과를 다시 검토하는 활동으로 쓰이지만 분야별 정의가 다르다.","paperReading":"독립 구현인지 원저자 코드 실행인지, 같은 데이터인지 새 데이터인지 구체적으로 적는다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"},{"term":"Statistical significance","korean":"통계적 유의성","ordinaryMeaning":"statistical은 통계의, significance는 중요성·의미","etymology":"significance의 “중요성”과 통계적 기술 용법을 구분합니다.","aiMeaning":"정해진 검정·가정·유의수준 아래 귀무가설과 관측 자료의 양립 정도를 판단하는 개념.","paperReading":"“Significant”가 크고 중요한 효과라는 뜻은 아니다. 효과크기·불확실성·다중 검정을 함께 본다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Confidence interval","korean":"신뢰구간","ordinaryMeaning":"confidence는 자신감·신뢰, interval은 간격·구간","etymology":"confidence(신뢰)+interval(구간)의 합성어입니다.","aiMeaning":"동일 절차를 반복할 때 정해진 비율로 참값을 포함하도록 구성한 추정 구간.","paperReading":"고정된 관측 구간에 참값이 95% 확률로 있다는 식의 빈도주의 해석은 피한다. 구성 방법·표본 단위를 확인한다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Effect size","korean":"효과크기","ordinaryMeaning":"변화·차이가 얼마나 큰지","etymology":"effect(효과)+size(크기)의 합성어입니다.","aiMeaning":"방법·처치·집단 간 차이를 원래 단위 또는 표준화된 단위로 나타낸 크기.","paperReading":"정확도 80%→82%는 2%포인트 증가다. 상대 2.5% 증가와 혼동하지 않는다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Calibration","korean":"보정","ordinaryMeaning":"측정 눈금을 기준에 맞춤","etymology":"계기 보정의 비유를 확률 예측에 적용합니다.","aiMeaning":"예측 확률이 관측 빈도와 맞는 정도.","paperReading":"0.9로 예측한 사례 중 실제로 얼마나 맞는지 본다. 정확도·순위 성능과 별도 측정이다.","sourceUrl":"https://proceedings.mlr.press/v70/guo17a.html"},{"term":"Robust","korean":"강건한","ordinaryMeaning":"튼튼하고 변화에 잘 견딤","etymology":"일상어 robust의 의미를 결과·방법의 안정성에 적용합니다.","aiMeaning":"명시한 변화·가정 위반·공격 조건에서 결과나 성능이 유지된다는 표현.","paperReading":"“Robust” 뒤에 무엇에 대해 강건한지 목적어를 붙여 번역한다. 조건 없는 만능 형용사로 쓰지 않는다.","sourceUrl":"https://arxiv.org/abs/2002.08347"},{"term":"Metric","korean":"지표","ordinaryMeaning":"측정 기준","etymology":"측정 관련 단어의 기술 용법입니다.","aiMeaning":"비교하려는 성질을 계산 가능한 수치로 나타낸 규칙.","paperReading":"지표 값이 클수록 좋은지, 분모가 무엇인지, 평균이 어떤 사례를 가리는지 적는다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"},{"term":"Precision","korean":"정밀도","ordinaryMeaning":"정확하고 세밀함","etymology":"일상적 정밀함과 분류 지표의 정의를 구분합니다.","aiMeaning":"양성으로 예측한 것 중 실제 양성인 비율 TP/(TP+FP).","paperReading":"분모가 “예측 양성”이다. 위험 경보 가운데 실제 위험이 얼마나 많은지 묻는 지표로 읽는다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Recall","korean":"재현율","ordinaryMeaning":"다시 불러내거나 찾아냄","etymology":"찾아낸다는 일반 뜻을 실제 양성 회수율에 적용합니다.","aiMeaning":"실제 양성 중 양성으로 예측한 비율 TP/(TP+FN). 이진 분류에서 TPR과 같다.","paperReading":"분모가 “실제 양성”이다. 놓치지 않고 얼마나 찾아냈는지 묻는다.","sourceUrl":"https://arxiv.org/abs/1610.02413"},{"term":"Accuracy","korean":"정확도","ordinaryMeaning":"얼마나 맞는지","etymology":"일상적 정확함을 정답 예측의 비율에 적용합니다.","aiMeaning":"전체 평가 사례 중 예측이 맞은 비율.","paperReading":"희귀한 양성 문제에서 전부 음성으로 답해도 높을 수 있다. 혼동행렬과 함께 본다.","sourceUrl":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html"},{"term":"p-value","korean":"p값","ordinaryMeaning":"검정에서 쓰는 확률 수치","etymology":"p는 확률을 나타내는 기호로 쓰며 단어의 별도 어원을 추정하지 않습니다.","aiMeaning":"귀무가설과 검정 가정 아래 관측값 이상으로 극단적인 통계량을 얻을 확률.","paperReading":"“귀무가설이 참일 확률”이나 “결과가 우연일 확률”로 번역하지 않는다. 사전 설정한 검정과 다중 비교를 확인한다.","sourceUrl":"https://www.itl.nist.gov/div898/handbook/"},{"term":"Trade-off","korean":"절충 관계","ordinaryMeaning":"하나를 얻으려 다른 것을 양보함","etymology":"trade(교환)+off의 표현을 목표 사이의 맞바꿈에 비유합니다.","aiMeaning":"한 목표의 개선이 다른 목표의 비용·성능 악화와 연결되는 관계.","paperReading":"공정성·정확도·프라이버시의 절충이 관측된 조건과 변화 범위를 함께 읽는다. 항상 불가피하다고 단정하지 않는다.","sourceUrl":"https://arxiv.org/abs/1610.02413"},{"term":"State of the art","korean":"최고 수준·SOTA","ordinaryMeaning":"해당 분야의 현재 기술 수준","etymology":"state(상태)+art(기술·기예)의 관용 표현입니다.","aiMeaning":"특정 시점·벤치마크·조건에서 기존 최고 수준을 가리키는 표현.","paperReading":"“SOTA” 옆에 날짜·데이터·지표·비교 예산을 붙여 읽는다. 서비스 전체가 최고라는 뜻은 아니다.","sourceUrl":"https://neurips.cc/public/guides/PaperChecklist"}],"templates":{"criticalReview":{"title":"논문 비판적 리뷰 · 1~2쪽 학습 양식","description":"아래 분량과 항목은 학습용 권장안입니다. 담당 교수의 지정 양식·채점 기준이 있으면 그것을 우선합니다.","sections":[{"title":"서지와 읽은 범위","prompts":["제목 / 저자 / 발표처 / 연도 / DOI·공식 URL / 읽은 버전·날짜","본문·부록·코드 중 어디까지 직접 확인했는가? 초록만 확인한 부분은 무엇인가?"]},{"title":"문제와 주장","prompts":["이 논문이 해결하려는 문제를 비전공자에게 세 문장으로 설명한다.","핵심 주장 1~3개를 조건을 포함해 적고, 각각 근거 그림·표·절 번호를 붙인다."]},{"title":"방법과 가정","prompts":["입력→핵심 방법→출력을 적고 새로운 부분을 표시한다.","데이터·모델·비교 방법·위협 모델·권한·예산·지표를 기록한다.","정리나 실험이 성립하려면 어떤 가정이 필요한가?"]},{"title":"근거 평가","prompts":["가장 강한 증거는 무엇이며 어떤 주장까지 지지하는가?","비교 예산과 설정은 공평한가? 불확실성·하위집단·실패 사례는 보고했는가?","관측 결과와 저자의 해석·추측을 구분한다."]},{"title":"한계와 제안","prompts":["결론을 바꿀 수 있는 한계 하나를 구체적인 근거와 함께 적는다.","시간·비용을 고려해 가장 가치 있는 추가 실험 하나를 제안한다.","이 논문을 내 연구에 활용할 수 있는 범위와 활용하면 안 되는 범위를 적는다."]},{"title":"토론 질문","prompts":["정답을 외우는 질문 대신 가정·지표 선택·현실 적용에 관한 질문 두 개를 쓴다.","질문을 바탕으로 어떤 판단이나 후속 실험이 달라지는지 적는다."]}]},"presentation":{"title":"논문 발표와 프로젝트 15분 발표 설계","description":"논문 세미나의 개별 발표 시간은 강의계획서에 고정되어 있지 않습니다. 아래 15분 구성은 8·15주차 프로젝트 발표 또는 교수와 합의한 짧은 발표를 위한 학습 제안입니다.","sections":[{"title":"0~2분 · 문제와 맥락","prompts":["청중이 알아야 할 문제·피해·사용 상황을 하나의 예로 보여 준다.","연구 질문과 왜 중요한지 한 문장으로 말한다."]},{"title":"2~5분 · 최소한의 배경과 설정","prompts":["핵심 용어는 최대 몇 개만 골라 일상 의미와 연구 의미를 연결한다.","위협 모델·데이터·비교 기준·평가 지표를 먼저 보여 준다."]},{"title":"5~9분 · 방법과 핵심 결과","prompts":["방법은 입력→변환→출력 순서로 설명한다.","가장 중요한 표·그림 하나를 골라 축·단위·조건·오차를 설명한다.","원문 결과와 자신의 재현 결과를 명확히 구분한다."]},{"title":"9~12분 · 비판과 안전","prompts":["가장 강한 증거와 가장 중요한 가정·한계를 짝지어 설명한다.","윤리·개인정보·보안·재현성에서 남은 문제를 숨기지 않는다."]},{"title":"12~15분 · 결론과 질문","prompts":["이 조건에서 무엇을 알게 되었고 아직 무엇을 모르는지 요약한다.","청중의 의견이 필요한 선택 또는 다음 실험 하나를 제시한다.","프로젝트 발표 뒤 질의·동료 평가 10분을 별도로 준비한다."]},{"title":"슬라이드 점검","prompts":["슬라이드마다 한 가지 메시지를 쓴다. 축·글씨·범례가 뒷자리에서도 읽히는지 본다.","모든 수치·이미지·논문 주장에 출처를 붙인다. 설명을 위해 만든 예시는 가상 예시라고 쓴다.","직접 확인하지 못한 부분을 묻는 질문에는 확인 범위를 정확히 답한다."]}]},"projectPlan":{"title":"개인 프로젝트 계획(안)","description":"8주차 계획 제출과 제안 발표를 돕는 양식입니다. 실행 가능한 최소 실험을 중심으로 작성하고, 과도한 범위는 줄입니다.","sections":[{"title":"질문·동기·범위","prompts":["연구 질문: 어떤 조건에서 무엇을 비교해 무엇을 알고 싶은가?","영향을 받는 사람·자산·실제 피해는 무엇인가?","이번 학기에 다룰 범위와 다루지 않을 범위는 무엇인가?"]},{"title":"선행 연구와 차이","prompts":["가장 가까운 선행 연구 2~3편과 공식 원문 링크를 적는다.","새 데이터·가정 검토·재현·평가·방어 설계 중 무엇을 기여하는가?"]},{"title":"위협·위험 모델","prompts":["보호 자산 / 행위자 / 지식 / 접근 권한 / 변경 가능 범위 / 질의·계산 예산","공격이 없는 실패도 포함하는가? 제외한 조건과 이유는 무엇인가?"]},{"title":"데이터와 실험","prompts":["데이터 출처·사용 권한·개인정보 여부·분할 방식을 적는다.","바꿀 요소·고정할 요소·기준 모델·제거 실험·반복 횟수를 적는다.","성능·안전·하위집단·정상 유용성 지표와 성공 판정을 미리 정한다."]},{"title":"안전·비용·승인","prompts":["합성·공개 자료로 대체 가능한가? 허가된 환경만 사용하는가?","민감정보, 유료 API, 사람 대상 연구, 외부 시스템 시험에 필요한 승인과 비용을 확인한다.","즉시 중단할 조건과 사고 시 연락·증거 보호 절차를 정한다."]},{"title":"일정과 산출물","prompts":["8주차 제안→9~11주차 최소 실험→12~13주차 보완→14주차 중간 점검→15주차 발표→발표 후 1주 이내 최종 보고서","위 일정의 주차별 실험 배치는 학습용 권장안이며 공식 추가 마감이 아니다.","실패 시 범위 축소안과 남길 수 있는 분석·문서 산출물을 적는다."]}]},"reproducibilityChecklist":{"title":"재현성·실험 보고 체크리스트","description":"다른 사람이 결과의 의미를 확인할 수 있도록 기록하는 보조 목록입니다. 코드 공개만으로 충족되지는 않습니다.","sections":[{"title":"실행 조건","prompts":["논문·모델·데이터·코드의 버전·날짜·공식 출처를 기록했는가?","의존성·하드웨어·정밀도·설정·시드·실행 명령 또는 절차를 기록했는가?","유료 API·비공개 데이터 등 독자가 접근할 수 없는 조건을 표시했는가?"]},{"title":"자료와 비교","prompts":["데이터 사용 권한·개인정보 처리·학습/검증/시험 분할을 확인했는가?","기준 방법에도 합리적인 튜닝과 동일한 예산을 적용했는가?","시험 세트를 설정 선택에 사용하지 않았는가? 데이터 중복·오염을 점검했는가?"]},{"title":"결과와 통계","prompts":["모든 지표의 정의·단위·분모·좋은 방향을 표시했는가?","반복 실행·불확실성·실패 사례·최악 하위집단을 가능한 범위에서 보고했는가?","유리한 조건만 남기지 않고 제외·중단한 실험의 이유를 기록했는가?"]},{"title":"보장과 공개","prompts":["수학적 보장, 실험적 관측, 추측을 구분했는가?","개인정보·비밀키·위험한 실행 자료·타인 저작물이 공개물에 포함되지 않았는가?","공개하기 어려운 부분은 이유와 안전한 대체 검증 방법을 설명했는가?"]},{"title":"최종 확인","prompts":["깨끗한 환경에서 가능한 최소 재실행을 했는가? 원본 결과와 차이를 기록했는가?","보고서의 핵심 문장마다 표·그림·로그·증거를 찾을 수 있는가?","최종 파일을 직접 열어 표·수식·링크·참고문헌을 검토했는가?"]}]},"responsibleResearch":{"title":"책임 있는 AI 보안·윤리 연구 계획","description":"허가·피해 최소화·자료 보호·정직한 보고를 연구 설계에 포함하는 체크리스트입니다. 기관의 연구윤리·보안·법률 절차를 대체하지 않습니다.","sections":[{"title":"권한과 범위","prompts":["누가 어떤 시스템·데이터의 시험을 허용했는가? 허가 범위를 문서로 확인한다.","공개된 서비스라는 이유로 무단 보안 시험을 하지 않는다. 외부 시스템 대신 로컬·합성 환경을 우선한다."]},{"title":"사람과 데이터","prompts":["개인정보·민감 집단·동의·철회·보존·접근 권한을 검토한다.","사람 대상 연구나 실제 의사결정 영향을 포함하면 기관 심의 필요 여부를 확인한다.","유해 콘텐츠를 다루는 연구자의 노출 부담과 지원 방법을 고려한다."]},{"title":"실험 안전","prompts":["실제 전송·결제·삭제·권한 변경을 모의 도구로 대체한다.","자원 한도·네트워크 범위·로그 보관·중단 조건을 정한다.","예상 밖 비공개 정보가 보이면 시험을 중단하고 필요한 최소 증거만 안전하게 보존한다."]},{"title":"정직한 해석","prompts":["관측하지 않은 수치·승인받지 않은 성과·없는 인용을 만들지 않는다.","결과가 지지하는 범위만 주장하고 실패·불확실성·이해충돌을 공개한다.","집단 점수 차이의 원인을 생물학적·본질적 특성으로 근거 없이 귀인하지 않는다."]},{"title":"공개와 사후 책임","prompts":["논문·코드·데이터의 사용·재배포 라이선스를 각각 확인한다.","실제 취약점은 정해진 조정 공개 절차를 따라 수정 기회와 영향 최소화를 고려한다.","보안상 제한한 자료에는 안전한 합성 예시·검증 절차·제한 이유를 제공한다."]}]}},"updates":[{"title":"공정성 용어 정정: Equalized Odds와 Equal Opportunity","syllabusNote":"2주차의 “기회 균등(Equalized Odds)” 표기는 두 영어 정의를 구분해 읽을 필요가 있습니다.","currentStatus":"Equalized Odds는 집단별 TPR과 FPR을 모두 같게 요구합니다. Equal Opportunity는 실제 양성에 대한 TPR만 같게 요구하는 완화 조건입니다. 번역의 혼동을 피하려고 영어 명칭과 계산식을 함께 표시했습니다.","teachingPoint":"TPR이 같아도 FPR이 다르면 Equal Opportunity는 만족할 수 있지만 Equalized Odds는 만족하지 않습니다. Equalized Odds의 odds를 일반 통계의 p/(1-p)와 바꿔 계산하지 않습니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://arxiv.org/abs/1610.02413","supports":"Hardt·Price·Srebro의 원 논문에서 두 공정성 정의와 관계를 제시한다."},{"url":"https://fairlearn.org/v0.11/user_guide/assessment/common_fairness_metrics.html","supports":"Fairlearn 공식 설명에서 Equal Opportunity를 Equalized Odds의 완화형으로 구분한다."}]},{"title":"한국 AI기본법: 정확한 시행일","syllabusNote":"7주차 강의계획서는 “2026.1 시행”으로 요약합니다.","currentStatus":"「인공지능 발전과 신뢰 기반 조성 등에 관한 기본법」의 확인한 법령 본문은 시행일을 2026-01-22로 표시합니다. 법령센터 페이지는 법률 제21311호, 2026-01-20 일부개정본을 표시합니다.","teachingPoint":"월 단위 안내를 2026년 1월 22일로 구체화합니다. 실제 적용 대상과 의무 판단은 해당 조문·부칙·시행령·최신 개정 이력을 별도로 확인해야 합니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://www.law.go.kr/LSW/lsInfoP.do?ancYnChk=0&chrClsCd=010202&efYd=20260122&lsiSeq=282791&urlMode=lsInfoP","supports":"국가법령정보센터의 법령명·시행일·법률 번호·개정일 표시."}]},{"title":"EU AI Act: 2026년 개정 후 단계별 적용","syllabusNote":"7주차의 EU AI Act 설명은 의무별 적용일을 분리하여 최신 일정을 읽어야 합니다.","currentStatus":"2026-10-12 확인한 EU 집행위 공식 안내에 따르면 AI Act는 2024-08-01 발효, 주요 일반 적용은 2026-08-02입니다. 금지 관행·AI 리터러시 의무는 2025-02-02, 거버넌스·GPAI 의무는 2025-08-02부터 적용되었습니다. AI Omnibus는 2026-07-27 발효되었으며 Annex III의 특정 고위험 용도 규칙은 2027-12-02, Annex I 규제 제품 내장 고위험 규칙은 2028-08-02로 연장되었습니다.","teachingPoint":"오래된 2026/2027 고위험 적용 일정만 인용하지 않습니다. 일반 적용일이 모든 의무의 동일한 마감일이라는 뜻은 아니며, 기존 시스템·특정 투명성 조항 등에는 별도 경과 규정이 있을 수 있습니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai","supports":"집행위의 최신 적용 일정 및 AI Omnibus 발효 안내."},{"url":"https://eur-lex.europa.eu/legal-content/ENG/TXT/PDF/?uri=OJ%3AL_202601744","supports":"Regulation (EU) 2026/1744 공식 법령 원문. 일정 변경의 법적 근거는 원문과 현행 통합본을 우선한다."},{"url":"https://eur-lex.europa.eu/eli/reg/2024/1689","supports":"EU AI Act 공식 법령 및 통합본 접근점."}]},{"title":"ISO/IEC 27090: 출판 진행 단계","syllabusNote":"14주차 강의계획서에는 “AI 보안 가이드, 개발 중”으로 표시되어 있습니다.","currentStatus":"2026-10-12 ISO 공식 카탈로그는 ISO/IEC 27090을 Under publication, 단계 60.00으로 표시하고 판 정보를 Edition 1, 2026-10으로 안내합니다. 확인 당시 60.60 Published 단계로 표시되어 있지 않았습니다. 제목은 Cybersecurity — Artificial intelligence (AI) — Addressing security threats and compromises to AI systems입니다.","teachingPoint":"“개발 중”보다 구체적으로 “출판 진행 중(60.00)”이라고 표시합니다. 발행 완료나 전문 확보를 주장하지 않으며, 특정 인증을 자동 제공하는 규격으로 설명하지 않습니다. 공개 카탈로그로 확인한 범위만 다룹니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://www.iso.org/standard/27090","supports":"공식 제목·판·출판 예정 월·단계 60.00 및 Under publication 상태."}]},{"title":"ISO/IEC 42005:2025: 영향평가 표준 발행 확인","syllabusNote":"7주차에는 ISO/IEC 42005가 영향평가 표준으로 언급되어 있습니다.","currentStatus":"ISO 공식 페이지에서 ISO/IEC 42005:2025, AI system impact assessment의 발행 상태 Published(60.60), 발행 월 2025-05를 확인했습니다.","teachingPoint":"2026년 수업에서 초안으로 소개하지 않습니다. 공개 설명은 AI 시스템의 사람·집단·사회 영향평가에 관한 지침이며, 전문의 세부 조항은 별도 접근·검토가 필요합니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://www.iso.org/standard/42005","supports":"표준명·판·발행 상태와 영향평가 범위에 관한 ISO 공식 카탈로그."}]},{"title":"NIST 문서: 판과 상태를 함께 쓰기","syllabusNote":"1·7주차는 NIST AI RMF 1.0, 9·14주차는 NIST AI 100-2를 활용합니다.","currentStatus":"수업 분석 대상인 AI RMF 1.0은 2023년 문서입니다. NIST의 AIRC 페이지는 1.0 개정 작업이 진행 중이라고 표시합니다. 적대적 ML 분류의 확인된 후속 발행본은 2025-03-24 발행 NIST AI 100-2e2025입니다.","teachingPoint":"수업에서 1.0을 분석하는 것과 그것이 영구적인 최신판이라는 주장은 다릅니다. 인용에는 NIST 문서 번호·연도·판을 붙이고 진행 중 개정을 이미 확정된 규칙처럼 사용하지 않습니다.","checkedDate":"2026-10-12","evidence":[{"url":"https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/","supports":"AI RMF 1.0 개정 진행 중 표시."},{"url":"https://www.nist.gov/publications/adversarial-machine-learning-taxonomy-and-terminology-attacks-and-mitigations-0","supports":"NIST AI 100-2e2025의 발행일·문서 번호·분류 범위."}]}],"recommendedProjects":[{"title":"공정성 지표가 다른 결론을 내리는 이유","question":"같은 합성 분류 결과에서 선택률·TPR·FPR·보정을 보면 어떤 판단 차이가 생기는가?","minimumDeliverable":"합성 데이터와 지표 계산표, 맥락별 선택 근거, 분모·표본 크기 점검.","scope":"2~3주차 연결. 실제 민감정보 수집 없이 가능. 공정성을 점수 하나로 인증하지 않는다."},{"title":"설명 기준 선택의 민감도","question":"기준 입력·배경 데이터 선택에 따라 설명이 얼마나 바뀌는가?","minimumDeliverable":"허가된 작은 모델의 설명 비교, 안정성과 충실성 점검 계획, 해석 한계.","scope":"4주차 연결. 설명의 변화와 현실의 인과효과를 혼동하지 않는다."},{"title":"공개 모델 카드의 증거 지도","question":"공개 문서의 안전·공정성 주장이 실제 어떤 평가 근거와 연결되는가?","minimumDeliverable":"동일한 검토 질문과 주장-증거 표, 미공개·미확인 항목 구분.","scope":"5~7주차 연결. 비공개 내부 정보를 추정하거나 기업의 준수 여부를 단정하지 않는다."},{"title":"합성 RAG 도우미의 권한 설계","question":"읽기·쓰기·전송을 분리하면 정상 작업과 실패의 영향 범위가 어떻게 달라지는가?","minimumDeliverable":"가상 도구 인터페이스·권한표·정상 작업 평가·실패 시나리오의 추상적 검증.","scope":"12~13주차 연결. 실제 외부 전송이나 공격 문구 없이 방어 아키텍처를 비교한다."},{"title":"보안 논문 평가 조건 비교","question":"같은 강건성 주장의 평가 권한·예산·지표가 논문별로 얼마나 다른가?","minimumDeliverable":"선정 기준, 조건별 비교표, 직접 비교 가능한 결과와 불가능한 결과, 후속 평가 제안.","scope":"9~14주차 연결. 공격 재현 없이 공개 근거를 분석하는 연구도 가능하다."}]},"standards":[{"id":"w07-s01","week":7,"role":"표준 분석","title":"ISO/IEC 42001:2023 — Information technology — Artificial intelligence — Management system","authors":"ISO/IEC JTC 1/SC 42","year":2023,"venue":"국제표준","citation":"ISO/IEC. (2023). ISO/IEC 42001:2023, Information technology — Artificial intelligence — Management system. ISO.","landingUrl":"https://www.iso.org/standard/42001","pdfUrl":null,"downloadStatus":"html_only","redistribution":"restricted","licenseNote":"유료 저작권 표준. 공식 공개 설명·범위만 확인했으며 51쪽 표준 원문을 구입·다운로드·복제하지 않았다. 공개 페이지도 재배포 허가로 간주하지 않는다. https://www.iso.org/standard/42001","sourceVersion":"2023 edition 1","readScope":"abstract_only","summary":{"question":"조직이 AI를 책임 있게 개발·제공·사용하기 위한 관리 체계를 어떻게 운영할 것인가?","background":"개별 모델 시험뿐 아니라 정책·역할·목표·점검·개선이 조직에 정착되어야 한다.","method":"공식 공개 설명은 AI 경영시스템의 수립·실행·유지·지속적 개선을 다루며 Plan–Do–Check–Act 접근을 설명한다. 이 안내는 공개 범위에 근거한다.","findings":"다양한 규모와 업종의 AI 개발·제공·사용 조직에 적용되는 경영시스템 표준임을 확인했다. 구체적 조항 준수 여부를 이 자료만으로 판단하지 않는다.","limitations":"유료 원문 미확보로 세부 조항·부속서·필수 증거를 완전히 분석하지 않았다. 아래 시험 연결은 학습용 예시이며 ISO 조항이나 인증 기준을 재현한 것이 아니다.","significance":"개별 AI 제품의 성능과 조직이 위험을 관리하는 능력을 구별하는 출발점이다.","beginnerExplanation":"좋은 결과를 반복해서 만들도록 책임자와 점검·개선 절차를 운영하는 틀이다. 인증 여부 하나로 특정 모델의 모든 안전성을 판단할 수 없다."},"readingGuide":["공식 소개의 적용 대상과 경영시스템 범위를 먼저 읽는다.","조항별 분석이 필요하면 정당하게 확보한 표준 원문으로 추가 확인한다.","아래 연결 예시는 자체 학습 설계이며 공식 ISO 시험표가 아니다."],"discussion":["조직의 절차가 존재한다는 증거와 실제 위험이 감소했다는 증거는 어떻게 다른가?","사용 사례에 따라 시험 항목·합격 기준·재평가 주기를 누가 정해야 하는가?"],"terms":[{"term":"AIMS","ordinaryMeaning":"AI를 관리하는 조직 체계","etymology":"Artificial Intelligence Management System의 약자다.","aiMeaning":"AI 관련 정책·목표·절차를 연결하는 경영시스템","paperReading":"제품 하나의 모델 구조와 구별한다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Management system","ordinaryMeaning":"운영 요소를 함께 묶은 체계","etymology":"management와 system의 결합이다.","aiMeaning":"역할·정책·절차·점검·개선의 상호작용","paperReading":"공개 설명이 조직 차원을 다룬다는 점을 읽는다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"PDCA","ordinaryMeaning":"계획·실행·점검·조치","etymology":"Plan, Do, Check, Act의 머리글자다.","aiMeaning":"관리 활동을 반복적으로 개선하는 순환","paperReading":"한 번 문서를 만든 뒤 끝나는 절차가 아니다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Continual improvement","ordinaryMeaning":"계속 이어가는 개선","etymology":"continual과 improvement의 결합이다.","aiMeaning":"점검 결과를 다음 운영 변경에 반영","paperReading":"개선 완료의 증거를 남길 필요를 생각한다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Conformity","ordinaryMeaning":"정해진 요구와 일치함","etymology":"일반적인 부합의 뜻을 요구사항 충족에 적용한다.","aiMeaning":"해당 기준의 요구를 충족하는 상태","paperReading":"이 공개 안내만으로 적합 판정을 하지 않는다.","sourceUrl":"https://www.iso.org/standard/42001"},{"term":"Risk treatment","ordinaryMeaning":"위험에 대응하는 조치","etymology":"risk와 treatment의 결합이다.","aiMeaning":"위험을 줄이거나 회피·수용·이전하는 대응","paperReading":"어떤 조치가 실제 위험에 맞는지 검토한다.","sourceUrl":"https://www.iso.org/standard/42001"}],"technicalMappingExamples":[{"source":"공개 범위에 따른 자체 학습 예시; 조항 번호 없음","requirement":"AI 관리의 책임과 절차를 운영한다.","test":"가상 서비스의 개발·배포·변경 책임자가 명확한지 사례 기반으로 점검한다.","evidence":"승인 기록·역할표·변경 이력","caution":"이 자료만으로 ISO 적합·인증 여부를 판정하지 않는다."},{"source":"공개 PDCA 설명에 따른 자체 학습 예시","requirement":"점검 결과를 개선에 반영한다.","test":"발견한 문제의 조치 완료와 재평가가 연결되는지 추적한다.","evidence":"문제·조치·재시험의 추적표","caution":"필수 조항의 직접 번역이나 완전한 인증 체크리스트가 아니다."}],"evidence":[{"url":"https://www.iso.org/standard/42001","supports":"공식 제목·판·범위·공개 접근 상태","accessedDate":"2026-10-12"}],"corrections":null,"sitePdfUrl":null},{"id":"w07-s02","week":7,"role":"표준 분석","title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","authors":"Elham Tabassi / NIST","year":2023,"venue":"NIST AI 100-1","citation":"Tabassi, E. (2023). Artificial Intelligence Risk Management Framework (AI RMF 1.0). NIST AI 100-1. https://doi.org/10.6028/NIST.AI.100-1","landingUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10","pdfUrl":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","downloadStatus":"downloaded","redistribution":"allowed","licenseNote":"NIST 직원 저작물 정책은 미국 내 비저작권 및 외국 권리를 주장할 범위에서 전 세계 복제·온라인 사용 허가를 설명한다. 별도 표시된 제3자 자료는 예외, 출처 표기 필요. https://www.nist.gov/nist-research-library/nist-publications Republished courtesy of the National Institute of Standards and Technology.","sourceVersion":"AI RMF 1.0, January 2023","readScope":"full_text","summary":{"question":"AI의 위험을 조직·사용 맥락에 맞춰 어떻게 식별·측정·관리할 것인가?","background":"AI의 위험은 보안 침해를 포함하지만 공정성·안전·프라이버시·사회적 피해까지 더 넓다. 맥락과 이해관계자에 따라 허용 수준도 달라진다.","method":"자발적·범용 위험관리 틀로 GOVERN, MAP, MEASURE, MANAGE의 네 기능과 세부 결과를 제시한다. 조직은 이를 실제 사용 사례의 프로파일과 증거에 연결한다.","findings":"신뢰성은 타당성·신뢰도, 안전, 보안·회복력, 책임성·투명성, 설명가능성·해석가능성, 프라이버시 강화, 유해 편향을 관리한 공정성의 일곱 특성으로 다뤄진다. GOVERN은 다른 기능 전체를 가로지른다.","limitations":"모든 시스템에 동일한 시험이나 합격선을 주는 인증 표준은 아니다. 지표가 부족한 위험과 가치 간 상충을 기록해야 한다. 여기서는 요청된 1.0판을 분석한다.","significance":"윤리 원칙을 책임자·맥락·시험·대응 증거로 연결하는 공통 언어를 제공한다.","beginnerExplanation":"무엇을 위해 쓰는지 정하고, 누구에게 어떤 문제가 생길지 살피고, 시험한 뒤 조치하는 순환이다. 보안 점수 하나로 전체 AI 위험을 대신할 수 없다."},"readingGuide":["Part 1에서 위험과 신뢰성 일곱 특성을 정리한다.","Part 2의 네 기능을 일회성 직선 단계로 오해하지 않는다.","아래 예시는 원문 결과를 수업 과제로 운영화한 것이며 NIST 지정 시험이 아니다."],"discussion":["조직의 절차가 존재한다는 증거와 실제 위험이 감소했다는 증거는 어떻게 다른가?","사용 사례에 따라 시험 항목·합격 기준·재평가 주기를 누가 정해야 하는가?"],"terms":[{"term":"GOVERN","ordinaryMeaning":"방향과 규칙을 정해 운영","etymology":"일반 동사 govern을 기능 이름으로 사용한다.","aiMeaning":"조직의 정책·책임·문화·감독을 정립","paperReading":"모든 위험관리 기능을 가로지른다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"},{"term":"MAP","ordinaryMeaning":"대상과 관계를 지도에 표시","etymology":"지도를 그리는 행위의 비유다.","aiMeaning":"사용 맥락·이해관계자·위험을 파악","paperReading":"측정 전에 무엇이 중요한지 정한다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"},{"term":"MEASURE","ordinaryMeaning":"크기나 상태를 잼","etymology":"측정이라는 일상 동사를 기능 이름으로 사용한다.","aiMeaning":"정량·정성 방법으로 위험과 특성을 평가","paperReading":"측정 불가능한 공백도 기록한다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"},{"term":"MANAGE","ordinaryMeaning":"자원과 조치를 조직해 처리","etymology":"관리라는 일반 동사를 기능 이름으로 사용한다.","aiMeaning":"위험을 우선순위화하고 대응·감시","paperReading":"점수 계산 후 실제 조치를 연결한다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"},{"term":"Profile","ordinaryMeaning":"대상의 특징을 정리한 윤곽","etymology":"옆모습·윤곽을 맥락별 구성에 빗댄 용법이다.","aiMeaning":"특정 조직·사용 사례에 맞춘 프레임워크 적용","paperReading":"현재 상태와 목표 상태의 차이를 본다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"},{"term":"Resilience","ordinaryMeaning":"충격 뒤 회복하는 힘","etymology":"복원·회복의 일반 뜻을 시스템에 적용한다.","aiMeaning":"교란에도 견디고 기능을 회복하는 능력","paperReading":"예방뿐 아니라 대응과 회복의 증거를 찾는다.","sourceUrl":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10"}],"technicalMappingExamples":[{"source":"GOVERN 2.1","requirement":"위험관리 역할·책임·의사소통 경로를 명확히 한다.","test":"가상 사고를 주고 누가 중단·통보·복구를 결정하는지 확인한다.","evidence":"역할표·사고 대응 훈련 기록","caution":"시험 시나리오는 자체 설계 예시다."},{"source":"MAP 5.1","requirement":"사용에 따른 영향의 가능성과 크기를 식별·문서화한다.","test":"이용자 및 비이용자 피해 시나리오의 누락을 검토한다.","evidence":"영향 평가·위험 목록·근거와 불확실성","caution":"정성 판단을 근거 없이 단일 숫자로 확정하지 않는다."},{"source":"MEASURE 2.11","requirement":"맥락에서 식별한 공정성·편향을 평가하고 기록한다.","test":"관련 집단별 오류와 불확실성을 비교하고 지표 선택 이유를 검토한다.","evidence":"평가 자료·집단별 결과·지표 선택 근거","caution":"같은 수치가 모든 맥락의 공정성을 보장하지 않는다."},{"source":"MANAGE 4.3","requirement":"사고·오류의 통보·대응·회복 절차를 실행·기록한다.","test":"가상 사고에서 발견부터 조치·재발 방지까지 추적한다.","evidence":"사고 기록·통보 이력·복구 검증","caution":"프레임워크 준수 자체가 사고 부재를 보증하지 않는다."}],"evidence":[{"url":"https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10","supports":"공식 제목·판·범위·공개 접근 상태","accessedDate":"2026-10-12"},{"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","supports":"48쪽 공식 PDF와 텍스트 추출 확인","accessedDate":"2026-10-12"},{"url":"https://www.nist.gov/itl/ai-risk-management-framework","supports":"1.0 개정 진행 안내와 원문 링크","accessedDate":"2026-10-12"}],"corrections":"2026-10-12 NIST 공식 안내에는 AI RMF 1.0 개정 진행이 표시되어 있다. 이 수업 자료는 요청된 2023년 1.0판에 고정하며 최신판으로 단정하지 않는다.","sitePdfUrl":"standards/w07-s02_nist_ai_rmf10.pdf"}]};
